    select id into v_subject from public.subjects where code = 'sat-math';
    values (v_subject, 'sat-practice-test-5-math', 'SAT Practice Test 5: Math', 'Official SAT Practice Test 5 (College Board), Math: 54 questions in two modules, including student-produced responses. Calculator allowed; 43 minutes per module.', 'full_mock', 'premium', 'draft', 86, 'source', 211, '[[200, 200], [200, 200], [200, 200], [200, 210], [200, 220], [200, 240], [210, 260], [220, 270], [230, 290], [270, 330], [290, 330], [300, 340], [310, 350], [320, 360], [330, 370], [340, 380], [340, 380], [350, 390], [350, 390], [360, 400], [370, 410], [380, 420], [380, 420], [390, 430], [400, 440], [410, 450], [420, 460], [430, 470], [440, 480], [450, 510], [460, 520], [470, 530], [480, 540], [490, 550], [510, 570], [520, 580], [530, 590], [540, 600], [550, 610], [560, 620], [570, 630], [580, 640], [600, 660], [610, 670], [630, 690], [640, 700], [660, 720], [680, 740], [700, 760], [720, 780], [750, 790], [760, 800], [780, 800], [790, 800], [790, 800]]'::jsonb)
    returning id into v_exam;
    values (v_subject, null, null, '{"blocks": [{"type": "image", "src": "/sat/test-05/math-m1-q01.png", "alt": "Figure for question 1", "width": 267}, {"type": "paragraph", "text": "The graph of a system of a linear equation and a nonlinear equation is shown. What is the solution $(x, y)$ to this system?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "The solution is the point where the two graphs intersect: $(4, 5)$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'easy', 'source', 'approved', 1, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "On the first day of a semester, a film club has $90$ members. Each day after the first day of the semester, $10$ new members join the film club. If no members leave the film club, how many total members will the film club have $4$ days after the first day of the semester?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$90 + 4(10) = 130$ members."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'easy', 'source', 'approved', 2, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "image", "src": "/sat/test-05/math-m1-q03.png", "alt": "Figure for question 3", "width": 260}, {"type": "paragraph", "text": "The graph of the linear function $f$ is shown, where $y = f(x)$. What is the $y$-intercept of the graph of $f$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "The line crosses the $y$-axis at $y = 8$, so the $y$-intercept is $(0, 8)$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'easy', 'source', 'approved', 3, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "math", "latex": "\\begin{aligned} s + 7r &= 27 \\\\ r &= 3 \\end{aligned}"}, {"type": "paragraph", "text": "What is the solution $(r, s)$ to the given system of equations?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Substitute $r = 3$: $s + 21 = 27$, so $s = 6$. As an ordered pair $(r, s)$ this is $(3, 6)$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'easy', 'source', 'approved', 4, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "image", "src": "/sat/test-05/math-m1-q05.png", "alt": "Figure for question 5", "width": 80}, {"type": "paragraph", "text": "The table shows selected values from function $f$."}, {"type": "paragraph", "text": "Which of the following is the best description of function $f$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Each time $x$ increases by $1$, $f(x)$ increases by the same amount, $1$. A constant rate of increase means $f$ is increasing linear."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'easy', 'source', 'approved', 5, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "image", "src": "/sat/test-05/math-m1-q06.png", "alt": "Figure for question 6", "width": 255}, {"type": "paragraph", "text": "The graph of a system of linear equations is shown. The solution to the system is $(x, y)$. What is the value of $x$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "The lines intersect at $(4, 1)$, so $x = 4$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'easy', 'source', 'approved', 6, 'spr', array['4']::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "math", "latex": "23, 27, 27, 32, 35, 36, 52"}, {"type": "paragraph", "text": "What is the range of the $7$ scores shown?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Range $=$ greatest $-$ least $= 52 - 23 = 29$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Problem-Solving and Data Analysis'), 'easy', 'source', 'approved', 7, 'spr', array['29']::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "image", "src": "/sat/test-05/math-m1-q08.png", "alt": "Figure for question 8", "width": 278}, {"type": "paragraph", "text": "In the figure, line $m$ is parallel to line $n$, and line $k$ intersects both lines. Which of the following statements is true?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "The angles marked $x^\\circ$ and $145^\\circ$ are vertical angles where line $k$ crosses line $n$, so they are equal: $x = 145$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Geometry and Trigonometry'), 'easy', 'source', 'approved', 8, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "The equation $x + y = 1{,}440$ represents the number of minutes of daylight (between sunrise and sunset), $x$, and the number of minutes of non-daylight, $y$, on a particular day in Oak Park, Illinois. If this day has $670$ minutes of daylight, how many minutes of non-daylight does it have?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$670 + y = 1{,}440$, so $y = 770$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'easy', 'source', 'approved', 9, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "Scott selected $20$ employees at random from all $400$ employees at a company. He found that $16$ of the employees in this sample are enrolled in exactly three professional development courses this year. Based on Scott''s findings, which of the following is the best estimate of the number of employees at the company who are enrolled in exactly three professional development courses this year?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "In the random sample, $\\tfrac{16}{20} = 80\\%$ are enrolled. Applying this to all employees: $0.8 \\times 400 = 320$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Problem-Solving and Data Analysis'), 'easy', 'source', 'approved', 10, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "If $4x - 28 = -24$, what is the value of $x - 7$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$4x - 28 = 4(x - 7)$, so $4(x - 7) = -24$ and $x - 7 = -6$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'easy', 'source', 'approved', 11, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "For a snowstorm in a certain town, the minimum rate of snowfall recorded was $0.6$ inches per hour, and the maximum rate of snowfall recorded was $1.8$ inches per hour. Which inequality is true for all values of $s$, where $s$ represents a rate of snowfall, in inches per hour, recorded for this snowstorm?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Every recorded rate is at least the minimum, $0.6$, and at most the maximum, $1.8$: $0.6 \\le s \\le 1.8$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'easy', 'source', 'approved', 12, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "math", "latex": "\\begin{aligned} y &= 4x \\\\ y &= x^2 - 12 \\end{aligned}"}, {"type": "paragraph", "text": "A solution to the given system of equations is $(x, y)$, where $x > 0$. What is the value of $x$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Set the expressions equal: $x^2 - 12 = 4x$, so $x^2 - 4x - 12 = 0$ and $(x - 6)(x + 2) = 0$. With $x > 0$, $x = 6$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Advanced Math'), 'medium', 'source', 'approved', 13, 'spr', array['6']::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "A store sells two different-sized containers of blueberries. The store''s sales of these blueberries totaled $896.86$ dollars last month. The equation $4.51x + 6.07y = 896.86$ represents this situation, where $x$ is the number of smaller containers sold and $y$ is the number of larger containers sold. According to the equation, what is the price, in dollars, of each smaller container?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Each smaller container adds $4.51$ dollars to the total for each one sold ($4.51x$), so it costs $\\$4.51$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'easy', 'source', 'approved', 14, 'spr', array['4.51', '451/100']::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "A right circular cylinder has a base diameter of $22$ centimeters and a height of $6$ centimeters. What is the volume, in cubic centimeters, of the cylinder?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "The radius is $11$, so $V = \\pi r^2 h = \\pi(121)(6) = 726\\pi$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Geometry and Trigonometry'), 'easy', 'source', 'approved', 15, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "image", "src": "/sat/test-05/math-m1-q16.png", "alt": "Figure for question 16", "width": 327}, {"type": "paragraph", "text": "The graph of the rational function $f$ is shown, where $y = f(x)$ and $x \\ge 0$. Which of the following is the graph of $y = f(x) + 5$, where $x \\ge 0$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Adding $5$ shifts the whole graph up $5$ units. The original curve levels off near $y = 1$ for large $x$, so the new one levels off near $y = 6$. Only graph D does this."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Advanced Math'), 'medium', 'source', 'approved', 16, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "At a particular track meet, the ratio of coaches to athletes is $1$ to $26$. If there are $x$ coaches at the track meet, which of the following expressions represents the number of athletes at the track meet?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "There are $26$ athletes for every coach, so $x$ coaches go with $26x$ athletes."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Problem-Solving and Data Analysis'), 'easy', 'source', 'approved', 17, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "Kaylani used fabric measuring $5$ yards in length to make each suit for a men''s choir. The relationship between the number of suits that Kaylani made, $x$, and the total length of fabric that she purchased $y$, in yards, is represented by the equation $y - 5x = 6$. What is the best interpretation of $6$ in this context?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$5x$ is the fabric used for the suits and $y$ is the fabric purchased, so $y - 5x = 6$ says she bought $6$ yards more than she used."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'medium', 'source', 'approved', 18, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "What is the value of $\\tan\\dfrac{92\\pi}{3}$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Tangent repeats every $\\pi$. $\\dfrac{92\\pi}{3} = 30\\pi + \\dfrac{2\\pi}{3}$, so the value equals $\\tan\\dfrac{2\\pi}{3} = -\\sqrt{3}$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Geometry and Trigonometry'), 'hard', 'source', 'approved', 19, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "image", "src": "/sat/test-05/math-m1-q20.png", "alt": "Figure for question 20", "width": 297}, {"type": "paragraph", "text": "In the triangle shown, what is the value of $\\cos x^\\circ$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "The side of length $11$ is adjacent to angle $x$, and $28$ is the hypotenuse, so $\\cos x^\\circ = \\tfrac{11}{28}$ (about $0.3929$)."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Geometry and Trigonometry'), 'medium', 'source', 'approved', 20, 'spr', array['.3928', '.3929', '11/28']::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "The function $g$ is defined by $g(x) = (x + 14)(t - x)$, where $t$ is a constant. In the $xy$-plane, the graph of $y = g(x)$ passes through the point $(24, 0)$. What is the value of $g(0)$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$g(24) = 38(t - 24) = 0$, so $t = 24$. Then $g(0) = (14)(24) = 336$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Advanced Math'), 'medium', 'source', 'approved', 21, 'spr', array['336']::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "math", "latex": "(x + 4)^2 + (y - 19)^2 = 121"}, {"type": "paragraph", "text": "The graph of the given equation is a circle in the $xy$-plane. The point $(a, b)$ lies on the circle. Which of the following is a possible value for $a$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "The center is $(-4, 19)$ and the radius is $11$, so $x$-coordinates on the circle range from $-15$ to $7$. Only $-14$ is in that range."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Geometry and Trigonometry'), 'medium', 'source', 'approved', 22, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "A right rectangular prism has a height of $9$ inches. The length of the prism''s base is $x$ inches, which is $7$ inches more than the width of the prism''s base. Which function $V$ gives the volume of the prism, in cubic inches, in terms of the length of the prism''s base?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "The width is $x - 7$, so the volume is length $\\times$ width $\\times$ height $= x(x - 7)(9) = 9x(x - 7)$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Advanced Math'), 'medium', 'source', 'approved', 23, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "Which of the following functions has(have) a minimum value at $-3$?"}, {"type": "math", "latex": "\\begin{aligned} &\\text{I. } f(x) = -6(3)^x - 3 \\\\ &\\text{II. } g(x) = -3(6)^x \\end{aligned}"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Both functions are a negative multiple of an increasing exponential, so both decrease without bound as $x$ grows and have no minimum value. ($f$ approaches $-3$ from below only as $x \\to -\\infty$.)"}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Advanced Math'), 'hard', 'source', 'approved', 24, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "The result of increasing the quantity $x$ by $400\\%$ is $60$. What is the value of $x$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Increasing by $400\\%$ multiplies by $1 + 4 = 5$: $5x = 60$, so $x = 12$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Problem-Solving and Data Analysis'), 'medium', 'source', 'approved', 25, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "The function $f$ is defined by $f(x) = ax^2 + bx + c$, where $a$, $b$, and $c$ are constants. The graph of $y = f(x)$ in the $xy$-plane passes through the points $(7, 0)$ and $(-3, 0)$. If $a$ is an integer greater than $1$, which of the following could be the value of $a + b$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$f(x) = a(x - 7)(x + 3) = ax^2 - 4ax - 21a$, so $b = -4a$ and $a + b = -3a$. With $a = 2$, $a + b = -6$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Advanced Math'), 'hard', 'source', 'approved', 26, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "The function $g$ is defined by $g(x) = x(x - 2)(x + 6)^2$. The value of $g(7 - w)$ is $0$, where $w$ is a constant. What is the sum of all possible values of $w$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$g$ is $0$ when its input is $0$, $2$, or $-6$. So $7 - w \\in \\{0, 2, -6\\}$, giving $w = 7$, $5$, or $13$. Their sum is $25$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Advanced Math'), 'hard', 'source', 'approved', 27, 'spr', array['25']::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "What is $20\\%$ of $440$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$0.20 \\times 440 = 88$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Problem-Solving and Data Analysis'), 'easy', 'source', 'approved', 1, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "image", "src": "/sat/test-05/math-m2-q02.png", "alt": "Figure for question 2", "width": 294}, {"type": "paragraph", "text": "Argon is placed inside a container with a constant volume. The graph shows the estimated pressure $y$, in pounds per square inch (psi), of the argon when its temperature is $x$ kelvins."}, {"type": "paragraph", "text": "What is the estimated pressure of the argon, in psi, when the temperature is $600$ kelvins?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "At $x = 600$ the line is at $y = 12$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'easy', 'source', 'approved', 2, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "The function $f$ is defined by $f(x) = 4x - 3$. What is the value of $f(10)$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$f(10) = 4(10) - 3 = 37$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'easy', 'source', 'approved', 3, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "Which expression is equivalent to $16x^3y^2 + 14xy$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "The greatest common factor is $2xy$: $16x^3y^2 + 14xy = 2xy(8x^2y + 7)$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Advanced Math'), 'easy', 'source', 'approved', 4, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "A veterinarian recommends that each day a certain rabbit should eat $25$ calories per pound of the rabbit''s weight, plus an additional $11$ calories. Which equation represents this situation, where $c$ is the total number of calories the veterinarian recommends the rabbit should eat each day if the rabbit''s weight is $x$ pounds?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$25$ calories for each of the $x$ pounds is $25x$, plus $11$ more: $c = 25x + 11$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'easy', 'source', 'approved', 5, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "If $6n = 12$, what is the value of $n + 4$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$n = 2$, so $n + 4 = 6$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'easy', 'source', 'approved', 6, 'spr', array['6']::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "math", "latex": "(d - 30)(d + 30) - 7 = -7"}, {"type": "paragraph", "text": "What is a solution to the given equation?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Add $7$ to both sides: $(d - 30)(d + 30) = 0$, so $d = 30$ or $d = -30$. Either is correct."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Advanced Math'), 'medium', 'source', 'approved', 7, 'spr', array['30', '-30']::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "Line $r$ in the $xy$-plane has a slope of $4$ and passes through the point $(0, 6)$. Which equation defines line $r$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Slope $4$ and $y$-intercept $6$ give $y = 4x + 6$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'easy', 'source', 'approved', 8, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "image", "src": "/sat/test-05/math-m2-q09.png", "alt": "Figure for question 9", "width": 291}, {"type": "paragraph", "text": "A competitive diver dives from a platform into the water. The graph shown gives the height above the water $y$, in meters, of the diver $x$ seconds after diving from the platform. What is the best interpretation of the $x$-intercept of the graph?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "The $x$-intercept, about $(1.6, 0)$, is where the height above the water is $0$: the diver hits the water at $1.6$ seconds."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Advanced Math'), 'easy', 'source', 'approved', 9, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "The kinetic energy, in joules, of an object with mass $9$ kilograms traveling at a speed of $v$ meters per second is given by the function $K$, where $K(v) = \\dfrac{9}{2}v^2$. Which of the following is the best interpretation of $K(34) = 5{,}202$ in this context?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "The input $v = 34$ is the speed in meters per second and the output $5{,}202$ is the kinetic energy in joules."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Advanced Math'), 'medium', 'source', 'approved', 10, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "image", "src": "/sat/test-05/math-m2-q11.png", "alt": "Figure for question 11", "width": 258}, {"type": "paragraph", "text": "The scatterplot shows the relationship between two variables $x$ and $y$. A line of best fit for the data is also shown."}, {"type": "paragraph", "text": "For how many of the $10$ data points is the actual $y$-value greater than the $y$-value predicted by the line of best fit?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "A point''s actual $y$-value is greater than the predicted value when the point lies above the line. Six of the ten points are above the line."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Problem-Solving and Data Analysis'), 'medium', 'source', 'approved', 11, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "At a movie theater, there are a total of $350$ customers. Each customer is located in either theater A, theater B, or theater C. If one of these customers is selected at random, the probability of selecting a customer who is located in theater A is $0.48$, and the probability of selecting a customer who is located in theater B is $0.24$. How many customers are located in theater C?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "The probability for theater C is $1 - 0.48 - 0.24 = 0.28$, so $0.28 \\times 350 = 98$ customers."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Problem-Solving and Data Analysis'), 'medium', 'source', 'approved', 12, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "What is the slope of the graph of $y = \\dfrac{1}{3}(29x + 10) + 5x$ in the $xy$-plane?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Distribute: $y = \\tfrac{29}{3}x + \\tfrac{10}{3} + 5x = \\tfrac{44}{3}x + \\tfrac{10}{3}$. The slope is $\\tfrac{44}{3}$ (about $14.67$)."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'medium', 'source', 'approved', 13, 'spr', array['14.66', '14.67', '44/3']::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "The length of each edge of a box is $29$ inches. Each side of the box is in the shape of a square. The box does not have a lid. What is the exterior surface area, in square inches, of this box without a lid?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "A cube without a lid has $5$ square faces, each $29^2 = 841$ square inches: $5 \\times 841 = 4{,}205$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Geometry and Trigonometry'), 'medium', 'source', 'approved', 14, 'spr', array['4205']::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "image", "src": "/sat/test-05/math-m2-q15.png", "alt": "Figure for question 15", "width": 148}, {"type": "paragraph", "text": "Five *Eretmochelys imbricata*, a type of sea turtle, each have a nest. The table shows an original data set of the number of eggs that each turtle laid in its nest."}, {"type": "paragraph", "text": "A sixth nest with $121$ eggs is added to create a new data set. Which of the following correctly compares the means of the two data sets?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Every original value is above $121$, so the original mean is above $121$. Adding a value below the mean pulls the mean down, so the original mean is greater."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Problem-Solving and Data Analysis'), 'medium', 'source', 'approved', 15, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "In $\\triangle RST$, the measure of $\\angle R$ is $63^\\circ$. Which of the following could be the measure, in degrees, of $\\angle S$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "The other two angles must total $180 - 63 = 117$ degrees, so $\\angle S$ is less than $117$. Only $116$ works."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Geometry and Trigonometry'), 'medium', 'source', 'approved', 16, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "Which expression is equivalent to $(8x^3 + 8) - (x^3 - 2)$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Distribute the subtraction: $8x^3 + 8 - x^3 + 2 = 7x^3 + 10$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Advanced Math'), 'easy', 'source', 'approved', 17, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "If $4\\sqrt{2x} = 16$, what is the value of $6x$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$\\sqrt{2x} = 4$, so $2x = 16$ and $x = 8$. Then $6x = 48$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Advanced Math'), 'medium', 'source', 'approved', 18, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "math", "latex": "2x - y > 883"}, {"type": "paragraph", "text": "For which of the following tables are all the values of $x$ and their corresponding values of $y$ solutions to the given inequality?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Check table D: $2(442) - 0 = 884$, $2(441) + 2 = 884$, and $2(440) + 4 = 884$, all greater than $883$. Each other table has a pair that fails (for example $(440, 0)$ gives $880$)."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'medium', 'source', 'approved', 19, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "math", "latex": "\\begin{aligned} 5y &= 10x + 11 \\\\ -5y &= 5x - 21 \\end{aligned}"}, {"type": "paragraph", "text": "The solution to the given system of equations is $(x, y)$. What is the value of $30x$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Add the equations: $0 = 15x - 10$, so $15x = 10$ and $30x = 20$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'medium', 'source', 'approved', 20, 'spr', array['20']::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "A rectangle is inscribed in a circle, such that each vertex of the rectangle lies on the circumference of the circle. The diagonal of the rectangle is twice the length of the shortest side of the rectangle. The area of the rectangle is $1{,}089\\sqrt{3}$ square units. What is the length, in units, of the diameter of the circle?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "If the short side is $s$, the diagonal is $2s$, so the long side is $s\\sqrt{3}$ and the area is $s^2\\sqrt{3} = 1{,}089\\sqrt{3}$, giving $s = 33$. The diagonal is a diameter of the circle: $2s = 66$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Geometry and Trigonometry'), 'hard', 'source', 'approved', 21, 'spr', array['66']::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "Rectangles $ABCD$ and $EFGH$ are similar. The length of each side of $EFGH$ is $6$ times the length of the corresponding side of $ABCD$. The area of $ABCD$ is $54$ square units. What is the area, in square units, of $EFGH$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Scaling lengths by $6$ scales area by $6^2 = 36$: $54 \\times 36 = 1{,}944$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Geometry and Trigonometry'), 'medium', 'source', 'approved', 22, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "Which expression is equivalent to $\\dfrac{42a}{k} + 42ak$, where $k > 0$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Write $42ak$ over $k$: $\\dfrac{42a + 42ak^2}{k} = \\dfrac{42a(k^2 + 1)}{k}$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Advanced Math'), 'medium', 'source', 'approved', 23, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "Which quadratic equation has no real solutions?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "An equation has no real solutions when its discriminant is negative. For D: $(-14)^2 - 4(5)(49) = 196 - 980 < 0$. The others have discriminants $\\ge 0$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Advanced Math'), 'medium', 'source', 'approved', 24, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "math", "latex": "P(t) = 260(1.04)^{\\left(\\frac{6}{4}\\right)t}"}, {"type": "paragraph", "text": "The function $P$ models the population, in thousands, of a certain city $t$ years after $2003$. According to the model, the population is predicted to increase by $4\\%$ every $n$ months. What is the value of $n$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "The population grows by $4\\%$ each time the exponent $\\tfrac{6}{4}t$ increases by $1$, that is, every $\\tfrac{4}{6} = \\tfrac{2}{3}$ of a year, which is $8$ months."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Advanced Math'), 'hard', 'source', 'approved', 25, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "A circle in the $xy$-plane has its center at $(-1, 1)$. Line $t$ is tangent to this circle at the point $(5, -4)$. Which of the following points also lies on line $t$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "The radius to $(5, -4)$ has slope $\\dfrac{-4 - 1}{5 - (-1)} = -\\dfrac{5}{6}$, so the tangent has slope $\\dfrac{6}{5}$: $y + 4 = \\tfrac{6}{5}(x - 5)$. At $x = 10$, $y = -4 + 6 = 2$, so $(10, 2)$ is on the line."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Geometry and Trigonometry'), 'hard', 'source', 'approved', 26, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "For an electric field passing through a flat surface perpendicular to it, the electric flux of the electric field through the surface is the product of the electric field''s strength and the area of the surface. A certain flat surface consists of two adjacent squares, where the side length, in meters, of the larger square is $3$ times the side length, in meters, of the smaller square. An electric field with strength $29.00$ volts per meter passes uniformly through this surface, which is perpendicular to the electric field. If the total electric flux of the electric field through this surface is $4{,}640$ volts $\\cdot$ meters, what is the electric flux, in volts $\\cdot$ meters, of the electric field through the larger square?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "With small side $s$, the total area is $s^2 + 9s^2 = 10s^2$, so $29(10s^2) = 4{,}640$ and $s^2 = 16$. The larger square''s area is $9 \\times 16 = 144$, so its flux is $29 \\times 144 = 4{,}176$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Geometry and Trigonometry'), 'hard', 'source', 'approved', 27, 'spr', array['4176']::text[]) returning id into v_q;
    update public.exams set status = 'published' where id = v_exam;
  end if;
end $sat$;

do $sat$
declare
  v_subject uuid; v_exam uuid; v_section uuid; v_stim uuid; v_q uuid;
begin
  -- SAT Practice Test 6: Reading and Writing
  if exists (select 1 from public.exams where slug = 'sat-practice-test-6-reading-and-writing') then
    raise notice 'skipping sat-practice-test-6-reading-and-writing (already imported)';
  else
    select id into v_subject from public.subjects where code = 'sat-english';
    values (v_subject, 'sat-practice-test-6-reading-and-writing', 'SAT Practice Test 6: Reading and Writing', 'Official SAT Practice Test 6 (College Board), Reading and Writing: 66 questions in two modules, timed as the paper test (39 minutes per module).', 'full_mock', 'premium', 'draft', 78, 'source', 212, '[[200, 200], [200, 200], [200, 200], [200, 200], [200, 200], [200, 210], [200, 230], [200, 250], [210, 270], [220, 280], [230, 290], [240, 300], [260, 320], [270, 330], [280, 330], [290, 350], [310, 370], [320, 380], [340, 380], [350, 390], [360, 400], [370, 410], [380, 420], [390, 430], [400, 440], [400, 440], [410, 450], [420, 460], [430, 470], [440, 480], [450, 490], [460, 500], [470, 510], [470, 510], [480, 520], [490, 530], [500, 540], [510, 550], [520, 560], [530, 570], [540, 580], [530, 590], [550, 610], [560, 620], [570, 630], [580, 640], [590, 650], [590, 650], [600, 660], [620, 660], [630, 670], [640, 680], [650, 690], [660, 700], [670, 710], [680, 720], [690, 730], [700, 740], [710, 750], [720, 760], [720, 760], [730, 770], [750, 770], [760, 780], [770, 790], [780, 800], [790, 800]]'::jsonb)
    returning id into v_exam;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text with the most logical and precise word or phrase?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice D is the best answer because in context, sharing “similarities with” means having some resemblance to. The text establishes a comparison between two groups of mammals, stating that although they aren’t closely related, hedgehog tenrecs and true hedgehogs play similar roles in their habitats, a circumstance that has resulted in the independent development of some of the same physical traits. This context supports the idea that hedgehog tenrecs resemble, or share basic similarities with, true hedgehogs in some respects."}, {"type": "paragraph", "text": "Choice A is incorrect because the text doesn’t suggest that hedgehog tenrecs are “examples of,” or representative of, true hedgehogs. The text states despite some shared physical traits, the two groups of mammals aren’t closely related; therefore, hedgehog tenrecs can’t be examples of true hedgehogs. Choice B is incorrect because in this context, “concerns about” would mean worries about or interests in. The text focuses on the various physical traits that hedgehog tenrecs and true hedgehogs share. There’s nothing in the text to suggest why hedgehog tenrecs would be worried about true hedgehogs, or why they would be interested in them. Choice C is incorrect because in this context, “indications of” would mean evidence of. By listing a set of traits that hedgehog tenrecs share with true hedgehogs, the text establishes a comparison between the two groups of mammals, and saying that the traits shared within one group of mammals provide evidence of another group of mammals wouldn’t be an effective way to establish the similarities between the two groups."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Craft and Structure'), 'medium', 'source', 'approved', 1, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text with the most logical and precise word or phrase?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice B is the best answer because it most logically completes the text’s discussion of Yaszek’s introduction to her science fiction anthology. In this context “overtly” means openly or without concealment. The text draws a contrast between the lack of “deliberately signaled” political themes in women- authored science fiction from the 1920s to the 1960s and what Yaszek notes about women-authored science fiction from the 1970s. This contrast implies that the work from the 1970s did clearly reflect feminist political themes. In other words, the text indicates that unlike women who wrote science fiction in the 1920s to the 1960s, the women who wrote science fiction in the 1970s expressed overtly feminist themes."}, {"type": "paragraph", "text": "Choice A is incorrect. In this context “prudently” would mean cautiously, which might plausibly describe the women who wrote science fiction from the 1920s to the 1960s, in that they tended to avoid revealing their political views; however, the text contrasts these authors with the women writing science fiction in the 1970s, thereby suggesting that the authors writing in the 1970s were not restrained in that way. Choice C is incorrect because in this context “cordially” would mean politely, and nothing in the text indicates that politeness was a significant factor for women writing science fiction either from the 1920s to the 1960s or in the 1970s. The text draws a contrast between the lack of “deliberately signaled” political themes in women-authored science fiction from the 1920s to the 1960s and what Yaszek notes about women-authored science fiction from the 1970s. It’s unclear how “less deliberately signaled” politics and an increasing sense of politeness toward feminism would constitute a meaningful contrast. Choice D is incorrect because in this context, “inadvertently” would mean unintentionally, and nothing in the text suggests that Yaszek thought the feminist elements of the women-authored science fiction from the 1970s arose without deliberate effort."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Craft and Structure'), 'medium', 'source', 'approved', 2, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text with the most logical and precise word or phrase?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice B is the best answer because it most logically completes the text’s discussion about research into social media use. In context, “redressing” means remedying or compensating for. The text indicates that there is a long-standing trend of overemphasizing teenagers and young adults in studies of social media use. It goes on to say that scholars have recently broadened the kinds of social media users they study by including senior citizens. This suggests that scholars are redressing the long-standing trend of overemphasis on younger users by studying older users as well."}, {"type": "paragraph", "text": "Choice A is incorrect because “exacerbating” means making worse or aggravating, which would not make logical sense in context. Expanding the focus of studies of social media use to include senior citizens would not make the long-standing trend of overemphasizing teenagers and young adults in studies of social media use worse; instead, it would help to remedy this trend. Choice C is incorrect because “epitomizing” means illustrating or providing an example, which would not make logical sense in context. Expanding the groups of social media users that scholars study to include senior citizens would not provide an example of the long-standing trend of overemphasizing teenagers and young people in research on social media use. Choice D is incorrect because “precluding” means making impossible in advance or preventing, which would not make logical sense in context. The text indicates that there is a long-standing trend of overemphasizing teenagers and young adults in social media research. Expanding the focus of social media research to include senior citizens, as the text indicates scholars have begun to do, could help to rectify the trend, but it could not prevent the trend or make the trend impossible in advance, since the trend started long before scholars started expanding their focus."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Craft and Structure'), 'medium', 'source', 'approved', 3, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "As used in the text, what does the word “disputing” most nearly mean?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice D is the best answer because as used in the text, “disputing” most nearly means providing resistance to. The narrator is in a taxi as it drives down a street lined with so many food vendors and shoppers that the narrator describes them as “the multitude of Paris,” meaning an immense group of people. The street is essentially a large open-air market, and there are so many people pushing small wagons of goods and carrying shopping baskets that “every inch” of the taxi’s progress is impeded. In other words, the people are providing resistance to the taxi’s attempt to drive down the street."}, {"type": "paragraph", "text": "Choice A is incorrect. Although in some contexts, “disputing” can mean arguing, the narrator doesn’t portray the shoppers and vendors as arguing with the driver of the taxi or, indeed, arguing at all. Choice B is incorrect. Although in some contexts, “disputing” can mean expressing disapproval, the narrator doesn’t suggest that the shoppers and vendors necessarily disapprove of the taxi’s attempt to drive down the street. Instead, their combined presence along the street has the effect of impeding the taxi’s progress. Choice C is incorrect because, as the narrator explains, both the multitude of people and the taxi are using a public space (a street) at the same time. The narrator doesn’t go so far as to suggest that the people feel that they, and not the taxi, possess exclusive access to the street."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Craft and Structure'), 'medium', 'source', 'approved', 4, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text with the most logical and precise word or phrase?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice D is the best answer because it most logically completes the text’s discussion of the twelfth-century Islamic philosopher Ibn Rushd. As used in this context, “inconsequential to” means not significant to. According to the text, Ibn Rushd’s works were primarily available in Spain, where he lived, far from central areas of the Muslim world, a fact that could support the conclusion that his influence on Muslim contemporaries was limited. The text implies, however, that recent scholarship has shown that his works still had an impact on other Muslim philosophers of his time. This context supports the idea that his works weren’t inconsequential to Islamic thought in this period."}, {"type": "paragraph", "text": "Choice A is incorrect because the issue under consideration in the text is whether other Muslim philosophers of Ibn Rushd’s time had access to his works, not whether his works were “controversial among,” or causing dispute among, other philosophers. Choice B is incorrect. The text implies that other Muslim philosophers of Ibn Rushd’s era were aware of his works, not that they were “antagonistic toward,” or hostile toward, them. There is no suggestion that Ibn Rushd’s writings elicited hostility from his contemporaries. Choice C is incorrect because in this context, “imitated by” would mean followed as a model by. Although the text implies that Ibn Rushd’s works were at least somewhat available in regions that were at the center of Islamic thought during the period, it doesn’t specifically address in what ways his works influenced contemporary Muslim philosophers. Thus, the text doesn’t support the idea that other philosophers modeled their own works after Ibn Rushd’s works."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Craft and Structure'), 'medium', 'source', 'approved', 5, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, 0, '{"blocks": [{"type": "paragraph", "text": "Which choice best describes the function of the underlined sentence in the text as a whole?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice A is the best answer because it most accurately describes the function of the underlined sentence in the text as a whole. The first sentence of the text indicates that Johnson returned to the US in 1938 at which time his painting style suddenly changed. The second sentence is underlined and gives more detail about this stylistic change, noting that his earlier work consisted largely of landscapes in an expressionist style and his new works were highly stylized portraits of Black Americans. In other words, the function of the underlined sentence is to elaborate on a transitional moment in Johnson’s painting career."}, {"type": "paragraph", "text": "Choice B is incorrect. Although the text does mention that Johnson spent a decade in Europe, it does not discuss what other travel Johnson might have done. Furthermore, although the text mentions African, American, and Scandinavian artistic elements in Johnson’s work, it does not indicate that he traveled to different locations to learn about these practices. Choice C is incorrect because the text does not focus on Johnson’s personal life nor does it address how successful his career was in general. Choice D is incorrect because, rather than call it into question, the underlined sentence continues the discussion of Johnson’s career by adding further relevant detail of Johnson’s artistic transformation."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Craft and Structure'), 'medium', 'source', 'approved', 6, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice best states the main purpose of the text?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice B is the best answer because it most accurately describes the main purpose of the text, which is to establish that pianist Martha Argerich’s performances appear easy because of her work to prepare for them. The text begins by stating that Argerich plays in such a way that it looks like the music is coming to her naturally in the moment, without planning. It goes on to point out that despite her skill and experience, Argerich works tirelessly and treats each piece of music as if it is new each time she performs it, and that it is this preparation that causes her playing to appear relaxed and natural. These details establish that the purpose of the text is to assert that Argerich’s performances look effortless because of how she prepares for them."}, {"type": "paragraph", "text": "Choice A is incorrect because the text doesn’t address how Argerich selects the music she’ll perform; instead, it describes how she approaches a piece of music in preparation for a performance. Choice C is incorrect because the text doesn’t discuss kinds of music beyond stating that Argerich is a classical pianist, and it doesn’t mention Argerich actually encountering any music for the first time; it indicates only that she approaches a piece of music she is going to perform as if she has never played it before. Choice D is incorrect because the text doesn’t mention music that Argerich is actually performing for the first time, only that Argerich approaches the pieces she performs as if they are new each time; further, the text doesn’t characterize this approach as unique, or something only Argerich does."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Craft and Structure'), 'medium', 'source', 'approved', 7, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, 0, '{"blocks": [{"type": "paragraph", "text": "Which choice best describes the function of the underlined portion in the text as a whole?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice B is the best answer because it best describes the function of the underlined portion in the text as a whole. The text describes the failed attempt of Israel Potter to establish a farm in New England during the late eighteenth century: according to his contract, he was to receive two hundred acres in exchange for three months’ work, but his employer then refused to fulfill the bargain and Israel had no recourse to law to obtain the land he was owed. Israel was therefore forced to find another means of supporting himself. To explain why Israel was particularly susceptible to his employer’s dishonesty, the underlined portion states that though Israel was “brave-hearted, and even much of a dare-devil upon a pinch,” he also possessed “a singular patience and mildness.” In other words, Israel could be courageous in certain circumstances, but he was usually meek and disinclined to argument, from which it is reasonable to infer that Israel was often taken advantage of. Thus, the underlined portion suggests that if not for a certain aspect of his character, Israel might not have been as easily thwarted in his ambition to establish a farm."}, {"type": "paragraph", "text": "Choice A is incorrect because although the underlined portion describes aspects of Israel’s personality, it does not address how he feels about his own personality. Choice C is incorrect because the underlined portion addresses Israel’s occasional courage and frequent meekness but does not address whether he would have the skills and resolve necessary to operate a farm if he owned sufficient property. Choice D is incorrect. Though the underlined portion does indicate that Israel could be courageous in certain circumstances, it does not say that he undertook acts of courage that others avoided, but rather that he was habitually meek. Even if the underlined portion did say that Israel was more courageous than most, this would not explain why he found himself under the circumstances described in the text—that is, as a consequence of his meek nature, cheated of the property to which he had a right."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Craft and Structure'), 'medium', 'source', 'approved', 8, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, 0, '{"blocks": [{"type": "paragraph", "text": "Based on the texts, how would the author of Text 2 most likely respond to the underlined claim in Text 1?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice D is the best answer because it reflects how the author of Text 2 would most likely respond to the underlined claim in Text 1. Text 1 begins by noting the success of The Nutcracker but then claims that the ballet is “stuck in the past” and should “no longer be produced.” Text 2 begins by conceding that The Nutcracker is indeed outdated but argues that it should continue to be performed, states that the show can be updated to include more contemporary dance styles, and provides an example of one such modernized version, Hot Chocolate Nutcracker. Hence, the author of Text 2 would most likely respond to the underlined claim in Text 1 by suggesting that dance companies should consider offering revised versions of The Nutcracker instead of completely rejecting the show."}, {"type": "paragraph", "text": "Choice A is incorrect because the author of Text 2 advocates for using creative ways to update The Nutcracker and therefore wouldn’t respond to the underlined claim by rejecting the suggestion that contemporary audiences would enjoy an updated version. Choice B is incorrect because although the authors of both texts claim that The Nutcracker is outdated, neither text suggests that contemporary audiences have largely stopped attending productions of the show. On the contrary, Text 2 states that The Nutcracker is a holiday favorite and generates substantial income for some dance companies. Choice C is incorrect because although Text 2 provides an example of a contemporized version of The Nutcracker, the text doesn’t suggest that offering modernized versions is a way to increase income for most dance companies. Rather, the author of Text 2 suggests that offering modernized versions is a way to make the ballet discussed in Text 1 feel less outdated."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Craft and Structure'), 'medium', 'source', 'approved', 9, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice best states the main idea of the text?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice D is the best answer because it most accurately states the main idea of the text. The text indicates that archaeologist Mª Ángeles Medina-Alcaide and her team used replicas of Paleolithic light sources to understand how Paleolithic artists moved through dark caves. The researchers learned, for example, that torches were more helpful for moving through caves than animal-fat lamps were. Thus, the main idea of the text is that Medina-Alcaide and her team tested Paleolithic light sources and learned some details about how Paleolithic artists traveled within dark caves."}, {"type": "paragraph", "text": "Choice A is incorrect because the text doesn’t address the usefulness of fireplaces for Paleolithic cave artists; it only mentions fireplaces briefly as one of the three lighting methods the researchers tested. Choice B is incorrect because the text doesn’t discuss how often Paleolithic cave artists used each kind of light source tested. Although the text does compare animal-fat lamps with another lighting method, the point of that comparison is that animal-fat lamps were less useful than torches when walking, not that one method was used more often than another. Choice C is incorrect because the text doesn’t discuss either how difficult it was for Medina-Alcaide and her team to replicate light sources or how the team felt about drawing conclusions from their study. Instead, the text reveals that the team was able to conclude that each light source likely had a distinct purpose."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 10, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice most effectively uses data from the table to complete the statement?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice A is the best answer because it most effectively uses data from the table to complete the statement about the US auto industry in the early twentieth century. The table shows the number of cars produced annually and number of companies producing cars in the United States between 1910 and 1925 in increments of five years. According to the table, the number of cars produced consistently increased from one increment to the next, going from 123,990 cars in 1910 to 3,185,881 cars in 1925. At the same time, the table shows that the number of companies producing cars consistently decreased, going from 320 companies in 1910 to only 80 companies in 1925. Thus, the table shows that the number of cars produced increased from 1910 to 1925, even as the number of companies producing cars decreased."}, {"type": "paragraph", "text": "Choice B is incorrect. The table shows that the number of cars produced in the US increased, going from 123,990 in 1910 to 3,185,881 in 1925, instead of remaining unchanged, and the table also shows that the number of companies producing cars decreased from 320 to 80 instead of remaining unchanged. Choice C is incorrect because the table indicates that the number of cars produced consistently increased from 1910 to 1925, going from 123,990 cars to 3,185,881 cars, instead of decreasing; moreover, the table shows that the number of companies producing cars from 1910 to 1925 declined from 320 to 80 instead of remaining unchanged. Choice D is incorrect because the table indicates that the number of companies producing cars consistently decreased from 1910 to 1925, going from 320 companies to only 80 companies."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 11, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which response from a survey given to shoppers who made a purchase at a retail store best supports the researchers’ explanation?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice A is the best answer because it best supports the researchers’ explanation of the results of rearranging a store’s layout. According to the text, Sam K. Hui and colleagues found that rearranging a store’s layout can encourage customers to make spontaneous purchases. The text states that the researchers explain that a change in layout causes shoppers to hunt for items’ new locations, which exposes the shoppers to more products and increases the likelihood that they’ll make an unplanned purchase. This quotation from a surveyed shopper indicates that the shopper spontaneously purchased a notebook while looking for cleaning supplies that weren’t in their usual place. The quotation therefore supports the researchers’ explanation that rearranging a store’s layout can lead shoppers to make unanticipated purchases."}, {"type": "paragraph", "text": "Choice B is incorrect because it doesn’t support the researchers’ explanation that rearranging a store’s layout can lead shoppers to make unanticipated purchases. Instead of attributing an unplanned purchase to a change in layout, the quotation notes that the shopper searched for but couldn’t find some items, and as a result the shopper purchased less, not more, than what was anticipated. Choice C is incorrect because the quotation attributes what was purchased to coupons that the shopper received, not to a new store layout. Thus, the quotation doesn’t support the researchers’ explanation that rearranging a store’s layout can lead shoppers to make unanticipated purchases. Choice D is incorrect because the quotation attributes what was purchased to the size and stock of the store, not to a new store layout. The shopper simply purchased products that the shopper wanted in a particular store because other stores didn’t carry those products, so the quotation doesn’t support the researchers’ explanation that rearranging a store’s layout can lead shoppers to make spontaneous purchases."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 12, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, 0, '{"blocks": [{"type": "paragraph", "text": "Which statement about the exhibitions, if true, would most directly support the underlined claim?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice A is the best answer because it presents a statement that, if true, would support the claim that the two exhibitions This Is the Day and The Dirty South showcase the diverse media artists have used to represent the Black experience in the US. The text describes the thematic focus of the two exhibitions: religious and spiritual expressions in the Black community and the connections between visual arts and music in Black culture in the American South between 1920 and 2020. If these exhibits included works created with many different materials and means of artistic expression (such as paint, textiles, sculptural stone, and musical forms), they would display how artists have portrayed and responded to the Black experience in the US as well as the variety of media that these artists have used to do so."}, {"type": "paragraph", "text": "Choice B is incorrect because it focuses on the number of artists whose works were included in the exhibitions, not on the means of expression that these artists have used. Therefore, the statement wouldn’t address the claim that the exhibits showcased the different media artists have used to represent the Black experience in the US. Choice C is incorrect because it focuses on how the works that were included in the exhibitions were sourced, not on the means of expression the artists whose works were featured have used. Therefore, the statement wouldn’t address the claim that the exhibits showcased the different media artists have used to represent the Black experience in the US. Choice D is incorrect. Although the statement focuses on similarities in the themes of the two exhibitions—that is, they both concern the Black experience in the US—it doesn’t mention the media that artists whose works were featured in the exhibitions have used to portray and respond to this experience."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 13, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice best describes data from the graph that support the researchers’ conclusion?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice C is the best answer because it describes data from the graph that support Jan Packer and colleagues’ conclusion about the effect of leave time on the attentiveness of university employees. According to the text, the researchers’ study design included a group of employees who took no leave, a group who took 2–4 days of leave, and a group who took 1–5 weeks of leave. The participants who took leave were tested for attentiveness one week before their leave (the first test administration), one week after their return to work (the second test administration), and two weeks after their return (the third test administration). The participants who took no leave were tested three times at random. The graph shows that at one week after their return to work, participants who took only 2–4 days of leave had an average attentiveness score of between 540 and 600, while participants who took 1–5 weeks of leave had an average score of between 480 and 540. At two weeks after their return to work, those who took only 2–4 days of leave had an average score of between 480 and 540, while those who took 1–5 weeks of leave had an average score of approximately 480. In other words, the graph shows that on both post-leave testing dates, participants with longer leave times had lower average attentiveness scores than those with shorter leave times. Since attentiveness is an indicator of cognitive functioning, these data confirm Packer and colleagues’ conclusion that longer leave times might not confer a greater cognitive benefit than shorter leave times do."}, {"type": "paragraph", "text": "Choice A is incorrect. The graph does show that in the second test administration, participants who took 2– 4 days of leave had higher average attentiveness scores than did those who took no leave and also shows that in the third test administration, those who took no leave had higher average scores than those who took 1–5 weeks of leave. But neither of these findings has a direct bearing on the researchers’ conclusion, which concerns a comparison of participants who took 2–4 days of leave with those who took 1–5 weeks, rather than a comparison of either group with participants who took no leave. Choice B is incorrect. Although the graph does show that in the first test administration, participants who took 2–4 days of leave had lower average attentiveness scores than did those who took 1–5 weeks of leave and those who took no leave, this test administration occurred before any participants went on leave; therefore, these results have no bearing on the researchers’ conclusion about how the amount of leave taken by participants affected their cognitive functioning."}, {"type": "paragraph", "text": "Choice D is incorrect. Although the graph does show that in the second and third test administrations, participants who took 2–4 days of leave had higher average attentiveness scores than did those who took no leave, the researchers’ conclusion is about the effects of short leave compared with the effects of long leave, not the effects of short leave compared with the effects of no leave. These results are therefore irrelevant to the conclusion."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 14, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice most effectively uses data from the graph to complete the text?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice B is the best answer because it describes data from the graph that complete the text’s discussion of lizard species’ use of maximal speed when escaping predators. According to the text, moving at maximal speed (the highest speed possible) requires so much energy that it is not always an effective strategy for animals, even when they are escaping predators. The graph displays data on the average percent of maximal speed used by lizard species while either escaping predators or pursuing prey. The graph categorizes the data for both pursuing and escaping by the number of species using 30%–39% of maximal speed, 40%–49% of maximal speed, 50%–59% of maximal speed, 60%–69% of maximal speed, 70%–79% of maximal speed, 80%–89% of maximal speed, and 90%–100% of maximal speed, respectively. In the graph, there is at least one species in each of the following percent categories for maximal speed while escaping predators: 50%– 59%, 60%–69%, 70%–79%, and 80%–89%. Thus, the data in the graph show that multiple lizard species move at an average of less than 90% of their maximal speed while escaping predation."}, {"type": "paragraph", "text": "Choice A is incorrect because the data in the graph isn’t organized in such a way that a comparison of the percentage of maximal speed used when escaping predation with the percentage used when pursuing prey is possible at the level of individual species. Choice C is incorrect. It is true that in the graph, the percent category with the largest number of species using maximal speed while escaping predators is 90%–100% (8 species total). However, these data don’t complete the text, which is concerned instead with how animals are discouraged from using maximal speed even when escaping predators because of the amount of energy required to use it. Choice D is incorrect because these data from the graph pertain to maximal speed while pursuing prey and therefore don’t complete the text’s discussion of lizard species’ use of maximal speed when escaping predators."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 15, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which finding, if true, would most directly support the researchers’ hypothesis?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice D is the best answer because it presents a finding that, if true, would support the researchers’ hypothesis that TMAO reduces water’s compressibility. The text explains that at great depths in the ocean, extreme pressure compresses the molecular structure of water by destabilizing the hydrogen bonds between adjacent molecules, thereby allowing water to penetrate proteins and harm the associated organisms. However, deep-sea organisms called piezophiles have adapted to live at these depths and previous studies show a positive correlation between the depth at which a piezophile species lives and the species’ level of the compound TMAO. Because this hypothesis links TMAO levels with reduced compressibility of water’s tetrahedral molecular structure, a finding that TMAO helps maintain the hydrogen bonds between water molecules under high pressure would strongly support that hypothesis."}, {"type": "paragraph", "text": "Choice A is incorrect. Although the researchers’ hypothesis suggests a relationship between TMAO and water molecules’ tetrahedral molecular structure, that relationship involves TMAO helping maintain water’s tetrahedral molecular structure under high pressure; as presented in the text, the hypothesis doesn’t contend that water molecules are impervious to, or incapable of being penetrated by, TMAO. Choice B is incorrect because the text discusses how the molecular structure of water, not TMAO, is compressed under extreme pressure and never addresses how TMAO might be affected by such pressure. Choice C is incorrect because the researchers’ hypothesis holds that water under extreme pressure is more resistant, not less, to being compressed when TMAO concentrations are higher. Moreover, the positive correlation mentioned in the text is between TMAO concentrations and the depths at which piezophiles live, not between concentrations of TMAO and the rate at which water’s molecular structure compresses as pressure increases."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 16, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice most logically completes the text?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice D is the best answer because it most logically completes the text’s discussion of the Cretaceous pterosaur Tupandactylus navigans. The text first describes what paleontologists initially speculated to be true of T. navigans based on observing only fossilized skulls of the pterosaur rather than complete skeletons—namely, that T. navigans had an oversized head crest and that, like other pterosaurs, its main mode of movement must have been flight. The text goes on to describe what researcher Victor Beccari and his team concluded based on studying a nearly complete fossilized skeleton of T. navigans, which provided additional information that fossilized skulls alone could not. Beccari and colleagues determined that T. navigans had long hind legs, short wings, and an unusually long neck, in addition to the oversized head crest previously observed by paleontologists. Taken together, these characteristics would have made sustained flight difficult and upright walking comfortable, which would make T. navigans different from other pterosaurs that moved mainly through flight. Thus, Beccari and colleagues suggest that previously held speculations of paleontologists are inaccurate: that instead of moving mainly through powered flight, T. navigans likely flew for shorter distances and spent more time walking than researchers previously thought."}, {"type": "paragraph", "text": "Choice A is incorrect because Beccari and his team determined, based on their examination of a nearly complete skeleton, that T. navigans would have found “sustained flight difficult,” which would differentiate it from most other pterosaurs that moved mainly through flight. Therefore, Beccari’s team would not suggest that T. navigans flew for longer distances than did other pterosaur species with large head crests. Choice B is incorrect because the fossilized skeleton studied by Beccari and colleagues was notable for its short wings, and because no indication in the text is made that other pterosaurs were thought by paleontologists to be comfortable walking. Therefore, Beccari’s team would not suggest that T. navigans had longer wings than other pterosaur species considered to have been comfortable walking. Choice C is incorrect because the text indicates that Beccari and his team agree with the paleontologists mentioned earlier in the text that T. navigans had a large-crested head. Therefore, Beccari’s team would not suggest that T. navigans had a smaller head than researchers previously expected."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 17, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice most logically completes the text?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice B is the best answer because it most logically completes the text’s discussion of a study involving ethical consumers. According to the text, ethical consumers are people who strive to purchase goods and services with positive or neutral effects on society and the environment. The text explains that consumer psychologists believe these consumers are more likely to purchase a product if its effects correspond better to their values. The text then introduces a study of ethical consumers’ attitudes toward a specific mobile phone, indicating that participants in their twenties had a less positive attitude toward the phone’s effects on society and the environment than participants in other age groups did. The text indicates that readers should assume there are no other differences between the participants in their twenties and those in other age groups. If the consumer psychologists’ theory is correct, as the text proposes, then the study’s finding suggests that ethical consumers in their twenties are less likely to purchase the phone than ethical consumers in other age groups are."}, {"type": "paragraph", "text": "Choice A is incorrect because the text mentions only the mobile phone used in the study and therefore provides no basis to compare participants’ attitudes toward that phone with their attitudes toward any other phone. Choice C is incorrect because the study’s finding suggests the contrary. The text indicates that study participants in their twenties had a less positive attitude toward the phone’s social and environmental effects than study participants in other age groups did. If the consumer psychologists’ theory is true, as the text proposes, then the study’s finding suggests that ethical consumers in their twenties are meaningfully less likely to purchase the phone than ethical consumers in other age groups are. Choice D is incorrect because there’s nothing in the text to suggest that ethical consumers in their twenties are more likely than ethical consumers in other age groups to consider a phone’s social and ecological effects when deciding whether to purchase it. Rather, the text’s discussion of people who identify as ethical consumers suggests that they all consider the social and ecological effects of products, regardless of age."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 18, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text so that it conforms to the conventions of Standard English?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice A is the best answer. The convention being tested is the use of verb forms within a sentence. The nonfinite past participle “created” is correctly used to form a supplementary element that modifies the noun phrase “the saloon,” identifying who established the Boston Saloon."}, {"type": "paragraph", "text": "Choice B is incorrect because it results in an ungrammatical sentence. The finite present tense verb “creates” can’t be used in this way to form a supplementary element to modify the noun phrase “the saloon.” Choice C is incorrect because it results in an ungrammatical sentence. The nonfinite present participle “creating” can’t be used in this way to form a supplementary element to modify the noun phrase “the saloon.” Choice D is incorrect because it results in an ungrammatical sentence. The finite present tense verb “create” can’t be used in this way to form a supplementary element to modify the noun phrase “the saloon.”"}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Standard English Conventions'), 'medium', 'source', 'approved', 19, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text so that it conforms to the conventions of Standard English?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice C is the best answer. The convention being tested is punctuation use between a verb and an object. No punctuation is needed between the verb “popularized” and its object “the use of Jamaican Creole.” The object helps complete the idea of the verb—in this case, it explains what Louise Bennett popularized—and any punctuation between the two results in an ungrammatical sentence."}, {"type": "paragraph", "text": "Choice A is incorrect because no punctuation is needed between the verb and its object. Choice B is incorrect because no punctuation is needed between the verb and its object. Choice D is incorrect because no punctuation is needed between the verb and its object."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Standard English Conventions'), 'medium', 'source', 'approved', 20, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text so that it conforms to the conventions of Standard English?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice D is the best answer. The convention being tested is subject-verb agreement. The singular verb “creates” agrees in number with the singular subject “technique.”"}, {"type": "paragraph", "text": "Choice A is incorrect because the plural verb “create” doesn’t agree in number with the singular subject “technique.” Choice B is incorrect because the plural verb “are creating” doesn’t agree in number with the singular subject “technique.”"}, {"type": "paragraph", "text": "Choice C is incorrect because the plural verb “have created” doesn’t agree in number with the singular subject “technique.”"}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Standard English Conventions'), 'medium', 'source', 'approved', 21, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text so that it conforms to the conventions of Standard English?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice D is the best answer. The convention being tested is end-of-sentence punctuation. This choice correctly uses a period to punctuate a declarative sentence that asks an indirect question (“Researchers Amit Kumar and Nicholas Epley investigated how people perceive acts of kindness”)."}, {"type": "paragraph", "text": "Choice A is incorrect. The structure of the sentence requires a declarative clause at the end of the sentence that states what Kumar and Epley did, not an interrogative clause that asks a direct question, such as “how do people perceive acts of kindness.” Choice B is incorrect. The structure of the sentence requires a declarative clause at the end of the sentence that states what Kumar and Epley did, not an interrogative clause that asks a direct question, such as “how do people perceive acts of kindness?” Choice C is incorrect. It’s unconventional to use a question mark in this way to punctuate a declarative sentence that asks an indirect question, such as “Researchers…kindness.”"}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Standard English Conventions'), 'medium', 'source', 'approved', 22, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text so that it conforms to the conventions of Standard English?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice D is the best answer. The convention being tested is subject-verb agreement. The plural verb “reveal” agrees in number with the plural subject “objects.”"}, {"type": "paragraph", "text": "Choice A is incorrect because the singular verb “was revealing” doesn’t agree in number with the plural subject “objects.” Choice B is incorrect because the singular verb “has revealed” doesn’t agree in number with the plural subject “objects.” Choice C is incorrect because the singular verb “reveals” doesn’t agree in number with the plural subject “objects.”"}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Standard English Conventions'), 'medium', 'source', 'approved', 23, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text so that it conforms to the conventions of Standard English?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice C is the best answer. The convention being tested is punctuation between sentences. In this choice, the period is used to correctly mark the boundary between one sentence (“Jamaican…microsculptures”) and another (“Creations… strands”). The noun phrase beginning with “creations” modifies the subject of the next sentence, “Wigan’s sculptures.”"}, {"type": "paragraph", "text": "Choice A is incorrect because it results in a run-on sentence. The sentences (“Jamaican…microsculptures” and “Creations…strands”) are fused without punctuation and/or a conjunction. Choice B is incorrect because it results in a comma splice. A comma can’t be used in this way to mark the boundary between sentences. Choice D is incorrect. Without a comma preceding it, the conjunction “and” can’t be used in this way to join sentences."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Standard English Conventions'), 'medium', 'source', 'approved', 24, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text so that it conforms to the conventions of Standard English?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice B is the best answer. The convention being tested is punctuation use between sentences. In this choice, the period is used to correctly mark the boundary between one sentence (“A ray...works”) and another (“Because...image”)."}, {"type": "paragraph", "text": "Choice A is incorrect because it results in a run-on sentence. The two sentences (“A ray…works” and “Because…image”) are fused without punctuation and/or a conjunction. Choice C is incorrect because it results in a comma splice. A comma can’t be used in this way to mark the boundary between sentences. Choice D is incorrect because it results in a comma splice. Since the contraction “it’s” creates a main clause, the comma after “single ray” can’t be used in this way to mark the boundary between two main clauses (“it’s...ray” and “all light…image”)."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Standard English Conventions'), 'medium', 'source', 'approved', 25, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text with the most logical transition?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice D is the best answer. “Instead” logically signals that the idea in this sentence—that researchers should use the word “lyfe”—is an alternative to the idea mentioned in the previous sentence (scientists’ use of the word “life”)."}, {"type": "paragraph", "text": "Choice A is incorrect because “previously” illogically signals that the idea in this sentence occurs before the action in the first sentence. Instead, the use of “lyfe” is an alternative to the previously mentioned use of “life.” Choice B is incorrect because “regardless” illogically signals that the idea in this sentence is true despite the information in the first sentence. Instead, the use of “lyfe” is an alternative to the previously mentioned use of “life.” Choice C is incorrect because “there” illogically signals that the idea in this sentence occurs in a place mentioned in the previous sentence. Instead, the use of “lyfe” is an alternative to the previously mentioned use of “life.”"}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Expression of Ideas'), 'medium', 'source', 'approved', 26, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text with the most logical transition?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice D is the best answer. “Today” logically signals that the information in the sentence—that the museum is able to display close to 30% of its collection— is true of the Art Institute of Chicago as it exists in the present day after the previously mentioned unveiling of the massive new gallery in 2009."}, {"type": "paragraph", "text": "Choice A is incorrect because “additionally” illogically signals that the information in the sentence is merely an additional fact related to the information about the museum before the new gallery opened. Instead, the sentence is about the museum in the present day after the new gallery opened. Choice B is incorrect because “for example” illogically signals that the information in the sentence exemplifies the previous information about the museum before the new gallery opened. Instead, the sentence is about the museum in the present day after the new gallery opened. Choice C is incorrect because “nevertheless” illogically signals that the information in the sentence is true despite the previous information about the museum before the new gallery opened. Instead, the sentence is about the museum in the present day after the new gallery opened."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Expression of Ideas'), 'medium', 'source', 'approved', 27, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text with the most logical transition?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice C is the best answer. “On the other hand” logically signals that the information in the sentence—that the snowpack at higher elevations in the Chuska Mountains was deepest in mid-March—contrasts with the previous information about the snowpack at lower elevations being deepest in early March."}, {"type": "paragraph", "text": "Choice A is incorrect because “in other words” illogically signals that information in the sentence is merely a paraphrase or restatement of the previous information about the snowpack at lower elevations. Instead, the information about the snowpack at higher elevations contrasts with that information. Choice B is incorrect because “for instance” illogically signals that the information in the sentence exemplifies the previous information about the snowpack at lower elevations. Instead, the information about the snowpack at higher elevations contrasts with that information. Choice D is incorrect because “in summary” illogically signals that the information in the sentence summarizes the previous information about the snowpack at lower elevations. Instead, the information about the snowpack at higher elevations contrasts with that information."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Expression of Ideas'), 'medium', 'source', 'approved', 28, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text with the most logical transition?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice C is the best answer. “In addition” logically signals that the claim in this sentence—that the Inca of South America may have used quipus to record more complex information—is an additional point related to the previous statement about the Inca using quipus to record countable information."}, {"type": "paragraph", "text": "Choice A is incorrect because “as a result” illogically signals that the claim in the sentence is a consequence or result of the previous statement about the Incas using quipus to record countable information. Instead, the possibility that the Inca used quipus to record more complex information is an additional point about how the quipus were used. Choice B is incorrect because “in other words” illogically signals that the claim in the sentence is merely a paraphrase or restatement of the previous statement about the Incas using quipus to record countable information. Instead, the possibility that the Inca used quipus to record more complex information is an additional point about how the quipus were used. Choice D is incorrect because “for example” illogically signals that the claim in the sentence exemplifies the previous statement about the Incas using quipus to record countable information. Instead, the possibility that the Inca used quipus to record more complex information is an additional point about how the quipus were used."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Expression of Ideas'), 'medium', 'source', 'approved', 29, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text with the most logical transition?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice B is the best answer. “Then” signals that this sentence’s claim about Darwin and Wallace follows logically from the previous information. In other words, both scientists independently arriving at the theory of natural selection was, arguably, an expected outcome of the circumstances mentioned in the previous sentence."}, {"type": "paragraph", "text": "Choice A is incorrect because “however” illogically signals that the claim in this sentence contrasts with the previous information about the ideas circulating among British scientists in the 1800s. Instead, this claim follows logically from that information. Choice C is incorrect because “moreover” illogically signals that the claim in this sentence merely adds to the previous information about the ideas circulating among British scientists in the 1800s. Instead, this claim follows logically from that information. Choice D is incorrect because “for example” illogically signals that this sentence provides an example supporting the previous information about the ideas circulating among British scientists in the 1800s. Instead, it presents a claim that follows logically from that information."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Expression of Ideas'), 'medium', 'source', 'approved', 30, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice most effectively uses relevant information from the notes to accomplish this goal?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice A is the best answer. The sentence emphasizes Janaki Ammal’s achievement, explaining that she successfully created sugarcane hybrids that are well suited to India’s climate by crossbreeding an imported sugarcane species with grasses native to India."}, {"type": "paragraph", "text": "Choice B is incorrect. The sentence emphasizes the goal of the Imperial Sugar Cane Institute in the 1930s; it doesn’t emphasize Janaki Ammal’s achievement."}, {"type": "paragraph", "text": "Choice C is incorrect. While the sentence mentions Ammal, it doesn’t emphasize her achievement of successfully creating sugarcane hybrids. Choice D is incorrect. While the sentence mentions the achievement of crossbreeding imported sugarcane species with grasses native to India, it doesn’t emphasize the achievement as belonging to Janaki Ammal."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 31, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice most effectively uses relevant information from the notes to accomplish this goal?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice B is the best answer. The sentence emphasizes a similarity between the sculptures Recognition and Students Aspire, noting that both sculptures show African American figures in poses that symbolize supportive relationships."}, {"type": "paragraph", "text": "Choice A is incorrect. The sentence describes one of the sculptures; it doesn’t emphasize a similarity between the two sculptures. Choice C is incorrect. The sentence specifies the different years the sculptures were completed in; it doesn’t emphasize a similarity between the two sculptures. Choice D is incorrect. The sentence emphasizes a difference between the two sculptures, noting that the figures in the sculptures have different feature definition; it doesn’t emphasize a similarity between the two sculptures."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 32, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice most effectively uses relevant information from the notes to accomplish this goal?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice C is the best answer. The sentence makes a generalization about the materials used in dhow replicas, noting that while some modern materials are used, most of the materials are traditional."}, {"type": "paragraph", "text": "Choice A is incorrect. The sentence provides an example of a traditional material used in ancient dhows; it doesn’t indicate that the material is used in dhow replicas or make any other generalization about materials used in those replicas."}, {"type": "paragraph", "text": "Choice B is incorrect. The sentence explains what an ancient dhow was; it doesn’t make a generalization about materials used to make dhow replicas. Choice D is incorrect. The sentence introduces the construction of dhow replicas to an audience unfamiliar with the vessel; it doesn’t make a generalization about the materials used in those replicas."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 33, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text with the most logical and precise word or phrase?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice C is the best answer because it most logically completes the text’s discussion of Ester Hernandez’s art. In this context, “featured” means shown prominently. The text focuses on where Hernandez’s works have been and continue to be displayed, explaining that her early works, which consisted of murals, could be viewed in outdoor spaces in San Francisco. The central contrast developed in the text is between where her early works could be viewed and where her works can be viewed now, which is in museums across the United States and around the world. The context therefore supports the idea that Hernandez’s works are now shown, or featured, in museums globally."}, {"type": "paragraph", "text": "Choice A is incorrect because in this context “invented” would mean created something for the first time, which isn’t supported since the text doesn’t discuss where Hernandez creates her works or whether they’re original or innovative."}, {"type": "paragraph", "text": "Choice B is incorrect because “adjusted” in this context would mean adapted. Although the text mentions that many of Hernandez’s early works were outdoor murals and thus it may be reasonable to infer that Hernandez altered her approach to creating art so that her works could be displayed in indoor venues instead, the text makes no mention of how Hernandez’s works might have been adapted for such venues. The text focuses on where Hernandez’s works have been and continue to be displayed, not on how she or anyone else may have adapted, or adjusted, her works. Choice D is incorrect because “recommended” in this context would mean endorsed or put forth as a suggestion for something that is worth seeing. Although it may be reasonable to say that in choosing to display certain works, museum curators believe such works are worth seeing, the text doesn’t discuss the reasons why museums display Hernandez’s works. Instead, the text mainly develops a contrast between where Hernandez’s early works could once be viewed and where her work can be viewed now."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Craft and Structure'), 'medium', 'source', 'approved', 1, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text with the most logical and precise word or phrase?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice D is the best answer because it most logically completes the text’s discussion of Carmen Lomas Garza’s artistic process. In this context, “inspired by” means influenced by or motivated by. The text refers to how, regardless of the scale of the work, Garza uses her memories of Texas and details from California to create her art. If Garza is basing her work on her direct experiences, then they play a part in her artistic process. This context thus suggests that Garza’s art is inspired by the experiences of her childhood in Texas and her current life in California."}, {"type": "paragraph", "text": "Choice A is incorrect because it wouldn’t make logical sense to indicate that Garza is “complimented by”—or praised by—something inanimate such as direct experience. Choice B is incorrect because describing Garza as “uncertain about”—or unsure or doubtful of—direct experience would suggest that she had misgivings about it. If Garza were unsure of her experiences, that would suggest that she couldn’t recall them, and Garza wouldn’t be able to represent direct experience in her art if she were uncertain of the memories or details. Choice C is incorrect because describing Garza as “unbothered by”—or uninterested in—her experience would imply the opposite of what the text suggests about Garza’s artistic process. The text indicates that Garza’s art comes from memories of her childhood in Texas and details of her surroundings in California."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Craft and Structure'), 'medium', 'source', 'approved', 2, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text with the most logical and precise word or phrase?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice C is the best answer because it most logically completes the text’s discussion of Bastos’s study of a wild kea parrot. In this context, “accidental” means unplanned or unintentional. The text first describes Bastos’s study, which concerns a kea that is observed using small stones to preen its feathers. The text then mentions colleagues who are skeptical (that is, they have doubt) about Bastos’s findings, and finally describes how Bastos and her team responded to the skepticism of those colleagues. Given that the colleagues mentioned in the text expressed skepticism regarding Bastos’s findings, the best answer choice must be one that completes the text in a manner such that the skeptics’ opinion regarding the kea’s use of stones disagrees with that held by Bastos and her team. Since Bastos and her team showed that the kea’s use of stones was deliberate (that is, intentional), the skeptics’ opinion in this context must be that the kea’s use of stones was unintentional, or accidental."}, {"type": "paragraph", "text": "Choice A is incorrect because the best answer choice is one that portrays skepticism, or doubt, of Bastos’s claim that the kea’s usage of stones was deliberate, or intentional. If the skeptics found the kea’s usage of stones “intriguing,” or fascinating, this would not be at odds with the position of Bastos and her team; in fact, it is reasonable to believe that someone who agreed that the kea’s stone usage was deliberate would also find it intriguing. Choice B is incorrect because if the skeptics believed that the kea’s usage of small stones was “obvious,” or evident, this would not be contrary to the observation of Bastos and her team that the kea’s usage of stones was deliberate: in fact, these opinions would be consistent with each other. Choice D is incorrect because if the skeptics believed that the kea’s usage of small stones was “observable,” or visible, this would not conflict with the claim of Bastos and her team that the kea’s usage of stones was deliberate: instead, these positions would agree."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Craft and Structure'), 'medium', 'source', 'approved', 3, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text with the most logical and precise word or phrase?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice B is the best answer because it most logically completes the text’s discussion of the Kelmscott Press’s books. In this context, “manifest in” means evident or apparent from. The text states that the Kelmscott Press, which was cofounded by William Morris, produced its books using preindustrial methods. The text notes the similarity between those methods, which include the use of handmade materials and intricate ornamentation, and methods used in the creation of medieval manuscripts. This context suggests that Morris’s repudiation of industrialization is apparent from, or manifest in, the methods and materials his company employed."}, {"type": "paragraph", "text": "Choice A is incorrect because there is nothing in the text to suggest that Morris’s repudiation of industrialization is “insensible to,” or unaware of or lacking perception of, the use of handmade materials and intricate ornamentation in the production of the Kelmscott editions. Instead, the text suggests that the methods and materials used to produce the Kelmscott editions are evidence of Morris’s repudiation of industrialization. Choice C is incorrect because it would not make sense to say that Morris’s repudiation of industrialization was “scrutinized by,” or examined closely by, the Kelmscott editions’ use of handmade materials and intricate ornamentation. Although creating the Kelmscott editions may have involved examining the books closely, the text does not mention this aspect of Morris’s work, and in any case, the action of using certain materials to create those editions cannot scrutinize Morris’s attitude toward industrialization."}, {"type": "paragraph", "text": "Choice D is incorrect because the text gives no indication that Morris’s repudiation of industrialization is “complicated by,” or made more complex or difficult by, the Kelmscott Press’s use of preindustrial methods and handcrafted elements to produce books. Instead, the text presents those methods as exemplifying Morris’s repudiation of industrialization."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Craft and Structure'), 'medium', 'source', 'approved', 4, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text with the most logical and precise word or phrase?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice B is the best answer because it most logically completes the text’s discussion of Mary Engle Pennington and Stephanie Kwolek. In this context, “tentative” means unsettled or not definite. The text indicates a contrast between Pennington and Kwolek in terms of their memorability (“place in our historical memory”) and states that Kwolek “will long be remembered” for her invention of Kevlar material. This context suggests that although Pennington had an impact on society, she may be less likely than Kwolek to be remembered for a very long time—in other words, that her memorability may be more tentative, or less definite, than Kwolek’s."}, {"type": "paragraph", "text": "Choice A is incorrect because the text establishes a contrast between Pennington and Kwolek in terms of their “place in our historical memory” for their achievements, and the statement that Kwolek “will be long remembered” while Pennington’s memorability may be more “permanent,” or enduring, wouldn’t supply a contrast; it would instead suggest that both people will remain memorable. Choice C is incorrect because the text establishes a contrast between Pennington and Kwolek in terms of their memorability, suggesting that Pennington is less likely than Kwolek to be “long remembered,” but doesn’t address how “warranted,” or based on good reason, each person’s “place in our historical memory” is. In fact, the text suggests that both Pennington and Kwolek had significant achievements, even if one may be more memorable. Choice D is incorrect because the text establishes a contrast between Pennington and Kwolek in terms of their “place in our historical memory” for their achievements, and the statement that Kwolek “will be long remembered” while Pennington’s memorability may be more “prominent,” or widely known, wouldn’t supply a contrast; it would instead suggest that both people are very memorable."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Craft and Structure'), 'medium', 'source', 'approved', 5, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice best states the main purpose of the text?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice C is the best answer because it most accurately describes the main purpose of the text, which is to portray Francie’s determination to reach her goal of reading all the books in the world. The text indicates that to achieve this aim, Francie works systematically and persistently: she reads all the books in the library in alphabetical order and devotes much time and effort to the project, finishing one book per day over a long period of time. The text then suggests that even though she progresses slowly (“she was still in the B’s”) and that she struggled with some books (“some of the B’s had been hard going”), she doesn’t give up because she thinks of herself as “a reader.” These details show Francie’s resolve."}, {"type": "paragraph", "text": "Choice A is incorrect. Although the text mentions several topics (bees and buffaloes, Bermuda vacations, and Byzantine architecture) that Francie has read about, it doesn’t indicate that any of these topics are unusual or that she especially enjoyed reading about one of these topics in particular. If anything, the text suggests that she may have found some of these topics to be dull, saying that she even read the “dry ones”— that is, the boring books—and that some of the books were “hard going,” meaning they were difficult to get through."}, {"type": "paragraph", "text": "Choice B is incorrect because the text doesn’t discuss Francie’s involvement in other activities, only her dedication to reading. Although it’s possible that Francie dedicates herself to reading because she prefers it to other activities, the text doesn’t indicate whether this is the case. Choice D is incorrect. Although the text mentions one author (Abbott) whose book Francie has read as well as several topics (bees and buffaloes, Bermuda vacations, and Byzantine architecture) she has encountered, the text doesn’t say whether Francie admires any of the books she’s read so far. Instead, the text focuses on the time and effort she devotes to reaching her goal of reading all the books in the world—even ones she doesn’t enjoy."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Craft and Structure'), 'medium', 'source', 'approved', 6, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice best states the main purpose of the text?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice D is the best answer because it most accurately states the main purpose of the text, which is to describe an experiment whose results cast doubt on an established hypothesis. The text begins by noting that researchers have long believed that woolly mammoths were hunted to extinction in North America by humans using spears with Clovis points. The text then describes an experiment conducted by an anthropologist to test this hypothesis. According to the text, the results of the experiment led the anthropologist to conclude that hunters using spears with Clovis points likely weren’t the primary cause of the extinction. The anthropologist’s results cast doubt on the long-held hypothesis presented at the beginning of the text and suggest that woolly mammoths may have become extinct in North America due to some other cause."}, {"type": "paragraph", "text": "Choice A is incorrect because there’s nothing in the text to suggest that researchers have been involved in an ongoing debate. On the contrary, the text suggests that most researchers agree on the cause of the woolly mammoth’s extinction in North America. Choice B is incorrect because the text never mentions any advantages or disadvantages of the method used in the experiment, focusing instead on the results achieved using that method. Choice C is incorrect because the text addresses only one hypothesis, that mammoths were hunted to extinction in North America by humans using spears with Clovis points. Rather than present a competing hypothesis, the text explains how one anthropologist designed an experiment to test this long-held hypothesis."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Craft and Structure'), 'medium', 'source', 'approved', 7, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, 0, '{"blocks": [{"type": "paragraph", "text": "Which choice best describes the function of the underlined portion?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice C is the best answer because it most effectively describes the function of the underlined portion. The text discusses the long-standing misconception that people in medieval Europe were uninterested in cleanliness and hygiene. As evidence that this idea is false, the text cites historian Eleanor Janega’s assertion that in medieval Europe, towns usually had at least one bathhouse, where people could take immersion baths or steam baths for a fee. The underlined portion then notes that mainly town dwellers had access to these bathhouses. The remainder of the text explains that those who lacked such access were nonetheless able to bathe in outdoor waterways or take sponge baths at home. Therefore, the underlined portion concedes that some people in medieval Europe lacked access to public bathhouses."}, {"type": "paragraph", "text": "Choice A is incorrect. The underlined portion establishes that amenities such as steam baths were mainly available to town dwellers, which suggests in turn that steam baths were largely unavailable to people in rural areas. Thus, the distinction made by the underlined portion is not between the popularity of steam baths in towns versus their lack of popularity in rural areas but instead between their presence in towns and absence in rural areas. Choice B is incorrect. Although the text does explain that recent historians have disproved the idea that medieval Europeans rarely bathed, it doesn’t attribute that misconception to earlier historians of medieval Europe or suggest that their research was subject to limitations. Moreover, the underlined portion addresses a limitation of life in medieval Europe, not of historical research. Choice D is incorrect because the underlined portion doesn’t address why historian Eleanor Janega decided to study the popularity of public bathhouses in medieval Europe—nor does any portion of the text. The text mentions Janega in passing, but it doesn’t go into detail about why she decided to study the popularity of public bathhouses in medieval Europe."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Craft and Structure'), 'medium', 'source', 'approved', 8, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, 0, '{"blocks": [{"type": "paragraph", "text": "Which choice best describes the function of the underlined portion in the text as a whole?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice C is the best answer because it most accurately describes how the underlined portion functions in the text as a whole. The text begins by mentioning scholarly accounts of the Chicano movement, which the underlined portion describes as tending “to focus on the most militant, outspoken figures in the movement,” making the movement as a whole seem uniformly radical. The text then indicates that the work of geographer Juan Herrera shows that focusing less on such militant figures and instead paying more attention to manifestations of the Chicano movement in less widely known neighborhood institutions and projects would reveal that the movement’s participants embraced a range of political orientations and approaches. Thus, the underlined portion describes a common approach to studying the Chicano movement that, according to the text, obscures the ideological diversity of the movement’s participants."}, {"type": "paragraph", "text": "Choice A is incorrect. Though the underlined portion does present a trend in scholarship on the Chicano movement, the text does not indicate that other scholars have reevaluated their methods in light of Herrera’s work. It only indicates that Herrera’s work suggests that the work of those other scholars does not provide a complete picture of the Chicano movement. Choice B is incorrect. Though the underlined portion does identify an aspect of the Chicano movement that the text indicates has been overemphasized, the text does not discuss the political orientations of the scholars whose work is mentioned in the text. Choice D is incorrect. Though the underlined portion does summarize the conventional method for analyzing the Chicano movement, the rest of the text does not address the effectiveness of “comparatively low-profile neighborhood institutions and projects.” Instead, the text suggests that those projects were led by people with a variety of approaches to community activism."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Craft and Structure'), 'medium', 'source', 'approved', 9, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice best states the main idea of the text?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice C is the best answer because it accurately states the main idea of the text. According to the text, contrary to what some might expect, foreign investment is typically lower in developing countries whose economies are more dependent on natural-resource extraction. The text explains that high reliance on natural- resource extraction can subject a developing country to economic shocks that can destabilize the local currency and introduce economic uncertainty that tends to keep investors away. In other words, although we may think otherwise, foreign investors are less willing to invest in projects in developing countries whose economies are heavily dependent on natural-resource extraction because those economies tend to exhibit instability that investors want to avoid."}, {"type": "paragraph", "text": "Choice A is incorrect. The text does indicate that foreign investment is typically lower in developing countries whose economies are more dependent on natural-resource extraction; the text further indicates that natural-resource extraction requires substantial initial investments (to acquire things like required technologies) for which there are fewer investors willing to participate at this stage than one might think. But the text does not implicate the cost of these initial investments as a reason why foreign investment is less widely available than some might think. Choice B is incorrect. The text indicates that greater dependence on natural-resource extraction makes a developing country less appealing to foreign investors because of associated economic instability. Rather than arguing that the goal of developing countries is to become less dependent on foreign investment, as the phrasing of choice B suggests, the text focuses only on why foreign investors become less involved with such countries, which suggests that more investment would be preferable. Choice D is incorrect. Although the text indicates that natural-resource extraction requires substantial initial investments (to acquire things like required technologies) and that there are fewer likely investors willing to participate at this stage than one might think, the text does not address what investors are likely to do over time as the industry stabilizes itself."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 10, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "It can most reasonably be inferred from the text that the finding about the microorganism community composition was important for which reason?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice C is the best answer because it accurately describes why the finding about the microorganism community composition was important. The text describes an experiment by Eva Kaštovská and her team in which they collected plant-soil cores at one elevation and transplanted them to sites at a lower elevation, where the mean air temperature was warmer. Kaštovská and her team observed that microorganism-mediated nutrient cycling was accelerated in the transplanted cores and that “crucially, microorganism community composition was unchanged,” which allowed the team to attribute the acceleration to changes in microorganism activity brought about by the difference in temperature. This strongly implies that the team wouldn’t have been able to make that attribution otherwise, meaning that a change in microorganism composition represented another possible explanation for the acceleration that had to be ruled out."}, {"type": "paragraph", "text": "Choice A is incorrect. Although the text says microorganism-mediated cycling of soil nutrients increased in the transplanted cores, this is unrelated to what’s important about the finding that the microorganism composition didn’t change— that it allowed the team to attribute the change in activity solely to the change in temperature. Choice B is incorrect. Although the text compares activity in one core at two different elevations, the text doesn’t address changes in activity at various elevations over time. Choice D is incorrect. Although different microorganisms likely exhibit different levels of activity, the text indicates that there was no change in microorganism composition, and there is nothing in the text about different microorganisms having different activity levels."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 11, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Based on the text, Huang, Seager, and colleagues would most likely agree with which statement about atmospheric NH3?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice C is the best answer because it states a conclusion the researchers likely agree with, given the details in the text. The text explains that a biosignature gas is a gas that can be used as an indicator that a planet harbors some form of life and some astronomers have proposed that NH₃ could serve as a biosignature gas. The researchers evaluating this claim found that the atmosphere of rocky planets would be unlikely to reach “detectably high levels” of NH₃ without biological activity, which would support the proposal of NH₃ serving as a biosignature gas. However, the text also states that mini-Neptune planets can produce NH₃ in the absence of biological activity. Thus, the text is structured to lead to the conclusion that detectable levels of NH₃ in the atmospheres of rocky planets could constitute a biosignature, but that is not the case for detectable levels of the gas in the atmospheres of mini-Neptune planets."}, {"type": "paragraph", "text": "Choice A is incorrect because the text indicates that biological activity likely accounts for detectable levels of NH₃ in the atmospheres of rocky planets but mini-Neptune planets can have detectable levels of NH₃ in their atmospheres in the absence of biological activity. Therefore, both rocky planets and mini- Neptune planets can have detectable levels of atmospheric NH₃. Choice B is incorrect because the text states that for NH₃ to reach detectable levels in the atmospheres of rocky planets likely means they harbor biological activity, meaning that rocky planets with detectable NH₃ usually harbor biological activity. However, that does not entail that every rocky planet with biological activity will have detectable levels of NH₃ in their atmospheres. Choice D is incorrect because the text claims only that some astronomers have proposed using NH₃ as a biosignature gas without mentioning a minimum concentration of atmospheric NH₃ that must be met for it to function as a biosignature gas."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 12, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice most effectively uses data from the graph to complete the text?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice C is the best answer because it most effectively uses data from the graph to complete the statement about the US national park with the highest number of recreation visits during a three-month period. The line graph shows the number of recreation visits to four US national parks for the months of June, July, and August 2021. According to the graph, the number of recreation visits to Yellowstone National Park in June was approximately 940,000; in July, the number of visits was approximately 1,080,000; and in August, the number of visits was approximately 920,000. In all three months, the number of visits to Yellowstone was higher than the number of visits to any other park in each month."}, {"type": "paragraph", "text": "Choice A is incorrect. According to the graph, the number of recreation visits to Zion National Park was approximately 680,000 in June, about 580,000 in July, and about 470,000 in August, each of which is lower than the number of visits to Yellowstone in the same months. Choice B is incorrect. According to the graph, the number of recreation visits to Rocky Mountain National Park was approximately 670,000 in June, about 900,000 in July, and about 750,000 in August, each of which is lower than the number of visits to Yellowstone in the same months. Choice D is incorrect. According to the graph, the number of recreation visits to Grand Canyon National Park was approximately 540,000 in June, about 560,000 in July, and about 430,000 in August, each of which is lower than the total visits to Yellowstone in the same months."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 13, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which quotation from “Lines Written in Early Spring” most effectively illustrates the claim?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice D is the best answer because it most effectively illustrates the claim that the speaker has contradictory feelings while experiencing the sights and sounds of spring. This quotation indicates that the speaker is reclined in a grove listening to a thousand sounds. Even though the speaker is in a “sweet mood” and thinking “pleasant thoughts,” those pleasant thoughts also bring to mind “sad thoughts.” In other words, these lines illustrate the claim that the speaker is having contradictory thoughts while immersed in the sights and sounds of spring."}, {"type": "paragraph", "text": "Choice A is incorrect. Although this quotation refers to several flowers (primroses and periwinkles) and indicates that the speaker is in a “bower,” or shady spot among the trees—details which suggest that the speaker is experiencing the sights of spring—it doesn’t suggest that the speaker is having contradictory feelings, only that the speaker believes that the flowers are experiencing enjoyment. Choice B is incorrect. Although this quotation focuses on the sights of spring—namely, new leaves on nearby trees appear to be opening up (“The budding twigs spread out their fan”) to feel the breeze—the quotation doesn’t suggest that the speaker feels conflicted about this: the statement “And I must think, do all I can” suggests the speaker’s determination to attribute feelings of pleasure to the trees, not that the speaker is experiencing contradictory feelings."}, {"type": "paragraph", "text": "Choice C is incorrect. Although this quotation indicates that the speaker isn’t certain what the birds are thinking (“Their thoughts I cannot measure”), there’s nothing to suggest that the speaker is experiencing contradictory feelings. Rather, the quotation suggests that although the speaker is uncertain about the birds’ feelings, the speaker believes that the birds’ movements likely suggest their pleasure."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 14, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice most effectively uses data from the table to complete the statement?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice D is the best answer because it most effectively uses data from the table to complete the statement comparing the mean ratings for two different groups of participants in a study. The text explains that a research team evaluated the study’s participants using various measures in order to learn whether there might be a medical benefit to telling patients they’re receiving a placebo. The table shows the team’s mean ratings for participants after 21 days for three of the measures: global improvement, symptom severity reduction, and quality of life improvement. According to the table, the mean ratings were higher for all three measures for participants aware of taking a placebo than for participants in the control group. Given that higher ratings indicate greater well-being, as the text states, the mean ratings in the table indicate greater overall well-being for participants aware of taking a placebo than for participants in the control group."}, {"type": "paragraph", "text": "Choice A is incorrect because the table doesn’t include data about individual participants; rather, it presents means, or mathematical averages, of ratings. For this reason, no conclusions can be drawn from data in the table about the extent to which well-being may have varied from participant to participant. Choice B is incorrect because according to the table, the mean ratings for participants aware of taking a placebo were higher for all three measures than for participants in the control group, not lower for two of the measures. Choice C is incorrect because it cites data from the table related to participants in the control group, not to participants aware of taking a placebo. Additionally, the mean ratings in the table for participants aware of taking a placebo are higher for all three measures than for participants in the control group. Given that higher ratings indicate greater well-being, as the text states, the ratings in the table for participants aware of taking a placebo indicate greater well-being for these participants in all three measures."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 15, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which finding, if true, would most directly support the idea advanced by Gil de Zúñiga and Diehl?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice B is the best answer because it presents a finding that, if true, would most directly support the idea advanced by Homero Gil de Zúñiga and Trevor Diehl that NFM (“news finds me”) attitude may reduce voting probability through an indirect effect. The text describes NFM as an attitude that has lowered people’s interest in actively acquiring news and introduces Gil de Zúñiga and Diehl’s study on the effects of NFM on people in the United States’ political knowledge and interest. The text goes on to say that despite the fact that the study didn’t occur near a major election, Gil de Zúñiga and Diehl still conclude that NFA may reduce voting probability. If the likelihood, or probability, that a person will vote is linked to that person’s level of political knowledge and interest, that would suggest that negatively affecting a person’s level of political knowledge and interest would also negatively affect how likely that person is to vote. Thus, if NFM attitude has a negative effect on political knowledge and interest, then it would also likely reduce voting probability."}, {"type": "paragraph", "text": "Choice A is incorrect because the finding that NFM attitude increases as major elections approach wouldn’t address the effect of NFM on the likelihood of voting, which is the idea advanced by Gil de Zúñiga and Diehl. Moreover, although the text mentions that there were no major elections that occurred near the time of the study, it doesn’t discern between major and minor elections when discussing voting probability. Choice C is incorrect because finding that NFM attitude shows little correlation with either political knowledge or political interest would undermine, not support, Gil de Zúñiga and Diehl’s idea that NFM may reduce voting probability because it suggests that NFM has no effect on political knowledge or political interest. Choice D is incorrect. Although Gil de Zúñiga and Diehl’s idea would be supported by the finding that the likelihood of voting increases as political knowledge increases, nothing in the text suggests that the researchers’ idea hinges on the size of people’s social networks."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 16, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice most logically completes the text?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice A is the best answer because it most logically completes the text’s discussion of the potential effects of logging on forest conservation. The text begins by stating that logging practices are often thought of as being contrary to forest conservation efforts. Then, the text presents the results of a research study examining the effect of limited logging practices on specific forest plots, finding that the plots with limited logging may be “more robust” (healthier) than the plots that hadn’t been logged at all. Given these results, it follows that logging may be a useful practice for maintaining healthy forests if it is practiced in a limited way."}, {"type": "paragraph", "text": "Choice B is incorrect because the study referenced in the text only provides information on limited logging as a potential forest management strategy. There is no information in the text about how other forest management strategies support forest conservation efforts. Therefore, the text does not support the assertion that other forest management strategies are more successful than limited logging. Choice C is incorrect because the text presents a research study with findings that specific plots of forest with limited logging may be more robust than the forest plots that were not logged. Rather than suggesting that it is hard to know whether limited logging might be beneficial, the text suggests that the practice could be useful in forest conservation efforts. Choice D is incorrect. The text discusses the results of a research study that compares the health of forest plots with limited logging to forest plots that were not logged. It does not take a position on the best way to support forest health but rather presents a research study with findings that question conventionally held thoughts regarding the practice of logging."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 17, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice most logically completes the text?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice D is the best answer because it presents the conclusion that most logically follows from the text’s discussion of the means authors use to write and revise their novels. After stating that many authors still choose to draft novels by hand even though computers are now widely used, the text acknowledges the speculation that the opposite choice—using only a computer—would have had an effect on such novels. However, the text then points out that every novel is the singular result of a combination of the particular conditions surrounding its creation. This suggests that it isn’t possible to determine the effect of any single condition (such as the means of writing) on its own; thus, there would be no way to reasonably evaluate how a novel would have turned out differently if it had been written by other means."}, {"type": "paragraph", "text": "Choice A is incorrect because the text doesn’t suggest that it’s more efficient to write a novel on a computer than to write it by hand; it doesn’t address efficiency at all. Therefore, it isn’t logical to conclude that authors who currently choose to write novels largely by hand should instead work only on a computer to increase their efficiency. Choice B is incorrect because the text doesn’t suggest anything about how successful authors are, regardless of the means by which they choose to write; therefore, it isn’t logical to conclude that authors who write largely by hand are likely to be more successful than those who work only on a computer."}, {"type": "paragraph", "text": "Choice C is incorrect because the text makes no mention of the time it takes to produce a novel, regardless of the means by which it’s written; therefore, it isn’t logical to conclude that novels written by hand take less time on average to produce than those written on a computer do."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 18, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text so that it conforms to the conventions of Standard English?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice C is the best answer. The convention being tested is end-of-sentence punctuation. This choice correctly uses a question mark to punctuate the coordinated interrogative clauses “What are atmospheric rivers” and “how do they affect our weather,” both of which ask direct questions."}, {"type": "paragraph", "text": "Choice A is incorrect because a period can’t be used in this way to punctuate an interrogative clause, such as “how do they affect our weather,” at the end of a sentence. Choice B is incorrect because the structure requires an interrogative clause and a question mark at the end of the sentence. Choice D is incorrect because the structure requires an interrogative clause at the end of the sentence."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Standard English Conventions'), 'medium', 'source', 'approved', 19, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text so that it conforms to the conventions of Standard English?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice A is the best answer. The convention being tested is subject-modifier placement. This choice makes the proper noun “Matthew Henson” the subject of the sentence and places it immediately after the modifying phrase “one… century.” In doing so, this choice clearly establishes that Matthew Henson—and not another noun in the sentence—is being described as one of the few African American global explorers during the turn of the 20th century."}, {"type": "paragraph", "text": "Choice B is incorrect because it results in a dangling modifier. The placement of the noun phrase “1891 and 1909” immediately after the modifying phrase illogically suggests that those years were one of the few African American global explorers during the turn of the 20th century. Choice C is incorrect because it results in a dangling modifier. The placement of the proper noun “Greenland” immediately after the modifying phrase illogically suggests that Greenland was one of the few African American global explorers during the turn of the 20th century. Choice D is incorrect because it results in a dangling modifier. The placement of the noun phrase “several treks across Greenland” immediately after the modifying phrase illogically suggests that the treks were one of the few African American global explorers during the turn of the 20th century."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Standard English Conventions'), 'medium', 'source', 'approved', 20, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text so that it conforms to the conventions of Standard English?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice A is the best answer. The convention being tested is subject-modifier placement. This choice makes the noun phrase “topological tapestries” the subject of the sentence and places it immediately after the modifying phrase “woven…grandmother.” In doing so, this choice clearly establishes that the topological tapestries—and not another noun in the sentence—are being described as woven from recycled yarn and hand tufted."}, {"type": "paragraph", "text": "Choice B is incorrect because it results in a dangling modifier. The placement of the noun phrase “Argentine textile artist Alexandra Kehayoglou” immediately after the modifying phrase illogically suggests that Kehayoglou is woven from recycled yarn and hand tufted. Choice C is incorrect because it results in a dangling modifier. The placement of the pronoun “she” and the noun phrase “Argentine textile artist Alexandra Kehayoglou” after the modifying phrase illogically suggests that Kehayoglou is woven from recycled yarn and hand tufted. Choice D is incorrect because it results in a dangling modifier. The placement of the noun “Alexandra Kehayoglou” immediately after the modifying phrase illogically suggests that Kehayoglou is woven from recycled yarn and hand tufted."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Standard English Conventions'), 'medium', 'source', 'approved', 21, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text so that it conforms to the conventions of Standard English?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice C is the best answer. The convention being tested is the coordination of main clauses within a sentence. This choice uses a semicolon in a conventional way to join the first main clause (“Clear… through”) and the second main clause (“wax…through”)."}, {"type": "paragraph", "text": "Choice A is incorrect because it results in a comma splice. Without a conjunction following it, a comma can’t be used in this way to join two main clauses. Choice B is incorrect because it results in a run-on sentence. The two main clauses (“Clear…through” and “wax…through”) are fused without punctuation and/or a conjunction. Furthermore, it results in a confusing and illogical sentence that suggests clear glass allows light to pass through wax paper, which doesn’t make sense in this context. Choice D is incorrect because when coordinating two longer main clauses such as these, it’s conventional to use a comma before the coordinating conjunction."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Standard English Conventions'), 'medium', 'source', 'approved', 22, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text so that it conforms to the conventions of Standard English?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice B is the best answer. The convention being tested is the punctuation of elements in a complex series. It’s conventional to use a semicolon to separate items in a complex series with internal punctuation, and in this choice, the semicolon after “leaves” is conventionally used to separate the first item (“natural debris, such as dried leaves”) and the second item (“man-made trash, such as plastic bags”) in the series of materials used by Gavua. Further, the comma after “trash” correctly separates the noun phrase “man-made trash” from the supplementary phrase (“such as plastic bags”) that describes it."}, {"type": "paragraph", "text": "Choice A is incorrect because a comma after “leaves” doesn’t match the semicolon used later to separate the second and third items in the series (“man- made...bags” and “and...glue”). Additionally, it’s not conventional to use a colon in this way to separate a supplementary phrase (“such as plastic bags”) from the noun phrase it modifies (“man-made trash”). Choice C is incorrect because a comma after “leaves” doesn’t match the semicolon used later to separate the second and third items in the series (“man-made...bags” and “and...glue”)."}, {"type": "paragraph", "text": "Choice D is incorrect because it’s not conventional to use a semicolon in this way to separate a supplementary phrase (“such as plastic bags”) from the noun phrase it modifies (“man-made trash”)."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Standard English Conventions'), 'medium', 'source', 'approved', 23, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text so that it conforms to the conventions of Standard English?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice A is the best answer. The convention being tested is the punctuation of supplementary elements within a sentence. This choice correctly uses a comma to separate the supplementary adverb “however” from the preceding main clause (“only...competitions”), and it uses a colon to introduce the list of dances that follows (“rumba…jive”). Further, placing the colon after “however” rather than before indicates that the information in the preceding main clause (only... competitions) is contrary to what might be assumed from the information in the previous sentence (Latin America has many more dance forms)."}, {"type": "paragraph", "text": "Choice B is incorrect. The comma after “however” can’t be used in this way to introduce a series (“rumba...jive”). Choice C is incorrect because it isn’t conventional to use a semicolon in this way to introduce a series of items, such as the list of dances. Choice D is incorrect because placing the semicolon after “competitions” illogically indicates that the following list of five Latin American dances (“rumba...jive”) is contrary to the information in the previous clause (only five Latin American dances are included in international ballroom dance competitions)."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Standard English Conventions'), 'medium', 'source', 'approved', 24, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text so that it conforms to the conventions of Standard English?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice D is the best answer. The convention being tested is punctuation use between two main clauses. In this choice, a colon is correctly used to mark the boundary between one main clause (“goats are notoriously indiscriminate”) and another main clause (“they will devour all kinds of shrubs and weeds”) and to introduce the following explanation of goats’ nondiscriminatory behavior when it comes to what they eat."}, {"type": "paragraph", "text": "Choice A is incorrect because when coordinating two longer main clauses such as these, it’s conventional to use a comma before the coordinating conjunction. Furthermore, the conjunction “and” fails to indicate that what follows is an explanation of goats’ nondiscriminatory behavior when it comes to their diets."}, {"type": "paragraph", "text": "Choice B is incorrect because it results in a comma splice. A comma can’t be used in this way to join two main clauses (“goats…indiscriminate” and “they… weeds”). Choice C is incorrect because it results in a run-on sentence. The two main clauses (“goats…indiscriminate” and “they…weeds”) are fused without punctuation and/or a conjunction."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Standard English Conventions'), 'medium', 'source', 'approved', 25, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text so that it conforms to the conventions of Standard English?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice B is the best answer. The convention being tested is subject-verb agreement. The plural verb “increase” agrees in number with the plural subject “toxins.”"}, {"type": "paragraph", "text": "Choice A is incorrect because the singular verb “is increasing” doesn’t agree in number with the plural subject “toxins.” Choice C is incorrect because the singular verb “increases” doesn’t agree in number with the plural subject “toxins.” Choice D is incorrect because the singular verb “has increased” doesn’t agree in number with the plural subject “toxins.”"}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Standard English Conventions'), 'medium', 'source', 'approved', 26, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text with the most logical transition?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice D is the best answer. “Finally” logically signals that the actions in this sentence—the removal, cataloging, and analysis of artifacts—are the next and final steps in a process, following the previous actions of surveying, digging, recording, and mapping."}, {"type": "paragraph", "text": "Choice A is incorrect because “for instance” illogically signals that the actions in this sentence are an example of the actions in the previous sentence. Instead, the removal, cataloging, and analysis of artifacts are the next and final steps in a process. Choice B is incorrect because “on the contrary” illogically signals that the actions in this sentence are directly opposed to the actions in the previous sentence. Instead, the removal, cataloging, and analysis of artifacts are the next and final steps in a process. Choice C is incorrect because “earlier” illogically signals that the actions in this sentence occur before the actions in the previous sentence. Instead, the removal, cataloging, and analysis of artifacts are the next and final steps in a process."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Expression of Ideas'), 'medium', 'source', 'approved', 27, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text with the most logical transition?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice A is the best answer. “In turn” logically signals that the information in the sentence—that the electrical currents create a protective barrier around Earth— is a result or consequence of the previous information about the circulation of liquid metals generating electrical currents that flow between Earth’s magnetic poles."}, {"type": "paragraph", "text": "Choice B is incorrect because “likewise” illogically signals that the information in the sentence is similar to the previous information about the circulation of liquid metals generating electrical currents that flow between Earth’s magnetic poles. Instead, the new information about the electrical currents is a direct result or consequence of the previous information. Choice C is incorrect because “nevertheless” illogically signals that the information in the sentence is true despite the previous information about the circulation of liquid metals generating electrical currents that flow between Earth’s magnetic poles. Instead, the new information about the electrical currents is a direct result or consequence of the previous information. Choice D is incorrect because “in reality” illogically signals that the information in the sentence contradicts the previous information about the circulation of liquid metals generating electrical currents that flow between Earth’s magnetic poles. Instead, the new information about the electrical currents is a direct result or consequence of the previous information."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Expression of Ideas'), 'medium', 'source', 'approved', 28, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text with the most logical transition?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice B is the best answer. “In fact” logically signals that the critics’ claim at the end of this sentence—that the two editions are essentially two different novels altogether—offers additional emphasis in support of the previous claim that the differences between the editions are extreme."}, {"type": "paragraph", "text": "Choice A is incorrect because “by contrast” illogically signals that the claim at the end of this sentence contrasts with the previous claim about the differences between the editions. Instead, the critics’ opinion offers additional emphasis in support of that claim. Choice C is incorrect because “nevertheless” illogically signals that the claim at the end of this sentence is true despite the previous claim about the differences between the two editions. Instead, the critics’ opinion offers additional emphasis in support of that claim. Choice D is incorrect because “in other words” illogically signals that the claim at the end of this sentence is merely paraphrasing the previous claim about the differences between the two editions. The critics’ opinion adds new information to the previous claim rather than simply paraphrasing it."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Expression of Ideas'), 'medium', 'source', 'approved', 29, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice most effectively uses relevant information from the notes to accomplish this goal?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice C is the best answer. The sentence emphasizes a similarity between the Choctaw Code Talkers and the Navajo Code Talkers by explaining that both groups used their native languages to transmit coded messages for the military."}, {"type": "paragraph", "text": "Choice A is incorrect. The sentence describes the Choctaw Code Talkers; it doesn’t emphasize a similarity between the Choctaw Code Talkers and the Navajo Code Talkers. Choice B is incorrect. The sentence introduces the Navajo Code Talkers; it doesn’t emphasize a similarity between the Choctaw Code Talkers and the Navajo Code Talkers. Choice D is incorrect. The sentence emphasizes a difference between the Choctaw Code Talkers and the Navajo Code Talkers; it doesn’t emphasize a similarity."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 30, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice most effectively uses relevant information from the notes to accomplish this goal?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice D is the best answer. The sentence contrasts the number of meteorite falls with the number of meteorite finds, noting that there have been over 60,000 meteorite finds but only about 1,200 recorded meteorite falls."}, {"type": "paragraph", "text": "Choice A is incorrect. While the sentence explains the difference between meteorite falls and meteorite finds, it doesn’t contrast the number of meteorite falls and meteorite finds. Choice B is incorrect. The sentence indicates the two categories of meteorites found on Earth; it doesn’t contrast the number of meteorite falls and meteorite finds. Choice C is incorrect. While the sentence notes the number of recorded meteorite falls, it doesn’t contrast this with the number of meteorite finds."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 31, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice most effectively uses relevant information from the notes to accomplish this goal?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice B is the best answer. The sentence emphasizes the sample collected from Serra de Itatiaia, noting that Bandeira collected a Polytrichum juniperinum sample there in 1925."}, {"type": "paragraph", "text": "Choice A is incorrect. The sentence introduces Bandeira to an audience unfamiliar with her work; it doesn’t emphasize the sample she collected from Serra de Itatiaia. Choice C is incorrect. While the sentence mentions the sample Bandeira collected from Serra de Itatiaia, it doesn’t emphasize this sample over the sample from Ponte do Inferno. Choice D is incorrect. The sentence provides examples of the botanical samples Bandeira collected; it doesn’t emphasize the sample collected from Serra de Itatiaia."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 32, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice most effectively uses relevant information from the notes to accomplish this goal?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice C is the best answer. The sentence indicates which classification category most routine diplomatic correspondence belongs in, explaining that it is classified as Confidential because it has the potential to damage national security if disclosed."}, {"type": "paragraph", "text": "Choice A is incorrect. While the sentence makes a claim about information classified as Confidential, it doesn’t indicate which category routine diplomatic correspondence belongs in. Choice B is incorrect. The sentence makes a generalization about how routine diplomatic correspondence is classified; it doesn’t indicate which classification category the correspondence belongs in. Choice D is incorrect. This sentence explains that routine diplomatic correspondence could affect national security if disclosed; it doesn’t indicate which category of sensitive information this correspondence belongs in."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 33, 'choice', array[]::text[]) returning id into v_q;
    update public.exams set status = 'published' where id = v_exam;
  end if;
  -- SAT Practice Test 6: Math
  if exists (select 1 from public.exams where slug = 'sat-practice-test-6-math') then
    raise notice 'skipping sat-practice-test-6-math (already imported)';
  else
    select id into v_subject from public.subjects where code = 'sat-math';
    values (v_subject, 'sat-practice-test-6-math', 'SAT Practice Test 6: Math', 'Official SAT Practice Test 6 (College Board), Math: 54 questions in two modules, including student-produced responses. Calculator allowed; 43 minutes per module.', 'full_mock', 'premium', 'draft', 86, 'source', 213, '[[200, 200], [200, 200], [200, 200], [200, 200], [200, 200], [200, 210], [200, 210], [200, 230], [220, 260], [240, 320], [280, 340], [300, 340], [310, 350], [320, 360], [330, 370], [340, 380], [340, 380], [350, 390], [350, 390], [360, 400], [370, 410], [380, 420], [380, 420], [390, 430], [400, 440], [410, 450], [420, 460], [430, 470], [440, 500], [450, 510], [460, 520], [470, 530], [480, 540], [500, 560], [510, 570], [520, 580], [530, 590], [540, 600], [550, 610], [560, 620], [570, 630], [590, 650], [600, 660], [610, 670], [630, 690], [640, 700], [660, 720], [680, 740], [700, 760], [720, 780], [750, 790], [760, 800], [780, 800], [790, 800], [790, 800]]'::jsonb)
    returning id into v_exam;
    values (v_subject, null, null, '{"blocks": [{"type": "math", "latex": "(p + 3) + 8 = 10"}, {"type": "paragraph", "text": "What value of $p$ is the solution to the given equation?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$p + 11 = 10$, so $p = -1$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'easy', 'source', 'approved', 1, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "image", "src": "/sat/test-06/math-m1-q02.png", "alt": "Figure for question 2", "width": 285}, {"type": "paragraph", "text": "The scatterplot shows the relationship between two variables, $x$ and $y$."}, {"type": "paragraph", "text": "Which of the following graphs shows the most appropriate model for the data?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "The data rise slowly at first and then more and more steeply, which is exponential growth. The curve in graph D passes through or close to every point; the curve in C sits well above the early points."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Problem-Solving and Data Analysis'), 'easy', 'source', 'approved', 2, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "math", "latex": "k^2 - 53 = 91"}, {"type": "paragraph", "text": "What is the positive solution to the given equation?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$k^2 = 144$, so the positive solution is $k = 12$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Advanced Math'), 'easy', 'source', 'approved', 3, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "During a portion of a flight, a small airplane''s cruising speed varied between $150$ miles per hour and $170$ miles per hour. Which inequality best represents this situation, where $s$ is the cruising speed, in miles per hour, during this portion of the flight?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "The speed was never below $150$ or above $170$: $150 \\le s \\le 170$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'easy', 'source', 'approved', 4, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "image", "src": "/sat/test-06/math-m1-q05.png", "alt": "Figure for question 5", "width": 291}, {"type": "paragraph", "text": "An object was launched upward from a platform. The graph shown models the height above ground, $y$, in meters, of the object $x$ seconds after it was launched. For which of the following intervals of time was the height of the object increasing for the entire interval?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "The graph rises from $x = 0$ to its peak at $x = 2$ and falls after that, so the height increases on the whole interval from $0$ to $2$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Advanced Math'), 'easy', 'source', 'approved', 5, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "How many **yards** are equivalent to $1{,}116$ inches? ($1$ yard $= 36$ inches)"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$1{,}116 \\div 36 = 31$ yards."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Problem-Solving and Data Analysis'), 'easy', 'source', 'approved', 6, 'spr', array['31']::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "math", "latex": "f(x) = 14 + 4x"}, {"type": "paragraph", "text": "The function $f$ represents the total cost, in dollars, of attending an arcade when $x$ games are played. How many games can be played for a total cost of $\\$58$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$14 + 4x = 58$, so $4x = 44$ and $x = 11$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'easy', 'source', 'approved', 7, 'spr', array['11']::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "math", "latex": "f(x) = x + b"}, {"type": "paragraph", "text": "For the linear function $f$, $b$ is a constant. When $x = 0$, $f(x) = 30$. What is the value of $b$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$f(0) = 0 + b = 30$, so $b = 30$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'easy', 'source', 'approved', 8, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "math", "latex": "P(t) = 1{,}800(1.02)^t"}, {"type": "paragraph", "text": "The function $P$ gives the estimated number of marine mammals in a certain area, where $t$ is the number of years since a study began. What is the best interpretation of $P(0) = 1{,}800$ in this context?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$t = 0$ is when the study began, and $P(0) = 1{,}800$ is the estimated number of marine mammals at that time."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Advanced Math'), 'easy', 'source', 'approved', 9, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "A manager is responsible for ordering supplies for a shaved ice shop. The shop''s inventory starts with $4{,}500$ paper cups, and the manager estimates that $70$ of these paper cups are used each day. Based on this estimate, in how many days will the supply of paper cups reach $1{,}700$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "The shop must use $4{,}500 - 1{,}700 = 2{,}800$ cups, which takes $2{,}800 \\div 70 = 40$ days."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'easy', 'source', 'approved', 10, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "math", "latex": "y > 4x + 8"}, {"type": "paragraph", "text": "For which of the following tables are all the values of $x$ and their corresponding values of $y$ solutions to the given inequality?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$4x + 8$ equals $16$, $24$, and $32$ at $x = 2$, $4$, $6$. Only table A has every $y$ greater: $19 > 16$, $30 > 24$, $41 > 32$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'medium', 'source', 'approved', 11, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "Which expression is equivalent to $(x^2 + 11)^2 + (x - 5)(x + 5)$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$(x^2 + 11)^2 = x^4 + 22x^2 + 121$ and $(x - 5)(x + 5) = x^2 - 25$. The sum is $x^4 + 23x^2 + 96$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Advanced Math'), 'medium', 'source', 'approved', 12, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "The function $h$ is defined by $h(x) = \\dfrac{8}{5x + 6}$. What is the value of $h(2)$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$h(2) = \\dfrac{8}{10 + 6} = \\dfrac{8}{16} = \\dfrac{1}{2}$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Advanced Math'), 'easy', 'source', 'approved', 13, 'spr', array['.5', '1/2']::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "image", "src": "/sat/test-06/math-m1-q14.png", "alt": "Figure for question 14", "width": 261}, {"type": "paragraph", "text": "The figure shows the lengths, in inches, of two sides of a right triangle. What is the area of the triangle, in square inches?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "The legs are $3$ and $5$, so the area is $\\tfrac{1}{2}(3)(5) = 7.5$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Geometry and Trigonometry'), 'easy', 'source', 'approved', 14, 'spr', array['7.5', '15/2']::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "image", "src": "/sat/test-06/math-m1-q15.png", "alt": "Figure for question 15", "width": 256}, {"type": "paragraph", "text": "The graph models the number of active projects a company was working on $x$ months after the end of November $2012$, where $0 \\le x \\le 6$. According to the model, what is the predicted number of active projects the company was working on at the end of November $2012$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "The end of November $2012$ is $x = 0$, where the graph is at $y = 5$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Advanced Math'), 'easy', 'source', 'approved', 15, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "The relationship between two variables, $x$ and $y$, is linear. For every increase in the value of $x$ by $1$, the value of $y$ increases by $8$. When the value of $x$ is $2$, the value of $y$ is $18$. Which equation represents this relationship?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "The slope is $8$. Using $(2, 18)$: $18 = 8(2) + b$, so $b = 2$ and $y = 8x + 2$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'medium', 'source', 'approved', 16, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "math", "latex": "P = N(19 - C)"}, {"type": "paragraph", "text": "The given equation relates the positive numbers $P$, $N$, and $C$. Which equation correctly expresses $C$ in terms of $P$ and $N$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Divide by $N$: $\\dfrac{P}{N} = 19 - C$, so $C = 19 - \\dfrac{P}{N}$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'medium', 'source', 'approved', 17, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "math", "latex": "w^2 + 12w - 40 = 0"}, {"type": "paragraph", "text": "Which of the following is a solution to the given equation?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Complete the square: $(w + 6)^2 = 76$, so $w = -6 \\pm \\sqrt{76} = -6 \\pm 2\\sqrt{19}$. One solution is $-6 + 2\\sqrt{19}$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Advanced Math'), 'medium', 'source', 'approved', 18, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "image", "src": "/sat/test-06/math-m1-q19.png", "alt": "Figure for question 19", "width": 302}, {"type": "paragraph", "text": "The table shown summarizes the number of employees at each of the $17$ restaurants in a town."}, {"type": "paragraph", "text": "Which of the following could be the median number of employees for the restaurants in this town?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "With $17$ values the median is the $9$th. The first three rows hold $2 + 4 + 2 = 8$ restaurants, so the $9$th is in the $20$ to $25$ group. Only $21$ is in that range."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Problem-Solving and Data Analysis'), 'medium', 'source', 'approved', 19, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "What is the $y$-coordinate of the $y$-intercept of the graph of $\\dfrac{3x}{7} = -\\dfrac{5y}{9} + 21$ in the $xy$-plane?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "At the $y$-intercept $x = 0$: $\\dfrac{5y}{9} = 21$, so $y = \\dfrac{189}{5} = 37.8$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'medium', 'source', 'approved', 20, 'spr', array['189/5', '37.8']::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "image", "src": "/sat/test-06/math-m1-q21.png", "alt": "Figure for question 21", "width": 258}, {"type": "paragraph", "text": "The graph of $y = 2x^2 + bx + c$ is shown, where $b$ and $c$ are constants. What is the value of $bc$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "The graph crosses the $y$-axis at $-6$, so $c = -6$. It passes through $(-2, -6)$ and $(0, -6)$, so the vertex is at $x = -1$: $-\\dfrac{b}{2(2)} = -1$ gives $b = 4$. Then $bc = -24$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Advanced Math'), 'hard', 'source', 'approved', 21, 'spr', array['-24']::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "In $2008$, Zinah earned $14\\%$ more than in $2007$, and in $2009$ Zinah earned $4\\%$ more than in $2008$. If Zinah earned $y$ times as much in $2009$ as in $2007$, what is the value of $y$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Successive increases multiply: $1.14 \\times 1.04 = 1.1856$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Problem-Solving and Data Analysis'), 'medium', 'source', 'approved', 22, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "image", "src": "/sat/test-06/math-m1-q23.png", "alt": "Figure for question 23", "width": 177}, {"type": "paragraph", "text": "Circle $A$ (shown) is defined by the equation $(x + 2)^2 + y^2 = 9$. Circle $B$ (not shown) is the result of shifting circle $A$ down $6$ units and increasing the radius so that the radius of circle $B$ is $2$ times the radius of circle $A$. Which equation defines circle $B$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Circle $A$ has center $(-2, 0)$ and radius $3$. Circle $B$ has center $(-2, -6)$ and radius $6$, so $r^2 = 36 = (4)(9)$: $(x + 2)^2 + (y + 6)^2 = (4)(9)$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Geometry and Trigonometry'), 'medium', 'source', 'approved', 23, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "image", "src": "/sat/test-06/math-m1-q24.png", "alt": "Figure for question 24", "width": 261}, {"type": "paragraph", "text": "Right triangle $ABC$ is shown. What is the value of $\\tan A$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Angle $B$ is $30^\\circ$ and $C$ is $90^\\circ$, so $A = 60^\\circ$ and $\\tan 60^\\circ = \\sqrt{3}$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Geometry and Trigonometry'), 'medium', 'source', 'approved', 24, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "At the time that an article was first featured on the home page of a news website, there were $40$ comments on the article. An exponential model estimates that at the end of each hour after the article was first featured on the home page, the number of comments on the article had increased by $190\\%$ of the number of comments on the article at the end of the previous hour. Which of the following equations best represents this model, where $C$ is the estimated number of comments on the article $t$ hours after the article was first featured on the home page and $t \\le 4$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "An increase of $190\\%$ each hour multiplies the count by $1 + 1.90 = 2.9$: $C = 40(2.9)^t$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Advanced Math'), 'hard', 'source', 'approved', 25, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "table", "header": ["$x$", "$g(x)$"], "rows": [["$-27$", "$3$"], ["$-9$", "$0$"], ["$21$", "$5$"]]}, {"type": "paragraph", "text": "The table shows three values of $x$ and their corresponding values of $g(x)$, where $g(x) = \\dfrac{f(x)}{x + 3}$ and $f$ is a linear function. What is the $y$-intercept of the graph of $y = f(x)$ in the $xy$-plane?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$f(x) = (x + 3)g(x)$, so $f(-9) = (-6)(0) = 0$ and $f(-27) = (-24)(3) = -72$. The slope is $\\dfrac{0 - (-72)}{-9 - (-27)} = 4$, so $f(x) = 4(x + 9) = 4x + 36$ and the $y$-intercept is $(0, 36)$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'hard', 'source', 'approved', 26, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "In right triangle $ABC$, angle $C$ is the right angle and $BC = 162$. Point $D$ on side $AB$ is connected by a line segment with point $E$ on side $AC$ such that line segment $DE$ is parallel to side $BC$ and $CE = 2AE$. What is the length of line segment $DE$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Triangles $ADE$ and $ABC$ are similar. Since $CE = 2AE$, $AE$ is one third of $AC$, so $DE$ is one third of $BC$: $\\tfrac{162}{3} = 54$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Geometry and Trigonometry'), 'hard', 'source', 'approved', 27, 'spr', array['54']::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "The function $f$ is defined by $f(x) = 8x$. For what value of $x$ does $f(x) = 72$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$8x = 72$, so $x = 9$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'easy', 'source', 'approved', 1, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "image", "src": "/sat/test-06/math-m2-q02.png", "alt": "Figure for question 2", "width": 200}, {"type": "paragraph", "text": "In the figure, two lines intersect at a point. Angle 1 and angle 2 are vertical angles. The measure of angle 1 is $72^\\circ$. What is the measure of angle 2?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Vertical angles are equal, so angle 2 also measures $72^\\circ$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Geometry and Trigonometry'), 'easy', 'source', 'approved', 2, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "On a street with $7$ houses, $2$ houses are blue. If a house from this street is selected at random, what is the probability of selecting a house that is blue?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$2$ of the $7$ houses are blue, so the probability is $\\tfrac{2}{7}$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Problem-Solving and Data Analysis'), 'easy', 'source', 'approved', 3, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "image", "src": "/sat/test-06/math-m2-q04.png", "alt": "Figure for question 4", "width": 262}, {"type": "paragraph", "text": "The graph of function $f$ is shown, where $y = f(x)$."}, {"type": "paragraph", "text": "Which of the following describes function $f$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "The graph is a straight line that rises from left to right, so $f$ is increasing linear."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'easy', 'source', 'approved', 4, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "image", "src": "/sat/test-06/math-m2-q05.png", "alt": "Figure for question 5", "width": 250}, {"type": "paragraph", "text": "The graph of the function $f$ is shown, where $y = f(x)$. What is the $y$-intercept of the graph?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "The line crosses the $y$-axis at $y = -4$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'easy', 'source', 'approved', 5, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "math", "latex": "\\begin{aligned} x &= 8 \\\\ x + 3y &= 26 \\end{aligned}"}, {"type": "paragraph", "text": "The solution to the given system of equations is $(x, y)$. What is the value of $y$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Substitute $x = 8$: $3y = 18$, so $y = 6$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'easy', 'source', 'approved', 6, 'spr', array['6']::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "The amount of Hanna''s bill for a food order was $\\$50$. Hanna gave a tip of $20\\%$ of the amount of the bill. What is the amount, in dollars, of the tip Hanna gave?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$0.20 \\times 50 = 10$ dollars."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Problem-Solving and Data Analysis'), 'easy', 'source', 'approved', 7, 'spr', array['10']::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "Which expression is equivalent to $5x^5 - 6x^4 + 8x^3$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Factor out the greatest common factor $x^3$: $x^3(5x^2 - 6x + 8)$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Advanced Math'), 'easy', 'source', 'approved', 8, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "The ratio of the length of line segment $XY$ to the length of line segment $ZV$ is $6$ to $1$. If the length of line segment $XY$ is $102$ inches, what is the length, in inches, of line segment $ZV$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$ZV$ is one sixth of $XY$: $102 \\div 6 = 17$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Problem-Solving and Data Analysis'), 'easy', 'source', 'approved', 9, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "math", "latex": "7(2x - 3) = 63"}, {"type": "paragraph", "text": "Which equation has the same solution as the given equation?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Dividing both sides by $7$ gives the equivalent equation $2x - 3 = 9$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'easy', 'source', 'approved', 10, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "The function $f$ defined by $f(t) = 14t + 9$ gives the estimated length, in inches, of a vine plant $t$ months after Tavon purchased it. Which of the following is the best interpretation of $9$ in this context?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$f(0) = 9$: at $t = 0$, the purchase date, the plant''s estimated length was $9$ inches."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'easy', 'source', 'approved', 11, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "math", "latex": "(x + 2)(x - 5)(x + 9) = 0"}, {"type": "paragraph", "text": "What is a positive solution to the given equation?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "The solutions are $-2$, $5$, and $-9$. The positive one is $5$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Advanced Math'), 'easy', 'source', 'approved', 12, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "Brian saves $\\dfrac{2}{5}$ of the $\\$215$ he earns each week from his job. If Brian continues to save at this rate, how much money, in dollars, will Brian save in $9$ weeks?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Each week he saves $\\tfrac{2}{5}(215) = 86$ dollars, so in $9$ weeks he saves $9 \\times 86 = 774$ dollars."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Problem-Solving and Data Analysis'), 'easy', 'source', 'approved', 13, 'spr', array['774']::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "A rectangle has an area of $155$ square inches. The length of the rectangle is $4$ inches less than $7$ times the width of the rectangle. What is the width of the rectangle, in inches?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "With width $w$: $w(7w - 4) = 155$, so $7w^2 - 4w - 155 = 0$, which factors as $(7w + 31)(w - 5) = 0$. The width is $5$ inches."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Advanced Math'), 'medium', 'source', 'approved', 14, 'spr', array['5']::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "math", "latex": "4, 10, 18, 4, 4, 5, 6, 5"}, {"type": "paragraph", "text": "What is the median of the data set shown?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "In order: $4, 4, 4, 5, 5, 6, 10, 18$. With $8$ values the median is the average of the $4$th and $5$th: $\\tfrac{5 + 5}{2} = 5$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Problem-Solving and Data Analysis'), 'easy', 'source', 'approved', 15, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "A right circular cylinder has a volume of $432$ cubic centimeters. The area of the base of the cylinder is $24$ square centimeters. What is the height, in centimeters, of the cylinder?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Volume $=$ base area $\\times$ height, so $h = \\tfrac{432}{24} = 18$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Geometry and Trigonometry'), 'easy', 'source', 'approved', 16, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "math", "latex": "x^2 = -841"}, {"type": "paragraph", "text": "How many distinct real solutions does the given equation have?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "A real number squared is never negative, so there are no real solutions."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Advanced Math'), 'easy', 'source', 'approved', 17, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "Line $k$ is defined by $y = 7x + \\dfrac{1}{8}$. Line $j$ is perpendicular to line $k$ in the $xy$-plane. What is the slope of line $j$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Perpendicular slopes are negative reciprocals. Line $k$ has slope $7$, so line $j$ has slope $-\\tfrac{1}{7}$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'medium', 'source', 'approved', 18, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "table", "header": ["Number of cars", "Maximum number of passengers and crew"], "rows": [["$3$", "$174$"], ["$5$", "$284$"], ["$10$", "$559$"]]}, {"type": "paragraph", "text": "The table shows the linear relationship between the number of cars, $c$, on a commuter train and the maximum number of passengers and crew, $p$, that the train can carry. Which equation represents the linear relationship between $c$ and $p$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "The slope is $\\tfrac{284 - 174}{5 - 3} = 55$, and $174 = 55(3) + 9$, so $p = 55c + 9$, which rearranges to $55c - p = -9$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'medium', 'source', 'approved', 19, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "If $4^{8c} = \\sqrt[3]{4^7}$, what is the value of $c$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$\\sqrt[3]{4^7} = 4^{7/3}$, so $8c = \\tfrac{7}{3}$ and $c = \\tfrac{7}{24}$ (about $0.2917$)."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Advanced Math'), 'medium', 'source', 'approved', 20, 'spr', array['.2916', '.2917', '7/24']::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "math", "latex": "\\begin{aligned} (x - 2) - 4(y + 7) &= 117 \\\\ (x - 2) + 4(y + 7) &= 442 \\end{aligned}"}, {"type": "paragraph", "text": "The solution to the given system of equations is $(x, y)$. What is the value of $6(x - 2)$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Add the equations: $2(x - 2) = 559$. Multiply by $3$: $6(x - 2) = 1{,}677$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'medium', 'source', 'approved', 21, 'spr', array['1677']::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "In triangle $ABC$, angle $B$ is a right angle. The length of side $AB$ is $10\\sqrt{37}$ and the length of side $BC$ is $24\\sqrt{37}$. What is the length of side $AC$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$AC$ is the hypotenuse: $AC^2 = 100(37) + 576(37) = 676(37)$, so $AC = 26\\sqrt{37}$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Geometry and Trigonometry'), 'medium', 'source', 'approved', 22, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "math", "latex": "f(x) = (1.84)^{\\frac{x}{4}}"}, {"type": "paragraph", "text": "The function $f$ is defined by the given equation. The equation can be rewritten as $f(x) = \\left(1 + \\dfrac{p}{100}\\right)^x$, where $p$ is a constant. Which of the following is closest to the value of $p$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$(1.84)^{x/4} = \\left(1.84^{1/4}\\right)^x \\approx 1.165^x$, so $\\tfrac{p}{100} \\approx 0.165$ and $p$ is closest to $16$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Advanced Math'), 'hard', 'source', 'approved', 23, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "The function $f$ is defined by $f(x) = a\\sqrt{x + b}$, where $a$ and $b$ are constants. In the $xy$-plane, the graph of $y = f(x)$ passes through the point $(-24, 0)$, and $f(24) < 0$. Which of the following must be true?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$f(-24) = a\\sqrt{b - 24} = 0$ gives $b = 24$. Then $f(24) = a\\sqrt{48} < 0$ means $a < 0$, so $a < b$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Advanced Math'), 'hard', 'source', 'approved', 24, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "In the $xy$-plane, a circle has center $C$ with coordinates $(h, k)$. Points $A$ and $B$ lie on the circle. Point $A$ has coordinates $\\left(h + 1, k + \\sqrt{102}\\right)$, and $\\angle ACB$ is a right angle. What is the length of $\\overline{AB}$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "The radius is $CA = \\sqrt{1 + 102} = \\sqrt{103}$. Triangle $ACB$ is an isosceles right triangle with legs $\\sqrt{103}$, so $AB = \\sqrt{103}\\cdot\\sqrt{2} = \\sqrt{206}$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Geometry and Trigonometry'), 'hard', 'source', 'approved', 25, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "image", "src": "/sat/test-06/math-m2-q26.png", "alt": "Figure for question 26", "width": 256}, {"type": "paragraph", "text": "The scatterplot shows the relationship between two variables, $x$ and $y$, for data set E. A line of best fit is shown. Data set F is created by multiplying the $y$-coordinate of each data point from data set E by $3.9$. Which of the following could be an equation of a line of best fit for data set F?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "The line for E is about $y = 12 + 1.5x$. Multiplying every $y$-value by $3.9$ multiplies the intercept and slope by $3.9$: about $y = 46.8 + 5.85x$, closest to $y = 46.8 + 5.9x$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Problem-Solving and Data Analysis'), 'hard', 'source', 'approved', 26, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "math", "latex": "\\begin{aligned} 48x - 64y &= 48y + 24 \\\\ ry &= \\frac{1}{8} - 12x \\end{aligned}"}, {"type": "paragraph", "text": "In the given system of equations, $r$ is a constant. If the system has no solution, what is the value of $r$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Rewrite: $48x - 112y = 24$ and $12x + ry = \\tfrac{1}{8}$. Multiplying the second by $4$ gives $48x + 4ry = \\tfrac{1}{2}$. No solution means parallel lines with different constants, so $4r = -112$ and $r = -28$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'hard', 'source', 'approved', 27, 'spr', array['-28']::text[]) returning id into v_q;
    update public.exams set status = 'published' where id = v_exam;
  end if;
end $sat$;

do $sat$
declare
  v_subject uuid; v_exam uuid; v_section uuid; v_stim uuid; v_q uuid;
begin
  -- SAT Practice Test 7: Reading and Writing
  if exists (select 1 from public.exams where slug = 'sat-practice-test-7-reading-and-writing') then
    raise notice 'skipping sat-practice-test-7-reading-and-writing (already imported)';
  else
    select id into v_subject from public.subjects where code = 'sat-english';
    values (v_subject, 'sat-practice-test-7-reading-and-writing', 'SAT Practice Test 7: Reading and Writing', 'Official SAT Practice Test 7 (College Board), Reading and Writing: 66 questions in two modules, timed as the paper test (39 minutes per module).', 'full_mock', 'premium', 'draft', 78, 'source', 214, '[[200, 200], [210, 220], [210, 220], [210, 220], [210, 220], [210, 230], [210, 240], [210, 250], [220, 260], [220, 270], [220, 280], [230, 290], [230, 300], [240, 310], [240, 320], [250, 330], [270, 330], [300, 340], [310, 350], [320, 360], [320, 360], [330, 370], [340, 380], [350, 390], [350, 390], [360, 400], [370, 410], [370, 410], [380, 420], [390, 430], [400, 440], [410, 450], [410, 450], [420, 460], [430, 470], [440, 480], [450, 490], [460, 500], [470, 510], [470, 530], [480, 540], [490, 550], [500, 560], [510, 570], [520, 580], [530, 590], [540, 600], [560, 620], [570, 630], [580, 640], [590, 650], [600, 660], [610, 670], [630, 690], [640, 700], [660, 700], [670, 710], [680, 720], [690, 730], [710, 750], [720, 760], [730, 770], [750, 770], [760, 780], [770, 790], [780, 800], [800, 800]]'::jsonb)
    returning id into v_exam;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text with the most logical and precise word or phrase?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice A is the best answer because it most logically completes the text’s discussion of a prediction about a kilonova. In this context, a “theory” is an explanation that is considered scientifically acceptable. The text states that astronomers predicted in the 1990s that a collision between a black hole and a neutron star or between two neutron stars could release a massive gamma ray burst called a kilonova, explaining that they determined this possibility based on their extensive work with existing data and simulations (“calculations and models”). In other words, the prediction was a theory—a well-supported explanation—that, as the text indicates, was later confirmed with observations in 2017."}, {"type": "paragraph", "text": "Choice B is incorrect because the text indicates that it is the prediction made by astronomers in the 1990s that was confirmed in 2017, and a prediction of an event isn’t “evidence,” or proof, of that event’s existence, even when the prediction is based on extensive study. Further, there would be no need for later confirmation of something that was already recognized as evidence. Choice C is incorrect because in this context, a “constant” is a situation or factor that doesn’t change. The text indicates that it is the prediction made by astronomers in the 1990s that was confirmed in 2017, and there is no reason to describe the prediction as a constant because the text doesn’t suggest that the prediction was completely unchanged over time—it addresses only the making of the prediction and its later confirmation. Choice D is incorrect because the text indicates that it is the prediction made by astronomers in the 1990s that was confirmed in 2017; although a prediction might be informed by an “experiment,” or a controlled test, a prediction is an idea rather than a test."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Craft and Structure'), 'medium', 'source', 'approved', 1, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "As used in the text, what does the word “clear” most nearly mean?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice D is the best answer because as used in the text, “clear” most nearly means transparent, or see-through. Muir states that the water beneath the boat “was so clear that it was almost invisible,” suggesting that those on the boat were able to see through the water and easily observe plants and fish below the surface."}, {"type": "paragraph", "text": "Choice A is incorrect. In some contexts “clear” can mean “simple,” or uncomplicated, but Muir is describing the water, and water isn’t typically described as either simple or complicated. Muir emphasizes the water’s transparency, not its simplicity. Choice B is incorrect. In some contexts “clear” can mean “understandable,” or reasonable or easily comprehended, but Muir is describing the water, and it doesn’t make much sense to describe water as understandable. Muir emphasizes the water’s transparency, not how easily the water can be understood. Choice C is incorrect. Although “clear” can mean “obvious,” or easily seen or understood, in some contexts, Muir’s description emphasizes that the water “was almost invisible” and that the boat seemed to be “sustained in the air,” suggesting that the water was almost impossible to see, not that it was obvious."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Craft and Structure'), 'medium', 'source', 'approved', 2, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text with the most logical and precise word or phrase?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice B is the best answer because it most logically completes the text’s discussion of how Maggie Lena Walker addressed the lack of financial services available to Black residents in Richmond, Virginia, at the turn of the twentieth century. In this context, “rectify” means to correct or remedy something undesirable. The text indicates that by chartering the St. Luke Penny Savings Bank in 1903, Walker took action to provide local Black residents with greater access to financial services like home loans and savings opportunities. This context supports the idea that she aimed to rectify the undesirable situation affecting these residents."}, {"type": "paragraph", "text": "Choice A is incorrect because in this context, “prolong” would mean to lengthen something in time. The text indicates that at the turn of the twentieth century, Black residents in Richmond, Virginia, were faced with a lack of formal banking options. The text then states that Walker founded a new bank that provided these residents with financial services. Therefore, instead of prolonging the situation, she took steps to rectify, or correct, it. Choice C is incorrect because in this context, “retain” would mean to continue to have or to keep something. According to the text, at the turn of the twentieth century, Black residents in Richmond, Virginia, had few formal banking options, and Walker chartered a new institution to provide these residents with expanded financial services; therefore, she took steps to rectify, not retain, the situation. Choice D is incorrect because in this context, “highlight” would mean to emphasize or call attention to something, but the text indicates that Walker took concrete steps beyond merely drawing attention to the situation Black residents were facing in Richmond, Virginia, at the turn of the twentieth century. According to the text, Walker worked to rectify, or correct, the lack of formal banking options that were available to these residents by establishing a bank that provided them with home loans and savings opportunities."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Craft and Structure'), 'medium', 'source', 'approved', 3, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text with the most logical and precise word or phrase?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice B is the best answer because it most logically completes the text’s discussion of a relationship between the results of randomized clinical tests of how effective common medical interventions are and the conclusions practitioners reach about such interventions in real-world settings. In this context, “corroborate” means confirm or support with evidence. The text indicates that one possible explanation for the relationship being discussed is that practitioners may overlook confounding variables—that is, additional factors other than the medical interventions being investigated that affect the observed outcomes. This means that practitioners may assume that an outcome is the direct result of a medical intervention when it is actually the result of a combination of factors. Clinical trials take steps to rule out factors other than the one being studied, so if those extra factors are actually having an effect on real-world outcomes, the trials are likely to produce conclusions different from those practitioners reach in their real-world observations. In other words, clinical trials may fail to corroborate practitioners’ conclusions."}, {"type": "paragraph", "text": "Choice A is incorrect because it wouldn’t make sense to say that the results of clinical trials could “circumvent,” or find a way around or bypass, conclusions practitioners reach in real-world scenarios with patients; it’s possible that researchers conducting the trials might avoid engaging with practitioners’ conclusions, but findings from a study can’t choose to get around something."}, {"type": "paragraph", "text": "Choice C is incorrect because it wouldn’t make sense to say that the results of clinical trials could “disseminate,” or spread widely, conclusions practitioners reach in real-world scenarios with patients; the researchers conducting the trials might choose to draw attention to practitioners’ conclusions, but findings from a study can’t spread anything. Choice D is incorrect because it wouldn’t make sense to say that the results of clinical trials could “implement,” or put into effect, conclusions practitioners reach in real-world scenarios with patients; the researchers conducting the trials might consider practitioners’ conclusions, but findings from a study can’t put anything into effect."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Craft and Structure'), 'medium', 'source', 'approved', 4, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text with the most logical and precise word or phrase?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice A is the best answer because it most logically completes the text’s discussion of diadromous fish. In this context, “demarcated from” means separate or set apart from. The text indicates that diadromous fish differ from euryhaline fish in that diadromous fish “migrate between freshwater and marine biomes during their life,” whereas euryhaline fish do not relocate to a different biome because they can tolerate higher salinity environments. Therefore, this context suggests that because of differences between their migration patterns, diadromous fish are distinct and can be demarcated from euryhaline fish."}, {"type": "paragraph", "text": "Choice B is incorrect. Although the text states that diadromous fish migrate and relocate, the text does not suggest that diadromous fish would be “reconstituted as,” or formed again as, anything new. Only their environments change and not the fish themselves. Choice C is incorrect because the text does not suggest that diadromous fish can be “conflated with,” or combined with, euryhaline fish. Instead, the text distinguishes the two types of fish by pointing out their differences with regard to migration and tolerance for salinity. Choice D is incorrect because the text indicates that based on migration habits and tolerance for salinity, diadromous fish are different from euryhaline fish; so it would not make logical sense to say that diadromous fish would be “derived from,” or be an extension of or result from, euryhaline fish."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Craft and Structure'), 'medium', 'source', 'approved', 5, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, 0, '{"blocks": [{"type": "paragraph", "text": "Which choice best describes the function of the underlined portion in the text as a whole?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice A is the best answer because it most accurately describes how the underlined portion functions in the text as a whole. The first two sentences of the text establish that in California, houses were heated by building fires year-round. The underlined portion then indicates that the fires didn’t merely provide physical warmth: they also represented being “home” and feeling protected. The underlined portion thus illustrates that a fire provides comfort beyond physical warmth."}, {"type": "paragraph", "text": "Choice B is incorrect because the underlined portion doesn’t summarize information that came before it. Whereas the previous two sentences describe fires’ ability to provide physical warmth to homes, the underlined portion focuses on the psychological comfort the fires offered. Choice C is incorrect. Although the text’s second sentence mentions that fires were built in the summer because fog came in, which may have cooled the house, this detail isn’t the focus of the underlined portion. Instead, the underlined portion indicates that fires were built for reasons beyond physical warmth: to create a sense of being home and safe."}, {"type": "paragraph", "text": "Choice D is incorrect because the underlined portion focuses on the emotional significance the author places on having a fire going inside the home. There is no indication that the author feels equally comfortable without a fire present."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Craft and Structure'), 'medium', 'source', 'approved', 6, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, 0, '{"blocks": [{"type": "paragraph", "text": "Which choice best states the function of the underlined portion of the text?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice A is the best answer because it most accurately describes how the underlined phrase functions in the text as a whole. The text states that the wax produced by Liu and colleagues’ reactor can be turned into a surfactant. The underlined phrase, which is set off with parentheses, then provides a definition for the term “surfactant,” explaining that it’s a chemical compound that can be used as a detergent. Thus, the underlined portion of the text functions to clarify the meaning of a scientific term."}, {"type": "paragraph", "text": "Choice B is incorrect. Though the text as a whole focuses broadly on an environmental concern, the underlined phrase does not; it simply indicates what a surfactant is. Choice C is incorrect. Though the text as a whole focuses on a scientific discovery (Liu and colleagues’ solution to the problem of plastic recycling), the underlined phrase does not explain its significance; it simply defines a scientific term used in the discussion. Choice D is incorrect. Though the text as a whole includes discussion of the result found by Liu and colleagues, the underlined phrase does not discuss it; it simply defines a scientific term used in the discussion. Additionally, at no point in the text is it mentioned that the team was confused."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Craft and Structure'), 'medium', 'source', 'approved', 7, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, 0, '{"blocks": [{"type": "paragraph", "text": "Which choice best describes the function of the underlined portion in the text as a whole?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice C is the best answer because it best describes the function of the underlined portion in the text as a whole. In the text, the speaker mentions the occurrence in nature of seedpods being shaken by a slight wind. The speaker then goes on to compare the black seeds to thoughts, using language that indicates that the speaker’s state of mind is unsettled (e.g., “my thoughts are spent”; “My thoughts tear me, I dread their fever”). The text concludes with a comparison between the speaker’s “scattered” state of mind and the “hot shrivelled seeds.” Thus, the underlined portion of the text presents an observation of an occurrence in the natural world that the speaker then expands on to convey a sense of a turbulent interior state."}, {"type": "paragraph", "text": "Choice A is incorrect because the text does not indicate that the seedpods are the cause of the speaker’s state of mind; thus, they could not be responsible for any misgivings the speaker has. Choice B is incorrect because the text does not contrast the natural landscape with the speaker’s state of mind or describe the wind shaking the seedpods as consistent; rather, the text suggests that the state of the natural world and the speaker’s state of mind are similar in that both are unsettled. Choice D is incorrect because there is no indication in the text that the speaker regularly engages in critical self-evaluation, only that in this particular instance the speaker’s state of mind is turbulent."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Craft and Structure'), 'medium', 'source', 'approved', 8, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, 0, '{"blocks": [{"type": "paragraph", "text": "Which choice best describes the function of the underlined portion in the text as a whole?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice A is the best answer because it most accurately describes how the underlined portion functions in the text as a whole. The first sentence of the text introduces literary scholar Jeremy Douglass’s warning to technology investors and enthusiasts against predicting the displacement of conventional books by newer media forms. The next sentence, which is underlined in part, presents Douglass’s observation that interactive texts are hardly new; they have been available for longer than technologists assume, beginning with the first time readers wrote notes in texts’ margins. Thus, the function of the underlined portion is to challenge the stance of the technology investors and enthusiasts mentioned earlier in the text. As the remainder of the text points out, newer media doesn’t necessarily replace older media, but rather, as Douglass believes, leads to new forms of expression."}, {"type": "paragraph", "text": "Choice B is incorrect because the underlined portion challenges the position taken by investors and enthusiasts; it doesn’t provide context for their claims."}, {"type": "paragraph", "text": "Choice C is incorrect because the underlined portion doesn’t mention academics or compare them to investors regarding their ability to see potential in using contemporary interactive texts; instead, the underlined portion challenges the position of investors and enthusiasts who predict that conventional books will be replaced by newer forms of media. Choice D is incorrect because the underlined portion doesn’t address technological challenges; instead, it disputes the stance taken by investors and enthusiasts, suggesting that conventional books haven’t been displaced by traditional interactions with texts, such as writing in the margins, and won’t be supplanted by newer forms of media either."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Craft and Structure'), 'medium', 'source', 'approved', 9, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which statement about M. robustus and the Octopus Garden is best supported by the text?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice A is the best answer because it most logically completes the text’s discussion of the M. robustus population at the Octopus Garden. The text states that the scientists concluded that the site is likely used only for reproduction because over three years they saw many adults, freshly hatched octopuses, and eggs but didn’t see any juveniles. This suggests that the M. robustus octopuses that hatch at the Octopus Garden leave the site when they reach an intermediary state of development, returning only as adults for reproductive purposes."}, {"type": "paragraph", "text": "Choice B is incorrect because the text never discusses the stability of the M. robustus population at the site, only that the scientists observed 6,000 adults, hatchlings, and eggs there. Further, the text presents the site’s temperatures as likely beneficial. Choice C is incorrect because the text doesn’t provide any details about the eggs at the site and makes no mention of nests; it indicates only that eggs are present along with hatchlings and adults. Choice D is incorrect because the text makes no mention of the hatchlings feeding at the Octopus Garden, indicating only that the temperatures at the site are probably beneficial and that the site is likely used for reproduction."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 10, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "What does the text most strongly suggest about the story of Hans Castorp?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice D is the best answer because it presents a statement about Hans Castorp’s story that is suggested by the text. The narrator of the text indicates that the story about Hans Castorp will be told not because there is something particularly notable about him, since he is pleasant but “perfectly ordinary,” but because the story itself is remarkable (“very much worth telling”). The narrator then notes that there is a benefit in being at the heart of the story—that it is “in Hans Castorp’s favor” that the story is his, and maybe uniquely so (“not every story happens to everybody”). Thus, the text suggests both that the story that will be told is a remarkable one that happened to an unremarkable person and that it is reasonable to argue that the person at the center of a valuable story takes on some of the story’s value."}, {"type": "paragraph", "text": "Choice A is incorrect. Although the narrator of the text makes the point that “not every story happens to everybody,” the narrator doesn’t state that stories are interesting simply because the people they are about are unique. Rather, the narrator suggests that one particular story is “very much worth telling” on its own and that Hans Castorp benefits from the fact that the story is remarkable and may be unique to him. Further, the narrator never suggests that the story will be hard to understand even though it is old. Choice B is incorrect. Although the narrator of the text suggests that Hans Castorp is of no particular importance, since he is a “perfectly ordinary” person, the narrator never reveals what makes the story of Castorp important, just that “the story itself” is “very much worth telling.” The narrator states that the story “took place long ago,” is “covered with the patina of history,” and can be told only “with verbs whose tense is that of the deepest past,” but the story’s age and the way it must be told aren’t presented as reasons the story is important; the narrator is simply providing details about how the story will be told. Choice C is incorrect because the narrator of the text doesn’t suggest that all stories about people who are “perfectly ordinary” (like Hans Castorp) must be told in particular ways to make it clear why those stories are consequential. Further, the narrator suggests that Hans Castorp’s story must be told “with verbs whose tense is that of the deepest past” because it took place so long ago, not because telling it that way will convey the story’s importance."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 11, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "According to the graph, about what percentage of participants mentioned costs in the interviews?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice D is the best answer because it states the percentage of participants who mentioned costs in the interviews conducted by Judith Hilton and her team. The text states that Hilton and her team interviewed participants about factors that would encourage them to switch from single-use plastic containers to reusable containers. The graph presents three factors mentioned in the interviews (convenience, costs, and established behaviors) and the percentage of participants who mentioned each one. The graph shows that about 50% of participants mentioned costs as a factor."}, {"type": "paragraph", "text": "Choice A is incorrect because the graph shows that about 50% of participants, not 10%, mentioned costs as a factor. Choice B is incorrect because the graph shows that about 50% of participants, not 95%, mentioned costs as a factor."}, {"type": "paragraph", "text": "Choice C is incorrect because the graph shows that about 50% of participants, not 25%, mentioned costs as a factor."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 12, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which quotation from a philosopher’s analysis of The Politics would best support the student’s claim?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice A is the best answer because it presents the quotation that best supports the student’s claim that in The Politics, Aristotle gives advice on preserving constitutions—preventing governments from falling and maintaining order—and specifically asserts that in a healthy state, laws must be followed as strictly as possible and infractions should not be overlooked even if they are minor. The philosopher states that when Aristotle builds his argument about the characteristics of a well-functioning government, Aristotle asserts that transgression, or violation of law, will ruin the state if it “creeps in unperceived,” or goes unnoticed. The philosopher then adds that Aristotle illustrates this point by comparing the situation to one in which small but frequent expenses diminish a fortune almost unnoticeably until, eventually, the fortune is entirely gone. In other words, the philosopher indicates that Aristotle makes the point that total obedience to law preserves a healthy state while even small violations, if ignored, will undermine the health of the state."}, {"type": "paragraph", "text": "Choice B is incorrect because the philosopher addresses Aristotle’s observation about corruption within the government (in particular, preventing the possibility that members of the government can take bribes), and although corruption can involve infractions, the observation is about a subset of people within the state and isn’t directly connected to the importance of upholding total obedience to the law throughout the state. Choice C is incorrect because the philosopher discusses Aristotle’s point about those who would intentionally destroy a constitution altogether and the need for rulers to remind the populace that it would be dangerous for a constitution to collapse, but neither idea is directly connected to the importance of upholding total obedience to the law. Choice D is incorrect because the philosopher explains that Aristotle makes the point that oligarchic leaders may retain power by having members of disenfranchised classes participate in government alongside governing classes, and this point doesn’t address the importance of ensuring obedience to the law and addressing even minor violations."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 13, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which finding from the study, if true, would most directly support the researchers’ conclusion?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice B is the best answer because it presents a finding that, if true, would most directly support the researchers’ conclusion that an observable pattern in time references in novels reflects a shift in human behavior prompted by the spread of electric lighting in the late nineteenth century. If novels published after 1880 contain significantly more references to activities occurring after 10 p.m. than novels from earlier periods do, this would suggest a change in human behavior and daily routines enabled by the availability of electric lighting. Before electric lighting—which provided illumination more easily than other available forms of light—many activities ceased after nightfall, so references to late-night activities would be less common in earlier novels. An increase in such references after 1880 would align with the researchers’ conclusion, reflecting an increase in late-night activities made possible by electric lighting."}, {"type": "paragraph", "text": "Choice A is incorrect because a decrease in references to 10 a.m. after the year 1800 would not support the researchers’ conclusion involving a shift in human behavior prompted by the spread of electric lighting toward the end of the 1800s. The time of 10 a.m. is in the morning and, in most places, characterized by daylight, so a change in references to that time would not be clearly linked to the impact of electric lighting. Choice C is incorrect because while an increase in implied time references relative to clock phrases in nineteenth-century novels could suggest a change in writing style or conventions, it does not directly support the conclusion involving a shift in human behavior prompted by the spread of electric lighting. The text indicates that the researchers’ conclusion is based on the content of the time references themselves, not the phrasing used."}, {"type": "paragraph", "text": "Choice D is incorrect. If references to noon and midnight are used with roughly the same frequency in all the novels analyzed by the researchers, this would reflect a lack of change in human behavior with regard to time and therefore would not support the researchers’ conclusion involving a shift in human behavior that occurred in response to the spread of electric lighting."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 14, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice most effectively uses data from the graph to complete the statement?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice A is the best answer because it most effectively uses data from the graph to complete the statement about Mahtta et al.’s proposal regarding factors that affect urban land expansion (ULE). According to the text, ULE is influenced by urban population growth and by gross domestic product (GDP) growth per capita. Reasoning that efficient national governments provide urban services and infrastructure needed to attract economic investment, Mahtta et al. suggest that, as governments become more efficient at providing urban services and infrastructure, GDP growth per capita will account for more ULE and urban population growth will account for less. But according to the graph, Region 1 saw an increase in the percentage attributed to urban population growth from 1970– 2000 (between 60 and 65%) to 2000–2014 (between 70 and 75%) and a decrease in the percentage attributed to GDP growth per capita from 1970–2000 (between 35 and 40%) to 2000–2014 (about 25%). Because the percentage attributed to GDP growth per capita decreased (the opposite of what Mahtta et al. claimed would happen if the governments had become more efficient), the data suggest that the governments of Region 1 became less efficient at providing urban services and infrastructure over that period."}, {"type": "paragraph", "text": "Choice B is incorrect. Neither the graph nor the text gives the regions’ relative levels of economic growth or what effect Mahtta et al. would expect such growth to have. Furthermore, Mahtta et al.’s proposal suggests that Region 1’s decline in the percentage of ULE attributed to GDP growth per capita from 1970–2000 (between 35 and 40%) to 2000–2014 (about 25%) would suggest decreasing, not increasing, government efficiency over this time. Choice C is incorrect. Neither the text nor the graph provides information about the relative efficiencies of different governments in Region 2. Choice D is incorrect. Mahtta et al.’s proposal suggests that more efficient governments will have a higher percentage of their ULE driven by GDP growth per capita and a lower percentage driven by urban population growth. For Region 2, the percentage of ULE attributed to GDP growth per capita increased from 1970–2000 (between 10 and 15%) to 2000–2014 (between 45 and 50%), but the opposite is true for Region 1, which saw the percentage of ULE attributed to GDP growth per capita decline over the same period. Thus, whereas the data suggest governments in Region 2 became more efficient, the data for Region 1 suggest that those governments became less efficient, not more."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 15, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice best describes data from the graph that support the student’s assertion?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice B is the best answer because it describes data from the graph that best support the student’s assertion that initial efforts at trade liberalization in China were shaped by firms having limited capital (assets available for use) and that this situation resolved during the 2000s. The text explains that an approach to trade liberalization involves engaging in processing imports, one type of which doesn’t require payment to a trade partner (processing with assembly) and one type of which requires upfront payment to a trade partner for raw materials (processing with inputs). The graph, which presents China’s imports for ordinary imports and both types of processing imports in the years 2000, 2003, and 2006, shows that while processing imports with assembly rose from about 250 hundred million dollars in 2000 to about 750 hundred million dollars in 2006, processing imports with inputs rose much more sharply, increasing from approximately 650 hundred million dollars in 2000 to about 2,300 hundred million dollars in 2006. Because processing with inputs requires firms to pay for materials (expending capital) and processing with assembly doesn’t, the sharper rise in processing imports with inputs suggests that Chinese firms’ assets—and thus their ability to engage in that type of processing imports—were relatively limited in (and before) 2000 and then substantially increased from 2000 to 2006. In other words, the data suggest that the situation of having limited capital resolved during the 2000s."}, {"type": "paragraph", "text": "Choice A is incorrect because the graph indicates that ordinary imports were greater than both types of processing imports in 2006, not that processing imports with inputs were greater than ordinary imports and processing imports with assembly that year. Choice C is incorrect because the observation that ordinary imports were greater than both types of processing imports in 2000, 2003, and 2006 doesn’t address a change within any type of imports from 2000 to 2006, and an indication of a change in that period that might be related to the availability of assets is needed to support the assertion that the situation of having limited capital resolved during the 2000s. Choice D is incorrect because the fact that processing imports with assembly were greater at the end of the period from 2000 to 2006 than processing imports with inputs were at the start of the same period doesn’t address a change within either type of imports during the period, and an indication of such a change that might be related to the availability of assets is needed to support the assertion that the situation of having limited capital resolved during the 2000s."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 16, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice most logically completes the text?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice C is the best answer because it most logically completes the text’s discussion of Kristin Laidre’s reasoning about the purpose of the tusk that many, but not all, narwhals have. The text explains that one group of scientists thinks the tusk may help narwhals detect the threat of freezing water and that Laidre disagrees with that idea, given the importance of avoiding a dangerous situation. It’s logical to suggest that if the tusk serves such an important purpose for narwhals, the trait would be more common among them—specifically, that more narwhals would have a tusk."}, {"type": "paragraph", "text": "Choice A is incorrect because there’s no reason to think Laidre would say that if the tusk has the important function of helping narwhals detect when the water around them is about to freeze (meaning that it isn’t always freezing), some narwhals would choose a different habitat altogether. Indeed, if it’s true that the tusk helps narwhals avoid areas with dangerous conditions when they occur in their Arctic Ocean habitat, the tusk would likely enable the narwhals to continue living in that habitat rather than drive them elsewhere entirely. Choice B is incorrect because the text focuses only on narwhals and makes no mention of other marine animals or how having a tusk might affect them. And if anything, it would be more logical to expect a very important trait to be more widespread, not less common, among other similar types of animals. Choice D is incorrect. Although the text describes narwhals as shy, it doesn’t indicate that the scientists’ conclusion has anything to do with shyness. And because shyness and detection of the threat of freezing water aren’t logically connected, there’s no reason to think that Laidre would expect narwhals to become less shy over time if the tusk serves that important purpose."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 17, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice most logically completes the text?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice D is the best answer because it most logically completes the text’s discussion of silicon carbide (SiC) fibers and creep, or deformation related to ongoing mechanical stress and elevated temperatures. The text states that Bhatt et al. found that a nitrogen-treated SiC fiber had a lower minimum creep rate than two polymer-derived SiC fibers did. Because having a lower creep rate means that the material is slower to deform with exposure to stress, as the text explains, this finding suggests that aerospace composites made with the nitrogen-treated SiC fiber may be able to withstand mechanical stress for a longer period than those made with the other two polymer-derived SiC fibers can."}, {"type": "paragraph", "text": "Choice A is incorrect because it overstates the implications of the study’s findings, which have to do with the rate of a material’s deformation under stress, not the absolute degree of deformation. The text states that Bhatt et al. observed that a nitrogen-treated SiC fiber had a lower minimum creep rate than two polymer-derived SiC fibers did, meaning only that it deformed more slowly over time under constant stress, not that it underwent less deformation overall."}, {"type": "paragraph", "text": "Choice B is incorrect because the text doesn’t establish any similarity between the two polymer-derived SiC fibers other than that both had a higher creep rate than the nitrogen-treated SiC fiber did in Bhatt et al.’s study. Moreover, reducing a material’s resistance to creep would mean that the material becomes more susceptible to deformation with exposure to stress and elevated temperatures, which would be expected to shorten rather than prolong the lifespan of machinery made with that material. Choice C is incorrect because the text suggests that the stability of aerospace equipment may be better improved by composites containing nitrogen-treated SiC fiber than by composites containing the two polymer-derived SiC fibers, not the other way around. The text indicates that Bhatt et al. observed that the nitrogen-treated SiC fiber had a lower minimum creep rate than the other two fibers did, meaning that it was slower to degrade under exposure to mechanical stress and elevated temperatures—suggesting that it may remain stable for longer periods."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 18, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text so that it conforms to the conventions of Standard English?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice A is the best answer. The convention being tested is the use of verb forms within a sentence. The singular verb “describes” agrees in number with the singular subject “map.”"}, {"type": "paragraph", "text": "Choice B is incorrect because the plural verb “describe” doesn’t agree in number with the singular subject “map.” Choice C is incorrect because the plural verb “have described” doesn’t agree in number with the singular subject “map.”"}, {"type": "paragraph", "text": "Choice D is incorrect because the plural verb “are describing” doesn’t agree in number with the singular subject “map.”"}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Standard English Conventions'), 'medium', 'source', 'approved', 19, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text so that it conforms to the conventions of Standard English?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice D is the best answer. The convention being tested is the use of determiners in a sentence. The plural determiner “these” agrees in number with the plural noun “letters” that it modifies. This choice clearly indicates that the letters demonstrate Alcott’s business sense."}, {"type": "paragraph", "text": "Choice A is incorrect because the singular determiner “one” doesn’t agree in number with the plural noun “letters.” Choice B is incorrect because the singular determiner “that” doesn’t agree in number with the plural noun “letters.” Choice C is incorrect because the singular determiner “this” doesn’t agree in number with the plural noun “letters.”"}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Standard English Conventions'), 'medium', 'source', 'approved', 20, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text so that it conforms to the conventions of Standard English?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice D is the best answer. The convention being tested is the use of verbs to express tense in a sentence. In this choice, the past tense verb “affected,” used in conjunction with the phrase “during this time,” correctly indicates that the dust storms occurred in the 1930s."}, {"type": "paragraph", "text": "Choice A is incorrect because the present progressive tense verb “are affecting” doesn’t indicate that the dust storms occurred in the 1930s. Choice B is incorrect because the future perfect tense verb “will have affected” doesn’t indicate that the dust storms occurred in the 1930s. Choice C is incorrect because the future tense verb “will affect” doesn’t indicate that the dust storms occurred in the 1930s."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Standard English Conventions'), 'medium', 'source', 'approved', 21, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text so that it conforms to the conventions of Standard English?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice C is the best answer. The convention being tested is the coordination of main clauses within a sentence. This choice correctly uses a comma and a coordinating conjunction (“but”) to join the first main clause (“Leibniz...century”) and the second main clause (“these ingenious...calculators”)."}, {"type": "paragraph", "text": "Choice A is incorrect because it results in a run-on sentence. The two main clauses are fused without punctuation and/or a conjunction. Choice B is incorrect because it results in a comma splice. Without a conjunction following it, a comma can’t be used in this way to join two main clauses. Choice D is incorrect because joining the two main clauses in this way with the subordinating conjunction “that” results in an ungrammatical and illogical sentence."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Standard English Conventions'), 'medium', 'source', 'approved', 22, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text so that it conforms to the conventions of Standard English?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice C is the best answer. The convention being tested is the use of verb forms within a sentence. The nonfinite past participle “characterized” is correctly used within a supplementary element that modifies the main clause “Zhang...shanshui,” defining qinglü shanshui and explaining some of its identifying traits."}, {"type": "paragraph", "text": "Choice A is incorrect because it results in a comma splice. Using the finite present perfect tense verb “has been characterized” creates a second main clause in the sentence, and the two main clauses can’t be joined in this way by only the comma before “a type.” Choice B is incorrect because it results in a comma splice. Using the finite future tense verb “will be characterized” creates a second main clause in the sentence, and the two main clauses can’t be joined in this way by only the comma before “a type.” Choice D is incorrect because it results in a comma splice. Using the finite present tense verb “is characterized” creates a second main clause in the sentence, and the two main clauses can’t be joined in this way by only the comma before “a type.”"}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Standard English Conventions'), 'medium', 'source', 'approved', 23, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text so that it conforms to the conventions of Standard English?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice A is the best answer. The convention being tested is punctuation use between sentences. In this choice, the period is used correctly to mark the boundary between one sentence (“What…vapor”) and another (“With…point”)."}, {"type": "paragraph", "text": "Choice B is incorrect because it results in a run-on sentence. The sentences (“What…vapor” and “with…point”) are fused without punctuation and/or a conjunction. Choice C is incorrect because it results in a comma splice. A comma can’t be used in this way to mark the boundary between sentences. Choice D is incorrect. Without a comma preceding it, the conjunction “and” can’t be used in this way to join sentences."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Standard English Conventions'), 'medium', 'source', 'approved', 24, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text so that it conforms to the conventions of Standard English?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice D is the best answer. The convention being tested is subject-modifier placement. This choice makes the noun phrase “the Alaska Centennial Commission” the subject of the sentence and places it immediately after the modifying phrase “wanting…Purchase.” In doing so, this choice clearly establishes that the Alaska Centennial Commission—and not another noun in the sentence— wanted to celebrate the 100th anniversary of the Alaska Purchase."}, {"type": "paragraph", "text": "Choice A is incorrect because it results in a dangling modifier. The placement of the noun phrase “a contest” immediately after the modifying phrase illogically suggests that the contest wanted to celebrate the 100th anniversary of the Alaska Purchase. Choice B is incorrect because it results in a dangling modifier. The placement of the noun phrase “an award of $\\$300$” immediately after the modifying phrase illogically suggests that the award of $\\$300$ wanted to celebrate the 100th anniversary of the Alaska Purchase. Choice C is incorrect because it results in a dangling modifier. The placement of the noun phrase “$\\$300$” immediately after the modifying phrase illogically suggests that the $\\$300$ wanted to celebrate the 100th anniversary of the Alaska Purchase."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Standard English Conventions'), 'medium', 'source', 'approved', 25, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text so that it conforms to the conventions of Standard English?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice D is the best answer. The convention being tested is the use of punctuation within a sentence. This choice correctly uses a comma to mark the boundary between the main clause (“Recently...supposed”) and the supplementary element (“a finding...Paleolithic”) that provides additional information about the implications of the Neronian tool discovery."}, {"type": "paragraph", "text": "Choice A is incorrect because a semicolon can’t be used in this way to join the main clause (“Recently...supposed”) and the supplementary element (“a finding... Paleolithic”). Choice B is incorrect because it results in a rhetorically unacceptable sentence fragment beginning with “a finding.” Choice C is incorrect because it results in a run-on sentence. The main clause (“Recently...supposed”) and the supplementary element (“a finding...Paleolithic”) are fused without punctuation and/or a conjunction."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Standard English Conventions'), 'medium', 'source', 'approved', 26, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text with the most logical transition?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice A is the best answer. “Additionally” logically signals that guard cells’ role in regulating water loss is an additional function of these specialized plant cells that is separate from the function of regulating carbon dioxide intake."}, {"type": "paragraph", "text": "Choice B is incorrect because “previously” illogically signals that the activity described in this sentence occurs earlier in a chronological sequence of events than the regulation of carbon dioxide intake described in the previous sentence. Instead, regulating water loss is an additional function of guard cells that is separate from the function of regulating carbon dioxide intake. Choice C is incorrect because “in conclusion” illogically signals that the description of guard cells’ role in regulating water loss concludes or summarizes the information about guard cells provided in the previous sentences. Instead, regulating water loss is one of the two distinct functions of guard cells described in the text. Choice D is incorrect because “instead” illogically signals that the activity described in this sentence happens in place of the activity of regulating carbon dioxide intake described in the previous sentence. Rather, regulating water loss is an additional function of guard cells."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Expression of Ideas'), 'medium', 'source', 'approved', 27, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice most effectively uses relevant information from the notes to accomplish this goal?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice D is the best answer. The sentence identifies the type of scientist Chaudhuri is, noting that she is a sedimentologist."}, {"type": "paragraph", "text": "Choice A is incorrect. The sentence provides an example of a type of sedimentary rock; it doesn’t identify what type of scientist Chaudhuri is. Choice B is incorrect. The sentence indicates types of rock that some scientists study; it doesn’t identify what type of scientist Chaudhuri is. Choice C is incorrect. While the sentence states that some scientists study sedimentary rocks, it doesn’t identify Chaudhuri as this type of scientist."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 28, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice most effectively uses relevant information from the notes to accomplish this goal?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice A is the best answer. The sentence indicates where “Raymond’s Run” takes place, stating that it takes place in Harlem."}, {"type": "paragraph", "text": "Choice B is incorrect. The sentence identifies the book in which the story “Raymond’s Run” was published; it doesn’t indicate where the story takes place."}, {"type": "paragraph", "text": "Choice C is incorrect. The sentence indicates the point of view used in “Raymond’s Run”; it doesn’t indicate where the story takes place. Choice D is incorrect. The sentence identifies the author of “Raymond’s Run”; it doesn’t indicate where the story takes place."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 29, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice most effectively uses relevant information from the notes to accomplish this goal?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice C is the best answer. The sentence contrasts the two styles of tiles, noting that tiles in the arista style have designs stamped into them, whereas tiles in the majolica style have designs painted directly on them."}, {"type": "paragraph", "text": "Choice A is incorrect because the sentence indicates that the two styles of tile can be found in the same location; it doesn’t contrast the two styles of tile."}, {"type": "paragraph", "text": "Choice B is incorrect because the sentence indicates that the Royal Alcázar of Seville features tiles in both the majolica and arista styles; it doesn’t contrast the two styles of tile. Choice D is incorrect because the sentence indicates that the tilework of the Royal Alcázar of Seville includes tiles in the majolica style; it doesn’t contrast tiles in the majolica style with tiles in the arista style."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 30, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice most effectively uses relevant information from the notes to accomplish this goal?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice B is the best answer. The sentence contrasts the two songs, noting that “Poor Miner’s Farewell” is about coal miners in Kentucky, whereas “Bring Him Back Home” is about Nelson Mandela."}, {"type": "paragraph", "text": "Choice A is incorrect. The sentence emphasizes a similarity between “Poor Miner’s Farewell” and “Bring Him Back Home”; it doesn’t contrast the two songs."}, {"type": "paragraph", "text": "Choice C is incorrect. While the sentence provides a description of the song “Bring Him Back Home,” it doesn’t mention “Poor Miner’s Farewell” or contrast the two songs. Choice D is incorrect. While the sentence provides a description of the song “Poor Miner’s Farewell,” it doesn’t mention “Bring Him Back Home” or contrast the two songs."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 31, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice most effectively uses relevant information from the notes to accomplish this goal?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice C is the best answer. Using a quotation from Stewart, the sentence challenges Thucydides’s explanation that the rise of Athens caused the conflict, suggesting that it was instead caused by a “clash of cultures.”"}, {"type": "paragraph", "text": "Choice A is incorrect. While the sentence uses a quotation, the quotation doesn’t challenge Thucydides’s explanation of the conflict. Choice B is incorrect. While the sentence mentions that Stewart challenged Thucydides’s explanation of the conflict, it doesn’t use a quotation to challenge Thucydides’s explanation: the quoted word “inevitable” is from Thucydides. Choice D is incorrect. While the sentence appears to refute Thucydides’s explanation, it does so in a way that misrepresents the information in the notes; Allison’s Thucydides trap theory is based on Thucydides’s explanation of the conflict. Thus, Allison’s theory affirms, rather than challenges, Thucydides’s explanation."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 32, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice most effectively uses relevant information from the notes to accomplish this goal?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice D is the best answer. The sentence presents an overview of the study’s findings, noting that, for some of the languages (the examples of Spanish and Vietnamese are given in the notes), the number of syllables spoken per second varied, while the amount of information conveyed per second remained roughly constant across all 17 languages."}, {"type": "paragraph", "text": "Choice A is incorrect. While the sentence describes one of the metrics the study assessed, it doesn’t present any of the study’s findings. Choice B is incorrect. While the sentence compares specific findings about two of the languages studied, it doesn’t provide an overview of the study’s findings across all 17 languages. Choice C is incorrect. The sentence compares specific findings about two of the languages studied; it doesn’t provide an overview of the study’s findings across all 17 languages. It also misrepresents the information from the notes about Spanish’s information rate."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 33, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text with the most logical and precise word or phrase?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice C is the best answer because it most logically completes the text’s discussion of carte de visite photos. To “popularize” a technology is to allow it to be used and appreciated widely. The text explains that unlike the photos produced by earlier forms of photographic technology, carte de visite photos were inexpensive and could easily be obtained by “everyday people,” who enjoyed exchanging the images. Therefore, carte de visite photos helped popularize photography."}, {"type": "paragraph", "text": "Choice A is incorrect because the text indicates that instead of weakening the emerging technology of photography, carte de visite photos allowed it to be more widely accessed and enjoyed by people. Choice B is incorrect. The text establishes that large numbers of people enjoyed using carte de visite photos, so it can be inferred that these photos caused photography to be praised, or celebrated. However, it wouldn’t make sense to say that inanimate objects—in this case, photos—had praised photography; instead, carte de visite consumers themselves would have praised it. Choice D is incorrect because the text explains that rather than isolating photography, or limiting its availability, carte de visite technology made photography more widely accessible to people."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Craft and Structure'), 'medium', 'source', 'approved', 1, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text with the most logical and precise word or phrase?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice D is the best answer because it most logically completes the text’s discussion of painter Alma W. Thomas’s work. In this context, “influenced” means to have had an effect on something’s development. The text indicates that there is a connection between Thomas’s work and the flowers and trees in her home’s garden, giving the example of Thomas’s brushstrokes being inspired by light shining through the leaves of a tree in front of her house. This context conveys that Thomas’s work was influenced by the flowers and trees in the garden."}, {"type": "paragraph", "text": "Choice A is incorrect because the text conveys that Thomas drew inspiration for her work from the plants in her garden, which suggests that the flowers and trees contributed positively to her work, not that they “restricted,” or limited, her work."}, {"type": "paragraph", "text": "Choice B is incorrect because it wouldn’t make sense to suggest that flowers and trees in a garden could have “announced,” or made known, a painter’s work."}, {"type": "paragraph", "text": "Choice C is incorrect because the text conveys that Thomas drew inspiration for her work from the plants in her garden, which suggests that the flowers and trees contributed positively to her work, not that they were a distraction. Further, it’s not clear how an artist’s work could itself be “distracted.”"}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Craft and Structure'), 'medium', 'source', 'approved', 2, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text with the most logical and precise word or phrase?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice C is the best answer because it most logically completes the text’s discussion of the conservationists’ efforts to increase Azores bullfinch’s numbers. In this context, “successful” means accomplishing a goal or purpose. According to the text, conservationists planted more than 500,000 native trees in an Azores bullfinch habitat in order to boost the bird’s population size. The text then indicates that the population size did indeed grow as a result of the planted trees. Thus, in this context, the conservationists’ approach of planting native trees was successful because it achieved the goal of increasing the bird’s population size."}, {"type": "paragraph", "text": "Choice A is incorrect because the text gives no indication that the conservationists’ approach of planting native trees to increase Azores bullfinch’s numbers was “amusing,” or comical or entertaining. Instead, the approach was seriously undertaken and ultimately accomplished. Choice B is incorrect because the text doesn’t address how much it cost to achieve the goal of planting native trees to increase Azores bullfinch’s numbers. The text indicates that the approach was beneficial and successful rather than “costly,” or expensive or harmful."}, {"type": "paragraph", "text": "Choice D is incorrect. According to the text, the conservationists’ approach of planting native trees to increase Azores bullfinch’s numbers was beneficial and successful rather than “disastrous,” or damaging or unsuccessful."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Craft and Structure'), 'medium', 'source', 'approved', 3, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text with the most logical and precise word or phrase?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice D is the best answer because it most logically completes the text’s discussion of the duration of gamma ray burst GRB 230307A. In this context, “an oddity” is something that is odd or unusual. The text explains that the burst lasted for 200 seconds and that other bursts generated by neutron mergers have usually lasted fewer than 2 seconds. In other words, the duration of gamma ray burst GRB 230307A was unusual."}, {"type": "paragraph", "text": "Choice A is incorrect because the text focuses on a difference between the duration of gamma ray burst GRB 230307A and the typical duration of bursts caused by neutron mergers, not “a coincidence,” or a point of correspondence, between them; the text indicates that GRB 230307A lasted much longer than what is typical of other bursts. Choice B is incorrect. In this context, “a reprieve” would be either a temporary relief from something or a delay of a punishment, neither of which would make sense as something that the duration of a gamma ray burst could provide to the burst itself. Choice C is incorrect. Although it would make sense to refer to gamma ray burst GRB 230307A itself as “an incident,” or a thing that occurred, the missing word describes the duration of the burst, and it doesn’t make much sense to describe a length of time as an incident. Further, the sentence emphasizes that the burst’s duration was very unusual, not simply that the burst occurred."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Craft and Structure'), 'medium', 'source', 'approved', 4, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text with the most logical and precise word or phrase?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice B is the best answer because it most logically completes the text’s discussion of Benjamin Franklin’s popularity in France. In this context, “esteem” means high regard. The text indicates that Franklin was very popular, or highly regarded, in France, where he sought the country’s support for the United States in its fight for independence, and indicates that his status helped him achieve his goal. The context therefore suggests that being held in high regard by the people likely helped Franklin convince France to help the United States."}, {"type": "paragraph", "text": "Choice A is incorrect because the text directly indicates that it was Franklin’s popularity that likely helped him convince France to help the United States, not his “thoughtfulness” (which in this context would mean either his careful reasoning and attention or his kind consideration of others’ needs). Choice C is incorrect because the text doesn’t suggest that there was any “controversy,” or dispute, about Franklin’s presence in France; instead, the text states that Franklin was very popular in France and directly indicates that this status likely helped him convince France to help the United States. Choice D is incorrect because the text directly indicates that it was Franklin’s popularity that likely helped him convince France to help the United States, not his “sincerity,” or his honesty."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Craft and Structure'), 'medium', 'source', 'approved', 5, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, 0, '{"blocks": [{"type": "paragraph", "text": "Which choice best describes the function of the underlined sentence in the text as a whole?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice A is the best answer because it most accurately describes how the underlined sentence functions in the text as a whole. The first sentence of the text establishes that scientists didn’t know much about the ocean floor in the 1950s. The second sentence, which is underlined, describes what many scientists thought at the time—that the ocean floor was mostly flat. The remainder of the text establishes that the ocean floor is far from flat, citing research conducted by Marie Tharp and Bruce Heezen. Thus, the purpose of the underlined sentence is to identify a scientific belief that Tharp and Heezen showed to be wrong."}, {"type": "paragraph", "text": "Choice B is incorrect. Although Tharp and Heezen’s work with sonar data in the Atlantic Ocean is mentioned later in the text, the underlined sentence doesn’t describe the design of their experiment. Instead, it identifies a belief held by scientists that Tharp and Heezen demonstrated to be wrong. Choice C is incorrect because the underlined sentence presents a belief held by many scientists in the 1950s; nowhere does the text mention a disagreement between Tharp and Heezen, whom the text describes as research partners working together to map the ocean floor. Choice D is incorrect because the underlined sentence doesn’t present data in support of a claim; instead, it presents a scientific belief that Tharp and Heezen’s work showed to be wrong."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Craft and Structure'), 'medium', 'source', 'approved', 6, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, 0, '{"blocks": [{"type": "paragraph", "text": "Which choice best describes the function of the underlined phrase in the text as a whole?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice B is the best answer because it accurately describes the function of the underlined phrase in the text as a whole. According to the text, advertisers were reluctant to support television in its early days. The underlined phrase then indicates that this reluctance was partly due to the US’s involvement in World War II, which hindered television production. Thus, the underlined phrase identifies a specific reason behind some advertisers’ hesitance to support television."}, {"type": "paragraph", "text": "Choice A is incorrect. The text merely mentions that television was expected to be financed through advertising, as radio was at the time. Nothing in the text compares the origins of radio and television. Choice C is incorrect. The underlined phrase focuses on a reason advertisers were reluctant to support television, not measures taken to convince advertisers to support television. Choice D is incorrect. The underlined phrase focuses on a reason advertisers were reluctant to support television, not what types of television programming were popular."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Craft and Structure'), 'medium', 'source', 'approved', 7, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, 0, '{"blocks": [{"type": "paragraph", "text": "Which choice best describes the function of the underlined sentence in the text as a whole?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice B is the best answer because it most accurately describes the function of the underlined sentence in the text as a whole. The text discusses the Bayeux Tapestry, making the point that the workers who produced the huge tapestry in the eleventh century might not have ever produced a tapestry so large before. The text goes on to suggest that because of this lack of previous experience, the workers developed and refined the process of joining the tapestry’s panels over time as they worked. The last sentence of the text then provides an example of an observation that suggests the workers’ process changed: clear misalignment of the borders of the two panels the workers joined first and virtually invisible joins completed later. Thus, the underlined sentence serves to support an argument about the workers who produced the tapestry."}, {"type": "paragraph", "text": "Choice A is incorrect because the example given in the last sentence of the text has to do with how the panels of the Bayeux Tapestry were joined by the workers, not with what is depicted in those panels; the text never identifies any people or places depicted in the tapestry. Choice C is incorrect because the last sentence compares how early panels in the Bayeux Tapestry were joined with how later panels in the same tapestry were joined; it doesn’t make any comparison between the Bayeux Tapestry and other tapestries from the same time in France. Choice D is incorrect because the last sentence doesn’t address the location where the Bayeux Tapestry was created; the first sentence of the text presents it as a given that the tapestry was created in France, but nothing in the text indicates how that origin was determined."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Craft and Structure'), 'medium', 'source', 'approved', 8, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Based on the texts, how would the author of Text 2 most likely respond to what “some researchers contend” as described in Text 1?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice D is the best answer because it reflects how the author of Text 2 would most likely respond to what the researchers mentioned in Text 1 contend. Text 1 discusses the lack of knowledge of how plate tectonics on Earth began. Text 1 also mentions researchers who contend that movements of tectonic plates began around 3 billion years ago. As support for this assertion, these researchers cite computer models (which are simulations, not empirical evidence) of the temperature in Earth’s mantle that show that at that time, the mantle would have been sufficiently molten for plates to move. However, the author of Text 2 asserts that empirical evidence from the geological record is necessary to make plausible claims about when tectonic movement began. Text 2 mentions an analysis performed by Wriju Chowdhury and his team of the geochemistry of zircon crystals (which would constitute empirical evidence). Chowdhury and his team argue, based on this analysis, that tectonic plates may have begun to move as early as 4.2 billion years ago. Therefore, since the author of Text 2 would consider Chowdhury et al.’s empirical evidence to be more conclusive than the computer models cited in Text 1, the author of Text 2 would most likely assert that a more definitive form of evidence than the computer models suggests a different timeline for the onset of plate tectonics on Earth."}, {"type": "paragraph", "text": "Choice A is incorrect because the author of Text 2 makes no claims about the temperature of Earth’s mantle and therefore wouldn’t argue that the temperature of Earth’s mantle 3 billion years ago was insufficient to allow tectonic movement."}, {"type": "paragraph", "text": "Choice B is incorrect because the author of Text 2 claims that empirical evidence is needed to fix the earliest date of tectonic movement. Computer models are simulations, not empirical evidence, so the author of Text 2 wouldn’t distinguish between different kinds of computer models but would instead argue that no computer models can reliably predict the onset of plate tectonics. Choice C is incorrect because the author of Text 2 wouldn’t consider any computer model to be able to provide evidence to support a plausible claim about tectonic movement, no matter how much such models were improved. The author of Text 2 would only accept empirical evidence."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Craft and Structure'), 'medium', 'source', 'approved', 9, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "What feature of Hevea brasiliensis does the text say is helpful for the process of making rubber?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice B is the best answer because it most accurately states what feature of Hevea brasiliensis is helpful for the process of making rubber. According to the text, this tree species produces latex, which is used to make rubber, and its inner bark contains a “network of tubes” that, when cut, enables the latex to flow out. The text explicitly states that this feature of Hevea brasiliensis is “helpful for the process of making rubber.”"}, {"type": "paragraph", "text": "Choice A is incorrect because the text doesn’t mention the quality of the rubber produced from the latex of Hevea brasiliensis or compare its quality to that of rubber produced from other sources. Choice C is incorrect because the text never discusses the climates in which Hevea brasiliensis grows. Moreover, the text mentions only one region where this tree is found: the Amazon rainforest."}, {"type": "paragraph", "text": "Choice D is incorrect. Because the text states that Hevea brasiliensis is the world’s “main source of natural rubber,” it can be inferred that there is at least one other source. However, the text doesn’t specify whether that other source is also a tree species and, if so, whether that species grows in the Amazon rainforest."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 10, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice best states the main idea of the text?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice B is the best answer because it best states the main idea of the text: that nature-based approaches can be effective for achieving conservation goals. The text indicates that in many cases where conservationists are trying to protect ecosystems, their methods depend on natural processes or features. The text then gives an example of this phenomenon, a project with the Quinault Indian Nation that allowed logjams to form naturally in a river, creating spawning habitats for blueback salmon."}, {"type": "paragraph", "text": "Choice A is incorrect. Although the text does suggest that the partnership with the Quinault Indian Nation was beneficial, this is not the central aim of the text; the text primarily argues that nature-based approaches to conservation can be effective. Choice C is incorrect. Although the text indicates that logjams are helpful to blueback salmon, the example of the blueback salmon project is included to illustrate the larger point made earlier in the text: that nature-based approaches to conservation are often effective. Choice D is incorrect. There is no evidence in the text to support a direct comparison of the efficacy of nature- based conservation approaches to other types of approaches. The text merely indicates that nature-based approaches can often be effective."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 11, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice most effectively uses data from the table to complete the student’s claim?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice D is the best answer because it effectively uses data from the table to complete the student’s claim about the highest percentage of bus stops with shaded shelter in the areas represented. The table shows the highest average surface temperature of five areas and the percentage of bus stops with shaded shelter in each area, and 29% is the highest percentage listed."}, {"type": "paragraph", "text": "Choice A is incorrect because the list of percentages of bus stops with shaded shelter does not include 50%; the highest percentage in the table is 29%."}, {"type": "paragraph", "text": "Choice B is incorrect because 15% is the lowest value in the listed percentages of bus stops with shaded shelter, not the highest value. Choice C is incorrect because the list of percentages of bus stops with shaded shelter does not include 90%; the highest percentage in the table is 29%."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 12, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "According to the table, what is the total area of Bahrain?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice C is the best answer because it states the total area of Bahrain that is indicated in the table. The table presents the total area (in square miles) and population for Bahrain, Qatar, and Kuwait, and it indicates that the total area of Bahrain is 304 square miles."}, {"type": "paragraph", "text": "Choice A is incorrect because the table indicates that 4,268,873 is the population of Kuwait, not the total area of Bahrain. Choice B is incorrect because the table indicates that 4,471 square miles is the total area of Qatar, not of Bahrain."}, {"type": "paragraph", "text": "Choice D is incorrect because the table indicates that 6,880 square miles is the total area of Kuwait, not of Bahrain."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 13, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, 0, '{"blocks": [{"type": "paragraph", "text": "Which quotation from an article about Echelman’s sculptures, if true, would most effectively illustrate the underlined claim?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice C is the best answer because it presents the quotation that most effectively illustrates the claim that Echelman’s sculptures appear delicate but are in fact quite durable. The text explains that Echelman’s sculptures include flowing shapes that mimic the wind. If it is true that the materials she uses are both flexible and strong, that would help explain why the works are durable even though they appear delicate."}, {"type": "paragraph", "text": "Choice A is incorrect because the claim in the text is not about how Echelman models her work before sculpting. Choice B is incorrect because the claim in the text is not about the planning and design phases of Echelman’s work. Choice D is incorrect because the claim in the text is not about how the sculptures relate to their locations."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 14, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which finding, if true, would most directly support the researchers’ conclusion?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice D is the best answer because it presents a finding that, if true, would most directly support the researchers’ conclusion that the transition from a stagnant lid regime to a tectonic plate regime occurred around 3.2 billion years ago. The text explains that early in Earth’s history, Earth exhibited a stagnant lid regime in which there’s no interaction between the lithosphere and the underlying mantle. The text further explains that, by contrast, once Earth began to exhibit a tectonic plate regime, its lithospheric and mantle material began to mix. If mantle-derived rocks younger than 3.2 billion years contain material not found in older mantle-derived rocks, that material must have originated somewhere other than the mantle. And if this material is found in both older and contemporaneous lithospheric rocks, that would imply that the lithosphere was able to mix with mantle material beginning around 3.2 billion years ago, as the researchers concluded."}, {"type": "paragraph", "text": "Choice A is incorrect. The text gives no basis for comparing the quantities of lithospheric and mantle-derived rocks. Choice B is incorrect. The text gives no basis for comparing the material makeup of lithospheric rocks to that of mantle- derived rocks. Choice C is incorrect. A positive correlation between the age of lithospheric rocks and these rocks’ chemical similarity to mantle-derived rocks would mean that the oldest rocks would be the most similar, which contradicts the text’s claim that lithospheric and mantle-derived rocks were completely separate until 3.2 billion years ago. If the researchers’ conclusion about the onset of tectonics on Earth is correct, then younger lithospheric rocks would show greater chemical similarity to mantle-derived rocks than older lithospheric rocks do."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 15, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice most logically completes the text?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice D is the best answer because it most logically completes the discussion of Uto-Aztecan languages. The text explains that the northern and southern branches of the Uto-Aztecan language family descended from a single language (believed to have originated in what is now the US Southwest), resulting in similarities across the family’s languages; however, the branches don’t have similar vocabulary for maize, even though maize has been cultivated by all Uto-Aztecan tribes. The text also indicates that maize originated in Mexico and spread northward into what is now the US Southwest—the area where the Uto-Aztecan language family originated. It follows, then, that the language family had already divided into northern and southern branches before maize reached that area; if maize had been present before the division occurred, the family’s origin language would have had terminology for it that likely would have been reflected in the branches, meaning they would have had similar vocabulary for maize. If maize arrived after the division occurred, however, the tribes in the two regions likely would have developed vocabulary pertaining to maize separately, at the times when they acquired the crop."}, {"type": "paragraph", "text": "Choice A is incorrect because the text focuses on vocabulary pertaining to maize in the branches of the Uto-Aztecan language family, and referring only to how some Uto-Aztecan tribes obtained maize wouldn’t directly address the role of language. Moreover, if northern Uto-Aztecan tribes had acquired maize from a southern Uto-Aztecan tribe, it’s reasonable to assume that the northern tribes might have also picked up southern Uto-Aztecan terminology for maize in that exchange. Choice B is incorrect because the text discusses the fact that the northern and southern branches of the Uto-Aztecan language family don’t have shared vocabulary pertaining to maize, not the idea that there are variations in such vocabulary within each branch—that is, the text focuses on differences between the two branches, not on differences between languages within a branch. Choice C is incorrect because the text focuses on vocabulary pertaining to maize in the branches of the Uto-Aztecan language family, and referring only to the timing and source of maize acquisition wouldn’t directly address the role of language. Furthermore, the text implies that southern Uto-Aztecan tribes probably acquired maize before the northern tribes did, given the evidence that maize originated in Mexico—the location of the best-known representative of the southern branch of the Uto-Aztecan language family—before spreading to the north."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 16, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice most logically completes the text?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice B is the best answer because it most logically completes the text’s discussion of the sediments found at the Gale Crater’s Murray Formation on Mars. The text states that data gathered by the Curiosity rover suggest that bodies of water deposited sediment on Mars’s surface long ago. The text goes on to say that studying the sediment, Rivera-Hernández et al. found some coarse grains they believe are sandstone, which tends to be left by flowing water, and many more fine grains they believe are mudstone, which tends to slowly sink in low-flow water. The text further indicates that the researchers noted cracks in the fine grains that suggest there were cycles of desiccation, or drying, at the site. Taken together, this information suggests that a lake (a body of low-flow water) existed at the site for a prolonged period but occasionally experienced drying and that there were periods in which one or more streams (flowing water) were present, since the extended existence of a lake would account for the abundance of fine grains, periods of drying would account for the cracks in the fine grains, and periods with streams would account for the sections of coarse grains."}, {"type": "paragraph", "text": "Choice A is incorrect because the text indicates that an abundance of fine grains of sediment was found at the Murray Formation site, which suggests that a low-flow water source (such as a lake) was present. Further, the text makes no mention of where the water at the site may have originated from. Choice C is incorrect because the evidence described in the text doesn’t support the idea that there were streams at the Murray Formation for an extended period and a lake for just a short time. The abundance of fine grains suggests that a lake (a body of low-flow water) was present for an extended time, not just a short time, and the sections of coarse grains suggest that one or more streams (bodies of flowing water) were intermittently present while the lake existed, not at a separate time. Choice D is incorrect. Although the text suggests that both a low-flow body of water (such as a lake) and flowing water (such as streams) existed at the Murray Formation site, meaning that there could have been a stream-fed lake, the text explains that the fine grains that signify the presence of a lake exhibit cracking that indicates periods of desiccation, or drying, which suggests that a lake was present but did occasionally dry out."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 17, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice most logically completes the text?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice B is the best answer because it most logically completes the text’s discussion of Sidonian coins. As the text explains, researchers determined that Sidonian coins were made of silver and copper and that from 450 BCE to 367 BCE, the percentage of silver in each coin decreased from 98% to 74.2% while the percentage of copper increased from 1% to 24.7%. The text indicates that because the coins containing less than 80% silver weren’t considered suitable for trade (suggesting that copper was less valuable than silver) and looked different from coins containing more silver, the researchers suspect there was a serious loss in confidence in the currency in Sidon in 367 BCE when the copper content was high. It’s reasonable to assume that it wasn’t possible to boost confidence simply by devoting a greater amount of valuable silver to the currency, since Sidon was under significant and ongoing financial pressure; however, keeping the total amount of silver the same and reducing the amount of copper in the coins would have resulted in smaller coins with a higher percentage of silver. Therefore, it makes sense to suggest that Abd’aštart I (the ruler after 367 BCE) likely restored confidence in the currency by deciding to keep the amount of silver in Sidonian coins consistent with that in coins minted in 367 BCE but to decrease the coins’ weight."}, {"type": "paragraph", "text": "Choice A is incorrect because the text conveys that a crisis in confidence in the currency of Sidon likely occurred around 367 BCE because the percentage of silver in coins had fallen below 80% (presumably because Sidon’s financial pressures meant that less silver was available for currency), making the coins unsuitable for trade. Thus, announcing that the threshold for the percentage of silver in coins would be raised—that is, that coins would need to contain even more than 80% silver to be suitable for trade—likely would have worsened the crisis rather than relieved it. Choice C is incorrect because the text strongly suggests that a crisis in confidence in the currency of Sidon was caused by the proportion of silver to copper in the coins in 367 BCE, with 74.2% being too little silver for the coins to be considered suitable for trade; therefore, it’s unlikely that minting coins with a similar proportion of silver to copper (that is, still around 74.2% silver) would have restored confidence, even if the coins were heavier."}, {"type": "paragraph", "text": "Choice D is incorrect because the text gives no indication that funding the mining of more copper would have relieved a crisis in confidence in the currency of Sidon. The text establishes that Sidonian coins that visibly contained copper weren’t considered suitable for trade, so Abd’aštart I wouldn’t have wanted to add even more copper to them, and it’s unclear how else copper mining would affect views of the currency."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 18, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text so that it conforms to the conventions of Standard English?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice D is the best answer. The convention being tested is the use of verb forms within a sentence. The nonfinite to-infinitive verb “to include” is correctly used to form a subordinate clause that indicates what the Olympic committee decided (to include tug-of-war as an Olympic event)."}, {"type": "paragraph", "text": "Choice A is incorrect because it results in an ungrammatical sentence. The finite verb “included” can’t be used in this way to form a subordinate clause that indicates what the Olympic committee decided. Choice B is incorrect because it results in an ungrammatical sentence. The nonfinite participle “including” can’t be used in this way to form a subordinate clause that indicates what the Olympic committee decided. Choice C is incorrect because it results in an ungrammatical sentence. The finite verb “include” can’t be used in this way to form a subordinate clause that indicates what the Olympic committee decided."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Standard English Conventions'), 'medium', 'source', 'approved', 19, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text so that it conforms to the conventions of Standard English?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice D is the best answer. The convention being tested is the use of verbs to express tense. In this choice, the past tense verb “malfunctioned” is consistent with the other past tense verbs (“ignited” and “was”) used to describe the destruction of the original Globe Theatre."}, {"type": "paragraph", "text": "Choice A is incorrect because the present tense verb “malfunctions” isn’t consistent with the other past tense verbs used to describe the destruction of the original Globe Theatre. Choice B is incorrect because the future tense verb “will malfunction” isn’t consistent with the other past tense verbs used to describe the destruction of the original Globe Theatre. Choice C is incorrect because the present perfect tense verb “has malfunctioned” isn’t consistent with the other past tense verbs used to describe the destruction of the original Globe Theatre."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Standard English Conventions'), 'medium', 'source', 'approved', 20, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text so that it conforms to the conventions of Standard English?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice C is the best answer. The convention being tested is punctuation use between a subject and a verb. No punctuation is needed when, as in this case, a subject (“Her portrait of novelist Zadie Smith”) is immediately followed by a main verb (“is displayed”)."}, {"type": "paragraph", "text": "Choice A is incorrect because no punctuation is needed between the subject and the verb. Choice B is incorrect because no punctuation is needed between the subject and the verb. Choice D is incorrect because no punctuation is needed between the subject and the verb."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Standard English Conventions'), 'medium', 'source', 'approved', 21, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text so that it conforms to the conventions of Standard English?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice C is the best answer. The convention being tested is pronoun-antecedent agreement. The singular pronoun “it” agrees in number with the singular antecedent “industry” and clearly indicates that the industry consists of just one or two suppliers per municipality."}, {"type": "paragraph", "text": "Choice A is incorrect. The plural pronoun “these” neither agrees in number with the singular antecedent “industry” nor clearly indicates that the industry—not another plural noun in the sentence, such as “start-up costs” or “barriers”— consists of just one or two suppliers per municipality. Choice B is incorrect because the plural pronoun “they” doesn’t agree in number with the singular antecedent “industry.” Choice D is incorrect because the singular pronoun “this” is ambiguous in this context; the resulting sentence leaves unclear what consists of just one or two suppliers per municipality."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Standard English Conventions'), 'medium', 'source', 'approved', 22, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text so that it conforms to the conventions of Standard English?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice C is the best answer. The convention being tested is the punctuation of elements in a complex series. It’s conventional to use a semicolon to separate items in a complex series with internal punctuation, and in this choice, the semicolon after “items” is conventionally used to separate the first item (“overseeing…items”) and the second item (“managing…law”) in a list of Hayden’s responsibilities."}, {"type": "paragraph", "text": "Choice A is incorrect because it fails to use appropriate punctuation to separate the first item and the second item in the complex series. Choice B is incorrect because a comma after “items” doesn’t match the semicolon used later to separate the second and third items in the series (“managing…law” and “and appointing the US poet laureate”). Choice D is incorrect because it results in a rhetorically unacceptable sentence fragment beginning with “Managing.”"}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Standard English Conventions'), 'medium', 'source', 'approved', 23, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text so that it conforms to the conventions of Standard English?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice A is the best answer. The convention being tested is the use of punctuation within a sentence. The comma after “work” pairs with the comma after “though” to separate the supplementary element “though” from the rest of the sentence. This supplementary element signals that what follows is an exception to Chen using software tools to create illustrations, and the pair of commas indicates that this element could be removed without affecting the grammatical coherence of the sentence."}, {"type": "paragraph", "text": "Choice B is incorrect because the comma after “work” must be paired with a comma after “though” to separate the supplementary element from the rest of the sentence. Choice C is incorrect because a semicolon can’t be paired with a comma in this way to separate the supplementary element from the rest of the sentence. Choice D is incorrect because a semicolon can’t be paired with a comma in this way to separate the supplementary element from the rest of the sentence."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Standard English Conventions'), 'medium', 'source', 'approved', 24, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text so that it conforms to the conventions of Standard English?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice B is the best answer. The convention being tested is the use of punctuation within a sentence. This choice correctly uses a comma to separate the supplementary adverb “though” from the preceding main clause (“They are hardly pristine”) and uses a semicolon to join the two main clauses (“They… though” and “many…objects”). Further, placing the semicolon after “though” indicates that the information in the preceding main clause (chondrites are far from pristine) is contrary to what might be assumed from the information in the previous sentence (chondrites have been generally unaltered by their environment)."}, {"type": "paragraph", "text": "Choice A is incorrect because placing the comma after “pristine” and using “though” as a subordinating conjunction illogically indicates that the information in the next main clause (many chondrites have experienced damage) is contrary to the information in the previous clause (chondrites are far from pristine)."}, {"type": "paragraph", "text": "Choice C is incorrect because placing the semicolon after “pristine” illogically indicates that the information in the next main clause (many chondrites have experienced damage) is contrary to the information in the previous clause (chondrites are far from pristine). Choice D is incorrect because it results in a comma splice. Without a conjunction following it, the comma after “though” can’t be used in this way to join two main clauses."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Standard English Conventions'), 'medium', 'source', 'approved', 25, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text so that it conforms to the conventions of Standard English?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice D is the best answer. The convention being tested is the use of punctuation within a sentence. This choice uses a semicolon in a conventional way to join the first main clause (“That the...involved”) and the second main clause (“establishing...divisive”). Further, the semicolon is the most appropriate choice when joining two separate, parallel statements, such as here, where the information following the semicolon contrasts with the information before."}, {"type": "paragraph", "text": "Choice A is incorrect because placing a colon after “involved” illogically indicates that the information in the second main clause (the precise location was the subject of disagreement) explains or amplifies the information in the previous main clause (the general location was agreed upon by all). Instead, the information in the second clause contrasts with the previous information. Choice B is incorrect because it results in a comma splice. Without a conjunction following it, a comma can’t be used in this way to join two main clauses. Choice C is incorrect because it results in a run-on sentence. The two main clauses are fused without punctuation and/or a conjunction."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Standard English Conventions'), 'medium', 'source', 'approved', 26, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text with the most logical transition?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice B is the best answer. “As a result” logically signals that the action described in this sentence—closing the area around Garisenda Tower to explore stabilization solutions—occurred as a consequence or result of measurements revealing the tower’s concerning rotation."}, {"type": "paragraph", "text": "Choice A is incorrect because “similarly” illogically signals that the action of closing the tower area is similar to the discovery of concerning rotation described in the previous sentence. Instead, closing the area around the tower to explore solutions occurred as a result of the measurements revealing the rotation."}, {"type": "paragraph", "text": "Choice C is incorrect because “for example” illogically signals that the action of closing the tower area serves as an example of the tower’s concerning rotation described in the previous sentence. Instead, closing the area around the tower to explore solutions occurred as a result of the measurements revealing the rotation."}, {"type": "paragraph", "text": "Choice D is incorrect because “in comparison” illogically signals that the action of closing the tower area is being compared to the discovery of concerning rotation described in the previous sentence. Instead, closing the area around the tower to explore solutions occurred as a result of the measurements revealing the rotation."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Expression of Ideas'), 'medium', 'source', 'approved', 27, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text with the most logical transition?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice D is the best answer. “Specifically” logically signals that the information in this sentence—that the Local Bubble’s expansion trapped clouds of gas and dust that formed new stars—provides specific, precise details elaborating on the more general information in the previous sentence about the relationship between the Local Bubble’s expansion and the formation of new stars."}, {"type": "paragraph", "text": "Choice A is incorrect because “hence” illogically signals that the information in this sentence is a result of the information in the previous sentence about the relationship between the Local Bubble’s expansion and the formation of new stars. Instead, this sentence provides specific, precise details elaborating on that information. Choice B is incorrect because “however” illogically signals that the information in this sentence contrasts with the information in the previous sentence about the relationship between the Local Bubble’s expansion and the formation of new stars. Instead, this sentence provides specific, precise details elaborating on that information. Choice C is incorrect because “admittedly” illogically signals that the information in this sentence provides an exception or caveat to the previous information about the relationship between the Local Bubble’s expansion and the formation of new stars. Instead, this sentence provides specific, precise details elaborating on that information."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Expression of Ideas'), 'medium', 'source', 'approved', 28, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text with the most logical transition?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice A is the best answer. “In particular” logically signals that the information in this sentence—that maize and wheat supply chains transformed North American foodways into a global food system—provides specific, precise details elaborating on the more general information in the previous sentence about the transformation of North American foodways (with maize and wheat the “certain grains” at the center of it)."}, {"type": "paragraph", "text": "Choice B is incorrect because “alternatively” illogically signals that the information in this sentence is an alternative option to the previous information about the transformation of North American foodways. Instead, the roles of maize and wheat in creating a global food system are specific, precise details elaborating on that information. Choice C is incorrect because “by comparison” illogically signals that the information in this sentence is being compared to the previous information about the transformation of North American foodways. Instead, the roles of maize and wheat in creating a global food system are specific, precise details elaborating on that information. Choice D is incorrect because “second of all” illogically signals that the information in this sentence is a second, separate claim from the previous claim that North American foodways were transformed. Instead, the roles of maize and wheat in creating a global food system are specific, precise details elaborating on that information, rather than a separate claim."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Expression of Ideas'), 'medium', 'source', 'approved', 29, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text with the most logical transition?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice D is the best answer. “To that end” logically signals that the information in this sentence—the students’ creation of a show with six starring female roles—is the product of a goal or desire in the previous sentence (the students’ wish to develop a musical with roles for female actors)."}, {"type": "paragraph", "text": "Choice A is incorrect because “in other words” illogically signals that the information in this sentence is a paraphrase or restatement of the previous information about the students’ wish to develop a musical with roles for female actors. Instead, the students’ show is the product of that desire. Choice B is incorrect because “in summary” illogically signals that the information in this sentence summarizes the previous information about the students’ wish to develop a musical with roles for female actors. Instead, the students’ show is the product of that desire. Choice C is incorrect because “for example” illogically signals that the information in this sentence is merely an example of the previous information about the students’ wish to develop a musical with roles for female actors. Instead, the students’ show is the direct product of that desire."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Expression of Ideas'), 'medium', 'source', 'approved', 30, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text with the most logical transition?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice C is the best answer. “More often” logically signals that the claim in this sentence—that new via ferratas favor recreation over utility—explains a difference between the new “sporting activity” routes and the older “mode of travel” routes. In so doing, it emphasizes and reinforces the previous claim (“modern via ferratas are rarely designed to simply reach a summit”)."}, {"type": "paragraph", "text": "Choice A is incorrect because “additionally” illogically signals that this sentence’s claim about new via ferratas adds a new, separate point to the previous claim (“modern via ferratas are rarely designed to simply reach a summit”). Instead, the second claim—that new routes favor recreation over utility—emphasizes and reinforces the previous one. Choice B is incorrect because “on the other hand” illogically signals that this sentence’s claim about new via ferratas contrasts with or opposes the previous claim (“modern via ferratas are rarely designed to simply reach a summit”). Instead, the second claim—that new routes favor recreation over utility—emphasizes and reinforces the previous one. Choice D is incorrect because “nonetheless” illogically signals that this sentence’s claim about new via ferratas is true despite the previous claim (“modern via ferratas are rarely designed to simply reach a summit”). Instead, the second claim—that new routes favor recreation over utility—emphasizes and reinforces the previous one."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Expression of Ideas'), 'medium', 'source', 'approved', 31, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice most effectively uses relevant information from the notes to accomplish this goal?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice A is the best answer. The sentence indicates the title of a novel that won a Nebula Award, noting that Babel-17 by Samuel Delany won the award in 1967."}, {"type": "paragraph", "text": "Choice B is incorrect because the sentence identifies the year that Samuel Delany published a science fiction novel; it doesn’t indicate the novel’s title or that it won a Nebula Award. Choice C is incorrect because the sentence provides an introduction of Samuel Delany; it doesn’t indicate the title of a novel that has won a Nebula Award. Choice D is incorrect because the sentence indicates that one of Samuel Delany’s novels met the qualification for a Nebula Award; it doesn’t indicate the novel’s title or that it won an award."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 32, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice most effectively uses relevant information from the notes to accomplish this goal?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice C is the best answer. The sentence indicates the year Yosemite Falls was completed, stating that it was completed in 1930."}, {"type": "paragraph", "text": "Choice A is incorrect. The sentence indicates where Obata created black ink paintings; it doesn’t indicate when the painting was completed. Choice B is incorrect. While the sentence identifies Obata as an artist who created a notable painting, it doesn’t indicate when that painting was completed. Choice D is incorrect. The sentence identifies the method Obata used; it doesn’t indicate when the painting was completed."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 33, 'choice', array[]::text[]) returning id into v_q;
    update public.exams set status = 'published' where id = v_exam;
  end if;
  -- SAT Practice Test 7: Math
  if exists (select 1 from public.exams where slug = 'sat-practice-test-7-math') then
    raise notice 'skipping sat-practice-test-7-math (already imported)';
  else
    select id into v_subject from public.subjects where code = 'sat-math';
    values (v_subject, 'sat-practice-test-7-math', 'SAT Practice Test 7: Math', 'Official SAT Practice Test 7 (College Board), Math: 54 questions in two modules, including student-produced responses. Calculator allowed; 43 minutes per module.', 'full_mock', 'premium', 'draft', 86, 'source', 215, '[[200, 200], [210, 230], [210, 240], [210, 250], [210, 260], [210, 270], [210, 280], [230, 290], [250, 300], [260, 310], [280, 340], [300, 360], [320, 360], [330, 370], [340, 380], [350, 390], [360, 400], [360, 400], [370, 410], [380, 420], [380, 420], [390, 430], [400, 440], [410, 450], [420, 460], [430, 470], [430, 470], [440, 480], [450, 490], [460, 500], [480, 520], [490, 530], [500, 540], [500, 560], [510, 570], [520, 580], [530, 590], [540, 600], [550, 610], [560, 620], [580, 640], [590, 650], [600, 660], [610, 670], [630, 690], [640, 700], [650, 710], [670, 730], [690, 750], [700, 760], [720, 770], [750, 780], [770, 800], [780, 800], [800, 800]]'::jsonb)
    returning id into v_exam;
    values (v_subject, null, null, '{"blocks": [{"type": "image", "src": "/sat/test-07/math-m1-q01.png", "alt": "Figure for question 1", "width": 322}, {"type": "paragraph", "text": "The scatterplot shows the temperature, in degrees Fahrenheit ($^\\circ$F), and the distance above sea level, in feet, measured at $6$ locations on Mount Jefferson. A line of best fit is also shown."}, {"type": "paragraph", "text": "At a distance of $4{,}000$ feet above sea level, what is the temperature, in $^\\circ$F, predicted by the line of best fit?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "At $x = 4{,}000$ the line of best fit is at about $35^\\circ$F."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Problem-Solving and Data Analysis'), 'easy', 'source', 'approved', 1, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "Rectangle P has an area of $72$ square inches. If a rectangle with an area of $20$ square inches is removed from rectangle P, what is the area, in square inches, of the resulting figure?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$72 - 20 = 52$ square inches."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Geometry and Trigonometry'), 'easy', 'source', 'approved', 2, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "math", "latex": "|p| + 61 = 65"}, {"type": "paragraph", "text": "Which value is a solution to the given equation?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$|p| = 4$, so $p = 4$ or $p = -4$. Only $4$ is listed."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'easy', 'source', 'approved', 3, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "Lorenzo purchased a box of cereal and some strawberries at the grocery store. Lorenzo paid $\\$2$ for the box of cereal and $\\$1.90$ per pound for the strawberries. If Lorenzo paid a total of $\\$9.60$ for the box of cereal and the strawberries, which of the following equations can be used to find $p$, the number of pounds of strawberries Lorenzo purchased? (Assume there is no sales tax.)"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "The strawberries cost $1.90p$ dollars and the cereal $2$ dollars, for a total of $9.60$: $1.90p + 2 = 9.60$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'easy', 'source', 'approved', 4, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "image", "src": "/sat/test-07/math-m1-q05.png", "alt": "Figure for question 5", "width": 296}, {"type": "paragraph", "text": "The bar graph summarizes the charge, in kilowatt-hours (kWh), a battery received each day for $15$ days."}, {"type": "paragraph", "text": "For how many of these $15$ days did the battery receive a charge of $0$ kWh?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "The bar above $0$ kWh reaches $6$ days."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Problem-Solving and Data Analysis'), 'easy', 'source', 'approved', 5, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "A line in the $xy$-plane has a slope of $9$ and passes through the point $(0, -5)$. The equation $y = px + r$ defines the line, where $p$ and $r$ are constants. What is the value of $p$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "In $y = px + r$, $p$ is the slope, so $p = 9$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'easy', 'source', 'approved', 6, 'spr', array['9']::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "What is an $x$-coordinate of an $x$-intercept of the graph of $y = 3(x - 14)(x + 5)(x + 4)$ in the $xy$-plane?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$y = 0$ when $x = 14$, $x = -5$, or $x = -4$. Any of these is correct."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Advanced Math'), 'easy', 'source', 'approved', 7, 'spr', array['14', '-5', '-4']::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "image", "src": "/sat/test-07/math-m1-q08.png", "alt": "Figure for question 8", "width": 322}, {"type": "paragraph", "text": "The graph shown gives the estimated value, in dollars, of a tablet as a function of the number of months since it was purchased. What is the best interpretation of the $y$-intercept of the graph in this context?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "The $y$-intercept is at $0$ months, the time of purchase, where the value is about $\\$225$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Advanced Math'), 'easy', 'source', 'approved', 8, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "Triangles $EFG$ and $JKL$ are congruent, where $E$, $F$, and $G$ correspond to $J$, $K$, and $L$, respectively. The measure of angle $E$ is $45^\\circ$ and the measure of angle $F$ is $20^\\circ$. What is the measure of angle $J$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Angle $J$ corresponds to angle $E$, so it measures $45^\\circ$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Geometry and Trigonometry'), 'easy', 'source', 'approved', 9, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "The function $f$ is defined by $f(x) = \\dfrac{1}{2}(x + 6)$. What is the value of $f(4)$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$f(4) = \\tfrac{1}{2}(10) = 5$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'easy', 'source', 'approved', 10, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "image", "src": "/sat/test-07/math-m1-q11.png", "alt": "Figure for question 11", "width": 254}, {"type": "paragraph", "text": "The graph of a system of an absolute value function and a linear function is shown. What is the solution $(x, y)$ to this system of two equations?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "The graphs intersect halfway between $x = -4$ and $x = -3$, at height halfway between $4$ and $5$: $\\left(-\\tfrac{7}{2}, \\tfrac{9}{2}\\right)$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'medium', 'source', 'approved', 11, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "math", "latex": "y = 6x + 3"}, {"type": "paragraph", "text": "One of the two equations in a system of linear equations is given. The system has infinitely many solutions. Which equation could be the second equation in this system?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Infinitely many solutions means the second equation is the same line. Dividing $2y = 2(6x + 3)$ by $2$ gives $y = 6x + 3$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'medium', 'source', 'approved', 12, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "If $\\dfrac{6}{7}p + 18 = 54$, what is the value of $7p$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$\\tfrac{6}{7}p = 36$, so $p = 42$ and $7p = 294$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'easy', 'source', 'approved', 13, 'spr', array['294']::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "math", "latex": "\\begin{aligned} y &= 9x + 12 \\\\ x + 7y &= 20 \\end{aligned}"}, {"type": "paragraph", "text": "The solution to the given system of equations is $(x, y)$. What is the value of $y$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Substitute: $x + 7(9x + 12) = 20$, so $64x = -64$ and $x = -1$. Then $y = 9(-1) + 12 = 3$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'medium', 'source', 'approved', 14, 'spr', array['3']::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "A circle in the $xy$-plane has the equation $(x - 13)^2 + (y - k)^2 = 64$. Which of the following gives the center of the circle and its radius?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$(x - h)^2 + (y - k)^2 = r^2$ has center $(h, k)$ and radius $r$. Here the center is $(13, k)$ and $r = \\sqrt{64} = 8$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Geometry and Trigonometry'), 'easy', 'source', 'approved', 15, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "The function $f$ is defined by $f(x) = |x - 4x|$. What value of $a$ satisfies $f(5) - f(a) = -15$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$f(x) = |-3x| = 3|x|$, so $f(5) = 15$. Then $15 - f(a) = -15$ gives $f(a) = 30$, so $|a| = 10$. Only $10$ is listed."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Advanced Math'), 'medium', 'source', 'approved', 16, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "For the exponential function $f$, the value of $f(0)$ is $c$, where $c$ is a constant. Of the following equations that define the function $f$, which equation shows the value of $c$ as the coefficient or the base?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "In $f(x) = 33(1.5)^x$, $f(0) = 33(1) = 33$, which is the coefficient. (All four equations define the same function, with $f(0) = 33$.)"}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Advanced Math'), 'medium', 'source', 'approved', 17, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "The function $f(t) = 40{,}000(2)^{\\frac{t}{790}}$ gives the number of bacteria in a population $t$ minutes after an initial observation. How much time, in minutes, does it take for the number of bacteria in the population to double?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "The base $2$ is raised to $\\tfrac{t}{790}$, so the population doubles each time $t$ increases by $790$ minutes."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Advanced Math'), 'easy', 'source', 'approved', 18, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "math", "latex": "\\frac{12}{n} - \\frac{2}{t} = -\\frac{2}{w}"}, {"type": "paragraph", "text": "The given equation relates the variables $n$, $t$, and $w$, where $n > 0$, $t > 0$, and $w > t$. Which expression is equivalent to $n$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$\\dfrac{12}{n} = \\dfrac{2}{t} - \\dfrac{2}{w} = \\dfrac{2(w - t)}{tw}$, so $n = \\dfrac{12tw}{2(w - t)} = \\dfrac{6tw}{w - t}$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Advanced Math'), 'hard', 'source', 'approved', 19, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "image", "src": "/sat/test-07/math-m1-q20.png", "alt": "Figure for question 20", "width": 327}, {"type": "paragraph", "text": "During a study, the temperature, in degrees Celsius ($^\\circ$C), of the air in a chamber was recorded to the nearest integer at certain times. The scatterplot shows the recorded temperature $y$, in $^\\circ$C, of the air in the chamber $x$ minutes after the start of the study."}, {"type": "paragraph", "text": "What was the average rate of change, in $^\\circ$C per minute, of the recorded temperature of the air in the chamber from $x = 5$ to $x = 7$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "At $x = 5$ the temperature is $14$ and at $x = 7$ it is $24$: $\\dfrac{24 - 14}{7 - 5} = 5$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Problem-Solving and Data Analysis'), 'medium', 'source', 'approved', 20, 'spr', array['5']::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "In August, a car dealer completed $15$ more than $3$ times the number of sales the car dealer completed in September. In August and September, the car dealer completed $363$ sales. How many sales did the car dealer complete in September?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "If September had $s$ sales, August had $3s + 15$: $s + 3s + 15 = 363$, so $4s = 348$ and $s = 87$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'medium', 'source', 'approved', 21, 'spr', array['87']::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "Points $Q$ and $R$ lie on a circle with center $P$. The radius of this circle is $9$ inches. Triangle $PQR$ has a perimeter of $31$ inches. What is the length, in inches, of $\\overline{QR}$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$PQ$ and $PR$ are radii, $9$ inches each, so $QR = 31 - 18 = 13$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Geometry and Trigonometry'), 'medium', 'source', 'approved', 22, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "In a set of four consecutive odd integers, where the integers are ordered from least to greatest, the first integer is represented by $x$. The product of $12$ and the fourth odd integer is at most $26$ less than the sum of the first and third odd integers. Which inequality represents this situation?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "The odd integers are $x$, $x + 2$, $x + 4$, $x + 6$. \"At most $26$ less than the sum of the first and third\" is $\\le x + (x + 4) - 26$, and the product of $12$ and the fourth is $12(x + 6)$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'hard', 'source', 'approved', 23, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "table", "header": ["$x$", "$y$"], "rows": [["$-2s$", "$24$"], ["$-s$", "$21$"], ["$s$", "$15$"]]}, {"type": "paragraph", "text": "The table shows three values of $x$ and their corresponding values of $y$, where $s$ is a constant. There is a linear relationship between $x$ and $y$. Which of the following equations represents this relationship?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "The slope is $\\dfrac{21 - 24}{-s - (-2s)} = -\\dfrac{3}{s}$. Using $(s, 15)$: $15 = -3 + b$, so $b = 18$ and $y = -\\dfrac{3}{s}x + 18$. Multiply by $s$: $sy = -3x + 18s$, or $3x + sy = 18s$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'hard', 'source', 'approved', 24, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "Which of the following expressions is equivalent to $(\\sin 24^\\circ)(\\cos 66^\\circ) + (\\cos 24^\\circ)(\\sin 66^\\circ)$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$24^\\circ$ and $66^\\circ$ are complementary, so $\\sin 24^\\circ = \\cos 66^\\circ$ and $\\sin 66^\\circ = \\cos 24^\\circ$. The expression becomes $(\\cos 66^\\circ)^2 + (\\cos 24^\\circ)^2$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Geometry and Trigonometry'), 'hard', 'source', 'approved', 25, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "The cost of renting a carpet cleaner is $\\$52$ for the first day and $\\$26$ for each additional day. Which of the following functions gives the cost $C(d)$, in dollars, of renting the carpet cleaner for $d$ days, where $d$ is a positive integer?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$C(d) = 52 + 26(d - 1) = 26d + 26$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'medium', 'source', 'approved', 26, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "math", "latex": "f(x) = (x - 2)(x + 15)"}, {"type": "paragraph", "text": "The function $f$ is defined by the given equation. For what value of $x$ does $f(x)$ reach its minimum?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "The zeros are $2$ and $-15$. The parabola opens upward, so the minimum is halfway between them: $x = \\dfrac{2 + (-15)}{2} = -\\dfrac{13}{2}$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Advanced Math'), 'hard', 'source', 'approved', 27, 'spr', array['-13/2', '-6.5']::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "A total of $165$ people contributed to a charity event as either a donor or a volunteer. $130$ people contributed as a donor. How many people contributed as a volunteer?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$165 - 130 = 35$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'easy', 'source', 'approved', 1, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "There are $250$ trees in a park. Of these trees, $6\\%$ are birch trees. How many birch trees are in the park?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$0.06 \\times 250 = 15$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Problem-Solving and Data Analysis'), 'easy', 'source', 'approved', 2, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "image", "src": "/sat/test-07/math-m2-q03.png", "alt": "Figure for question 3", "width": 267}, {"type": "paragraph", "text": "The graph of the quadratic function $y = f(x)$ is shown. What is the vertex of the graph?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "The lowest point of the parabola is at $(0, 2)$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Advanced Math'), 'easy', 'source', 'approved', 3, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "The number of raccoons in a $131$-square-mile area is estimated to be $2{,}358$. What is the estimated population density, in raccoons per square mile, of this area?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$2{,}358 \\div 131 = 18$ raccoons per square mile."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Problem-Solving and Data Analysis'), 'easy', 'source', 'approved', 4, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "math", "latex": "-11, -9, 26"}, {"type": "paragraph", "text": "A data set of three numbers is shown. If a number from this data set is selected at random, what is the probability of selecting a positive number?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Only $26$ is positive, so the probability is $\\tfrac{1}{3}$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Problem-Solving and Data Analysis'), 'easy', 'source', 'approved', 5, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "math", "latex": "f(x) = 45x + 600"}, {"type": "paragraph", "text": "The function $f$ gives the monthly fee $f(x)$, in dollars, a facility charges to keep $x$ crates in storage. What is the monthly fee, in dollars, the facility charges to keep $50$ crates in storage?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$f(50) = 45(50) + 600 = 2{,}850$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'easy', 'source', 'approved', 6, 'spr', array['2850']::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "The function $f$ is defined by $f(x) = 5\\left(\\dfrac{1}{4} - x\\right)^2 + \\dfrac{11}{4}$. What is the value of $f\\left(\\dfrac{1}{4}\\right)$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$f\\left(\\tfrac{1}{4}\\right) = 5(0)^2 + \\tfrac{11}{4} = \\tfrac{11}{4}$ (or $2.75$)."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Advanced Math'), 'easy', 'source', 'approved', 7, 'spr', array['11/4', '2.75']::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "If $8x = 6$, what is the value of $72x$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$72x = 9(8x) = 9(6) = 54$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'easy', 'source', 'approved', 8, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "Which expression is equivalent to $23x^3 + 2x^2 + 9x$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Factor $x$ out of each term: $x(23x^2 + 2x + 9)$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Advanced Math'), 'easy', 'source', 'approved', 9, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "Which expression is equivalent to $(9x^3 + 5x + 7) + (6x^3 + 5x^2 - 5)$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Combine like terms: $15x^3 + 5x^2 + 5x + 2$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Advanced Math'), 'easy', 'source', 'approved', 10, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "At a state fair, attendees can win tokens that are worth a different number of points depending on the shape. One attendee won $S$ square tokens and $C$ circle tokens worth a total of $1{,}120$ points. The equation $80S + 90C = 1{,}120$ represents this situation. How many more points is a circle token worth than a square token?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "A square token is worth $80$ points and a circle token $90$, so a circle token is worth $10$ more."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'easy', 'source', 'approved', 11, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "image", "src": "/sat/test-07/math-m2-q12.png", "alt": "Figure for question 12", "width": 256}, {"type": "paragraph", "text": "In the given scatterplot, a line of best fit for the data is shown."}, {"type": "paragraph", "text": "Which of the following is closest to the slope of the line of best fit shown?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "The line rises from about $y = 1.5$ at $x = 0$ to about $y = 14$ at $x = 7$, a slope of roughly $\\tfrac{12.5}{7} \\approx 2$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Problem-Solving and Data Analysis'), 'easy', 'source', 'approved', 12, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "A circle has a radius of $2.1$ inches. The area of the circle is $b\\pi$ square inches, where $b$ is a constant. What is the value of $b$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Area $= \\pi r^2 = \\pi(2.1)^2 = 4.41\\pi$, so $b = 4.41$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Geometry and Trigonometry'), 'easy', 'source', 'approved', 13, 'spr', array['4.41', '441/100']::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "In triangle $XYZ$, angle $Y$ is a right angle, point $P$ lies on $\\overline{XZ}$, and point $Q$ lies on $\\overline{YZ}$ such that $\\overline{PQ}$ is parallel to $\\overline{XY}$. If the measure of angle $XZY$ is $63^\\circ$, what is the measure, in degrees, of angle $XPQ$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Angle $X = 180 - 90 - 63 = 27^\\circ$. Since $\\overline{PQ} \\parallel \\overline{XY}$, angle $ZPQ$ equals angle $ZXY = 27^\\circ$, so angle $XPQ = 180 - 27 = 153^\\circ$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Geometry and Trigonometry'), 'medium', 'source', 'approved', 14, 'spr', array['153']::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "An investment account was opened with an initial value of $\\$890$. The value of the account doubled every $10$ years. Which equation represents the value of the account $M(t)$, in dollars, $t$ years after the account was opened?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Doubling every $10$ years means a factor of $2$ for each $10$ years: $M(t) = 890(2)^{t/10}$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Advanced Math'), 'medium', 'source', 'approved', 15, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "math", "latex": "\\begin{aligned} y &< x \\\\ x &< 22 \\end{aligned}"}, {"type": "paragraph", "text": "For which of the following tables are all the values of $x$ and their corresponding values of $y$ solutions to the given system of inequalities?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Every pair needs $y < x$ and $x < 22$. In table A each $y$ is one less than $x$ and every $x$ is below $22$. Tables C and D have $x > 22$, and B has $y > x$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'medium', 'source', 'approved', 16, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "Which expression is equivalent to $\\dfrac{h^{15}q^7}{h^5q^{21}}$, where $h > 0$ and $q > 0$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Subtract exponents: $h^{15-5} = h^{10}$ and $q^{7-21} = q^{-14}$, giving $\\dfrac{h^{10}}{q^{14}}$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Advanced Math'), 'medium', 'source', 'approved', 17, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "math", "latex": "\\begin{aligned} 3y &= 4x + 17 \\\\ -3y &= 9x - 23 \\end{aligned}"}, {"type": "paragraph", "text": "The solution to the given system of equations is $(x, y)$. What is the value of $39x$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Add the equations: $0 = 13x - 6$, so $13x = 6$ and $39x = 18$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'medium', 'source', 'approved', 18, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "math", "latex": "h(t) = -16t^2 + b"}, {"type": "paragraph", "text": "The function $h$ estimates an object''s height, in feet, above the ground $t$ seconds after the object is dropped, where $b$ is a constant. The function estimates that the object is $3{,}364$ feet above the ground when it is dropped at $t = 0$. Approximately how many seconds after being dropped does the function estimate the object will hit the ground?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$h(0) = b = 3{,}364$. The object hits the ground when $16t^2 = 3{,}364$: $t^2 = 210.25$, so $t = 14.5$ seconds."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Advanced Math'), 'medium', 'source', 'approved', 19, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "math", "latex": "2x^2 - 8x - 7 = 0"}, {"type": "paragraph", "text": "One solution to the given equation can be written as $\\dfrac{8 - \\sqrt{k}}{4}$, where $k$ is a constant. What is the value of $k$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "By the quadratic formula, $x = \\dfrac{8 \\pm \\sqrt{64 - 4(2)(-7)}}{2(2)} = \\dfrac{8 \\pm \\sqrt{120}}{4}$, so $k = 120$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Advanced Math'), 'hard', 'source', 'approved', 20, 'spr', array['120']::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "image", "src": "/sat/test-07/math-m2-q21.png", "alt": "Figure for question 21", "width": 328}, {"type": "paragraph", "text": "A line intersects two parallel lines, forming four acute angles and four obtuse angles. The measure of one of the acute angles is $(9x - 560)^\\circ$. The sum of the measures of one of the acute angles and three of the obtuse angles is $(-18x + w)^\\circ$. What is the value of $w$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "All acute angles are equal and each obtuse angle is $180 - (9x - 560)$. The sum is $(9x - 560) + 3(740 - 9x) = 1{,}660 - 18x$, so $w = 1{,}660$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Geometry and Trigonometry'), 'hard', 'source', 'approved', 21, 'spr', array['1660']::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "table", "header": ["$x$", "$f(x)$"], "rows": [["$-4$", "$0$"], ["$-\\dfrac{19}{5}$", "$1$"], ["$-\\dfrac{18}{5}$", "$2$"]]}, {"type": "paragraph", "text": "For the linear function $f$, the table shows three values of $x$ and their corresponding values of $f(x)$. If $h(x) = f(x) - 13$, which equation defines $h$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$f$ rises $1$ for every $\\tfrac{1}{5}$ increase in $x$, a slope of $5$, and $f(-4) = 0$, so $f(x) = 5x + 20$. Then $h(x) = 5x + 7$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'medium', 'source', 'approved', 22, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "The linear function $g$ is defined by $g(x) = b - 15x$, where $b$ is a constant. If $g(c + 7) = \\dfrac{c}{4}$, where $c$ is a constant, which of the following expressions represents the value of $b$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$b - 15(c + 7) = \\tfrac{c}{4}$, so $b = \\tfrac{c}{4} + 15c + 105 = \\tfrac{61c}{4} + 105$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'hard', 'source', 'approved', 23, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "In triangle $XYZ$, angle $Z$ is a right angle and the length of $\\overline{YZ}$ is $24$ units. If $\\tan X = \\dfrac{12}{35}$, what is the perimeter, in units, of triangle $XYZ$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$\\tan X = \\dfrac{YZ}{XZ} = \\dfrac{12}{35}$, so $XZ = 70$. The hypotenuse is $\\sqrt{24^2 + 70^2} = 74$, and the perimeter is $24 + 70 + 74 = 168$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Geometry and Trigonometry'), 'hard', 'source', 'approved', 24, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "math", "latex": "x^2 + 14x + y^2 = 6y + 109"}, {"type": "paragraph", "text": "In the $xy$-plane, the graph of the given equation is a circle. What is the length of the circle''s radius?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Complete the squares: $(x + 7)^2 + (y - 3)^2 = 109 + 49 + 9 = 167$, so the radius is $\\sqrt{167}$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Geometry and Trigonometry'), 'hard', 'source', 'approved', 25, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "The speed of a vehicle is increasing at a rate of $7.3$ meters per second squared. What is this rate, in **miles per minute squared**, rounded to the nearest tenth? (Use $1$ mile $= 1{,}609$ meters.)"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$7.3 \\dfrac{\\text{m}}{\\text{s}^2} \\times \\dfrac{(60\\text{ s})^2}{1\\text{ min}^2} \\times \\dfrac{1\\text{ mi}}{1{,}609\\text{ m}} = \\dfrac{7.3 \\times 3{,}600}{1{,}609} \\approx 16.3$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Problem-Solving and Data Analysis'), 'hard', 'source', 'approved', 26, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "math", "latex": "\\begin{aligned} y &= -2.5 \\\\ y &= x^2 + 8x + k \\end{aligned}"}, {"type": "paragraph", "text": "In the given system of equations, $k$ is a positive integer constant. The system has no real solutions. What is the least possible value of $k$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Set equal: $x^2 + 8x + k + 2.5 = 0$. No real solutions requires $64 - 4(k + 2.5) < 0$, so $k > 13.5$. The least integer is $14$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Advanced Math'), 'hard', 'source', 'approved', 27, 'spr', array['14']::text[]) returning id into v_q;
    update public.exams set status = 'published' where id = v_exam;
  end if;
end $sat$;

do $sat$
declare
  v_subject uuid; v_exam uuid; v_section uuid; v_stim uuid; v_q uuid;
begin
  -- SAT Practice Test 8: Reading and Writing
  if exists (select 1 from public.exams where slug = 'sat-practice-test-8-reading-and-writing') then
    raise notice 'skipping sat-practice-test-8-reading-and-writing (already imported)';
  else
    select id into v_subject from public.subjects where code = 'sat-english';
    values (v_subject, 'sat-practice-test-8-reading-and-writing', 'SAT Practice Test 8: Reading and Writing', 'Official SAT Practice Test 8 (College Board), Reading and Writing: 66 questions in two modules, timed as the paper test (39 minutes per module).', 'full_mock', 'premium', 'draft', 78, 'source', 216, '[[200, 200], [210, 220], [210, 220], [210, 220], [210, 220], [210, 230], [210, 240], [220, 250], [220, 260], [230, 270], [230, 280], [240, 290], [240, 300], [250, 310], [260, 320], [270, 330], [300, 340], [310, 350], [320, 360], [330, 370], [330, 370], [340, 380], [350, 390], [350, 390], [360, 400], [370, 410], [380, 420], [380, 420], [390, 430], [400, 440], [410, 450], [410, 450], [420, 460], [430, 470], [440, 480], [450, 490], [460, 500], [470, 510], [470, 530], [480, 540], [490, 550], [500, 560], [510, 570], [520, 580], [530, 590], [540, 600], [550, 610], [560, 620], [570, 630], [580, 640], [590, 650], [600, 660], [610, 670], [630, 690], [640, 700], [660, 700], [670, 710], [680, 720], [690, 730], [700, 740], [710, 750], [720, 760], [730, 770], [740, 780], [760, 790], [780, 800], [800, 800]]'::jsonb)
    returning id into v_exam;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text with the most logical and precise word or phrase?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice B is the best answer because it most logically completes the text’s discussion of Juarez. In this context, “important” means marked by significant work or consequence. The text indicates that Juarez, who was the first president of Mexico from an Indigenous community, became a certain kind of figure in Mexico’s history. It then supports that claim by describing some of the “many significant accomplishments” from Juarez’s long tenure in office. This context conveys that Juarez is a significant and consequential figure in Mexico’s history."}, {"type": "paragraph", "text": "Choice A is incorrect because the text focuses on Juarez’s role as the first president of Mexico from an Indigenous community and on his many major accomplishments during his lengthy time in office; nothing in the text suggests that Juarez was “unpredictable,” or tended to behave in ways that couldn’t be predicted. Choice C is incorrect because nothing in the text suggests that Juarez was a particularly “secretive” figure, or that he tended to keep things private or hidden from others. Instead, the text focuses on things that are known about Juarez: that he was the first president of Mexico from an Indigenous community, that he had a lengthy tenure, and that his many major accomplishments included consolidating the national government’s authority and advancing Indigenous rights. Choice D is incorrect because the text focuses on the idea that Juarez, who was the first president of Mexico from an Indigenous community, had many major accomplishments during his lengthy time in office. Rather than suggesting that Juarez was an “ordinary,” or common and typical, figure in Mexico’s history, this context conveys that Juarez was instead a notable figure."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Craft and Structure'), 'medium', 'source', 'approved', 1, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text with the most logical and precise word or phrase?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice D is the best answer because it most logically completes the text’s discussion of the research that Lopes-Ferreira and her colleagues are conducting on the stingray species Potamotrygon rex. As used in this context, “a substantial” effect means an effect that is sizable or noteworthy. The text indicates that the researchers are seeking to determine whether there are “considerable variations” in the potency of stingray venom that are associated with variation in the stingrays’ age and sex. This context suggests that the researchers want to find out whether stingray age and sex have a substantial effect on venom toxicity."}, {"type": "paragraph", "text": "Choice A is incorrect because there’s nothing in the text that suggests that the researchers have been studying whether the stingrays’ age and sex have “a disconcerting,” or an unsettling and disturbing, effect on the stingrays’ venom. The text indicates that the researchers wish to determine if stingray age and sex cause large variations in the toxicity of stingray venom, not if the effect of age and sex is disconcerting. Choice B is incorrect because the text indicates that researchers want to find out whether differences in stingray age and sex produce differences in stingray venom, not that the researchers want to find out whether age and sex have “an acceptable,” or a satisfactory, effect on venom. The text makes no mention of what would make an effect on venom toxicity acceptable and gives no indication that the researchers are interested in that question."}, {"type": "paragraph", "text": "Choice C is incorrect because it wouldn’t make sense in context for the researchers to be looking for “an imperceptible,” or an unnoticeable, effect of age and sex on stingray venom. The text says that the researchers are trying to determine if there are “considerable variations” in venom toxicity linked to age and sex, not that the researchers are trying to find effects that they can’t perceive."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Craft and Structure'), 'medium', 'source', 'approved', 2, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text with the most logical and precise word or phrase?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice A is the best answer because it most logically completes the text’s discussion of how kelp forests help marine animals. In this context, “tranquil” means free from disturbance, or calm. The text indicates that ocean currents are powerful and make it difficult for marine animals to hide from predators and that kelp forests slow currents down to create calmer areas. In other words, kelp forests create a more tranquil environment."}, {"type": "paragraph", "text": "Choice B is incorrect because the text indicates that kelp forests provide shelter for marine animals, meaning they create environments that are safer, not more “dangerous.” Choice C is incorrect because the text discusses how kelp forests affect currents in the ocean, and it isn’t clear how an ocean environment could be “imaginative,” or full of imagination. Choice D is incorrect because the text indicates that kelp forests create a calm and safe environment, and an environment that is “surprising” would be characterized by unexpected occurrences, not calmness."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Craft and Structure'), 'medium', 'source', 'approved', 3, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text with the most logical and precise word or phrase?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice C is the best answer because it logically and precisely completes the text’s discussion of The Mule Bone, a play that Zora Neale Hurston and Langston Hughes wrote together. In this context, “collaboration” means working together with someone to write a literary work. The text indicates that most writers prefer to work alone and that working together destroyed the friendship between Hurston and Hughes. This establishes that The Mule Bone is a relatively rare example of collaboration in literature."}, {"type": "paragraph", "text": "Choice A is incorrect because in this context, “characterization” would mean a literary work’s portrayal of characters’ psychological experiences and motivations, but the text doesn’t discuss characterization in The Mule Bone specifically or in collaborative works more generally. Choice B is incorrect because in this context, “interpretation” would mean the explanation of a literary work’s meaning or significance, but the text doesn’t discuss how readers or critics have interpreted The Mule Bone; instead, the text discusses how the play was written collaboratively and how the writing process affected the two authors."}, {"type": "paragraph", "text": "Choice D is incorrect because in this context, “commercialization” would mean writing a literary work in such a way as to ensure its commercial appeal, but the text never discusses commercial appeal as a factor in the writing of The Mule Bone specifically or the writing of collaborative works more generally."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Craft and Structure'), 'medium', 'source', 'approved', 4, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text with the most logical and precise word or phrase?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice C is the best answer because it most logically completes the text’s discussion of how Ofelia Zepeda has contributed to the field of linguistics. As used in this context, “extensive” means having a wide or considerable extent. The text indicates that Zepeda’s many accomplishments in linguistics are varied, including teaching linguistics, writing poetry in more than one language, creating a grammar book, and co-founding a language institute. This context supports the idea that Zepeda’s contributions to the field are extensive."}, {"type": "paragraph", "text": "Choice A is incorrect because the sentence presents Zepeda’s accomplishments as examples to support the claim made in the first part of the sentence. It wouldn’t make sense to say that achievements as a professor, poet and author, and co-founder of a language institute demonstrate that Zepeda’s contributions in her field are “pragmatic,” or related to practical matters and not involving intellectual or artistic matters. Choice B is incorrect because the sentence presents Zepeda’s accomplishments as a professor, poet and author, and co-founder of a language institute as examples to support the claim made in the first part of the sentence. There’s no reason to believe that the positive achievements listed demonstrate that Zepeda’s contributions in her field are “controversial,” or have caused disputes and opposing viewpoints. Choice D is incorrect because in this context, “universal” would mean including or covering everything in a group. The sentence presents Zepeda’s accomplishments as examples to support the claim made in the first part of the sentence, and it wouldn’t make sense to say that these specific achievements—particularly as the author of a grammar book specific to the Tohono O’odham language—demonstrate that Zepeda’s contributions relate to everything in the field of linguistics."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Craft and Structure'), 'medium', 'source', 'approved', 5, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice best states the main purpose of the text?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice C is the best answer because it most accurately describes the main purpose of the text. The text states that archaeologists recently discovered a well-preserved food shop, or thermopolium, in Pompeii, Italy. The text then further describes the contents of the discovery and provides an example of what was found. Thus, the overall purpose of the text is to present a recent archaeological discovery."}, {"type": "paragraph", "text": "Choice A is incorrect. Although the text states that archaeologists found ancient artworks, it doesn’t compare these artworks to modern ones or to any other artworks. Choice B is incorrect. Although the archaeological discovery discussed in the text was made in Italy, the text doesn’t provide any information about politics or government in Italy. Choice D is incorrect because the text doesn’t discuss the climate where the archaeological discovery was made or in any other region."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Craft and Structure'), 'medium', 'source', 'approved', 6, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice best states the main purpose of the text?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice D is the best answer because it most accurately reflects the main purpose of the text. The text portrays Miss Pyne as awaiting the arrival of a carriage while Martha brings strawberries and flowers from the garden into the house. The text also describes the surroundings of the scene, stating that Miss Pyne looks “stately and calm,” the evening is bright and cool, and birds are singing in the garden as the sun sets. Then the last sentence states that the house was “wide open to the long-expected guest,” which strongly suggests that Miss Pyne’s anticipation and Martha’s activities were in preparation for the guest who is expected to arrive in the carriage. Thus, the text depicts the setting and conveys what these characters are doing as they await the arrival of their visitor."}, {"type": "paragraph", "text": "Choice A is incorrect because there is nothing in the text to indicate that the characters feel any worry about the guest’s arrival. The text indicates that the guest was “long-expected,“ but characterizing Miss Pyne as “stately and calm” conflicts with the idea that the characters are worried about the guest. Choice B is incorrect because the text describes a moment in time when two characters are awaiting the arrival of a visitor rather than an extended period over which characters could be seen changing. Choice C is incorrect. Although the text describes the activity indoors (Miss Pyne sitting calmly), it describes a higher level of activity, not stillness, outside (Martha bringing fruit and flowers and birds singing)."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Craft and Structure'), 'medium', 'source', 'approved', 7, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice best describes the overall structure of the text?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice A is the best answer because it most accurately describes the overall structure of the text. The narrator begins by explaining how Charlot carefully delivers Atlante’s letter to Rinaldo, and then relates that Rinaldo feels “transported with joy” after reading the letter. Therefore, the overall structure of the text is best described as a description of the delivery of a letter followed by the portrayal of a character’s happiness after reading the letter."}, {"type": "paragraph", "text": "Choice B is incorrect because the text indicates that the letter has been written; there’s no explanation why another character hasn’t written one. In addition, the text’s description of Rinaldo “in a melancholy posture” suggests that he’s sad and thoughtful, not that he’s desperate to receive the letter. Choice C is incorrect. Although the text states that Charlot won’t toss the letter to Rinaldo because she doesn’t want it to fall, the text doesn’t refer to the contents of the letter. Instead, the text describes how happy Rinaldo feels after reading it. Choice D is incorrect. Although the text does describe Rinaldo’s reaction to the letter, the text doesn’t begin by discussing Atlante’s inspiration for writing the letter. Instead, the text begins by discussing the delivery of the letter."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Craft and Structure'), 'medium', 'source', 'approved', 8, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, 0, '{"blocks": [{"type": "paragraph", "text": "Which choice best describes the function of the underlined portion in the text as a whole?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice A is the best answer because it best describes how the underlined portion functions in the text as a whole. The text says that the increased production quotas of food processing companies during World War II enabled employees to make better bargains in exchange for their labor. The underlined portion presents an example of this increased bargaining power: employees requested more favorable benefits, and employers complied because they were under pressure to fulfill the demanding terms of their contracts. Thus, the underlined portion of the text elaborates on a claim about labor relations in a particular industry (food processing) made earlier in the text."}, {"type": "paragraph", "text": "Choice B is incorrect because there is no indication in the text that the economic factors that influenced food processing also influenced other parts of the economy; thus, the bargaining described in the underlined portion of the text cannot be called an example of a trend. Choice C is incorrect because the underlined portion supports the historical narrative of labor activism in food processing that is sketched in the text, instead of noting an exception to that narrative. Choice D is incorrect because while the underlined portion does discuss the demands that workers made in exchange for their labor, it does not discuss the identities of the workers."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Craft and Structure'), 'medium', 'source', 'approved', 9, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "According to the text, why was Wang and his team’s discovery of the Terropterus xiushanensis fossil significant?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice D is the best answer because it states why Wang and his team’s discovery of the Terropterus xiushanensis fossil was significant. The text explains that up until Wang and his team’s discovery, the only fossil evidence of mixopterids came from the paleocontinent of Laurussia. Wang and his team, however, identified fossil remains of a mixopterid species from the paleocontinent Gondwana. Therefore, the team’s discovery was significant because the fossil remains of a mixopterid species were outside of the paleocontinent Laurussia."}, {"type": "paragraph", "text": "Choice A is incorrect. Although the text states that Wang and his team identified fossilized remains of a mixopterid species that lived more than 400 million years ago, it doesn’t indicate that mixopterid fossils previously found by scientists dated to a more recent period than that. Choice B is incorrect. Although the text states that mixopterids are related to modern arachnids and horseshoe crabs, it doesn’t suggest that the fossil discovered by Wang and his team confirmed that this relationship is closer than scientists had previously thought. Choice C is incorrect because the team’s fossil established the presence of mixopterids on Gondwana, not on Laurussia. Moreover, the text only discusses the fossil in relation to the geographical distribution of mixopterids, not in relation to their evolution."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 10, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice most effectively uses data from the table to complete the statement?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice B is the best answer because it most effectively uses data from the table to complete the statement about video game availability. The text states that just a few games released in the past are available today and then indicates that there is a period of years from which only 14.22 percent of the games released are available. The table shows that 14.22 percent of games are still available from the years 1995–1999."}, {"type": "paragraph", "text": "Choice A is incorrect because the years 2000–2004 are not represented in the table. Choice C is incorrect because the years 1970–1974 are not represented in the table. Choice D is incorrect because the years 1985–1989 correspond to a percentage of games still available of 15.38 percent, not 14.22 percent."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 11, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Based on the information in the table, at what depth does the southern stoplight loosejaw live?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice C is the best answer. The table shows the depths below the ocean surface at which four species of deep-sea fish live. According to the table, the range of depths at which the southern stoplight loosejaw lives is 500–2,000 meters below the surface."}, {"type": "paragraph", "text": "Choice A is incorrect because the table indicates that the southern stoplight loosejaw lives 500–2,000 meters below the ocean surface, not at depths more than 2,000 meters below the surface. Choice B is incorrect because the table indicates that the southern stoplight loosejaw lives 500–2,000 meters below the ocean surface, not 150–400 meters below the surface. Choice D is incorrect because the table indicates that the southern stoplight loosejaw lives 500–2,000 meters below the ocean surface, not 250–500 meters below the surface."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 12, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice most effectively uses data from the table to complete the statement?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice A is the best answer because it effectively uses data from the table to complete the statement, identifying the month in which the United States had the highest number of housing starts in 2022. According to the table, which shows the number of US housing starts from January to April 2022, the highest number of housing starts was 1,803 thousand, which occurred in April."}, {"type": "paragraph", "text": "Choice B is incorrect because March had 1,713 thousand housing starts, which is lower than the number of starts in April and in February. Choice C is incorrect because January had 1,669 thousand housing starts, which is the lowest of all the months listed in the table. Choice D is incorrect because February had 1,771 thousand housing starts, which is lower than the number of starts in April."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 13, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which finding, if true, would most directly support the student’s claim?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice A is the best answer because it presents a finding that, if true, would support the claim about Chambi’s photographs. The text describes a student advancing the claim that Chambi’s photographs “have considerable ethnographic value”—meaning that they are valuable as records of cultures—and that they “capture diverse elements of Peruvian society” in a respectful way. If it’s true that Chambi carefully photographed people from a range of different communities in Peru as well as photographed the customs and sites of different communities, that would lend support to the claim that the photographs have ethnographic value as depictions of diverse elements of society in Peru."}, {"type": "paragraph", "text": "Choice B is incorrect because the student’s claim is that Chambi’s photographs have considerable ethnographic value because they depict diverse elements of Peruvian society; the student doesn’t claim anything about the technical skill demonstrated in the photographs. Choice C is incorrect because neither Chambi’s reputation nor the locations where his photographs may have been published would be relevant to the student’s claim that his photographs are valuable as an ethnographic record of Peru’s diverse society. Choice D is incorrect because the popularity among other photographers of the people and places that Chambi photographed would be irrelevant to the student’s claim that Chambi’s photographs are valuable as an ethnographic record of Peru’s diverse society."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 14, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which finding, if true, would most directly support the researchers’ hypothesis?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice D is the best answer because it presents a finding that, if true, would most directly support the researchers’ hypothesis about the connection between the dusky shark population decline and the eastern oyster population decline. The text indicates that although dusky sharks don’t usually eat eastern oysters, they do consume cownose rays, which are the main predators of eastern oysters. An increase in the abundance of cownose rays in the region in response to a decline in the abundance of dusky sharks would directly support the researchers’ hypothesis: a higher number of cownose rays would consume more eastern oysters, driving down the oyster population."}, {"type": "paragraph", "text": "Choice A is incorrect because a finding that there’s an association between a decline in the regional abundance of some of dusky sharks’ prey and the regional abundance of dusky sharks wouldn’t directly support the researchers’ hypothesis that a decline in dusky sharks has led to a decline in eastern oysters in the region. Although such a finding might help explain why shark abundance has declined, it would reveal nothing about whether the shark decline is related to the oyster decline. Choice B is incorrect because a finding that eastern oyster abundance tends to be greater when dusky sharks and cownose rays are present than when only dusky sharks are present wouldn’t support the researchers’ hypothesis that a decline in dusky sharks has led to a decline in eastern oysters in the region. The text indicates that the sharks prey on the rays, which are the main predators of the oysters; if oyster abundance is found to be greater when rays are present than when rays are absent, that would suggest that rays aren’t keeping oyster abundance down, and thus that a decline in rays’ predators, which would be expected to lead to an increase in the abundance of rays, wouldn’t bring about a decline in oyster abundance as the researchers hypothesize. Choice C is incorrect because a finding that consumption of eastern oysters by cownose rays increased substantially before dusky sharks declined in regional abundance wouldn’t support the researchers’ hypothesis that the decline in dusky sharks has led to a decline in eastern oysters in the region. Such a finding would suggest that some factor other than shark abundance led to an increase in rays’ consumption of oysters and thus to a decrease in oyster abundance, thereby weakening the researchers’ hypothesis."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 15, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which finding, if true, would most directly support the researchers’ hypothesis?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice C is the best answer because it presents a finding that, if true, would support the researchers’ hypothesis about the plants’ dependence on dissolving rock. The text indicates that the roots of the two plant species grow directly into quartzite rock, where hairs on the roots secrete acids that dissolve the rock. The researchers hypothesize that the plants depend on this process because dissolving rock opens spaces for the roots to grow and releases phosphates that provide the plants with phosphorus, a vital nutrient. If the plants carry out this process of dissolving rock even when the rock already has spaces into which the roots could grow, that would support the researchers’ hypothesis because it suggests that the plants are getting some advantage—such as access to phosphorus—from the action of dissolving rock. If the plants don’t benefit from dissolving rock, they would be expected to grow in the cracks that already exist, as doing so would mean that the plants don’t have to spend energy creating and secreting acids; if, however, the plants create new entry points by dissolving rock even when cracks already exist, that would support the hypothesis that they depend on dissolving rock for some benefit."}, {"type": "paragraph", "text": "Choice A is incorrect because the existence of soil-inhabiting members of the Velloziaceae family with similar root structures to those of the two species discussed in the text wouldn’t support the researchers’ hypothesis that the species discussed in the text depend on dissolving rock. If other such members exist, that might suggest that the root structures can serve more functions than secreting acids to dissolve rock (since dissolving rock may not be necessary for plants living in soil), but that wouldn’t suggest anything about whether the species discussed in the text benefit from dissolving rock. Choice B is incorrect because differences in the proportions of citric and malic acid secreted by the two species would be irrelevant to the hypothesis that the plants depend on dissolving rock. There’s no information in the text to suggest that the proportion of each acid has any bearing on the process of dissolving rock or on any benefits the plants might receive from that process. Choice D is incorrect because if the two species thrive on rocks without phosphates, that would weaken the researchers’ hypothesis that the plants depend on dissolving rock partly because dissolving rock gives them access to phosphates. If the plants can survive on rocks without getting a vital nutrient by dissolving those rocks, then either the nutrient isn’t actually vital for those plants or they can get the nutrient in some way other than by dissolving rocks."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 16, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice most logically completes the text?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice A is the best answer because it most logically completes the text’s discussion of mosquito repellents. The text begins by explaining that many repellents work by using natural components to activate multiple odor receptors on mosquitoes’ antennae, and that new repellents must be created whenever mosquitoes become resistant to older ones. The text then highlights a research team’s discovery that EBF, a molecular component of a chrysanthemum-flower extract, can repel mosquitoes by activating a single odor receptor, Or31, that is shared by all species of mosquitoes known to carry diseases. The text suggests that compared to the repellents mentioned earlier, a repellent that acts on the Or31 receptor would be more effective: by noting that all mosquito species known to carry diseases share the Or31 receptor, the text suggests that the Or31 receptor may be unique in this respect, meaning that a repellent such as EBF that acts on it would be more effective since it works on a single receptor shared by all mosquito species that carry diseases, rather than a combination of receptors that is not shared by all species. Once mosquitoes become resistant to EBF, it would therefore make sense for researchers to look for other molecular components similar to EBF that target the activation of Or31 receptors, since a single such component could also repel all disease-carrying mosquitoes."}, {"type": "paragraph", "text": "Choice B is incorrect because nothing in the text suggests that EBF molecules are difficult to extract from chrysanthemums and that investigating alternative extraction methods would therefore be useful for developing efficient and effective mosquito repellents. Rather, the text suggests that researchers developing new mosquito repellents should aim to identify molecular components similar to EBF, since that component targets the Or31 odor receptor shared by all species of mosquitoes known to carry diseases. Choice C is incorrect because nothing in the text suggests that researchers are unaware of the precise location of Or31 and other odor receptors in mosquitoes’ antennae or that knowing this information would be useful for developing efficient and effective mosquito repellents. Rather, the text suggests that researchers developing new mosquito repellents should aim to identify molecular components similar to EBF, which targets the Or31 odor receptor. Choice D is incorrect because it doesn’t logically follow that the discovery of one odor receptor shared by all disease-bearing mosquitoes should lead to further research into which repellents might activate the greatest number of odor receptors. Rather, the text suggests that researchers developing new mosquito repellents should instead search for additional molecular components that, like EBF, activate the one odor receptor that is known to be shared by all disease- bearing mosquitoes."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 17, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice most logically completes the text?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice D is the best answer because it most logically completes the text’s discussion of Shultz’s finding about male tanagers. The text explains that because carotenoids both contribute to deeply saturated feathers and offer health benefits, having deeply saturated feathers is usually “an honest signal” (a true indication) that a bird is generally fit. However, Shultz and others have found that certain male tanagers can appear to have deeply saturated feathers even if they haven’t consumed a diet rich in carotenoids, thanks to microstructures in their feathers that manipulate light. If those birds aren’t necessarily eating carotenoid- rich diets, they may actually be less fit than other birds that appear to have similarly saturated feathers; this suggests that a male tanager’s appearance may function as a dishonest signal, or a false indication, of the bird’s overall fitness."}, {"type": "paragraph", "text": "Choice A is incorrect because Shultz’s finding suggests that some tanagers can signal fitness without consuming the carotenoids that contribute to fitness, thereby making those signals dishonest, not that tanagers can give honest signals of their fitness without consuming carotenoids. Choice B is incorrect because Shultz’s finding suggests that the microstructures in certain tanagers’ feathers can give a dishonest signal of fitness, not that the microstructures are less effective than actual pigmentation for signaling fitness. Whether the signal of fitness is honest or dishonest has no bearing on how effective the signal is: a signal is effective if potential mates behave as though it’s true, regardless of whether it’s actually true. Since there’s no information in the text about how potential mates respond to the dishonest signals of some tanagers, there’s no support for the idea that the dishonest signals are less effective than the honest signals. Choice C is incorrect because Shultz’s finding suggests that certain male tanagers may appear to be fitter than they actually are, not that scientists haven’t determined why tanagers prefer mates with colorful appearances."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 18, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text so that it conforms to the conventions of Standard English?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice C is the best answer. The convention being tested is subject-verb agreement. The singular verb “has been” agrees in number with the singular subject “writing.”"}, {"type": "paragraph", "text": "Choice A is incorrect because the plural verb “were” doesn’t agree in number with the singular subject “writing.” Choice B is incorrect because the plural verb “have been” doesn’t agree in number with the singular subject “writing.” Choice D is incorrect because the plural verb “are” doesn’t agree in number with the singular subject “writing.”"}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Standard English Conventions'), 'medium', 'source', 'approved', 19, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text so that it conforms to the conventions of Standard English?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice B is the best answer. The convention being tested is the use of non-finite (untensed) verb forms in a sentence. The modal “would,” which indicates the future from a perspective in the past, should be accompanied by a non-finite plain form verb. In this choice, the non-finite plain form verb “create” is used correctly in conjunction with the non-finite plain form verb “increase” to describe what the lock would do."}, {"type": "paragraph", "text": "Choice A is incorrect because the finite present tense verb “creates” can’t be used in this way with the modal “would” to describe what the lock would do."}, {"type": "paragraph", "text": "Choice C is incorrect because the present participle “creating” can’t be used in this way with the modal “would” to describe what the lock would do. Choice D is incorrect because the finite past tense verb “created” can’t be used in this way with the modal “would” to describe what the lock would do."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Standard English Conventions'), 'medium', 'source', 'approved', 20, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text so that it conforms to the conventions of Standard English?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice B is the best answer. The convention being tested is the use of punctuation around noun phrases. No punctuation is needed because the coordinated noun phrase “Thomas Hart Benton and Jackson Pollock” is a restrictive appositive, meaning that it provides essential identifying information about the noun phrase before it, “the renowned twentieth-century US artists.”"}, {"type": "paragraph", "text": "Choice A is incorrect because no punctuation is needed between the noun phrase “the renowned twentieth-century US artists” and the restrictive appositive “Thomas Hart Benton and Jackson Pollock.” Additionally, no punctuation is needed between the sentence’s subject (“paintings by the renowned twentieth- century US artists Thomas Hart Benton and Jackson Pollock”) and the main verb (“were featured”). Choice C is incorrect because no punctuation is needed between the coordinated elements “Thomas Hart Benton” and “Jackson Pollock.” Additionally, no punctuation is needed between the sentence’s subject (“paintings by the renowned twentieth-century US artists Thomas Hart Benton and Jackson Pollock”) and the main verb (“were featured”). Choice D is incorrect because no punctuation is needed between the noun phrase “the renowned twentieth- century US artists” and the restrictive appositive “Thomas Hart Benton and Jackson Pollock.”"}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Standard English Conventions'), 'medium', 'source', 'approved', 21, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text so that it conforms to the conventions of Standard English?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice A is the best answer. The convention being tested is the use of punctuation to mark boundaries between supplements and clauses. The comma after “equations” is used to separate the independent clause (“Hopper’s… equation”) from the supplementary adverb phrase “though.” The colon after “though” is used to mark the boundary between the clause ending with “though” and the following clause (“as…age”). A colon used in this way introduces information that illustrates or explains information that has come before it. In this case, the colon after “though” introduces the following explanation of how Hopper’s subsequent career would involve more than just solving equations: she would become a pioneering computer programmer."}, {"type": "paragraph", "text": "Choice B is incorrect because it results in a comma splice. A comma can’t be used in this way to join two independent clauses (“Hopper’s…though” and “as… age”) such as these. Choice C is incorrect because it results in an illogical sequence of sentences. Placing the period after “equations” and beginning the next sentence with “Though” illogically suggests that the following information (that Hopper would help usher in the digital age) is contrary to the information in the previous sentence (Hopper’s subsequent career would involve more than just solving equations). Instead, the information that follows supports the information from the previous sentence by explaining how her work and influence extended beyond solely solving equations. Choice D is incorrect because it results in a run-on sentence. The two independent clauses (“Hopper’s…though” and “as…age”) are fused without punctuation."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Standard English Conventions'), 'medium', 'source', 'approved', 22, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text so that it conforms to the conventions of Standard English?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice D is the best answer. The convention being tested is subject-verb agreement. The plural verb “attest” agrees in number with the plural subject “trailblazing accomplishments.”"}, {"type": "paragraph", "text": "Choice A is incorrect because the singular verb “attests” doesn’t agree in number with the plural subject “trailblazing accomplishments.” Choice B is incorrect because the singular verb “has attested” doesn’t agree in number with the plural subject “trailblazing accomplishments.” Choice C is incorrect because the singular verb “is attesting” doesn’t agree in number with the plural subject “trailblazing accomplishments.”"}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Standard English Conventions'), 'medium', 'source', 'approved', 23, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text so that it conforms to the conventions of Standard English?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice C is the best answer. The convention being tested is the punctuation of a supplementary phrase following a clause. This choice uses a comma to separate the supplementary adverb phrase “however” from the independent clause it modifies (“They…antiquity”) and uses a semicolon to join the first independent clause (“They…antiquity”) and the second independent clause (“some…literature”). Further, placing the semicolon after “however” indicates that the information in the clause that this is part of (that neoclassical writers were not the first to adopt classical literary modes) is contrary to what might be assumed from the information in the previous sentence (that the neoclassical writers were unique in imitating classical epic poetry and satires)."}, {"type": "paragraph", "text": "Choice A is incorrect because it fails to mark the boundary after “however” between the two independent clauses with appropriate punctuation. Choice B is incorrect because the comma after “however” can’t be used in this way to mark the boundary between the two independent clauses. Choice D is incorrect because placing the semicolon after “antiquity” illogically indicates that the information in the clause that this is part of (that prominent Renaissance figures were also influenced by classical literature) is contrary to the information in the previous clause (that neoclassical writers were not the first to adopt classical literary modes)."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Standard English Conventions'), 'medium', 'source', 'approved', 24, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text so that it conforms to the conventions of Standard English?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice C is the best answer. The convention being tested is the use of punctuation and verb forms within a sentence. This choice leaves the verb “admired” in its nonfinite past participle form to function within a supplementary element (“much…followed”). Offset by commas after “works” and “followed,” this supplementary element interrupts the main clause (“English poet and Shakespeare contemporary John Donne’s works…had…been essentially gathering dust…”) with additional information about the works’ reception during Donne’s lifetime."}, {"type": "paragraph", "text": "Choice A is incorrect because it fails to offset the supplementary element (“much…followed”) with appropriate punctuation, and using the finite verb “were much admired” results in an ungrammatical sentence. Choice B is incorrect because using the finite verb “were much admired” results in an ungrammatical sentence. Choice D is incorrect because it fails to offset the supplementary element (“much…followed”) with appropriate punctuation, and using the finite verb “had been much admired” results in an ungrammatical sentence."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Standard English Conventions'), 'medium', 'source', 'approved', 25, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text so that it conforms to the conventions of Standard English?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice D is the best answer. The convention being tested is subject-modifier placement. This choice makes “silica glass’s atomic arrangement” the subject of the sentence and places it immediately after the modifying phrase “compared to that of alumina glass.” In doing so, this choice clearly establishes that silica glass’s atomic arrangement—and not another noun in the sentence—is being compared to the atomic arrangement (“that”) of alumina glass."}, {"type": "paragraph", "text": "Choice A is incorrect because it results in a dangling modifier. The placement of the noun phrase “silica glass” immediately after the modifying phrase illogically suggests that silica glass itself (rather than its atomic arrangement) is being compared to alumina glass’s atomic arrangement. Choice B is incorrect because it results in a dangling modifier. The placement of the noun phrase “silica glass” immediately after the modifying phrase illogically suggests that silica glass itself (rather than its atomic arrangement) is being compared to alumina glass’s atomic arrangement. Choice C is incorrect because it results in a dangling modifier. The placement of the noun phrase “a significant disadvantage” immediately after the modifying phrase illogically suggests that “a significant disadvantage” is being compared to alumina glass’s atomic arrangement."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Standard English Conventions'), 'medium', 'source', 'approved', 26, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text with the most logical transition?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice A is the best answer. “Still” logically signals that the information about Sher-Gil in this sentence—that she longed to leave Paris and return to India— contrasts with what one would expect after reading about Sher-Gil’s experiences in Paris in the previous sentences."}, {"type": "paragraph", "text": "Choice B is incorrect because “therefore” illogically signals that the information about Sher-Gil in this sentence is a result or consequence of the descriptions in the previous sentences. Instead, this information contrasts with what one would expect after reading about Sher-Gil’s experiences in Paris. Choice C is incorrect because “indeed” illogically signals that the information about Sher-Gil in this sentence offers additional emphasis in support of the descriptions in the previous sentences. Instead, this information contrasts with what one would expect after reading about Sher-Gil’s experiences in Paris. Choice D is incorrect because “furthermore” illogically signals that the information about Sher-Gil in this sentence offers additional support for or confirmation of the descriptions in the previous sentences. Instead, this information contrasts with what one would expect after reading about Sher-Gil’s experiences in Paris."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Expression of Ideas'), 'medium', 'source', 'approved', 27, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text with the most logical transition?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice B is the best answer. “Specifically” logically signals that the information in this sentence—that Molina and Rowland’s research laid the foundation for a later treaty—provides specific, precise details elaborating on the previous sentence’s more general claim about the influence of the research."}, {"type": "paragraph", "text": "Choice A is incorrect because “regardless” illogically signals that the information in this sentence is true despite the previous sentence’s claim about the influence of Molina and Rowland’s research. Instead, this information—that the research laid the foundation for a later treaty—provides specific details elaborating on the previous claim. Choice C is incorrect because “however” illogically signals that the information in this sentence contrasts with the previous sentence’s claim about the influence of Molina and Rowland’s research. Instead, this information—that the research laid the foundation for a later treaty—provides specific details elaborating on the previous claim. Choice D is incorrect because “earlier” illogically signals that the information in this sentence occurred at a time before Molina and Rowland’s research influenced the fight against CFCs. Instead, this information—that the research laid the foundation for a later treaty—provides specific details elaborating on the previous claim about the research’s influence."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Expression of Ideas'), 'medium', 'source', 'approved', 28, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text with the most logical transition?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice C is the best answer. “Indeed” logically signals that the description of the art installation in this sentence—its blue room and preening unicorn that leave visitors “dazzled and confused”—offers additional emphasis in support of the previous sentence’s claim about the installation’s “whimsical yet perplexing experience.”"}, {"type": "paragraph", "text": "Choice A is incorrect because “second” illogically signals that the description in this sentence is a second, separate claim from the previous sentence’s claim about the installation’s “whimsical yet perplexing experience.” Instead, the specific details describing the installation emphasize and support the previous claim. Choice B is incorrect because “instead” illogically signals that the description in this sentence is an alternative to the previous sentence’s claim about the installation’s “whimsical yet perplexing experience.” Rather, the specific details describing the installation emphasize and support that claim. Choice D is incorrect because “nevertheless” illogically signals that the description in this sentence is true despite the previous sentence’s claim about the installation’s “whimsical yet perplexing experience.” Instead, the specific details describing the installation emphasize and support that claim."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Expression of Ideas'), 'medium', 'source', 'approved', 29, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice most effectively uses relevant information from the notes to accomplish this goal?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice A is the best answer. The sentence emphasizes the distance covered by the Philadelphia and Lancaster Turnpike, noting that the turnpike, which connected the two Pennsylvania cities in its name, was sixty-two miles long."}, {"type": "paragraph", "text": "Choice B is incorrect. The sentence emphasizes the significance of the turnpike; it doesn’t emphasize the distance that the turnpike covered. Choice C is incorrect. While the sentence mentions that the turnpike connected two Pennsylvania cities, it doesn’t emphasize the specific distance covered by the turnpike. Choice D is incorrect. The sentence emphasizes when the turnpike was built; it doesn’t emphasize the distance that the turnpike covered."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 30, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice most effectively uses relevant information from the notes to accomplish this goal?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice C is the best answer. The sentence emphasizes the aim, or goal, of the research study, noting what Terada set out to do: determine whether some of the Moon’s oxygen was coming from Earth."}, {"type": "paragraph", "text": "Choice A is incorrect. The sentence focuses on how the Kaguya satellite collected data; it doesn’t emphasize the aim of the research study. Choice B is incorrect. While the sentence mentions what Terada was curious about before conducting the research study, it doesn’t emphasize his study’s aim. Choice D is incorrect. The sentence presents the research study’s conclusion; it doesn’t emphasize the study’s aim."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 31, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice most effectively uses relevant information from the notes to accomplish this goal?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice A is the best answer. The sentence emphasizes the aim of the research study by highlighting what the researchers conducting the study wanted to know—specifically, which factors influence clutch size among lizards."}, {"type": "paragraph", "text": "Choice B is incorrect because the sentence emphasizes what researchers determined at the end of the study, not what the study’s aim was. Choice C is incorrect because the sentence emphasizes a finding from the research study, not the aim of the study. Choice D is incorrect because the sentence emphasizes the research study’s methodology, not its aim."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 32, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice most effectively uses relevant information from the notes to accomplish this goal?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice D is the best answer. The sentence uses information from the notes to make a generalization about the kind of study Glickman, Brown, and Song conducted. Specifically, the sentence indicates that the study was of a kind that used statistical methods to address questions of authorship within the field of music."}, {"type": "paragraph", "text": "Choice A is incorrect because the sentence summarizes the methodology and findings of a particular analysis of a single song; it doesn’t make a generalization about the kind of study conducted. Choice B is incorrect because the sentence mentions the data and conclusion of a particular analysis of a single song; it doesn’t make a generalization about the kind of study conducted. Choice C is incorrect because the sentence focuses on a specific conclusion from a particular analysis of a single song; it doesn’t make a generalization about the kind of study conducted."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 33, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text with the most logical and precise word or phrase?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice B is the best answer because it best completes the text’s discussion of how viewers respond to colors. The text presents something art scholars have noted and gives the example of people tending to find paintings with blues and greens more appealing than those with yellows and oranges. This context conveys that certain colors are more “attractive to” viewers than other colors are."}, {"type": "paragraph", "text": "Choice A is incorrect because the text indicates only that people tend to find some colors more appealing than others and gives no indication that certain colors are ever “confusing for,” or puzzling to, viewers. Choice C is incorrect because the text discusses the relative appeal of certain colors in paintings but gives no indication that any colors would ever be “corrected by” viewers, or somehow fixed or improved by them. Choice D is incorrect because it wouldn’t make much sense to say that some colors are more “similar to” viewers than others, which would suggest that colors and viewers are alike to different degrees. Further, the text primarily emphasizes a difference, not a similarity, in how appealing paintings tend to be based on the colors they contain."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Craft and Structure'), 'medium', 'source', 'approved', 1, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text with the most logical and precise word or phrase?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice A is the best answer because it most logically completes the text’s discussion of how biodiversity loss due to invasive species can be avoided. As used in this context, “preventable” means able to be stopped or kept from happening. The text indicates that “people can take simple steps” to avoid bringing possible invasive species into new environments. It presents these steps as an example of how biodiversity loss due to invasive species is preventable."}, {"type": "paragraph", "text": "Choice B is incorrect because it wouldn’t make sense to say that a simple step like washing your shoes after traveling is an example of biodiversity loss due to invasive species being “undeniable,” or something that can’t be proved to be wrong. Although the text may suggest that biodiversity loss due to invasive species is something that really happens, the word that completes the text must make the first sentence into an assertion that is illustrated by the second sentence, and the second sentence illustrates the idea that biodiversity loss due to invasive species is preventable, not undeniable. Choice C is incorrect because it wouldn’t make sense to say that a simple step like washing your shoes after traveling is an example of biodiversity loss due to invasive species being “common,” or something that happens regularly. Additionally, the text doesn’t provide any information about how frequently invasive species cause biodiversity loss. Choice D is incorrect because it wouldn’t make sense to say that a simple step like washing your shoes after traveling is an example of biodiversity loss due to invasive species being “concerning,” or something that is troubling or causes worry. Although the text implies that the phenomenon of biodiversity loss due to invasive species is itself a concerning phenomenon, the word that completes the text must make the first sentence into an assertion that is illustrated by the second sentence, and the second sentence illustrates the idea that biodiversity loss due to invasive species is preventable, not concerning."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Craft and Structure'), 'medium', 'source', 'approved', 2, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text with the most logical and precise word or phrase?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice B is the best answer because it most logically completes the text’s discussion about recycling plastics. In this context, “inadequate” means not satisfactory. The text indicates that the mechanical plastic-recycling process affects the environment and causes “the loss of material quality.” The text contrasts that with Chazovachii’s chemical plastic-recycling process, which is cleaner and produces a desirable product. The text’s emphasis on the negative aspects of mechanical recycling suggests that it is inadequate in terms of environmental impact and the quality of the material the process yields."}, {"type": "paragraph", "text": "Choice A is incorrect because in this context “resilient” would mean able to withstand difficulty and the text does not characterize the plastic-recycling process as having this quality or describe any difficulties that these processes might need to overcome. Choice C is incorrect because in this context “dynamic” would mean constantly changing. Although the text suggests that there have been changes in the field of recycling, as is the case with the advent of Chazovachii’s chemical recycling process, there is nothing to suggest that the mechanical process itself has changed or is prone to change. Choice D is incorrect because in this context “satisfactory” would mean acceptable but not perfect. The text mentions only shortcomings of the mechanical process (environmental effects and lower material quality), so the text more strongly supports a negative view of this process and provides no evidence that it would be considered satisfactory."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Craft and Structure'), 'medium', 'source', 'approved', 3, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text with the most logical and precise word or phrase?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice D is the best answer because it most logically completes the text’s discussion of the Three Sisters intercropping system. As used in this context, “intricate” would mean made up of complexly related elements. The text indicates that in the Three Sisters system, maize, squash, and beans form a “web of relations” in which the crops interact in various ways. The text’s description of these interactions—the bean vines growing on the maize stalks, the squash vines keeping weeds away, and the beans adding nutrients that the maize and squash use—provides context suggesting that this “web of relations” is intricate."}, {"type": "paragraph", "text": "Choice A is incorrect because describing the relationship among the crops in the Three Sisters system as “indecipherable,” or impossible to comprehend, would not make sense in context. Although the text presents the relationship as complex, the text’s description of the role that each crop plays makes it clear that the relationship is well understood, not indecipherable. Choice B is incorrect because the text discusses the practical benefits that each plant in the Three Sisters system provides to other members of the system, showing that the relationship among the crops that make up the system is not “ornamental,” or mainly serving a decorative purpose. Choice C is incorrect because describing the relationship among the crops in the Three Sisters system as “obscure,” or unknown or poorly understood, would not make sense in context. Although the text presents the relationship as complex, the text’s description of the role that each crop plays makes it clear that the relationship is well understood, not obscure."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Craft and Structure'), 'medium', 'source', 'approved', 4, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text with the most logical and precise word or phrase?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice D is the best answer because it most logically completes the text’s discussion of baleen whale accessory spleens. In this context, “latent” means dormant or functionless. The text sets up a contrast between the idea that baleen whale accessory spleens appear not to have a function and the research indicating that the accessory spleen may actually have a role in supporting the whales’ diving mechanisms. This context therefore conveys the idea that the assumption that baleen whale accessory spleens are latent may be incorrect."}, {"type": "paragraph", "text": "Choice A is incorrect because it wouldn’t make sense to say that the role of the accessory spleen is “replicable,” or capable of being reproduced. The text indicates that the role of the accessory spleen seems to have no function, but some researchers think it does have a role; the text doesn’t address whether the role of the accessory spleen could or couldn’t be reproduced. Choice B is incorrect because suggesting that the role of the accessory spleen is “predetermined,” or decided in advance, wouldn’t make sense in context. Although the researchers may agree that the role of the accessory spleen or any other organ hasn’t been determined in advance, the text focuses on the idea that the accessory spleen was thought to have been functionless but may in fact serve an active role for baleen whales. Choice C is incorrect because it’s the opposite of what the context of the text is conveying. The second sentence of the text indicates that baleen whale accessory spleens may not be useless, not that they aren’t “operative,” or functional."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Craft and Structure'), 'medium', 'source', 'approved', 5, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice best states the main purpose of the text?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice A is the best answer because it most accurately states the main purpose of the text. After providing a brief introduction to computer scientist Luis von Ahn, the text focuses on discussing how von Ahn’s digitization work led to the invention of a digital security test known as reCAPTCHA."}, {"type": "paragraph", "text": "Choice B is incorrect because the text doesn’t address how digital scanners work."}, {"type": "paragraph", "text": "Choice C is incorrect. Although the text mentions von Ahn’s book-digitizing project, that information is provided as a detail, not as the main purpose of the text. Choice D is incorrect because the text doesn’t provide any indication of reCAPTCHA’s popularity; instead, it describes reCAPTCHA’s origin."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Craft and Structure'), 'medium', 'source', 'approved', 6, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice best describes the overall structure of the text?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice C is the best answer because it most accurately describes the overall structure of the text. Throughout the text, the speaker characterizes nighttime as if it were a person who wears clothing (“a garment” that is “velvet soft” and “violet blue”) and a veil “over her face” and who moves her hands “slowly with their gem-starred light” through her dark hair. Thus, the text is structured as an extended comparison of night to a human being."}, {"type": "paragraph", "text": "Choice A is incorrect because the text never mentions any particular location; instead, it focuses on presenting a single description of night as a person with certain clothing and features. Choice B is incorrect because the text doesn’t make any reference to the sun or sunrise; instead, it focuses on presenting a single image of night as a person with certain clothing and features. Choice D is incorrect. Rather than describing how nighttime changes seasonally (or in any other way), the text presents a single image of night as a person with certain clothing and features."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Craft and Structure'), 'medium', 'source', 'approved', 7, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice best states the main purpose of the text?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice A is the best answer because it most accurately portrays the main purpose of the text. At the beginning of the text, Tom asserts that he and the other people staging the play are doing so only for “a little amusement among ourselves” and aren’t interested in attracting an audience or any attention with the production. Then, Tom promises that the play they chose is modest and appropriate, and he further reasons that using the well-written prose of “some respectable author” is better than using their own words. Overall, the main purpose of the text is to convey Tom’s promise that the play will be inoffensive and involve only a few people."}, {"type": "paragraph", "text": "Choice B is incorrect because the text doesn’t indicate that Tom had earlier intentions for the play’s performance or that anything has changed since the group first decided to stage a play. Instead, the text focuses on how harmless the entire endeavor will be. Choice C is incorrect. Although Tom mentions that using the words of a “respectable author” will be better than using their own words, he never addresses the idea that the people around him generally aren’t skilled enough to stage a play. Choice D is incorrect because in the text Tom specifically says that they “want no audience, no publicity,” which indicates that they don’t plan on promoting the play at all."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Craft and Structure'), 'medium', 'source', 'approved', 8, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Based on the texts, how would Behrenfeld and colleagues (Text 2) most likely respond to the “conventional wisdom” discussed in Text 1?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice A is the best answer because based on Text 2, it represents how Behrenfeld and colleagues would most likely respond to the “conventional wisdom” discussed in Text 1. The conventional wisdom cited holds the opinion that when there is species diversity within a phytoplankton population, “one species should emerge after outcompeting the rest”—that is, after being so successful in competing for resources that the other species vanish from the population. However, Text 2 explains that according to Behrenfeld and colleagues, phytoplankton are so small and spaced so far apart in the water that there is “much less” direct competition for resources within phytoplankton populations than scientists had previously thought."}, {"type": "paragraph", "text": "Choice B is incorrect because Text 2 never discusses whether routine replenishment of ocean nutrients affects competition between phytoplankton species. Choice C is incorrect because the interspecies competition discussed in both texts is specifically between phytoplankton species, and neither text considers whether phytoplankton compete for resources with larger nonphytoplankton species. Choice D is incorrect because according to Text 2, Behrenfeld and colleagues argue that water density decreases, not increases, competition between phytoplankton species."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Craft and Structure'), 'medium', 'source', 'approved', 9, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "According to the text, what did the narrator and Mario do while riding in the car?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice D is the best answer because it most accurately describes what the narrator and Mario did while riding in the car. The text describes a car trip that the narrator is taking with her family. The text states that during the car ride, the narrator and Mario “played games” to see how many different license plates they could spot."}, {"type": "paragraph", "text": "Choice A is incorrect because the text doesn’t mention the narrator and Mario reading during the car ride and instead describes them playing games. Choice B is incorrect because the text doesn’t mention the narrator and Mario singing songs during the car ride and instead describes them playing games. Choice C is incorrect because the text doesn’t mention the narrator and Mario sleeping during the car ride and instead describes them playing games."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 10, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "According to the text, how did Richard Wagner achieve moments of extremely high volume in his operas?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice B is the best answer because it presents a statement about how Richard Wagner achieved moments of extremely high volume in his operas that is supported by the text. The text states that European composers experimented with volume in their works by increasing the number of musicians in the orchestra and provides the example of Wagner, who “added more horns, trombones, and tubas to the orchestra.” The text explains that by having more of these instruments playing at the same time, the overall volume of the orchestra could be dramatically increased at key moments in Wagner’s operas."}, {"type": "paragraph", "text": "Choice A is incorrect because the text never indicates that Wagner moved his operas indoors to achieve moments of extremely high volume, nor does it indicate that his operas were previously performed outdoors. The only technique discussed in the text for achieving extremely high volume is Wagner’s addition of more instruments to create a bigger, louder orchestra. Choice C is incorrect because the text never says that Wagner built or used a specially designed concert hall to increase volume through echoes. The only technique discussed in the text is Wagner’s addition of more instruments to create a bigger, louder orchestra. Choice D is incorrect because the text never mentions any special training for singers related to volume or singing for extended periods. The text’s focus is entirely on the orchestra and how Wagner and other European composers used instruments to experiment with volume in their musical works."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 11, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which statement about the difrasismo in cuauhtli in ocelotl is most strongly supported by the text?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice C is the best answer because it presents a statement about the difrasismo in cuauhtli in ocelotl that is directly supported by the text. The text begins by describing difrasismo, a device used in Classical Nahuatl poetry. The text then mentions the device’s two functions: a formal one (giving structure to lines of verse) and a ritualistic one. The text indicates that the relation between the words in a difrasismo may appear tenuous without the additional information supplied by Aztec ceremonial culture but that the meaning becomes intelligible in the context of that information. Therefore, the difrasismo’s apparent obscurity can be resolved when considered in the proper cultural context."}, {"type": "paragraph", "text": "Choice A is incorrect because the text doesn’t indicate that the two nouns used in a difrasismo are semantically equivalent; instead, the text indicates that the two nouns used in a difrasismo make up a single metaphor whose meaning is often intelligible only in the context of information supplied by Aztec ceremonial culture."}, {"type": "paragraph", "text": "Choice B is incorrect because the text doesn’t indicate that there’s a relationship between the formal function of the difrasismo and the difrasismo’s intelligibility. Additionally, the text suggests that present-day readers who are familiar with Aztec ceremonial culture wouldn’t find the difrasismo to be unintelligible. Choice D is incorrect because the text doesn’t indicate that the frequency of difrasismo’s use in Classical Nahuatl is a necessary feature of intelligibility: the text indicates that an infrequently used difrasismo would presumably also be intelligible to members of an Aztec audience who are sufficiently familiar with Aztec ceremonial culture."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 12, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice best states the main idea of the text?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice D is the best answer because it most accurately states the main idea of the text. The text explains that economist Adam Smith’s famous metaphor of the invisible hand was putatively (that is, widely assumed but not proven) intended to illustrate a robust model (a consistently accurate generalization) of how individuals pursuing their own economic interests can create broader benefits for the population. The text then emphasizes the lack of affirmative evidence for this idea by calling out the term “putatively,” and explaining that, according to Gavin Kennedy, Smith used the metaphor only once in his works, in reference to specific circumstances related to the now-outdated economic view known as mercantilism, and that the metaphor didn’t garner much attention until economists in the twentieth century held it up as a paradigm (a theoretical framework in the field) and thereby implied that Smith shared some of their views on economics. By emphasizing “putatively,” the text implies that there is no independent reason to believe that Smith would agree with the metaphor’s use outside of the specific context for which he wrote it and that, therefore, the twentieth-century economists who used it did so to support their own views without regard for the metaphor’s importance to Smith’s work."}, {"type": "paragraph", "text": "Choice A is incorrect. Although the text indicates that Smith’s metaphor was largely ignored until some twentieth-century economists revived it and bolstered its status, the text suggests that the later economists used Smith’s metaphor to self-servingly boost their own work while ignoring the original context in which Smith wrote it. Moreover, the statement in this choice fails to reflect the text’s emphasis on Smith’s limited use of the metaphor in his work. Choice B is incorrect. Although the text indicates that some twentieth-century economists altered the significance of Smith’s metaphor, the text doesn’t suggest that the metaphor is a “useful model” of how aggregate benefits arise from individuals’ selfish actions, let alone that this usefulness is unaffected by taking the metaphor out of its original context. Choice C is incorrect. Although the text indicates that Smith’s metaphor was intended as a model of how individuals acting in their own interest produce aggregate benefits and it was written within the context of the now-outdated economic theory of mercantilism, these points are subordinate to the primary idea in the text, which is that Smith’s use of the metaphor was tightly constrained but twentieth-century economists ignored the original context so that they could use the metaphor to suggest, without support, that Smith would agree with their economic views."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 13, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice best describes data from the table that support the researchers’ claim?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice B is the best answer because it provides the most direct support from the table for the claim that two languages can convey similar amounts of information even if they’re spoken at different rates. The table shows the approximate rates at which five languages are spoken and the rates at which those five languages convey information. Vietnamese is spoken at around 5.3 syllables per second, whereas Spanish is spoken at around 7.7 syllables per second, but the two languages convey information at very similar rates: Vietnamese at a rate of around 42.5 bits per second and Spanish at a rate of around 42.0 bits per second. Thus, the description of Vietnamese conveying information at around the same rate that Spanish does despite being spoken more slowly supports the claim in the text that languages can convey the same amount of information even if spoken at different rates."}, {"type": "paragraph", "text": "Choice A is incorrect because it isn’t true that Thai and Hungarian have the lowest rates of speech of the five languages shown. According to the table, Hungarian is spoken at around 5.9 syllables per second, which is faster than Vietnamese (5.3 syllables per second). Additionally, even if this statement were true, the assertion that two languages are spoken the slowest and convey information the slowest wouldn’t support the claim that languages can convey the same amount of information even if they’re spoken at different rates. Choice C is incorrect because it isn’t true that the fastest-spoken language (Spanish, at 7.7 syllables per second) also conveys information the fastest: Spanish conveys information at 42.0 bits per second, which is slower than the 42.5 bits-per-second rate at which Vietnamese conveys information. Additionally, even if this statement were true, the assertion that the language spoken the fastest also conveys information the fastest has no bearing on the claim that languages can convey the same amount of information even if they’re spoken at different rates. Choice D is incorrect because it isn’t true that Serbian conveys information faster than Spanish does. According to the table, Serbian conveys information at a rate of around 39.1 bits per second, which is slower than the 42.0 bits-per-second rate at which Spanish conveys information."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 14, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice best describes data from the table that support Barrett and Rayfield’s suggestion?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice C is the best answer because it accurately describes data from the table that support Barrett and Rayfield’s suggestion about bite force estimates. According to the text, Barrett and Rayfield believe that estimates of dinosaur bite force may be strongly influenced by the methods used to produce them—that is, that different methods may produce significantly different results. The table shows that the studies by Bates and Falkingham and by Cost et al. used the same estimation method (muscular and skeletal modeling) and produced similar bite force estimates (approximately 35,000–57,000 newtons and 35,000–63,000 newtons, respectively). The study by Meers, however, used body-mass scaling and produced a much higher bite force estimate (183,000–235,000 newtons), while the study by Gignac and Erickson used tooth-bone interaction analysis and produced a much lower bite force estimate (8,000–34,000 newtons). The fact that one method produced similar estimates in two different studies and that two different methods used in other studies produced substantially different estimates supports the idea that dinosaur bite force estimates are significantly influenced by the methodology used to produce them."}, {"type": "paragraph", "text": "Choice A is incorrect because it inaccurately describes data from the table. The table does show that the studies by Meers and by Cost et al. used different estimation methods and produced very different ranges of estimated dinosaur bite force, which would support Barrett and Rayfield’s suggestion that different methodologies may produce significantly different estimates. However, the table doesn’t show that the study by Meers produced the lowest estimated maximum bite force while the study by Cost et al. produced the highest. In fact, the study by Meers estimated a maximum bite force of approximately 235,000 newtons, which is the highest of all the estimated maximums. Choice B is incorrect. Although the data from Gignac and Ericson’s study are accurately described, a single set of findings from one study using only one methodology can’t show that different methodologies may produce significantly different dinosaur bite force estimates, as Barrett and Rayfield suggest. Choice D is incorrect. Although the table shows that the maximum bite force estimated by Cost et al. was higher than that estimated by Bates and Falkingham, the difference is relatively small; in fact, both teams estimated a minimum bite force of approximately 35,000 newtons and a maximum bite force close to approximately 60,000 newtons. Because these findings demonstrate that a single methodology (muscular and skeletal modeling) produced similar overall results in two studies, the findings don’t support Barrett and Rayfield’s suggestion that different methodologies may produce significantly different dinosaur bite force estimates."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 15, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which finding from the researchers’ study, if true, would most strongly support their claim?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice A is the best answer because it presents a finding that, if true, would most strongly support the researchers’ claim that they found evidence that experiencing awe can make people feel more connected to others and thus more likely to behave altruistically (with beneficial and unselfish concern for others). According to the text, the researchers tested for this effect by first having participants look at either something known to be awe-inspiring (very tall trees) or something ordinary (a plain building) and then purposely spilling pens near the participants. The finding that participants who had looked at the trees helped pick up significantly more pens than did participants who had looked at the building would support the researchers’ claim by demonstrating that the people who had experienced awe behaved more altruistically when the experimenter needed help than the other participants did."}, {"type": "paragraph", "text": "Choice B is incorrect because a finding about helpful participants using positive words to describe the trees and the building after the experiment was over wouldn’t have any bearing on the researchers’ claim that experiencing awe increases altruistic behavior. The text doesn’t address the use of positive words to describe things or suggest any connection between using such words and having experienced awe, so that behavior wouldn’t serve as evidence that experiencing awe played a role in promoting helpful behavior. Choice C is incorrect because a finding that participants who didn’t help the experimenter were significantly more likely than others to report having experienced awe whether they had looked at the building or the trees would weaken the researchers’ claim that experiencing awe increases altruistic behavior by suggesting that the opposite might be true—that experiencing awe is in fact linked to choosing not to act in a way that benefits someone else. Choice D is incorrect because a finding about participants noticing that the experimenter had dropped the pens wouldn’t have any bearing on the researchers’ claim about people behaving altruistically. Being aware of a challenge or problem isn’t necessarily beneficial on its own and isn’t the same as offering help, so the finding wouldn’t support the idea that experiencing awe increases altruistic behavior."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 16, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice most logically completes the text?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice C is the best answer because it most logically completes the text’s discussion of the sweet potato in Polynesia. The text indicates that the sweet potato is found in Polynesia but originated in South America, and that the sweet potato was being cultivated by Native Hawaiians and other Indigenous peoples in Polynesia long before sea voyages between South America and Polynesia began. The text goes on to note that research by Muñoz-Rodríguez and colleagues has established that the Polynesian varieties of sweet potato split from South American varieties more than 100,000 years ago, which is thousands of years before humans settled in Polynesia. If Polynesian peoples were cultivating the sweet potato before sea voyages between Polynesia and South America began, and if Polynesian varieties of sweet potato diverged from South American varieties well before people were in Polynesia, it can reasonably be concluded that humans didn’t play a role in bringing the sweet potato to Polynesia."}, {"type": "paragraph", "text": "Choice A is incorrect. The text doesn’t provide any information about when the sweet potato began to be cultivated in South America, so there’s no support for the conclusion that cultivation began in Polynesia before it began in South America. Choice B is incorrect because the text indicates that the sweet potato was being cultivated in Polynesia long before sea journeys between Polynesia and South America began. Therefore, it wouldn’t be reasonable to conclude that Polynesian peoples acquired the sweet potato from South American peoples. Additionally, the text indicates that the Polynesian varieties of sweet potato diverged from the South American varieties thousands of years before people settled in Polynesia, which suggests that the sweet potato was already present in Polynesia when people arrived. Choice D is incorrect because the text states that the domestic sweet potato, which is found in Polynesia, descends from a wild South American plant, not from a domesticated South American plant. The only people that the text describes as cultivating the sweet potato are Native Hawaiians and other Indigenous peoples of Polynesia."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 17, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice most logically completes the text?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice D is the best answer because it most logically completes the text’s discussion of the morphology (form and structure) of sea stars, a type of echinoderm. The text indicates that echinoderms have radially symmetrical body plans (symmetrical around a central point, usually in the form of a star), whereas most animals have bilaterally symmetrical body plans (symmetrical along an axis running from head to tail through a trunk). According to the text, sea stars are unusual echinoderms because, despite their radial body plan, they descended from known bilateral ancestors. This shift in body plan was thought to be a process of losing the genetic markers associated with the head region. The text explains that by comparing the genes of one sea star species (P. miniata) to those of a close relative, the acorn worm, researchers determined that instead, anterior (head) genes are active across the sea star’s entire body, posterior (tail) genes are active in limited, peripheral locations of the body, and no trunk-related genes are active. This finding strongly suggests that, rather than becoming “headless” as they evolved from a bilateral ancestor, sea stars developed a body plan consisting almost entirely of a head region with a minimal tail region and no trunk region present."}, {"type": "paragraph", "text": "Choice A is incorrect because the text doesn’t identify how any particular region of sea stars’ bodies influences the layout of sea stars’ radial symmetry. Moreover, the text indicates that the radial symmetry of echinoderms is “usually starlike,” not that a starlike layout distinguishes sea stars from other echinoderms. Choice B is incorrect because the text doesn’t suggest that the idea that sea stars evolved from an ancestor with bilateral symmetry is incorrect (describing the bilateral origin as “known”) and doesn’t address any body plans other than those with radial or bilateral symmetry. The text strongly suggests that rather than revealing something about sea stars’ origin, Formery et al.’s findings contradict the assumption that the current body plan of sea stars is “headless.” Choice C is incorrect because the text suggests that Formery et al. were able to make determinations about P. miniata sea stars’ body plan based on the comparability of genetic markers between P. miniata and S. kowalevskii acorn worms. The text indicates only that little or no activity was observed in certain types of genes associated with body development in P. miniata, not that those genes turned out to largely differ from body-development genes in S. kowalevskii."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 18, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text so that it conforms to the conventions of Standard English?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice A is the best answer. The convention being tested is finite and nonfinite verb forms within a sentence. A main clause requires a finite verb to perform the action of the subject (in this case, “embryos”), and this choice supplies the clause with the finite present tense verb “enter” to indicate how the embryos achieve diapause."}, {"type": "paragraph", "text": "Choice B is incorrect because the nonfinite to-infinitive “to enter” doesn’t supply the main clause with a finite verb. Choice C is incorrect because the nonfinite participle “having entered” doesn’t supply the main clause with a finite verb."}, {"type": "paragraph", "text": "Choice D is incorrect because the nonfinite participle “entering” doesn’t supply the main clause with a finite verb."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Standard English Conventions'), 'medium', 'source', 'approved', 19, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text so that it conforms to the conventions of Standard English?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice B is the best answer. The convention being tested is the use of verbs to express tense. In this choice, the past perfect verb “had doubled” properly indicates that the doubling of the organization’s initial membership occurred during a specific period before the present (between the organization’s founding in 1967 and the end of the 1990s)."}, {"type": "paragraph", "text": "Choice A is incorrect because the present perfect verb “has doubled” doesn’t indicate that the organization’s doubling of its initial membership occurred during a specific period in the past. Choice C is incorrect because the present tense verb “doubles” doesn’t indicate that the organization’s doubling of its initial membership occurred during a specific period in the past. Choice D is incorrect because the future tense verb “will double” doesn’t indicate that the organization’s doubling of its initial membership occurred during a specific period in the past."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Standard English Conventions'), 'medium', 'source', 'approved', 20, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text so that it conforms to the conventions of Standard English?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice C is the best answer. The convention being tested is punctuation use between sentences. In this choice, the period after “percent” is used correctly to mark the boundary between one sentence (“After…percent”) and another (“Such… up”)."}, {"type": "paragraph", "text": "Choice A is incorrect because it results in a comma splice. A comma can’t be used in this way to mark the boundary between sentences. Choice B is incorrect. Without a comma preceding it, the conjunction “and” can’t be used in this way to join sentences. Choice D is incorrect because it results in a run-on sentence. The sentences (“After…percent” and “Such…up”) are fused without punctuation and/or a conjunction."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Standard English Conventions'), 'medium', 'source', 'approved', 21, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text so that it conforms to the conventions of Standard English?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice A is the best answer. The convention being tested is finite verb use in a main clause. A main clause requires a finite verb to perform the action of the subject (in this case, Ashford’s “gestures” and “habit”), and this choice supplies the finite past tense verb “helped” to indicate what Ashford’s gestures and habit helped accomplish."}, {"type": "paragraph", "text": "Choice B is incorrect because the non-finite participle “helping” doesn’t supply the main clause with a finite verb. Choice C is incorrect because the relative clause “that helped” doesn’t supply the main clause with a finite verb. Choice D is incorrect because the non-finite to-infinitive “to help” doesn’t supply the main clause with a finite verb."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Standard English Conventions'), 'medium', 'source', 'approved', 22, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text so that it conforms to the conventions of Standard English?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice C is the best answer. The convention being tested is the punctuation of a supplementary element within a sentence. The dash after “Springs” pairs with the dash after “earth” to separate the supplementary element “in this case, the porous rocks of the hills around Hot Springs” from the rest of the sentence."}, {"type": "paragraph", "text": "Choice A is incorrect because it fails to use appropriate punctuation to separate the supplementary element from the rest of the sentence. Choice B is incorrect because a colon can’t be paired with a dash in this way to separate the supplementary element from the rest of the sentence. Choice D is incorrect because a comma can’t be paired with a dash in this way to separate the supplementary element from the rest of the sentence."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Standard English Conventions'), 'medium', 'source', 'approved', 23, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text so that it conforms to the conventions of Standard English?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice A is the best answer. The convention being tested is the use of a colon within a sentence. In this choice, the colon is used in a conventional way to introduce the following description of how the number of jams available varied."}, {"type": "paragraph", "text": "Choice B is incorrect because it creates a comma splice. A comma can’t be used in this way to join two main clauses (“the number…varied” and “some…six”)."}, {"type": "paragraph", "text": "Choice C is incorrect because it results in an illogical and confusing sentence. Using the conjunction “while” to join the main clause (“the number…varied”) with the following clause’s description of the number of jams available suggests that the variation in the number of jams is in contrast to some shoppers having twenty-four options. Choice D is incorrect because it results in an illogical and confusing sentence. Using “while” in this way suggests that the number of jams available varied during the time in which some shoppers had twenty-four options and others had six. The sentence makes clear, however, that what follows “varied” is a description of the variation, not a separate, simultaneous occurrence."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Standard English Conventions'), 'medium', 'source', 'approved', 24, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text so that it conforms to the conventions of Standard English?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice B is the best answer. The convention being tested is the punctuation of items in a complex series (a series including internal punctuation). In this choice, the semicolon after “Lagos” is conventionally used to separate the first item (“The Joys…Lagos”) and the second item (“A Kind…Nigeria”) in the series. Further, the comma after “Marriage” correctly separates the title “A Kind of Marriage” from the supplementary phrase (“a television…Nigeria”) that describes it."}, {"type": "paragraph", "text": "Choice A is incorrect because the comma after “Lagos” doesn’t match the semicolon used later in the series to separate the second item (“A Kind…Nigeria”) from the third item (“and…autobiography”). Choice C is incorrect because the comma after “Lagos” doesn’t match the semicolon used later in the series to separate the second item (“A Kind…Nigeria”) from the third item (“and… autobiography”). Additionally, a colon can’t be used in this way to separate the title “A Kind of Marriage” from the supplementary phrase (“a television…Nigeria”) that describes it. Choice D is incorrect because it fails to use appropriate punctuation to separate the title “A Kind of Marriage” from the supplementary phrase (“a television…Nigeria”) that describes it."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Standard English Conventions'), 'medium', 'source', 'approved', 25, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text so that it conforms to the conventions of Standard English?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice A is the best answer. The convention being tested is the use of punctuation within a sentence. This choice correctly uses a comma to separate the supplementary adverb “though” from the preceding main clause (“Jetties can sometimes have the opposite effect”) and uses a semicolon to join the next main clause (“obstructing…areas”) to the rest of the sentence. Further, placing the semicolon after “though” logically indicates that the information earlier in this sentence (that jetties can sometimes cause erosion) is contrary to what might be assumed from the information in the previous sentence (that jetties are often constructed for the purpose of protecting coastlines from erosion)."}, {"type": "paragraph", "text": "Choice B is incorrect because it fails to mark the boundary between the two main clauses with appropriate punctuation. With “though…areas” functioning as a subordinate clause following the comma, this choice illogically indicates that the following information (that obstructing the natural flow of sand along the shore can sometimes lead to erosion) is contrary to the information earlier in the sentence (that jetties can sometimes cause erosion). Instead, the information following “though” supports the previous claim about the erosive effects of jetties. Choice C is incorrect because it’s not conventional to use a semicolon in this way to separate a main clause from a dependent clause. Further, it illogically indicates that the following information (that obstructing the natural flow of sand along the shore can sometimes lead to erosion) is contrary to the information earlier in the sentence (that jetties can sometimes cause erosion). Instead, the information following “though” supports the previous claim about the erosive effects of jetties. Choice D is incorrect because it results in a comma splice. Commas can’t be used in this way to set off a supplementary word or phrase between two main clauses."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Standard English Conventions'), 'medium', 'source', 'approved', 26, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text with the most logical transition?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice A is the best answer. “In fact” logically signals that the information in this sentence about the large number of recordings in ANLA’s collection emphasizes and supports the previous claim that ANLA is known for its impressive audio collection."}, {"type": "paragraph", "text": "Choice B is incorrect because “after” illogically signals that the information in this sentence occurs later in a sequence of events than the previous claim about ANLA’s impressive audio collection. Instead, the information about the large number of recordings emphasizes and supports that claim. Choice C is incorrect because “regardless” illogically signals that the information in this sentence is true despite the previous claim about ANLA’s impressive audio collection. Instead, the information about the large number of recordings emphasizes and supports that claim. Choice D is incorrect because “instead” illogically signals that the information in this sentence presents an alternative to the previous claim about ANLA’s impressive audio collection. Rather, the information about the large number of recordings emphasizes and supports that claim."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Expression of Ideas'), 'medium', 'source', 'approved', 27, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text with the most logical transition?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice A is the best answer. “Currently” logically signals that the archaeologists’ use of drones (a current technology) to photograph the lines is the present-day continuation of the ongoing archaeological research described in the previous sentence."}, {"type": "paragraph", "text": "Choice B is incorrect because “in comparison” illogically signals that the action described in this sentence offers a comparison to the ongoing archaeological research described in the previous sentence. Instead, the use of drones is the present-day continuation of that research. Choice C is incorrect because “still” illogically signals that the action described in this sentence occurs despite the ongoing archaeological research described in the previous sentence. Instead, the use of drones is the present-day continuation of that research. Choice D is incorrect because “however” illogically signals that the action described in this sentence occurs either despite or in contrast to the ongoing archaeological research described in the previous sentence. Instead, the use of drones is the present-day continuation of that research."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Expression of Ideas'), 'medium', 'source', 'approved', 28, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text with the most logical transition?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice C is the best answer. “By contrast” logically signals that the information in this sentence—that dogs can see, hear, and smell by the end of two weeks— contrasts with the preceding information (that wolves can smell but not see or hear at the same age)."}, {"type": "paragraph", "text": "Choice A is incorrect because “in other words” illogically signals that the information about domesticated dogs in this sentence paraphrases the information about wolves in the previous sentence. Instead, the information about dogs contrasts with what came before. Choice B is incorrect because “for instance” illogically signals that the information about domesticated dogs in this sentence exemplifies the information about wolves in the previous sentence. Instead, the information about dogs contrasts with what came before. Choice D is incorrect because “accordingly” illogically signals that the information about domesticated dogs in this sentence is in accordance with, or results from, the information about wolves in the previous sentence. Instead, the information about dogs contrasts with what came before."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Expression of Ideas'), 'medium', 'source', 'approved', 29, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text with the most logical transition?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice B is the best answer. “On the contrary” logically signals that the information in this sentence—that Dies Irae’s appearance of depth is merely an illusion—contrasts with the previous statement about a viewer’s possible assumption regarding the street painting."}, {"type": "paragraph", "text": "Choice A is incorrect because “additionally” illogically signals that this sentence is simply additional information about a viewer’s possible assumption regarding the street painting. Instead, the information about how Wenner achieved the illusion of depth contrasts with the previous sentence’s description of the illusion."}, {"type": "paragraph", "text": "Choice C is incorrect because “as a result” illogically signals that the information in this sentence is a result of, or caused by, a viewer’s possible assumption regarding the street painting. Instead, the information about how Wenner achieved the illusion of depth contrasts with the previous sentence’s description of the illusion. Choice D is incorrect because “next” illogically signals that the information in this sentence is the next step in a process. Instead, the information about how Wenner achieved the illusion of depth contrasts with the previous sentence’s description of the illusion."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Expression of Ideas'), 'medium', 'source', 'approved', 30, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text with the most logical transition?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice D is the best answer. “As such” correctly signals that the claim in this sentence—that Ostrom’s work is a repudiation of the “tragedy of the commons” view—follows logically from the information about Ostrom’s studies in the previous sentence. According to that sentence, Ostrom’s studies demonstrate that common pool resources can in fact be sustainably managed by the people who use them."}, {"type": "paragraph", "text": "Choice A is incorrect because “by contrast” illogically signals that the information in this sentence contrasts with the information about Ostrom’s studies in the previous sentence. Instead, the claim that Ostrom’s work repudiates the “tragedy of the commons” view follows logically from that information. Choice B is incorrect because “for example” illogically signals that the claim in this sentence exemplifies the information about Ostrom’s studies in the previous sentence. Instead, the claim that Ostrom’s work repudiates the “tragedy of the commons” view follows logically from that information. Choice C is incorrect because “that said” illogically signals that the information in this sentence is an exception or caveat to the information about Ostrom’s studies in the previous sentence. Instead, the claim that Ostrom’s work repudiates the “tragedy of the commons” view follows logically from that information."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Expression of Ideas'), 'medium', 'source', 'approved', 31, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice most effectively uses relevant information from the notes to accomplish this goal?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice B is the best answer. The sentence effectively explains an advantage of infilling: it’s less invasive than using a power grinder."}, {"type": "paragraph", "text": "Choice A is incorrect. The sentence identifies a disadvantage of power grinding; it doesn’t explain an advantage of infilling. Choice C is incorrect. The sentence identifies the two techniques park rangers use; it doesn’t explain an advantage of infilling. Choice D is incorrect. The sentence indicates that power grinding and infilling are different in one aspect; it fails to explain an advantage of infilling."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 32, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice most effectively uses relevant information from the notes to accomplish this goal?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice D is the best answer. The sentence emphasizes the role a misconception played in the naming of a place, explaining that Spanish explorers mistook a peninsula for an island and, as a result, named the peninsula after a fictional island, California."}, {"type": "paragraph", "text": "Choice A is incorrect. The sentence mentions a novel that featured a fictional island, California; it doesn’t emphasize the role a misconception played in the naming of a place. Choice B is incorrect. The sentence notes that Baja California was originally named after a fictional place; it doesn’t emphasize the role a misconception—specifically, the Spanish explorers’ mistaken belief that the peninsula was an island—played in the naming of a place. Choice C is incorrect. The sentence indicates when Spanish explorers learned of the peninsula they called California; it doesn’t emphasize the role a misconception played in the naming of a place."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 33, 'choice', array[]::text[]) returning id into v_q;
    update public.exams set status = 'published' where id = v_exam;
  end if;
  -- SAT Practice Test 8: Math
  if exists (select 1 from public.exams where slug = 'sat-practice-test-8-math') then
    raise notice 'skipping sat-practice-test-8-math (already imported)';
  else
    select id into v_subject from public.subjects where code = 'sat-math';
    values (v_subject, 'sat-practice-test-8-math', 'SAT Practice Test 8: Math', 'Official SAT Practice Test 8 (College Board), Math: 54 questions in two modules, including student-produced responses. Calculator allowed; 43 minutes per module.', 'full_mock', 'premium', 'draft', 86, 'source', 217, '[[200, 200], [210, 230], [210, 240], [210, 250], [210, 260], [210, 270], [210, 280], [210, 290], [220, 300], [230, 310], [260, 340], [290, 350], [320, 360], [330, 370], [340, 380], [350, 390], [350, 390], [360, 400], [370, 410], [380, 420], [380, 420], [390, 430], [390, 430], [400, 440], [410, 450], [420, 460], [430, 470], [440, 480], [450, 490], [460, 500], [470, 510], [480, 520], [490, 530], [490, 550], [500, 560], [510, 570], [520, 580], [540, 600], [550, 610], [560, 620], [570, 630], [590, 650], [600, 660], [610, 670], [630, 690], [640, 700], [660, 720], [670, 730], [690, 750], [710, 770], [740, 780], [760, 790], [770, 800], [780, 800], [800, 800]]'::jsonb)
    returning id into v_exam;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "A bus is traveling at a constant speed along a straight portion of road. The equation $d = 30t$ gives the distance $d$, in feet from a road marker, that the bus will be $t$ seconds after passing the marker. How many feet from the marker will the bus be $2$ seconds after passing the marker?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$d = 30(2) = 60$ feet."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'easy', 'source', 'approved', 1, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "For a particular machine that produces beads, $29$ out of every $100$ beads it produces have a defect. A bead produced by the machine will be selected at random. What is the probability of selecting a bead that has a defect?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$29$ of every $100$ beads are defective, so the probability is $\\tfrac{29}{100}$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Problem-Solving and Data Analysis'), 'easy', 'source', 'approved', 2, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "image", "src": "/sat/test-08/math-m1-q03.png", "alt": "Figure for question 3", "width": 255}, {"type": "paragraph", "text": "What is the $y$-intercept of the graph shown?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "The curve crosses the $y$-axis at $y = 8$, so the $y$-intercept is $(0, 8)$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Advanced Math'), 'easy', 'source', 'approved', 3, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "Which expression is equivalent to $(2x^2 + x - 9) + (x^2 + 6x + 1)$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Combine like terms: $3x^2 + 7x - 8$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Advanced Math'), 'easy', 'source', 'approved', 4, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "An analyst collected data on the price of a carton of grape tomatoes at $30$ locations selected at random in Utah. The mean price of a carton of grape tomatoes in Utah was estimated to be $\\$4.23$, with an associated margin of error of $\\$0.08$. Which of the following is a plausible statement about the mean price of a carton of grape tomatoes for all locations that sell this product in Utah?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "The plausible values are the estimate plus or minus the margin of error: $4.23 \\pm 0.08$, from $\\$4.15$ to $\\$4.31$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Problem-Solving and Data Analysis'), 'medium', 'source', 'approved', 5, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "math", "latex": "2.6 + x = 2.8"}, {"type": "paragraph", "text": "What value of $x$ is the solution to the given equation?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$x = 2.8 - 2.6 = 0.2$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'easy', 'source', 'approved', 6, 'spr', array['0.2', '1/5']::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "Out of $300$ seeds that were planted, $80\\%$ sprouted. How many of these seeds sprouted?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$0.80 \\times 300 = 240$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Problem-Solving and Data Analysis'), 'easy', 'source', 'approved', 7, 'spr', array['240']::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "math", "latex": "f(x) = 4x + b"}, {"type": "paragraph", "text": "For the linear function $f$, $b$ is a constant and $f(7) = 28$. What is the value of $b$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$4(7) + b = 28$, so $b = 0$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'easy', 'source', 'approved', 8, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "Right triangles $LMN$ and $PQR$ are similar, where $L$ and $M$ correspond to $P$ and $Q$, respectively. Angle $M$ has a measure of $53^\\circ$. What is the measure of angle $Q$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Corresponding angles of similar triangles are equal, so angle $Q$ measures $53^\\circ$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Geometry and Trigonometry'), 'easy', 'source', 'approved', 9, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "What is the equation of the line that passes through the point $(0, 5)$ and is parallel to the graph of $y = 7x + 4$ in the $xy$-plane?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "A parallel line has the same slope, $7$, and the $y$-intercept $5$: $y = 7x + 5$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'easy', 'source', 'approved', 10, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "image", "src": "/sat/test-08/math-m1-q11.png", "alt": "Figure for question 11", "width": 256}, {"type": "paragraph", "text": "Which of the following equations is the most appropriate linear model for the data shown in the scatterplot?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "The points fall from about $10$ near $x = 0$, so the model needs a negative slope and a positive $y$-intercept near $10$: $y = -1.9x + 10.1$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Problem-Solving and Data Analysis'), 'easy', 'source', 'approved', 11, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "A model predicts that the population of Bergen was $15{,}000$ in $2005$. The model also predicts that each year for the next $5$ years, the population $p$ increased by $4\\%$ of the previous year''s population. Which equation best represents this model, where $x$ is the number of years after $2005$, for $x \\le 5$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Starting at $15{,}000$ and growing by $4\\%$ a year multiplies by $1.04$ each year: $p = 15{,}000(1.04)^x$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Advanced Math'), 'medium', 'source', 'approved', 12, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "math", "latex": "\\begin{aligned} 2a + 8b &= 198 \\\\ 2a + 4b &= 98 \\end{aligned}"}, {"type": "paragraph", "text": "The solution to the given system of equations is $(a, b)$. What is the value of $b$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Subtract the second equation from the first: $4b = 100$, so $b = 25$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'easy', 'source', 'approved', 13, 'spr', array['25']::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "The expression $90y^5 - 54y^4$ is equivalent to $ry^4(15y - 9)$, where $r$ is a constant. What is the value of $r$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$ry^4(15y - 9) = 15ry^5 - 9ry^4$. Matching $15r = 90$ (and $9r = 54$) gives $r = 6$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Advanced Math'), 'medium', 'source', 'approved', 14, 'spr', array['6']::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "image", "src": "/sat/test-08/math-m1-q15.png", "alt": "Figure for question 15", "width": 248}, {"type": "paragraph", "text": "The graph of $y = f(x)$ is shown, where the function $f$ is defined by $f(x) = ax^3 + bx^2 + cx + d$ and $a$, $b$, $c$, and $d$ are constants. For how many values of $x$ does $f(x) = 0$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$f(x) = 0$ where the graph meets the $x$-axis. It crosses at three points (near $0$, $4$, and $7$)."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Advanced Math'), 'medium', 'source', 'approved', 15, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "The area $A$, in square centimeters, of a rectangular cutting board can be represented by the expression $w(w + 9)$, where $w$ is the width, in centimeters, of the cutting board. Which expression represents the length, in centimeters, of the cutting board?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Area $=$ width $\\times$ length, and the width is $w$, so the length is $w + 9$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Advanced Math'), 'easy', 'source', 'approved', 16, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "math", "latex": "p = \\frac{k}{4j + 9}"}, {"type": "paragraph", "text": "The given equation relates the distinct positive numbers $p$, $k$, and $j$. Which equation correctly expresses $4j + 9$ in terms of $p$ and $k$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Multiply both sides by $4j + 9$ and divide by $p$: $4j + 9 = \\dfrac{k}{p}$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Advanced Math'), 'easy', 'source', 'approved', 17, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "Circle $A$ has a radius of $3n$ and circle $B$ has a radius of $129n$, where $n$ is a positive constant. The area of circle $B$ is how many times the area of circle $A$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "The radius of $B$ is $43$ times the radius of $A$, so its area is $43^2 = 1{,}849$ times as large."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Geometry and Trigonometry'), 'medium', 'source', 'approved', 18, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "The measure of angle $R$ is $\\dfrac{2\\pi}{3}$ radians. The measure of angle $T$ is $\\dfrac{5\\pi}{12}$ radians greater than the measure of angle $R$. What is the measure of angle $T$, in **degrees**?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$T = \\dfrac{2\\pi}{3} + \\dfrac{5\\pi}{12} = \\dfrac{13\\pi}{12}$ radians $= \\dfrac{13}{12} \\times 180^\\circ = 195^\\circ$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Geometry and Trigonometry'), 'medium', 'source', 'approved', 19, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "math", "latex": "y = x^2 - 14x + 22"}, {"type": "paragraph", "text": "The given equation relates the variables $x$ and $y$. For what value of $x$ does the value of $y$ reach its minimum?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "The parabola opens upward, with vertex at $x = -\\dfrac{-14}{2(1)} = 7$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Advanced Math'), 'medium', 'source', 'approved', 20, 'spr', array['7']::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "A small business owner budgets $\\$2{,}200$ to purchase candles. The owner must purchase a minimum of $200$ candles to maintain the discounted pricing. If the owner pays $\\$4.90$ per candle to purchase small candles and $\\$11.60$ per candle to purchase large candles, what is the maximum number of large candles the owner can purchase to stay within the budget and maintain the discounted pricing?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "To maximize large candles, buy exactly $200$ in total: $L$ large and $200 - L$ small. Then $4.90(200 - L) + 11.60L \\le 2{,}200$, so $980 + 6.70L \\le 2{,}200$ and $L \\le 182.08\\ldots$. The maximum is $182$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'hard', 'source', 'approved', 21, 'spr', array['182']::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "math", "latex": "\\begin{aligned} y &\\le x + 7 \\\\ y &\\ge -2x - 1 \\end{aligned}"}, {"type": "paragraph", "text": "Which point $(x, y)$ is a solution to the given system of inequalities in the $xy$-plane?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "For $(14, 0)$: $0 \\le 21$ and $0 \\ge -29$, both true. Each other point fails one inequality."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'medium', 'source', 'approved', 22, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "image", "src": "/sat/test-08/math-m1-q23.png", "alt": "Figure for question 23", "width": 194}, {"type": "paragraph", "text": "The frequency table summarizes a data set of the weights, rounded to the nearest pound, of $71$ tortoises. A weight of $39$ pounds is added to the original data set, creating a new data set of the weights, rounded to the nearest pound, of $72$ tortoises. Which statement best compares the mean and median of the new data set to the mean and median of the original data set?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$39$ is above every original value, so the mean increases. The original median is the $36$th value; the cumulative counts are $12, 20, 25, 32, 41$, so the $36$th and $37$th values are both $17$. The new median (average of the $36$th and $37$th) is still $17$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Problem-Solving and Data Analysis'), 'hard', 'source', 'approved', 23, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "math", "latex": "x - 29 = (x - a)(x - 29)"}, {"type": "paragraph", "text": "Which of the following are solutions to the given equation, where $a$ is a constant and $a > 30$?"}, {"type": "math", "latex": "\\begin{aligned} &\\text{I. } a \\\\ &\\text{II. } a + 1 \\\\ &\\text{III. } 29 \\end{aligned}"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$x = 29$ makes both sides $0$. Otherwise divide by $x - 29$: $1 = x - a$, so $x = a + 1$. Checking $x = a$ gives $a - 29 = 0$, false since $a > 30$. So II and III only."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Advanced Math'), 'hard', 'source', 'approved', 24, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "In the $xy$-plane, the graph of the equation $y = -x^2 + 9x - 100$ intersects the line $y = c$ at exactly one point. What is the value of $c$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "A horizontal line meets a parabola once only at the vertex. The vertex is at $x = \\tfrac{9}{2}$, where $y = -\\tfrac{81}{4} + \\tfrac{81}{2} - 100 = -\\tfrac{319}{4}$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Advanced Math'), 'hard', 'source', 'approved', 25, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "The functions $f$ and $g$ are defined by the given equations, where $x \\ge 0$. Which of the following equations displays, as a constant or coefficient, the maximum value of the function it defines, where $x \\ge 0$?"}, {"type": "math", "latex": "\\begin{aligned} &\\text{I. } f(x) = 18(1.25)^x + 41 \\\\ &\\text{II. } g(x) = 9(0.73)^x \\end{aligned}"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$f$ grows without bound, so it has no maximum. $g$ decreases for $x \\ge 0$, so its maximum is $g(0) = 9$, which appears as the coefficient. Only II."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Advanced Math'), 'hard', 'source', 'approved', 26, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "The perimeter of an equilateral triangle is $852$ centimeters. The three vertices of the triangle lie on a circle. The radius of the circle is $w\\sqrt{3}$ centimeters. What is the value of $w$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Each side is $284$. The radius of the circle through the vertices of an equilateral triangle is $\\dfrac{s}{\\sqrt{3}} = \\dfrac{284}{\\sqrt{3}} = \\dfrac{284\\sqrt{3}}{3}$, so $w = \\dfrac{284}{3}$ (about $94.67$)."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Geometry and Trigonometry'), 'hard', 'source', 'approved', 27, 'spr', array['284/3', '94.66', '94.67']::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "image", "src": "/sat/test-08/math-m2-q01.png", "alt": "Figure for question 1", "width": 266}, {"type": "paragraph", "text": "What is the $y$-intercept of the line graphed?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "The line crosses the $y$-axis at $y = 5$, so the $y$-intercept is $(0, 5)$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'easy', 'source', 'approved', 1, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "table", "header": ["Type of store", "Average number of employees"], "rows": [["Warehouse store", "$365$"], ["Department store", "$213$"], ["Supermarket", "$130$"]]}, {"type": "paragraph", "text": "For a certain region, the table shows the average number of store employees in $2016$ by type of store. Based on the table, how much greater was the average number of store employees in warehouse stores than in supermarkets?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$365 - 130 = 235$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Problem-Solving and Data Analysis'), 'easy', 'source', 'approved', 2, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "image", "src": "/sat/test-08/math-m2-q03.png", "alt": "Figure for question 3", "width": 234}, {"type": "paragraph", "text": "In the figure, line $m$ is parallel to line $n$, and line $t$ intersects both lines. What is the value of $x$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "The $33^\\circ$ angle at line $n$ corresponds to the acute angle at line $m$ on the same side of $t$. Angle $x$ forms a straight line with that acute angle, so $x = 180 - 33 = 147$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Geometry and Trigonometry'), 'easy', 'source', 'approved', 3, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "Sean rents a tent at a cost of $\\$11$ per day plus a onetime insurance fee of $\\$10$. Which equation represents the total cost $c$, in dollars, to rent the tent with insurance for $d$ days?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$\\$11$ for each of $d$ days is $11d$, plus the one-time $\\$10$: $c = 11d + 10$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'easy', 'source', 'approved', 4, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "image", "src": "/sat/test-08/math-m2-q05.png", "alt": "Figure for question 5", "width": 291}, {"type": "paragraph", "text": "For the right triangle shown, $a = 4$ and $b = 5$. Which expression represents the value of $c$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "By the Pythagorean theorem, $c^2 = a^2 + b^2$, so $c = \\sqrt{4^2 + 5^2}$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Geometry and Trigonometry'), 'easy', 'source', 'approved', 5, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "The function $g$ is defined by $g(x) = 6x$. For what value of $x$ is $g(x) = 54$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$6x = 54$, so $x = 9$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'easy', 'source', 'approved', 6, 'spr', array['9']::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "The function $f$ is defined by $f(x) = 8x^3 + 4$. What is the value of $f(2)$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$f(2) = 8(8) + 4 = 68$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Advanced Math'), 'easy', 'source', 'approved', 7, 'spr', array['68']::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "The function $f$ is defined by $f(x) = \\dfrac{1}{10}x - 2$. What is the $y$-intercept of the graph of $y = f(x)$ in the $xy$-plane?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$f(0) = -2$, so the $y$-intercept is $(0, -2)$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'easy', 'source', 'approved', 8, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "A producer is creating a video with a length of $70$ minutes. The video will consist of segments that are $1$ minute long and segments that are $3$ minutes long. Which equation represents this situation, where $x$ represents the number of $1$-minute segments and $y$ represents the number of $3$-minute segments?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "The $1$-minute segments take $x$ minutes and the $3$-minute segments take $3y$ minutes: $x + 3y = 70$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'easy', 'source', 'approved', 9, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "The function $f$ is defined by $f(x) = 7x^3$. In the $xy$-plane, the graph of $y = g(x)$ is the result of shifting the graph of $y = f(x)$ down $2$ units. Which equation defines function $g$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Shifting down $2$ units subtracts $2$ from every output: $g(x) = 7x^3 - 2$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Advanced Math'), 'easy', 'source', 'approved', 10, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "math", "latex": "\\begin{aligned} y &= -3x \\\\ 4x + y &= 15 \\end{aligned}"}, {"type": "paragraph", "text": "The solution to the given system of equations is $(x, y)$. What is the value of $x$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Substitute: $4x - 3x = 15$, so $x = 15$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'easy', 'source', 'approved', 11, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "image", "src": "/sat/test-08/math-m2-q12.png", "alt": "Figure for question 12", "width": 302}, {"type": "paragraph", "text": "In the right triangle shown, what is the value of $\\sin A$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$\\sin A = \\dfrac{\\text{opposite}}{\\text{hypotenuse}} = \\dfrac{BC}{AB} = \\dfrac{35}{171}$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Geometry and Trigonometry'), 'easy', 'source', 'approved', 12, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "What is the area, in square centimeters, of a rectangle with a length of $34$ centimeters (cm) and a width of $29$ cm?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$34 \\times 29 = 986$ square centimeters."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Geometry and Trigonometry'), 'easy', 'source', 'approved', 13, 'spr', array['986']::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "If $\\dfrac{x}{y} = 4$ and $\\dfrac{24x}{ny} = 4$, what is the value of $n$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$\\dfrac{24x}{ny} = \\dfrac{24}{n} \\cdot \\dfrac{x}{y} = \\dfrac{96}{n} = 4$, so $n = 24$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'medium', 'source', 'approved', 14, 'spr', array['24']::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "A bowl contains $20$ ounces of water. When the bowl is uncovered, the amount of water in the bowl decreases by $1$ ounce every $4$ days. If $9$ ounces of water remain in this bowl, for how many days has it been uncovered?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$20 - 9 = 11$ ounces have evaporated, at $4$ days per ounce: $11 \\times 4 = 44$ days."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'medium', 'source', 'approved', 15, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "If $9(4 - 3x) + 2 = 8(4 - 3x) + 18$, what is the value of $4 - 3x$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Let $u = 4 - 3x$: $9u + 2 = 8u + 18$, so $u = 16$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'medium', 'source', 'approved', 16, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "A certain township consists of a $5$-hectare industrial park and a $24$-hectare neighborhood. The total number of trees in the township is $4{,}529$. The equation $5x + 24y = 4{,}529$ represents this situation. Which of the following is the best interpretation of $x$ in this context?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$5x$ is the number of trees in the $5$-hectare industrial park, so $x$ is the average number of trees per hectare there."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'medium', 'source', 'approved', 17, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "Which expression is equivalent to $a^{\\frac{11}{12}}$, where $a > 0$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$\\sqrt[144]{a^{132}} = a^{132/144} = a^{11/12}$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Advanced Math'), 'medium', 'source', 'approved', 18, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "image", "src": "/sat/test-08/math-m2-q19.png", "alt": "Figure for question 19", "width": 309}, {"type": "paragraph", "text": "The dot plots represent the distributions of values in data sets A and B."}, {"type": "paragraph", "text": "Which of the following statements must be true?"}, {"type": "paragraph", "text": "I. The median of data set A is equal to the median of data set B."}, {"type": "paragraph", "text": "II. The standard deviation of data set A is equal to the standard deviation of data set B."}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Each set has $17$ values, so the median is the $9$th. Counting dots from the left, the $9$th value is $13$ in both sets, so I is true. The sets are spread differently (B has more values at the ends), so their standard deviations are not equal."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Problem-Solving and Data Analysis'), 'medium', 'source', 'approved', 19, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "A circle has center $O$, and points $R$ and $S$ lie on the circle. In triangle $ORS$, the measure of $\\angle ROS$ is $88^\\circ$. What is the measure of $\\angle RSO$, in degrees? (Disregard the degree symbol when entering your answer.)"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$OR$ and $OS$ are radii, so the triangle is isosceles and its base angles are equal: $\\dfrac{180 - 88}{2} = 46$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Geometry and Trigonometry'), 'medium', 'source', 'approved', 20, 'spr', array['46']::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "The regular price of a shirt at a store is $\\$11.70$. The sale price of the shirt is $80\\%$ less than the regular price, and the sale price is $30\\%$ greater than the store''s cost for the shirt. What was the store''s cost, in dollars, for the shirt? (Disregard the $\\$$ sign when entering your answer. For example, if your answer is $\\$4.97$, enter $4.97$)"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "The sale price is $0.20 \\times 11.70 = 2.34$ dollars, which is $1.30$ times the cost. So the cost is $2.34 \\div 1.30 = 1.80$ dollars."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Problem-Solving and Data Analysis'), 'hard', 'source', 'approved', 21, 'spr', array['1.8', '9/5']::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "A cube has an edge length of $68$ inches. A solid sphere with a radius of $34$ inches is inside the cube, such that the sphere touches the center of each face of the cube. To the nearest cubic inch, what is the volume of the space in the cube **not** taken up by the sphere?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Cube: $68^3 = 314{,}432$. Sphere: $\\tfrac{4}{3}\\pi(34)^3 \\approx 164{,}636$. The difference is about $149{,}796$ cubic inches."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Geometry and Trigonometry'), 'hard', 'source', 'approved', 22, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "math", "latex": "y = 6x + 18"}, {"type": "paragraph", "text": "One of the equations in a system of two linear equations is given. The system has no solution. Which equation could be the second equation in the system?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "No solution means a parallel line with a different intercept. $-6x + y = 22$ is $y = 6x + 22$: same slope $6$, different intercept."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'medium', 'source', 'approved', 23, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "Triangles $PQR$ and $LMN$ are graphed in the $xy$-plane. Triangle $PQR$ has vertices $P$, $Q$, and $R$ at $(4, 5)$, $(4, 7)$, and $(6, 5)$, respectively. Triangle $LMN$ has vertices $L$, $M$, and $N$ at $(4, 5)$, $(4, 7 + k)$, and $(6 + k, 5)$, respectively, where $k$ is a positive constant. If the measure of $\\angle Q$ is $t^\\circ$, what is the measure of $\\angle N$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Both triangles have a right angle at $(4, 5)$ and two equal legs ($2$ and $2$; $2 + k$ and $2 + k$), so both are isosceles right triangles. Angles $Q$ and $N$ are complementary acute angles of such triangles, so $\\angle N = (90 - t)^\\circ$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Geometry and Trigonometry'), 'hard', 'source', 'approved', 24, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "math", "latex": "\\begin{aligned} 2x + 3y &= 7 \\\\ 10x + 15y &= 35 \\end{aligned}"}, {"type": "paragraph", "text": "For each real number $r$, which of the following points lies on the graph of each equation in the $xy$-plane for the given system?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "The second equation is $5$ times the first, so both describe the line $2x + 3y = 7$. If $y = r$, then $x = \\dfrac{7 - 3r}{2} = -\\dfrac{3r}{2} + \\dfrac{7}{2}$, which is choice B."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'hard', 'source', 'approved', 25, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "math", "latex": "\\frac{x^2}{\\sqrt{x^2 - c^2}} = \\frac{c^2}{\\sqrt{x^2 - c^2}} + 39"}, {"type": "paragraph", "text": "In the given equation, $c$ is a positive constant. Which of the following is one of the solutions to the given equation?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Subtract: $\\dfrac{x^2 - c^2}{\\sqrt{x^2 - c^2}} = \\sqrt{x^2 - c^2} = 39$, so $x^2 = c^2 + 39^2$ and $x = \\pm\\sqrt{c^2 + 39^2}$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Advanced Math'), 'hard', 'source', 'approved', 26, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "The quadratic function $g$ models the depth, in meters, below the surface of the water of a seal $t$ minutes after the seal entered the water during a dive. The function estimates that the seal reached its maximum depth of $302.4$ meters $6$ minutes after it entered the water and then reached the surface of the water $12$ minutes after it entered the water. Based on the function, what was the estimated depth, to the nearest meter, of the seal $10$ minutes after it entered the water?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$g(t) = a(t - 6)^2 + 302.4$ with $g(12) = 0$: $36a = -302.4$, so $a = -8.4$. Then $g(10) = -8.4(16) + 302.4 = 168$ meters."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Advanced Math'), 'hard', 'source', 'approved', 27, 'spr', array['168']::text[]) returning id into v_q;
    update public.exams set status = 'published' where id = v_exam;
  end if;
end $sat$;

do $sat$
declare
  v_subject uuid; v_exam uuid; v_section uuid; v_stim uuid; v_q uuid;
begin
  -- SAT Practice Test 9: Reading and Writing
  if exists (select 1 from public.exams where slug = 'sat-practice-test-9-reading-and-writing') then
    raise notice 'skipping sat-practice-test-9-reading-and-writing (already imported)';
  else
    select id into v_subject from public.subjects where code = 'sat-english';
    values (v_subject, 'sat-practice-test-9-reading-and-writing', 'SAT Practice Test 9: Reading and Writing', 'Official SAT Practice Test 9 (College Board), Reading and Writing: 66 questions in two modules, timed as the paper test (39 minutes per module).', 'full_mock', 'premium', 'draft', 78, 'source', 218, '[[200, 200], [210, 220], [210, 220], [210, 220], [210, 220], [210, 230], [210, 240], [210, 250], [220, 260], [220, 270], [230, 280], [230, 290], [240, 300], [250, 310], [260, 320], [270, 330], [280, 340], [300, 340], [310, 350], [320, 360], [330, 370], [330, 370], [340, 380], [350, 390], [360, 400], [360, 400], [370, 410], [380, 420], [380, 420], [390, 430], [400, 440], [410, 450], [410, 450], [420, 460], [430, 470], [440, 480], [450, 490], [460, 500], [470, 510], [470, 530], [470, 530], [480, 540], [490, 550], [500, 560], [510, 570], [520, 580], [530, 590], [540, 600], [560, 620], [570, 630], [580, 640], [590, 650], [600, 660], [610, 670], [620, 680], [630, 690], [660, 700], [670, 710], [680, 720], [690, 730], [710, 750], [720, 760], [730, 770], [740, 780], [760, 790], [780, 800], [800, 800]]'::jsonb)
    returning id into v_exam;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "As used in the text, what does the word “arranged” most nearly mean?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice A is the best answer because as used in the text, “arranged” most nearly means “organized.” The text states that a welcome feature of Manchester’s art galleries (as opposed to others) is that the titles of the paintings are easy to see and that a catalogue is therefore unneeded while visitors browse the art galleries. This suggests that the paintings are displayed in a systematic, or organized, way."}, {"type": "paragraph", "text": "Choice B is incorrect. “Ranked” might mean either classified or placed in orderly rows. Neither of these meanings would necessarily imply that the names of the paintings are easy to see (even if the paintings are placed in rows, their labels might be obscured). Choice C is incorrect because it would not make sense in context to describe the paintings as “scheduled,” or planned to take place at a certain time. Choice D is incorrect because if the paintings were “discussed,” or talked about, this would have no bearing on whether the names of the paintings could be easily seen."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Craft and Structure'), 'medium', 'source', 'approved', 1, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text with the most logical and precise word or phrase?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice D is the best answer because it most logically completes the text’s discussion of the challenge of generating electricity from ocean waves. In this context, “consistent” means steady or unchanging over time. The text introduces a challenge and then explains that wave power varies, or changes, unpredictably in ways that cause problems for electricity generation. This context conveys that the challenge being described is a lack of consistency."}, {"type": "paragraph", "text": "Choice A is incorrect because the text introduces a challenge and then elaborates on it by emphasizing that the unpredictable nature of variations in ocean waves causes problems, which doesn’t indicate that wave power isn’t “accidental,” or isn’t happening unintentionally. It wouldn’t make sense to describe waves—a natural occurrence—as happening intentionally. Choice B is incorrect because “confident” means having a feeling of self-assurance, and it wouldn’t make sense to describe wave power itself in terms of either having or lacking a sense of confidence. Choice C is incorrect because the text introduces a challenge and then elaborates on it by emphasizing that the unpredictable nature of variations in ocean waves causes problems, which doesn’t indicate that wave power isn’t “expensive,” or isn’t costly. If anything, technological and planning problems might actually increase the expense of generating electricity from waves."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Craft and Structure'), 'medium', 'source', 'approved', 2, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text with the most logical and precise word or phrase?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice C is the best answer because it most logically completes the text’s discussion of John Ashbery’s poems. As used in this context, “interpret” would mean decipher the meaning of. The text indicates that Ashbery’s poems have many unusual features, that it’s difficult to tell what exactly the poems’ subject matter is, and that scholars strongly disagree about the poems. This context conveys the idea that it’s difficult to interpret Ashbery’s poems."}, {"type": "paragraph", "text": "Choice A is incorrect because “delegate” means to assign someone as a representative of another person or to entrust something to someone else, neither of which would make sense in context. The text is focused only on the difficulty that readers have interpreting Ashbery’s poems due to their many unusual features; it doesn’t suggest anything about the poems being difficult to delegate. Choice B is incorrect because describing Ashbery’s poems as difficult to “compose,” or put together or produce, would make sense only if the text were about Ashbery’s experience of writing the poems. It could be true that it was difficult for Ashbery to compose his poems, but the text doesn’t address this; it instead discusses how readers interpret and engage with the poems. Choice D is incorrect because describing Ashbery’s poems as being difficult to “renounce,” or give up or refuse, wouldn’t make sense in context. The text focuses on the idea that features of Ashbery’s poems are odd or unclear and have caused heated scholarly debate. This context suggests that the poems are difficult to interpret, not that the poems are difficult to renounce."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Craft and Structure'), 'medium', 'source', 'approved', 3, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text with the most logical and precise word or phrase?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice C is the best answer because it most logically completes the discussion of the artist Diego Velázquez’s influence outside Spain. As used in this context, “confined to” means restricted to. The text says that Velázquez was the leading artist in the Spanish court during the seventeenth century, but it also notes that other painters around the world were influenced by his techniques and style. Thus, Velázquez’s influence was hardly (or almost not) confined to, or restricted to, Spain."}, {"type": "paragraph", "text": "Choice A is incorrect because if Velázquez was a leading artist in Spain, it doesn’t make logical sense to claim that his influence was hardly (or almost not) derived from, or obtained from, Spain. Moreover, the other painters around the world who employed Velázquez’s techniques would by definition be influenced by Spanish style. Choice B is incorrect because if Velázquez was a leading artist in the court of King Philip IV of Spain, then his influence must have been widely recognized, or acknowledged, rather than being hardly (or almost not) recognized. Choice D is incorrect because the text gives no indication that deliberately limiting Velázquez’s influence outside Spain was ever considered by anyone. Thus, even if it is true that his influence was not repressed, or restrained, it doesn’t make logical sense to say so in this context."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Craft and Structure'), 'medium', 'source', 'approved', 4, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text with the most logical and precise word or phrase?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice B is the best answer because it most logically completes the discussion of Octavia Butler’s career. In this context, “impenetrable” means impossible to enter. The text indicates that the field of science fiction was dominated by white males when Butler, a Black woman, started writing, but she published several science fiction short stories and a novel and later won a prestigious award; that is, Butler pursued science fiction writing and had success. This context suggests that Butler didn’t view the genre as impossible to enter."}, {"type": "paragraph", "text": "Choice A is incorrect. In this context, “legitimate” would mean genuinely good or valid. Nothing in the text suggests that Butler didn’t think the science fiction genre was good or valid; in fact, it indicates that she pursued and made a successful career of publishing work in that field. Choice C is incorrect. In this context, “compelling” would mean attracting or demanding attention. The text indicates that Butler chose to write science fiction, so it wouldn’t make sense to say that she didn’t see the field as drawing her attention. Choice D is incorrect. To say that Butler didn’t consider science fiction “indecipherable,” or impossible to understand, would suggest that Butler did understand it. However, the text doesn’t address Butler’s ability to interpret works in the genre; rather, it focuses on Butler’s successful pursuit of writing science fiction."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Craft and Structure'), 'medium', 'source', 'approved', 5, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, 0, '{"blocks": [{"type": "paragraph", "text": "Which choice best describes the function of the underlined sentence?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice C is the best answer because it most accurately describes how the underlined sentence functions in the text as a whole. The underlined sentence establishes a difference between Uncle Katsuhisa and the narrator’s father by describing Uncle Katsuhisa as “loud” and the narrator’s father as “quiet.” The text then elaborates on that contrast, describing some ways Uncle Katsuhisa is very noisy even when he isn’t speaking."}, {"type": "paragraph", "text": "Choice A is incorrect because the text doesn’t indicate what kinds of topics Uncle Katsuhisa enjoys discussing, only that he is loud even when he isn’t speaking."}, {"type": "paragraph", "text": "Choice B is incorrect because the text never indicates how Uncle Katsuhisa feels about meeting new people, only how loud he is. Choice D is incorrect because the text never describes a conversation occurring between any people; it refers to talking only when stating that Uncle Katsuhisa is loud even when he isn’t speaking."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Craft and Structure'), 'medium', 'source', 'approved', 6, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, 0, '{"blocks": [{"type": "paragraph", "text": "Which choice best describes the function of the underlined sentence in the text as a whole?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice A is the best answer because it best describes how the underlined sentence functions in the text as a whole. According to the text, it was hard for Yamauchi to adapt her short story into the play And the Soul Shall Dance because the story had included little dialogue, instead describing the characters’ silent thoughts. The underlined sentence offers information about how Yamauchi ultimately succeeded in adapting the story into a play: it explains that Yamauchi created situations where the characters of the play could reveal their internal thoughts while speaking with each other."}, {"type": "paragraph", "text": "Choice B is incorrect because neither the underlined sentence nor the text as a whole makes any mention of playwrights other than Yamauchi or how the play might have influenced them. Choice C is incorrect because the text states that Yamauchi is best known for her play And the Soul Shall Dance, which conveys that the play is better known than the short story it’s based on is. Choice D is incorrect because neither the underlined sentence nor the text as a whole mentions the actors who performed in the play or Yamauchi’s approach to choosing them."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Craft and Structure'), 'medium', 'source', 'approved', 7, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, 0, '{"blocks": [{"type": "paragraph", "text": "Which choice best describes the function of the underlined portion in the text as a whole?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice A is the best answer because it most accurately describes the function of the underlined portion in the text as a whole. The text establishes that many countries have adopted risk-disclosure requirements for financial products due to concerns that consumers don’t understand the risks associated with the products. According to the text, Seira et al. found that the effects of such messaging on consumer behavior were small and temporary. The text then adds that the researchers assert that because the cost of the messaging is negligible, the approach may be worth doing even if the effects are limited. Thus, the underlined portion notes a factor—very low cost—that led the researchers to not completely dismiss risk-disclosure messaging despite their evidence of its limited utility."}, {"type": "paragraph", "text": "Choice B is incorrect because the underlined portion doesn’t refer to a particular type of risk-disclosure messaging, whether Seira et al. considered it or not; the underlined portion simply indicates that the cost of the messaging (broadly) is very low, which makes the approach worth pursuing even if its effects are limited."}, {"type": "paragraph", "text": "Choice C is incorrect. Although the underlined portion does describe a consideration that led the researchers to recommend risk-disclosure messaging despite the messaging’s small effects on consumer behavior, it directly states that the cost of such messaging is negligible, or very low—meaning that both the effects and the costs are small, not that the effects are small only relative to the costs. Choice D is incorrect because there’s no indication that Seira et al. suggest that risk-disclosure messaging could be more effective if it had lower costs; rather, the underlined portion indicates that Seira et al. believe the already negligible cost of messaging makes the approach worth pursuing even if its effects are limited."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Craft and Structure'), 'medium', 'source', 'approved', 8, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Based on the texts, how would Focarelli and Panetta (Text 2) most likely respond to Fan’s findings (Text 1)?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice C is the best answer because, based on the information presented in the texts, it represents how Focarelli and Panetta would most likely respond to Fan’s findings. Text 1 indicates that Fan found that a newspaper merger would result in a rise in subscription prices. This rise wouldn’t benefit customers, who would have to pay more for news after a merger. Text 2 presents Focarelli and Panetta’s argument that merger research tends to focus too much on what happens immediately after the merger. Text 2 goes on to describe their finding that mergers can be economically beneficial for consumers over the long term. This suggests that Focarelli and Panetta would encourage Fan to investigate the long-term effect of the hypothetical newspaper merger on subscription prices."}, {"type": "paragraph", "text": "Choice A is incorrect because Text 2 doesn’t indicate that Focarelli and Panetta connect the effects of mergers to specific locations. Instead, Focarelli and Panetta focus on the length of time over which the effects of mergers should be evaluated. Choice B is incorrect because Text 2 indicates that Focarelli and Panetta found that merged companies experience “efficiency gains” over the long term, meaning that their expenses go down relative to their output, not that their expenses increase. Choice D is incorrect because there’s no indication in Text 2 that Focarelli and Panetta believe that the newspaper industry is different from any other industry when it comes to the effects of mergers. Although their own research was about consumer banking, Text 2 suggests that they view their conclusions as applicable to mergers in general."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Craft and Structure'), 'medium', 'source', 'approved', 9, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "According to the text, why are ecologists worried about Pando?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice A is the best answer because it presents an explanation that is directly stated in the text for why ecologists are worried about Pando. The text states that Pando is a colony of about 47,000 quaking aspen trees that represents one of the largest organisms on Earth. According to the text, ecologists are worried that Pando’s growth is declining, partly because animals are feeding on the trees. In other words, the ecologists are worried that Pando isn’t growing at the same rate it used to."}, {"type": "paragraph", "text": "Choice B is incorrect. Rather than indicating that Pando isn’t producing young trees anymore, the text reveals that Pando is indeed producing young trees, stating that those trees can be protected from grazing deer by strong fences."}, {"type": "paragraph", "text": "Choice C is incorrect because the text states that fences can be used to prevent deer from eating Pando’s young trees, not that Pando itself can’t grow in new areas because it’s blocked by fences. Choice D is incorrect because the text offers no evidence that Pando’s root system is incapable of supporting new trees or is otherwise a cause of worry for ecologists."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 10, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "According to the table, in which year was the dolphin with the ID FB43 recorded with her calf?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice D is the best answer because it accurately reflects the data in the table. According to the table, the dolphin with ID FB43 has a recording year of 1992."}, {"type": "paragraph", "text": "Choice A is incorrect. None of the dolphins in the table have a recording year of 1999. Choice B is incorrect. The table shows 2012 as the recording year for the dolphin with ID FB07, not ID FB43. Choice C is incorrect. None of the dolphins in the table have a recording year of 2020."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 11, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice most effectively uses data from the table to complete the text?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice C is the best answer because it most effectively uses data from the table to complete the statement about the forestry student’s project. The table shows five types of maple trees, each tree’s maximum height, and whether each tree is native to North America. The text indicates that the student needs to recommend a maple tree that’s native to North America and won’t reach a height greater than 60 feet. The red maple is the only tree listed in the table that meets these criteria: its maximum height is 60 feet—meaning that it won’t grow higher than 60 feet— and it’s native to North America."}, {"type": "paragraph", "text": "Choice A is incorrect because the text states that the student needs to recommend a tree that’s native to North America and won’t grow higher than 60 feet, but the table shows that the maximum height of the silver maple is 70 feet. Choice B is incorrect because the text states that the student needs to recommend a tree that’s native to North America and won’t grow higher than 60 feet, but the table shows that the maximum height of the sugar maple is 75 feet. Choice D is incorrect because the text states that the student needs to recommend a tree that’s native to North America and won’t grow higher than 60 feet, but the table shows that the Norway maple isn’t native to North America."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 12, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice best describes data in the graph that support Ayalew and her colleagues’ hypothesis?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice D is the best answer because it best describes data in the graph supporting Ayalew and her colleagues’ hypothesis that plants’ response to kanamycin exposure involves altering their uptake of metals. The graph compares the metal content of two groups of plants, one with kanamycin exposure and a control group without such exposure. The amount of zinc in plants without kanamycin exposure is around 400 parts per million, while the amount of zinc in plants with kanamycin exposure is lower, at around 300 parts per million. Similarly, the amount of iron in plants without kanamycin exposure is a little over 600 parts per million, while the amount of iron in plants with kanamycin exposure is lower, at a little over 200 parts per million. Thus, the graph shows that plants with kanamycin exposure have significantly lower levels of both iron and zinc than the plants without kanamycin exposure. This is evidence supporting the hypothesis that kanamycin exposure results in plants altering their uptake of metals."}, {"type": "paragraph", "text": "Choice A is incorrect because the graph shows that control plants contained higher levels of iron than zinc, not higher levels of zinc than iron; similarly, the plants exposed to kanamycin contained higher levels of zinc than iron, not higher levels of iron than zinc. Choice B is incorrect. Though the claim that both groups of plants contained more than 200 parts per million of both iron and zinc is supported by the graph, this alone does not state whether plants with kanamycin exposure have a different metal content than plants without kanamycin exposure."}, {"type": "paragraph", "text": "Choice C is incorrect. The graph shows that the zinc levels for the control plants (those without kanamycin exposure) were around 400 parts per million, not 300 parts per million, and that the zinc levels for plants with kanamycin exposure were around 300 parts per million, not 400 parts per million."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 13, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice best describes data from the table that support the researcher’s hypothesis?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice C is the best answer because it describes data from the table that support the researcher’s hypothesis. According to the text, the researcher hypothesized that Arctic ground squirrels would exhibit longer torpor bouts and shorter arousal episodes than Alaska marmots do—or, put the other way, that the marmots would show shorter torpor bouts and longer arousal episodes than the ground squirrels do. The table shows data about torpor bouts and arousal episodes for the two species from 2008 to 2011. According to the table, the average duration of torpor bouts was 13.81 days for Alaska marmots, shorter than the average of 16.77 days for Arctic ground squirrels, and the average duration of arousal episodes was 21.2 hours for Alaska marmots, longer than the average of 14.2 hours for Arctic ground squirrels. Thus, the table supports the researcher’s hypothesis by showing that Alaska marmots had shorter bouts of torpor and longer arousal episodes than Arctic ground squirrels did."}, {"type": "paragraph", "text": "Choice A is incorrect because it inaccurately describes data from the table and doesn’t support the researcher’s hypothesis. The table shows that the average duration of arousal episodes was less than a day for both Alaska marmots (21.2 hours) and Arctic ground squirrels (14.2 hours). Additionally, information about arousal episodes for Alaska marmots and Arctic ground squirrels isn’t sufficient to support a hypothesis involving comparisons of both arousal episodes and torpor bouts for those animals. Choice B is incorrect because it doesn’t support the researcher’s hypothesis, which involves comparisons of arousal episodes as well as torpor bouts for Alaska marmots and Arctic ground squirrels. Noting that both animals had torpor bouts lasting several days, on average, doesn’t address arousal episodes at all, nor does it reveal how the animals’ torpor bouts compared. Choice D is incorrect because it doesn’t support the researcher’s hypothesis. Although the table does show that Alaska marmots had more torpor bouts (12) than arousal episodes (11) and that their arousal episodes were much shorter than their torpor bouts (21.2 hours and 13.81 days, respectively), comparing data across only Alaska marmot behaviors isn’t sufficient to support a hypothesis about torpor and arousal behaviors of both Alaska marmots and Arctic ground squirrels."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 14, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice most effectively uses data from the graph to complete the student’s conclusion?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice A is the best answer because it most effectively uses data from the graph to complete the student’s conclusion about beehive structure. The text explains that in the hives of honeybees, the hexagonal cells housing drone eggs are larger than the hexagonal cells housing worker eggs, and that this size difference results in a construction problem that the bees address by using nonhexagonal cells to fill gaps between sections of drone-egg cells and worker-egg cells. The text also states that the size difference between drone-egg cells and worker-egg cells varies by species of honeybee. The graph displays data on the percentage of nonhexagonal cells in the hives of three species. In the hives of the western honeybee, the percentages of five-sided, seven-sided, and eight-sided cells are all less than 0.5%. But in the hives of the black dwarf honeybee, the percentages of five-sided and seven-sided cells are higher than those for the western honeybee: about 2.5% for both. And for the dwarf honeybee, the percentages of five-sided and seven-sided cells are also higher than those for the western honeybee: slightly over 2.5% and slightly over 2.0%, respectively; additionally, the dwarf honeybee possesses a higher percentage of eight-sided cells than the western honeybee does. Taken altogether, the graph shows that the hives of the western honeybee consist of a smaller percentage of nonhexagonal cells than the hives of the two other species do. Since the nonhexagonal cells exist only to solve the construction problem arising from the difference in size between drone-egg cells and worker-egg cells, a smaller percentage of nonhexagonal cells would be associated with a smaller size difference between the two types of cells. Therefore, it can be concluded from the data that worker-egg cells are probably closer in size to drone-egg cells in the hives of the western honeybee than in the hives of the other two species."}, {"type": "paragraph", "text": "Choice B is incorrect because, as the text states, honeybee species deposit their eggs in hexagonal cells, not in nonhexagonal ones. Thus, the western honeybee and black dwarf honeybee wouldn’t deposit drone eggs in eight-sided cells, and the dwarf honeybee wouldn’t deposit drone eggs in seven-sided cells. Choice C is incorrect. The text explains that honeybees rely mainly on one geometric shape, the hexagon, when constructing their hives, and the graph shows that the western honeybee relies on the same nonhexagonal shapes as the dwarf honeybee does: five-sided, seven-sided, and eight-sided cells. In other words, the western honeybee and dwarf honeybee rely on the same number of geometric shapes. For the black dwarf honeybee, the graph displays data only for five-sided and seven-sided cells, which suggests a total absence of eight-sided cells. Yet this would be only one less nonhexagonal shape than is seen in the western honeybee. Thus, based on the graph, it would be inaccurate to say that the western honeybee relies on “many more” geometrical shapes than the other two species do. Choice D is incorrect. As the text explains, honeybee hives consist mainly of hexagonal cells, and sections of nonhexagonal cells are used to connect sections of hexagonal cells of different sizes. Since the graph indicates that the percentage of nonhexagonal cells is lower for the western honeybee than it is for the dwarf honeybee or black dwarf honeybee, the western honeybee would conversely have a higher percentage of hexagonal cells than the either the dwarf honeybee or black dwarf honeybee does, not a lower percentage."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 15, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which finding, if true, would most directly support Barboza and Trejos’s claim?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice D is the best answer because it presents a finding that, if true, would most directly support Barboza and Trejos’s claim that rural female entrepreneurs who have received small loans from ALSOL are strategic in selling their goods less frequently than they could, even if it means missing payments. The text explains that borrowers in the ALSOL program use proceeds from their businesses to repay loans in equal weekly payments, with almost no penalty for missed payments. According to the text, Barboza and Trejos found that rural borrowers miss weekly payments in part because they don’t sell their goods as often as they could, a move the researchers claim allows the entrepreneurs to help increase profits for the goods they sell. Finding that the cost of bringing goods to towns with marketplaces is high for rural entrepreneurs but is largely independent of how many goods are brought would support the researchers’ claim: traveling to marketplaces less frequently would mean that a rural entrepreneur spends less on travel overall, and taking a large load of goods to a marketplace for essentially the same cost as taking a small load would allow the entrepreneur to more substantially offset the cost of travel with greater overall sales at the marketplace, resulting in more profit per good sold—even if those profits are earned less frequently and don’t support weekly loan payments."}, {"type": "paragraph", "text": "Choice A is incorrect because the finding that many marketplaces require entrepreneurs to pay the operators of the marketplace a fixed percentage of proceeds to be able to sell goods there wouldn’t explain why rural entrepreneurs strategically choose to sell their goods less frequently than they could in order to increase their profits per unit sold. With a fixed percentage of proceeds due to operators, the amount entrepreneurs have to pay operators would also be fixed regardless of frequency of selling. Choice B is incorrect because the finding that rural entrepreneurs can usually sell their goods for higher prices in cities than in their local areas but also face higher competition to sell goods in cities wouldn’t explain why rural entrepreneurs strategically choose to sell their goods less frequently than they could in order to increase their profits per unit sold. This is because both the higher prices and higher competition in cities would be stable factors—meaning there would be no clear reason for the rural entrepreneurs not to take every available chance to sell their goods in cities and to instead sell their goods in cities only sometimes. Choice C is incorrect because the finding that rural entrepreneurs have lower costs and thus tend to require smaller initial loans than urban entrepreneurs do has no bearing on rural borrowers strategically choosing to sell their goods less frequently than they could specifically to increase their profits per unit sold. The cost of producing goods doesn’t depend on the frequency with which an entrepreneur sells those goods, so lower frequency alone wouldn’t affect profits, and the initial loan amount is set and has nothing to do with how much profit is earned from each sale."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 16, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice most logically completes the text?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice B is the best answer because it most logically completes the text’s discussion of Anita Allen’s argument about judges citing philosophers in their judicial opinions. The text indicates that judges sometimes cite philosophers when writing their judicial opinions and that, according to Allen, judges tend to cite philosophers whose views are in agreement with those of the judges themselves. Allen claims, however, that the best judicial opinions consider potential objections and rebut them, which suggests that judges may be able to strengthen their opinions by including discussions of philosophers with views contrary to their own."}, {"type": "paragraph", "text": "Choice A is incorrect because Allen’s claim is that judges could improve their judicial opinions by citing philosophers who disagree with the views expressed in the opinions, which would necessarily require judges to consult philosophical works. Choice C is incorrect because there’s no discussion in the text about making judicial opinions more easily understood by any particular group of readers. The focus of the text is on Allen’s claim that judicial opinions could be strengthened by the inclusion of discussions of philosophers whose views disagree with those of the judges authoring the opinions. Choice D is incorrect because the text presents Allen’s argument that discussing philosophers whose views judges disagree with could strengthen judicial opinions, not that doing so could bring those opinions into line with views that are popular among philosophers."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 17, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice most logically completes the text?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice A is the best answer because it presents the conclusion that most logically follows from the text’s discussion of military veterans working in civilian government jobs in the United States. The text indicates that the proportion of military veterans working in civilian government jobs is considerably higher than the proportion of military veterans in the population as a whole. The text also notes that the unusually high representation of military veterans in these jobs may be a result of the organizational structures shared by civilian government entities and the military. Hence, it’s reasonable to infer that it’s the familiarity of the structures of civilian government that makes jobs there particularly attractive to military veterans."}, {"type": "paragraph", "text": "Choice B is incorrect because the text doesn’t address what a typical relationship between military service and later career preferences would be, and there’s no indication that it’s atypical for veterans to work in civilian government jobs after they’ve left the military. On the contrary, the text suggests that many military veterans are drawn to such jobs. Choice C is incorrect because the text is focused on the high representation of military veterans in civilian government jobs and doesn’t address nonveterans or their possible interest in military service."}, {"type": "paragraph", "text": "Choice D is incorrect because the text conveys that military veterans may be particularly interested in civilian government jobs due to the familiarity of organizational structures that are already in place, but there’s no reason to think that this interest would mean that more civilian government jobs will start to require military experience."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 18, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text so that it conforms to the conventions of Standard English?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice A is the best answer. The convention being tested is the use of finite verbs in a relative clause. Relative clauses, such as the one beginning with “which,” require a finite verb, a verb that can function as the main verb of a clause. This choice correctly supplies the clause with the finite past tense verb “provided.”"}, {"type": "paragraph", "text": "Choice B is incorrect because the non-finite participle “having provided” doesn’t supply the clause with a finite verb. Choice C is incorrect because the non-finite to-infinitive “to provide” doesn’t supply the clause with a finite verb. Choice D is incorrect because the non-finite participle “providing” doesn’t supply the clause with a finite verb."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Standard English Conventions'), 'medium', 'source', 'approved', 19, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text so that it conforms to the conventions of Standard English?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice A is the best answer. The convention being tested is subject–verb agreement. The singular verb “allows” agrees in number with the singular subject “landing.”"}, {"type": "paragraph", "text": "Choice B is incorrect because the plural verb “are allowing” doesn’t agree in number with the singular subject “landing.” Choice C is incorrect because the plural verb “have allowed” doesn’t agree in number with the singular subject “landing.” Choice D is incorrect because the plural verb “allow” doesn’t agree in number with the singular subject “landing.”"}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Standard English Conventions'), 'medium', 'source', 'approved', 20, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text so that it conforms to the conventions of Standard English?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice B is the best answer. The convention being tested is pronoun–antecedent agreement. The plural pronoun “they” agrees in number with the plural antecedent “woodcuts” and clearly identifies what was exhibited at the Smithsonian American Art Museum."}, {"type": "paragraph", "text": "Choice A is incorrect because the singular pronoun “it” doesn’t agree in number with the plural antecedent “woodcuts.” Choice C is incorrect because the singular pronoun “this” doesn’t agree in number with the plural antecedent “woodcuts.”"}, {"type": "paragraph", "text": "Choice D is incorrect because the plural pronoun “some” is illogical in this context (referring to “some” of two woodcuts)."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Standard English Conventions'), 'medium', 'source', 'approved', 21, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text so that it conforms to the conventions of Standard English?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice C is the best answer. The convention being tested is punctuation use between a main clause and two supplementary elements. In this choice, the commas after “nickname” and “however” are correctly used to separate the supplementary adverb “however” from the main clause (“Scott-Heron… nickname”) on one side and the supplementary participial phrase (“feeling… bluesologist”) on the other."}, {"type": "paragraph", "text": "Choice A is incorrect because it fails to mark the boundary between the supplementary adverb “however” and the supplementary phrase (“feeling… bluesologist”). Choice B is incorrect because a semicolon can’t be used in this way to join the supplementary adverb “however” and the supplementary phrase (“feeling…bluesologist”). Choice D is incorrect because a semicolon can’t be used in this way to join the main clause (“Scott-Heron…nickname”) and the supplementary word and phrase (“however” and “feeling…bluesologist”). Moreover, placing the semicolon after “nickname” illogically signals that the following information (Scott-Heron’s feeling that the nickname didn’t encapsulate his devotion to the blues tradition) is contrary to the information in the previous clause (Scott-Heron’s resistance to the nickname)."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Standard English Conventions'), 'medium', 'source', 'approved', 22, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text so that it conforms to the conventions of Standard English?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice C is the best answer. The convention being tested is the use of punctuation between titles and proper nouns. No punctuation is needed to offset the proper noun “Yuree Lee” from the title “plant cell biologist” that describes Lee."}, {"type": "paragraph", "text": "Choice A is incorrect because no punctuation is needed. Choice B is incorrect because no punctuation is needed. Choice D is incorrect because no punctuation is needed around the proper noun “Yuree Lee.” Setting the phrase off with punctuation suggests that it could be removed without affecting the coherence of the sentence, which isn’t the case."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Standard English Conventions'), 'medium', 'source', 'approved', 23, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text so that it conforms to the conventions of Standard English?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice C is the best answer. The convention being tested is punctuation use within a sentence. A colon can be used between two main clauses to signal that what follows is an elaboration of what came before. In this choice, the colon correctly introduces the following explanation of the divergent milk preservation strategies that emerged."}, {"type": "paragraph", "text": "Choice A is incorrect because it results in a run-on sentence. The main clause (“As…emerged”) and the subordinate clause followed by another main clause (“whereas…steppe”) are fused without punctuation and/or a conjunction. Choice B is incorrect. Without a comma preceding it, the conjunction “and” can’t be used in this way to join a main clause (“As…emerged”) and a subordinate clause followed by another main clause (“whereas…steppe”). Choice D is incorrect because it results in a comma splice. A comma can’t be used in this way to join a main clause (“As…emerged”) and a subordinate clause followed by another main clause (“whereas…steppe”)."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Standard English Conventions'), 'medium', 'source', 'approved', 24, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text so that it conforms to the conventions of Standard English?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice A is the best answer. The convention being tested is the use of verb forms within a sentence. The nonfinite present participle “suggesting” is correctly used to form a restrictive participial phrase (“suggesting...Holocene”) within the main clause (“This hypothesis...cannot stand...”). This participial phrase functions as part of the sentence’s subject (“This...Holocene”), providing essential identifying information about what the hypothesis states—namely, that certain trees survived without interruption or human intervention throughout the Holocene."}, {"type": "paragraph", "text": "Choice B is incorrect because it results in an ungrammatical sentence. The finite verb “suggested” can’t be used in this way within the subject of the sentence."}, {"type": "paragraph", "text": "Choice C is incorrect because it results in an ungrammatical sentence. The finite verb “suggests” can’t be used in this way within the subject of the sentence."}, {"type": "paragraph", "text": "Choice D is incorrect because it results in an ungrammatical sentence. The finite verb “has suggested” can’t be used in this way within the subject of the sentence."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Standard English Conventions'), 'medium', 'source', 'approved', 25, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text so that it conforms to the conventions of Standard English?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice B is the best answer. The convention being tested is subject-verb agreement. The singular verb “is” agrees in number with the singular subject “the shape.”"}, {"type": "paragraph", "text": "Choice A is incorrect because the plural verb “are” doesn’t agree in number with the singular subject “the shape.” Choice C is incorrect because the plural verb “were” doesn’t agree in number with the singular subject “the shape.” Choice D is incorrect because the plural verb “have been” doesn’t agree in number with the singular subject “the shape.”"}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Standard English Conventions'), 'medium', 'source', 'approved', 26, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text with the most logical transition?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice A is the best answer. “Meanwhile” logically signals that the action described in this sentence (Obinze’s move to London to pursue a career) is simultaneous with the action described in the previous sentence (Ifemelu’s move to the United States). The first sentence establishes that the actions take place around the same time, referring to the characters’ “divergent experiences” following high school."}, {"type": "paragraph", "text": "Choice B is incorrect because “nevertheless” illogically signals that the information in this sentence about Obinze’s move to London is true despite the previous information about Ifemelu’s move to the United States. Instead, as the first sentence establishes, Obinze’s move and Ifemelu’s move are related, parallel experiences that occur around the same time. Choice C is incorrect because “secondly” illogically signals that the information in this sentence is a second point or reason separate from the previous information about Ifemelu’s move to the United States. Instead, as the first sentence establishes, Obinze’s move and Ifemelu’s move are related, parallel experiences that occur around the same time."}, {"type": "paragraph", "text": "Choice D is incorrect because “in fact” illogically signals that the information in this sentence emphasizes, modifies, or contradicts the previous information about Ifemelu’s move to the United States. Instead, as the first sentence establishes, Obinze’s move and Ifemelu’s move are related, parallel experiences that occur around the same time."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Expression of Ideas'), 'medium', 'source', 'approved', 27, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text with the most logical transition?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice B is the best answer. “Additionally” logically signals that the claim in this sentence—that some Supreme Court justices worry that viewers (of televised court arguments) would watch only short, misleading clips—adds to the information in the previous sentence. Specifically, the previous sentence indicates one concern raised by those opposed to televising the court’s oral arguments, and the claim that follows indicates a second, additional concern."}, {"type": "paragraph", "text": "Choice A is incorrect because “however” illogically signals that the claim in this sentence contrasts with the information in the previous sentence. Instead, the claim adds to the information, indicating a second, additional concern that some Supreme Court justices have about televising the court’s arguments. Choice C is incorrect because “in comparison” illogically signals that the claim in this sentence is being compared to the information in the previous sentence. Instead, the claim adds to the information, indicating a second, additional concern that some Supreme Court justices have about televising the court’s arguments."}, {"type": "paragraph", "text": "Choice D is incorrect because “for example” illogically signals that the claim in this sentence exemplifies the information in the previous sentence. Instead, the claim adds to the information, indicating a second, additional concern that some Supreme Court justices have about televising the court’s arguments."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Expression of Ideas'), 'medium', 'source', 'approved', 28, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text with the most logical transition?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice D is the best answer. “Thus” logically signals that the claim in this sentence—that animals performing only basic actions should allocate relatively few resources to their brain tissue—is a consequence of the previous sentence’s claim about the energy demands of animal brains (namely, that the more diverse an animal’s behaviors, the more energy its brain needs)."}, {"type": "paragraph", "text": "Choice A is incorrect because “subsequently” illogically signals that the claim in this sentence occurs later in a chronological sequence of events than the previous sentence’s claim about the energy demands of animal brains. Instead, the second claim is a consequence of the first. Choice B is incorrect because “besides” illogically signals that the claim in this sentence provides a separate point in addition to, or apart from, the previous sentence’s claim about the energy demands of animal brains. Instead, the second claim is a consequence of the first."}, {"type": "paragraph", "text": "Choice C is incorrect because “nevertheless” illogically signals that the claim in this sentence is true in spite of the previous sentence’s claim about the energy demands of animal brains. Instead, the second claim is a consequence of the first."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Expression of Ideas'), 'medium', 'source', 'approved', 29, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text with the most logical transition?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice B is the best answer. “By contrast” logically signals that the information in this sentence—that a firefly’s glow ceases when it stops drawing in oxygen— contrasts with the previous sentence’s discussion of the processes that cause a firefly to begin to glow."}, {"type": "paragraph", "text": "Choice A is incorrect because “for instance” illogically signals that the information in the sentence exemplifies the previous sentence’s discussion of how a firefly begins to glow. Instead, it contrasts with the previous sentence’s discussion."}, {"type": "paragraph", "text": "Choice C is incorrect because “specifically” illogically signals that the information in the sentence provides specific details elaborating on the previous sentence’s discussion of how a firefly begins to glow. Instead, it contrasts with the previous sentence’s discussion. Choice D is incorrect because “in conclusion” illogically signals that the information in the sentence sums up the previous sentence’s discussion of how a firefly begins to glow. Instead, it contrasts with the previous sentence’s discussion."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Expression of Ideas'), 'medium', 'source', 'approved', 30, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice most effectively uses relevant information from the notes to accomplish this goal?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice B is the best answer. The sentence explains an advantage of microprobes, noting that because microprobes weigh as little as 50 milligrams, they can explore areas inaccessible to rovers."}, {"type": "paragraph", "text": "Choice A is incorrect. The sentence indicates that rovers can land successfully on Mars despite their weight; it doesn’t explain an advantage of microprobes."}, {"type": "paragraph", "text": "Choice C is incorrect. While the sentence mentions that microprobes have been proposed as an alternative to rovers, it doesn’t explain an advantage of microprobes. Choice D is incorrect. The sentence emphasizes a similarity between microprobes and rovers; it doesn’t explain an advantage of microprobes."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 31, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice most effectively uses relevant information from the notes to accomplish this goal?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice A is the best answer. The sentence emphasizes the significance of Ochoa’s discovery, noting that it proved critical to deciphering the human genetic code, which resulted in a better understanding of how genetic variations affect human health."}, {"type": "paragraph", "text": "Choice B is incorrect. While the sentence explains what Ochoa discovered, it doesn’t emphasize the significance of the discovery. Choice C is incorrect. While the sentence explains what Ochoa discovered, it doesn’t emphasize the significance of the discovery. Choice D is incorrect. While the sentence mentions that Ochoa’s discovery was crucial, it emphasizes Ochoa’s incorrect hypothesis, not the significance of the discovery."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 32, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice most effectively uses relevant information from the notes to accomplish this goal?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice C is the best answer. The sentence effectively introduces the poetry collection Precario/Precarious, noting that it is a collection by Vicuña that was published in 1983 by Tanam Press."}, {"type": "paragraph", "text": "Choice A is incorrect. While the sentence mentions the 1983 poetry collection Precario/Precarious, it focuses mainly on Vicuña’s visual art. Choice B is incorrect. The sentence doesn’t introduce the 1983 poetry collection Precario/Precarious; instead, it introduces Vicuña. Choice D is incorrect. The sentence emphasizes the location of Vicuña’s 1971 exhibition Pinturas, poemas y explicaciones; it doesn’t introduce the 1983 poetry collection Precario/Precarious."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 33, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "As used in the text, what does the word “completing” most nearly mean?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice B is the best answer because as used in the text, “completing” most nearly means finishing. In the text, the narrator conveys that the task of translating a novel has been an all-consuming one and that she hopes things will “be normal again” once she has “sent off the manuscript.” In other words, the narrator is looking forward to finishing her work on the manuscript and returning to other things."}, {"type": "paragraph", "text": "Choice A is incorrect because in this context, “completing” doesn’t mean destroying, or ruining. The narrator addresses her desire to send off the manuscript she’s focused on and her hope that things will be “normal again” once she does, conveying that she is looking forward to finishing the work, not to ruining it. Choice C is incorrect because in this context, “completing” doesn’t mean advertising, or publicly promoting. The narrator addresses her complete focus on the translation and her hope that things will be “normal again” once she has “sent off the manuscript,” conveying that she is looking forward to finishing the task, not to promoting the resulting manuscript. Choice D is incorrect because in this context, “completing” doesn’t mean rejecting, or refusing or repelling. The narrator makes it clear that she is absorbed in working on the translation and plans to send off the manuscript, suggesting that instead of refusing to do the work, she is continuing to do it (even if she looks forward to things being “normal again” when she’s done)."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Craft and Structure'), 'medium', 'source', 'approved', 1, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text with the most logical and precise word or phrase?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice C is the best answer because it most logically completes the text’s discussion of how predators feed their young. As used in this context, “provide” means supply or make something that’s needed available. The text indicates that some predators supply prey for their young by either leaving dead prey nearby or by bringing live prey to them. Other predators, the text states, feed their young directly from their own mouths. This context supports the idea that predatory animals have various ways to provide food for their young."}, {"type": "paragraph", "text": "Choice A is incorrect because in this context, “avoid” would mean keep away from or refrain from, neither of which would make sense in context. Nothing in the text suggests that predators refrain from food for their young. Choice B is incorrect because in this context, “guess” would mean speculate or suppose, and it’s unclear what it would mean for predators to speculate food for their young."}, {"type": "paragraph", "text": "Choice D is incorrect because in this context, “describe” would mean explain, and it’s unclear what it would mean for predators to explain food for their young."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Craft and Structure'), 'medium', 'source', 'approved', 2, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text with the most logical and precise word or phrase?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice B is the best answer because it most logically completes the text’s discussion of Cole’s book Blind Spot. In this context, “enthusiasm for” means excitement about. The text explains that Blind Spot consists of original photographs as well as poetic prose—two elements that correspond to Cole’s passions, identified in the text, for photography and the written word. This context suggests that Cole’s excitement about photography and writing led him to create a book that successfully combines the two mediums."}, {"type": "paragraph", "text": "Choice A is incorrect because describing Cole as feeling “indifference to” his two passions wouldn’t make sense in context. If Cole is indifferent to his passions, that would mean he doesn’t care about photography or writing—in which case they wouldn’t be his passions at all. Choice C is incorrect because there’s nothing in the text to suggest that Cole feels “concern about,” or uneasiness about, his passions. The text’s use of the word “culminates” indicates that Blind Spot represents a triumphant climax of Cole’s passions, not a work that results from his sense of discomfort with photography and writing. Choice D is incorrect because there’s nothing in the text to suggest that Cole feels “surprise at,” or astonished by, his passions. The text indicates that Cole’s feeling about his passions “culminates” in a book that “evocatively” combines photographs and writing, suggesting that Cole has a long-standing and skillful relationship to his passions, not that he is startled by them."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Craft and Structure'), 'medium', 'source', 'approved', 3, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text with the most logical and precise word or phrase?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice B is the best answer because it most logically completes the text’s discussion of Marilyn Dingle’s baskets. In this context, to say that Dingle’s baskets are “handmade from” particular plants means that Dingle creates baskets herself using those plants but without using machines. The text says that Dingle “skillfully winds” parts of palmetto palm plants around sweetgrass plants to make baskets with an appearance that “no factory can reproduce.” This context suggests that Dingle’s baskets are handmade from sweetgrass and palmetto palm."}, {"type": "paragraph", "text": "Choice A is incorrect because the text describes how Dingle uses sweetgrass and palmetto palm to create her baskets, not how her baskets are “indicated by,” or signified by, sweetgrass and palmetto palm. Choice C is incorrect. Although Dingle’s baskets are described as being made using sweetgrass and palm, there’s nothing in the text to suggest that the baskets are “represented by,” or exemplified or portrayed by, sweetgrass and palmetto palm. Instead, the focus of the text is on Dingle’s use of sweetgrass and palmetto palm and the impossibility of replicating the appearance of her baskets using machines. Choice D is incorrect because there’s nothing in the text to suggest that Dingle’s baskets are “collected with,” or brought together in a group with, sweetgrass and palmetto palm. Instead, the text describes how Dingle uses those plants to make her baskets."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Craft and Structure'), 'medium', 'source', 'approved', 4, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text with the most logical and precise word or phrase?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice C is the best answer because it most logically completes the text’s discussion of Annie Dodge Wauneka’s work as a Navajo Nation legislator. As used in this context, “persistent” means existing continuously. The text states that Wauneka “continuously worked to promote public health,” traveling extensively and authoring a medical dictionary; this indicates that Wauneka’s effort was persistent."}, {"type": "paragraph", "text": "Choice A is incorrect because describing Wauneka’s effort related to public health as “impartial,” or not partial or biased and treating all things equally, wouldn’t make sense in context. The text suggests that Wauneka’s continuous work was partial in one way, as she focused specifically on promoting public health throughout the Navajo homeland and to speakers of the Navajo language."}, {"type": "paragraph", "text": "Choice B is incorrect because the text emphasizes that Wauneka’s effort to promote public health as a Navajo Nation legislator was continuous and extensive, involving wide travels and the authoring of a medical dictionary. Because this work clearly involved care and dedication, it wouldn’t make sense to describe it as “offhand,” or casual and informal. Choice D is incorrect because nothing in the text suggests that Wauneka’s effort to promote public health was “mandatory,” or required by law or rule, even though Wauneka was a Navajo Nation legislator. Rather than suggesting that Wauneka’s effort was required for any reason, the text emphasizes the continuous and extensive nature of her work."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Craft and Structure'), 'medium', 'source', 'approved', 5, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, 0, '{"blocks": [{"type": "paragraph", "text": "Which choice best describes the function of the underlined sentence in the text as a whole?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice D is the best answer because it most accurately describes how the underlined sentence functions in the text as a whole. The text begins by pointing out one of the advantages of oral histories: that they allow researchers to document the daily experiences of people. The text then goes on to describe how Karida Brown utilized interviews with coal miners and their families for her book about twentieth-century coal mining in Kentucky. The underlined sentence affirms that the general advantages of oral histories mentioned earlier in the text were also benefits in Brown’s particular case. Thus, the underlined sentence describes how Karida Brown benefited from incorporating oral history in her book."}, {"type": "paragraph", "text": "Choice A is incorrect because though the text mentions coal miners who live in Kentucky, the underlined sentence does not offer a geographical fact about Kentucky. Choice B is incorrect because the underlined sentence does not mention United States politics or that Brown is an expert in this particular area."}, {"type": "paragraph", "text": "Choice C is incorrect. Although the text mentions that Brown’s book revolved around coal miners during the twentieth century, the underlined sentence does not focus on a major historical event during this time."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Craft and Structure'), 'medium', 'source', 'approved', 6, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice best states the main purpose of the text?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice D is the best answer because it accurately states the text’s main purpose. The poem begins with the speaker urging a child to “go forth” with her encouragement (“my heart’s desire”). The speaker goes on to suggest that new experiences (“Great reaches, yet unknown”) lie ahead for the son that “life is calling” him to seek out. Thus, the main purpose is to encourage a child to embrace the experiences available to him in his life."}, {"type": "paragraph", "text": "Choice A is incorrect because the speaker encourages the child to pursue new experiences (“Great reaches”) without knowing exactly what those experiences will be (“yet unknown”) or suggesting that they should match the speaker’s own accomplishments. Choice B is incorrect because the speaker focuses on positive possibilities for her son (“Great reaches, yet unknown”) and her enthusiastic encouragement to embrace those possibilities (“life is calling you!”), while there is no mention of raising a child or associated struggles. Choice C is incorrect because the speaker frames the possibilities for her son in a positive light when she says that “great reaches, yet unknown” are waiting for him, and this positive outlook for the son is consistent throughout the text."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Craft and Structure'), 'medium', 'source', 'approved', 7, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, 0, '{"blocks": [{"type": "paragraph", "text": "Which choice best describes the function of the underlined sentence in the text as a whole?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice D is the best answer because it best describes how the underlined sentence functions in the text as a whole. The first sentence of the text establishes that Lily can be “keenly sensitive to” scenes that serve as a “fitting background” for her feelings—that is, she’s very aware of when a setting seems to reflect her mood. The next sentence, which is underlined, then demonstrates this awareness: Lily views the landscape she’s in as a large-scale reflection of her current mood, identifying with elements such as its calmness. Thus, the function of the underlined sentence is to illustrate an idea introduced in the previous sentence."}, {"type": "paragraph", "text": "Choice A is incorrect because the underlined sentence describes the scene only in very general terms, referring to its calmness, breadth, and long stretches of land. It’s the next sentence that adds specific details about colors, light, and various trees nearby. Choice B is incorrect because nothing in the underlined sentence suggests that Lily is experiencing an internal conflict. In fact, the sentence indicates that Lily thinks the landscape reflects her own feeling of calmness. Choice C is incorrect because the only assertion in the underlined sentence is that Lily feels that broad aspects of the landscape, such as its calmness, reflect her current mood, and that assertion isn’t expanded on in the next sentence. Instead, the next sentence describes specific details of the scene without connecting them to Lily’s feelings."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Craft and Structure'), 'medium', 'source', 'approved', 8, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, 0, '{"blocks": [{"type": "paragraph", "text": "Which choice best describes the function of the underlined statement in the text as a whole?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice A is the best answer because it most accurately describes how the underlined statement functions in the text as a whole. The underlined statement mentions a category of animals that have a feature in common: they tend to have fixed geographic ranges throughout their lifetimes. The text then presents the speculation of some researchers that the Arctic woolly mammoth might also share this characteristic. However, an examination of the content of strontium in the strata (or layers) of a woolly mammoth tusk indicated that contrary to the researchers’ hypothesis, the mammoth had an expanding range in its environment that contracted in its last 1.5 years of life. Thus, the underlined statement discusses a characteristic shared by certain animals in order to explain why researchers raised a possibility that turned out not to be supported by data described later in the text."}, {"type": "paragraph", "text": "Choice B is incorrect. Though the underlined statement presents a pattern of behavior (the habit of certain animals of staying within a fixed geographic range), the rest of the text does not present a theory of exceptions to that pattern; rather, the researchers are merely concerned with whether one particular animal has behavior consistent with the pattern. Choice C is incorrect. Though the underlined statement does describe a similarity in the behavior of certain animals (their tendency to stay within a fixed geographic range), this is not done in order to show why a method described later in the text failed to show whether another animal showed that behavior; rather, the method of analysis of strata of a woolly mammoth tusk showed that the mammoth’s behavior was different from that of the animals mentioned in the underlined statement. Choice D is incorrect. Though the underlined statement mentions a trait shared by a number of animals (their fixed geographic range), the rest of the text does not present a hypothesis regarding the origin of that trait; rather, the researchers are concerned with whether another particular animal shares that trait."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Craft and Structure'), 'medium', 'source', 'approved', 9, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "According to the text, what did Gloria Richardson lead?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice A is the best answer because it presents information about Gloria Richardson that is supported by the text. The text provides a number of details about Gloria’s involvement in efforts to promote racial equality, including that she was the leader of what became known as the Cambridge movement."}, {"type": "paragraph", "text": "Choice B is incorrect because the text never indicates that Gloria Richardson led her daughter Donna’s high school. The text says only that Gloria was inspired by her daughter to become involved in efforts to promote racial equality. Choice C is incorrect because the text doesn’t mention protests related to environmental protections. Rather, the text discusses Gloria Richardson’s involvement in efforts to promote racial equality. Choice D is incorrect because the text doesn’t indicate that Gloria Richardson led a new business in Cambridge, Maryland. Rather, the text states that she led what became known as the Cambridge movement."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 10, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "According to the text, what is true about Elinor?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice D is the best answer because it provides a detail about Elinor that is established in the text. The text indicates that although Elinor is “only nineteen,” she gives good advice and exhibits such a high level of understanding and judgment that she serves as “the counsellor of her mother.” Thus, Elinor is mature beyond her years."}, {"type": "paragraph", "text": "Choice A is incorrect because it isn’t supported by the text: although the text says that Elinor advises her mother and often counteracts her mother’s impulses, there’s no mention of Elinor arguing with her mother or failing to change her mother’s mind. Choice B is incorrect because it isn’t supported by the text: although the text mentions that Elinor has strong feelings, it doesn’t indicate that she’s excessively sensitive when it comes to family issues. Choice C is incorrect because it isn’t supported by the text: there’s no mention of what Elinor thinks about her mother and no suggestion that she thinks her mother is a bad role model. Because she’s described as having “an excellent heart,” Elinor likely doesn’t think ill of her mother."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 11, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice best describes the main idea of the text?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice A is the best answer because it most accurately states the main idea of the text. The text describes the book Vibration Cooking: or, the Travel Notes of a Geechee Girl as Smart-Grosvenor’s “most influential project” and as “unusual for its time.” The text also notes that the book and author have influenced contemporary approaches to writing about food and cooking. Therefore, the text mainly conveys that Vibration Cooking: or, the Travel Notes of a Geechee Girl is an unconventional and important contribution to food writing."}, {"type": "paragraph", "text": "Choice B is incorrect. Although the text mentions that Smart-Grosvenor worked in national public television and radio and was a food writer, these details aren’t the main focus. Rather than focusing on Smart-Grosvenor’s various jobs, the text focuses specifically on one specific book she wrote. Choice C is incorrect. Although the text suggests that Vibration Cooking: or, the Travel Notes of a Geechee Girl was groundbreaking, it doesn’t suggest that the book didn’t receive praise when it was published. In fact, the text states that the book is “long admired.” Choice D is incorrect because the text states that Smart-Grosvenor was a culinary anthropologist and that her book influenced later approaches to food writing but doesn’t indicate that Smart-Grosvenor or her book influenced people to begin cooking for themselves."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 12, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Based on the text, what is true about Mrs. Ochiltree’s acquaintances?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice D is the best answer because it presents a statement about Mrs. Ochiltree’s acquaintances that is supported by the text. The text indicates that Mrs. Ochiltree makes comments about her acquaintances that are frank, or direct and blunt, and sometimes startling. It also states that because of this behavior, the acquaintances tend to avoid Mrs. Ochiltree. Together, these details suggest that the acquaintances choose not to be around Mrs. Ochiltree because they are offended by the things she has said about them."}, {"type": "paragraph", "text": "Choice A is incorrect because the text doesn’t suggest that Mrs. Ochiltree’s acquaintances avoid discussing topics that would upset Mrs. Ochiltree; instead, it states that they avoid being around Mrs. Ochiltree at all. Choice B is incorrect because the text makes it clear that Mrs. Ochiltree knows her acquaintances often avoid her and is pleased about it (she “rather exulted in it”), not that she wants to spend more time with them. Choice C is incorrect because the text doesn’t suggest that Mrs. Ochiltree’s acquaintances don’t speak with Mrs. Ochiltree because they are too focused on their own concerns, but rather because they don’t like the frank comments she makes."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 13, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which quotation from Mrs. Spring Fragrance’s letters most effectively illustrates the claim?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice C is the best answer because it presents a quotation that illustrates the claim that Mrs. Spring Fragrance demonstrates concern for what’s happening at home while she’s in California. By giving reminders to “care for the cat, the birds, and the flowers,” “not eat too quickly,” and avoid engaging in strenuous activity in the heat, Mrs. Spring Fragrance shows that she’s thinking about what’s happening at home and wants to ensure everything is taken care of."}, {"type": "paragraph", "text": "Choice A is incorrect because the quotation, while it does suggest that Mrs. Spring Fragrance has made fudge at home before, is focused on preparations for an upcoming festival, not on concerns for anything happening at home while Mrs. Spring Fragrance is away. Choice B is incorrect because the quotation has to do with an upcoming event during Mrs. Spring Fragrance’s trip—visiting San José and meeting someone new—rather than her concern for what’s happening at home. Choice D is incorrect because the quotation is focused on how Mrs. Spring Fragrance feels about her trip and the friends she’s seeing, not on her concern for what’s happening at home."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 14, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which finding, if true, would most directly undermine Foster’s hypothesis?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice C is the best answer because it presents a finding that, if true, would weaken Foster’s hypothesis that damage to eelgrass roots improves the health of eelgrass meadows by boosting genetic diversity. The text indicates that sea otters damage eelgrass roots but that eelgrass meadows near Vancouver Island, where there’s a large otter population, are comparatively healthy. When Foster and her colleagues compared the Vancouver Island eelgrass meadows to those that don’t have established otter populations, the researchers found that the Vancouver Island meadows are more genetically diverse than the other meadows are. This finding led Foster to hypothesize that damage to the eelgrass roots encourages eelgrass reproduction, thereby improving genetic diversity and the health of the meadows. If, however, other meadows not included in the study are less healthy the larger the local otter population is and the longer the otters have been in residence, that would suggest that damage to the eelgrass roots, which would be expected to increase with the size and residential duration of the otter population, isn’t leading meadows to be healthier. Such a finding would therefore weaken Foster’s hypothesis."}, {"type": "paragraph", "text": "Choice A is incorrect because finding that small, recently introduced otter populations are near other eelgrass meadows in the study wouldn’t weaken Foster’s hypothesis. If otter populations were small and only recently established, they wouldn’t be expected to have caused much damage to eelgrass roots, so even if those eelgrass meadows were less healthy than the Vancouver Island meadows, that wouldn’t undermine Foster’s hypothesis. In fact, it would be consistent with Foster’s hypothesis since it would suggest that the greater damage caused by larger, more established otter populations is associated with healthier meadows. Choice B is incorrect because the existence of areas with otters but without eelgrass meadows wouldn’t reveal anything about whether the damage that otters cause to eelgrass roots ultimately benefits eelgrass meadows. Choice D is incorrect because the health of plants other than eelgrass would have no bearing on Foster’s hypothesis that damage to eelgrass roots leads to greater genetic diversity and meadow health. It would be possible for otters to have a negative effect on other plants while nevertheless improving the health of eelgrass meadows by damaging eelgrass roots."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 15, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which finding, if true, would most directly support Paredes’s argument?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice D is the best answer because it presents a finding that, if true, would support Paredes’s argument about the origin of Mexican American folklore. The text describes a disagreement among scholars about whether Mexican American folklore mostly derived from the folklore of Spain (the view held by Espinosa and others) or originated in Mexico and the United States through ongoing cultural interactions there (the view held by Paredes and others). If Mexican American folklore collected in the twentieth century mostly consists of ballads about history and social life that originated recently, then that would support Paredes’s argument by suggesting that the folklore mostly arose after Spanish rule ended in the early nineteenth century and that the folklore reflects cultural interactions in Mexico and the United States rather than traditions from Spain."}, {"type": "paragraph", "text": "Choice A is incorrect because the inclusion of songs influenced by sixteenth- century Spanish poetry among Mexican American folklore collected in the twentieth century would not support Paredes’s view that the folklore was the result of cultural interactions in Mexico and the United States rather than an offshoot of Spanish folklore. If anything, the presence of such songs among the folklore collected in the twentieth century would weaken Paredes’s argument, since it would reflect the influence of Spanish culture on the folklore. Choice B is incorrect because the mere presence of similarities in Mexican American folklore across regions would not be sufficient to draw a conclusion about where the folklore originated, let alone to support Paredes’s argument that the folklore reflects various cultural interactions in Mexico and the United States. In fact, Paredes would likely expect there to be regional variations in folklore as different cultures have interacted in different places. Choice C is incorrect because scholars’ previous ignorance of the folklore would have no bearing on Paredes’s argument that Mexican American folklore mostly reflects cultural interactions in Mexico and the United States; the folklore’s actual origins exist regardless of the scholars’ awareness."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 16, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice most logically completes the text?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice B is the best answer because it presents the conclusion that most logically follows from the text’s discussion of the study by Versace and colleagues. The text indicates that newborn animals of some species are attracted to faces and to stimuli that resemble faces. These species, the text says, share two characteristics: they’re social and they practice parental care, meaning that parents care for their young. The text goes on to describe Versace and colleagues’ experiment, which showed that Testudo tortoises, which aren’t social and don’t practice parental care, were attracted to a stimulus that resembles a face. Since Versace and colleagues have shown that a species that isn’t social and doesn’t practice parental care nevertheless has the innate characteristic of being attracted to face-like stimuli, it follows that this characteristic shouldn’t be assumed to be an adaptation related to social interaction or parental care."}, {"type": "paragraph", "text": "Choice A is incorrect because the text indicates that the tortoise hatchlings, which are solitary and don’t practice parental care, were attracted to the face-like stimuli, not that they perceived the stimuli as threatening. Choice C is incorrect because the phenomenon discussed in the text is an attraction to faces and face-like stimuli on the part of newborn animals, which can’t show any learned characteristics since they were just born. Additionally, the text tells us that the tortoises Versace and colleagues studied aren’t social and don’t practice parental care, so any findings about those tortoises wouldn’t be relevant to the question of whether an attraction to faces in social species that practice parental care is innate or learned. Choice D is incorrect because the text gives no indication that adult tortoises were tested on face-like stimuli and, if adults were in fact tested, no information about how they responded is provided. Since no information about adult tortoises’ responses is provided, no conclusion comparing those responses to the responses of newly hatched tortoises can be supported."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 17, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice most logically completes the text?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice D is the best answer because it most logically completes the text’s discussion of aptamers’ capacity to test for pathogens in food. The text explains that although synthetic aptamer molecules can be used to test for foodborne bacterial pathogens because they bind to target molecules, it hasn’t been clear how likely it is that they will indicate a negative result when a target pathogen is absent in real-world foods. The text then indicates that Somvanshi et al. created test paper that changes from pink to purple when aptamers in it bind to a particular strain of E. coli bacteria, O157:H7, and tested it with store-bought pear juice (that is, a real-world food); the paper changed to purple when exposed to juice to which the target pathogen E. coli O157:H7 had been added, but it remained pink when exposed to juice treated with other E. coli strains or other bacteria species. Based on this result, it seems the aptamers in the paper successfully bound to the target (O157:H7) and the tests had a high degree of specificity (providing negative results for samples where the target was absent even though other bacteria were present) when applied to a real-world food."}, {"type": "paragraph", "text": "Choice A is incorrect because nothing in the text suggests that E. coli O157:H7 differs from other pathogens in a way that makes it more suitable for aptamer- based testing of any kind and that specificity is likely to be lower when aptamer- based tests target other bacteria; the text simply indicates that Somvanshi et al. used O157:H7 as the target for aptamer-based test paper in their study and suggests that the paper had a high degree of specificity. Choice B is incorrect because the text indicates that the specificity of aptamer-based tests in real- world foods is uncertain for pathogens broadly, not just for E. coli, and similarity between strains (of E. coli or of other pathogens) isn’t mentioned. Moreover, the results presented in the text suggest that aptamers are actually capable of distinguishing between strains of E. coli, since Somvanshi et al.’s paper turned purple when exposed to E. coli O157:H7 and remained pink when exposed to other strains. Choice C is incorrect because the text suggests that the aptamers in the test papers didn’t bind to different strains of E. coli. The text explains that the test papers turn purple when the aptamers bind to the targeted pathogen and that in the pear juice tests, the test papers turned purple when exposed to samples with the targeted strain of E. coli (O157:H7) but remained pink when exposed to samples with other strains of E. coli. In other words, the aptamers bound only to the targeted strain, not to the other strains. Further, specificity would be affected if the aptamers had bound to multiple strains and not just the targeted one; that result would cause the specificity to be low."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 18, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text so that it conforms to the conventions of Standard English?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice C is the best answer. The convention being tested is the use of possessive determiners. The plural possessive determiner “their” agrees in number with the plural conjoined noun phrase “Watson and Crick” and thus indicates that the findings were those of Watson and Crick."}, {"type": "paragraph", "text": "Choice A is incorrect because “they’re” is the contraction for “they are,” not a possessive determiner. Choice B is incorrect because “it’s” is the contraction for “it is” or “it has,” not a possessive determiner. Choice D is incorrect because the singular possessive determiner “its” doesn’t agree in number with the plural conjoined noun phrase “Watson and Crick.”"}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Standard English Conventions'), 'medium', 'source', 'approved', 19, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text so that it conforms to the conventions of Standard English?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice D is the best answer. The convention being tested is the use of finite and nonfinite verb forms within a sentence. The nonfinite to-infinitive “to tell” is correctly used to form a nonfinite (infinitive) clause that explains the reason Engle uses poetry in her novel."}, {"type": "paragraph", "text": "Choice A is incorrect because the finite present tense verb “tells” can’t be used in this way to explain the reason that Engle uses poetry in her novel. Choice B is incorrect because the finite past tense verb “told” can’t be used in this way to explain the reason that Engle uses poetry in her novel. Choice C is incorrect because the finite present progressive tense verb “is telling” can’t be used in this way to explain the reason that Engle uses poetry in her novel."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Standard English Conventions'), 'medium', 'source', 'approved', 20, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text so that it conforms to the conventions of Standard English?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice C is the best answer. The convention being tested is the use of verb forms within a sentence. The plural verb “study” agrees in number with the plural subject “many.”"}, {"type": "paragraph", "text": "Choice A is incorrect because the singular verb “is studying” doesn’t agree in number with the plural subject “many.” Choice B is incorrect because the singular verb “has studied” doesn’t agree in number with the plural subject “many.”"}, {"type": "paragraph", "text": "Choice D is incorrect because the singular verb “studies” doesn’t agree in number with the plural subject “many.”"}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Standard English Conventions'), 'medium', 'source', 'approved', 21, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text so that it conforms to the conventions of Standard English?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice C is the best answer. The convention being tested is punctuation between a subject and a verb. When, as in this case, a subject (“her 2019 novel Gingerbread”) is immediately followed by a verb (“offers”), no punctuation is needed."}, {"type": "paragraph", "text": "Choice A is incorrect because no punctuation is needed between the subject and the verb. Choice B is incorrect because no punctuation is needed between the subject and the verb. Choice D is incorrect because no punctuation is needed between the subject and the verb."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Standard English Conventions'), 'medium', 'source', 'approved', 22, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text so that it conforms to the conventions of Standard English?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice B is the best answer. The convention being tested is the use of punctuation within a sentence. This choice uses a semicolon in a conventional way to join the first main clause (“Gitlin’s…content”) and the second main clause beginning with a supplementary phrase (“in…audiences”). Further, placing a comma after “era” separates the supplementary phrase “in that era” from the rest of the main clause that follows (“even…audiences”)."}, {"type": "paragraph", "text": "Choice A is incorrect because it results in a comma splice. Without a conjunction following it, a comma can’t be used in this way to join two main clauses. Further, this choice fails to mark the boundary between the supplementary phrase “in that era” and the rest of the main clause that follows (“even…audiences”). Choice C is incorrect because it results in a run-on sentence. The two main clauses (“Gitlin’s… content” and “in…audiences”) are fused without punctuation and/or a conjunction."}, {"type": "paragraph", "text": "Choice D is incorrect because it results in a comma splice. Without a conjunction following it, a comma can’t be used in this way to join two main clauses."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Standard English Conventions'), 'medium', 'source', 'approved', 23, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text so that it conforms to the conventions of Standard English?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice D is the best answer. The convention being tested is the use of punctuation around noun phrases. No punctuation is needed because the noun phrase “aluminum oxide” is a restrictive appositive, meaning that it provides essential identifying information about the noun phrase before it, “the chemical compound,” and thus doesn’t require punctuation around it."}, {"type": "paragraph", "text": "Choice A is incorrect because no punctuation is needed. Choice B is incorrect because no punctuation is needed. Choice C is incorrect because the noun phrase “aluminum oxide” is a restrictive appositive. Setting the phrase off with punctuation suggests that it could be removed without affecting the coherence of the sentence, which isn’t the case."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Standard English Conventions'), 'medium', 'source', 'approved', 24, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text so that it conforms to the conventions of Standard English?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice C is the best answer. The convention being tested is the use of verb forms in a sentence. The nonfinite past participle phrase “highly prized” is correctly used to form a supplementary element that modifies the main clause “this…artistry,” describing memorable features of Brass Era automotive design."}, {"type": "paragraph", "text": "Choice A is incorrect because it results in a comma splice. Using the finite present tense verb phrase “are highly prized” creates a second main clause in the sentence, and two main clauses can’t be joined in this way with only a comma after “artistry.” Choice B is incorrect because it results in a comma splice. Using the finite past perfect tense verb phrase “had been highly prized” creates a second main clause in the sentence, and two main clauses can’t be joined in this way with only a comma after “artistry.” Choice D is incorrect because it results in a comma splice. Using the finite past tense verb phrase “were highly prized” creates a second main clause in the sentence, and two main clauses can’t be joined in this way with only a comma after “artistry.”"}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Standard English Conventions'), 'medium', 'source', 'approved', 25, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text so that it conforms to the conventions of Standard English?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice C is the best answer. The convention being tested is the use of punctuation within a sentence. This choice correctly uses a comma to separate the supplementary adverb “though” from the preceding main clause (“Economists…conservation”) and uses a semicolon to join the next main clause (“efficiency gains…rises”) to the rest of the sentence. Further, placing the semicolon after “though” indicates that the information in the preceding main clause (“improvements in efficiency often correlate negatively with resource conservation”) is contrary to what might be assumed from the information in the previous sentence (resource consumption would be expected to decrease with the development of new, more efficient technologies)."}, {"type": "paragraph", "text": "Choice A is incorrect because it results in a comma splice. Commas can’t be used in this way to punctuate a supplementary word or phrase between two main clauses. Choice B is incorrect because it fails to mark the boundary between the two main clauses (“Economists...though” and “efficiency gains…rises”) with appropriate punctuation. Moreover, placing the semicolon after “conservation” illogically indicates that the information in the next clause (gains in efficiency may lead to an increase in resource consumption) is contrary to the information in the previous clause (“improvements in efficiency often correlate negatively with resource conservation”). Choice D is incorrect because placing a comma after “conservation” illogically indicates that the information in the next clause (gains in efficiency may lead to an increase in resource consumption) is contrary to the information in the previous clause (“improvements in efficiency often correlate negatively with resource conservation”)."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Standard English Conventions'), 'medium', 'source', 'approved', 26, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text with the most logical transition?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice C is the best answer. “Similarly” logically signals that the activity described in this sentence (Nancy Tuttle Craig distributing Votes for Women Tea in her Los Angeles grocery stores) is like the activity described in the previous sentence (the Woman’s Suffrage Party selling Equality Tea at fairs in San Francisco). Together, the two examples support the preceding claim that “activists across the state sold tea to promote the cause of suffrage.”"}, {"type": "paragraph", "text": "Choice A is incorrect because “for example” illogically signals that the activity described in this sentence exemplifies the activity described in the previous sentence. Instead, the two activities are similar, and both support the preceding claim about selling tea to promote women’s right to vote. Choice B is incorrect because “to conclude” illogically signals that the activity described in this sentence concludes or summarizes the information in the previous sentences. Instead, the activity is similar to the one described in the previous sentence, and both support the preceding claim about selling tea to promote women’s right to vote. Choice D is incorrect because “in other words” illogically signals that the activity described in this sentence paraphrases the activity described in the previous sentence. Instead, the two activities are similar, and both support the preceding claim about selling tea to promote women’s right to vote."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Expression of Ideas'), 'medium', 'source', 'approved', 27, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text with the most logical transition?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice A is the best answer. “Specifically” logically signals that the information in this sentence—that the Sun releases charged particles that later collide with atoms, resulting in auroral light—provides specific, precise details about how auroras result from the Sun’s activity."}, {"type": "paragraph", "text": "Choice B is incorrect because “similarly” illogically signals that the information in this sentence is similar to the general information about auroras in the previous sentence. Instead, this sentence provides specific, precise details about how auroras form. Choice C is incorrect because “nevertheless” illogically signals that the information in this sentence is despite the general information about auroras in the previous sentence. Instead, this sentence provides specific, precise details about how auroras form. Choice D is incorrect because “hence” illogically signals that the information in this sentence is a result of the general information about auroras in the previous sentence. Instead, this sentence provides specific, precise details about how auroras form."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Expression of Ideas'), 'medium', 'source', 'approved', 28, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice most effectively uses relevant information from the notes to accomplish this goal?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice B is the best answer. The sentence compares the lengths of the two rail tunnels, noting that the Channel Tunnel (about 31 miles long) is slightly shorter than the Seikan Tunnel (roughly 33 miles long)."}, {"type": "paragraph", "text": "Choice A is incorrect. The sentence makes a generalization about the length of some rail tunnels; it doesn’t compare the lengths of the two rail tunnels. Choice C is incorrect. The sentence describes a single rail tunnel; it doesn’t compare the lengths of the two rail tunnels. Choice D is incorrect. While the sentence mentions the two rail tunnels, it doesn’t compare their lengths."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 29, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice most effectively uses relevant information from the notes to accomplish this goal?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice C is the best answer. The sentence effectively emphasizes the fossil’s significance, explaining that the fossil is rare and illustrates an early stage in the evolution of pinnipeds from their land-dwelling ancestors."}, {"type": "paragraph", "text": "Choice A is incorrect. The sentence describes the fossil Rybczynski found; it doesn’t emphasize the fossil’s significance. Choice B is incorrect. The sentence mentions that a fossil resembling both pinnipeds and their ancestors was found; it doesn’t emphasize the fossil’s significance. Choice D is incorrect. The sentence notes a term used to describe the fossil Rybczynski found; it doesn’t emphasize the fossil’s significance."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 30, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice most effectively uses relevant information from the notes to accomplish this goal?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice D is the best answer. The sentence uses “whereas” to contrast the emissivities of the two fibers, noting that the emissivity of the reflective metal fibers was just 0.02, far lower than that of the silicon carbide fibers (0.74)."}, {"type": "paragraph", "text": "Choice A is incorrect. The sentence emphasizes the ability of reflective metal fibers and silicon carbide fibers to emit heat; it doesn’t contrast the emissivities of the two fibers. Choice B is incorrect. The sentence states a law of thermodynamics: the amount of heat a material absorbs is equal to the amount it emits. The sentence doesn’t contrast the emissivity of reflective metal fibers with that of silicon carbide fibers. Choice C is incorrect. While the sentence includes a generalization about the emissivities of reflective metal fibers and silicon carbide fibers, it emphasizes Abebe’s plans for their use in a garment; it doesn’t contrast the emissivities of the two fibers."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 31, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice most effectively uses relevant information from the notes to accomplish this goal?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice C is the best answer. The sentence explains an advantage of the “Women and the Vote” format, noting that the format appealed to audiences because it allowed them to control the experience."}, {"type": "paragraph", "text": "Choice A is incorrect. The sentence describes a digital drawing on the “Women and the Vote” website; it doesn’t explain an advantage of the play’s format."}, {"type": "paragraph", "text": "Choice B is incorrect. The sentence explains how audiences interacted with the “Women and the Vote” website; it doesn’t explain an advantage of the play’s format. Choice D is incorrect. While the sentence mentions that “Women and the Vote” had an interactive format, it doesn’t explain what advantage this format might have."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 32, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice most effectively uses relevant information from the notes to accomplish this goal?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice B is the best answer. The sentence presents both the study and its methodology (that is, the researcher’s approach to the problem), explaining that Yuan used computer simulations to study the effect of the mother duck’s wake on the ducklings’ energy expenditure."}, {"type": "paragraph", "text": "Choice A is incorrect. The sentence describes the findings of Yuan’s study; it doesn’t present the study and its methodology. Choice C is incorrect. While the sentence provides general information about Yuan’s study, it doesn’t present the study’s methodology. Choice D is incorrect. The sentence describes the findings of Yuan’s study; it doesn’t present the study and its methodology."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 33, 'choice', array[]::text[]) returning id into v_q;
    update public.exams set status = 'published' where id = v_exam;
  end if;
  -- SAT Practice Test 9: Math
  if exists (select 1 from public.exams where slug = 'sat-practice-test-9-math') then
    raise notice 'skipping sat-practice-test-9-math (already imported)';
  else
    select id into v_subject from public.subjects where code = 'sat-math';
    values (v_subject, 'sat-practice-test-9-math', 'SAT Practice Test 9: Math', 'Official SAT Practice Test 9 (College Board), Math: 54 questions in two modules, including student-produced responses. Calculator allowed; 43 minutes per module.', 'full_mock', 'premium', 'draft', 86, 'source', 219, '[[200, 200], [210, 220], [210, 220], [210, 230], [210, 240], [210, 250], [220, 260], [240, 270], [250, 280], [260, 300], [280, 340], [310, 350], [320, 360], [330, 370], [340, 380], [350, 390], [360, 400], [370, 410], [370, 410], [380, 420], [390, 430], [390, 430], [400, 440], [410, 450], [420, 460], [430, 470], [440, 480], [450, 490], [460, 500], [470, 510], [480, 520], [490, 530], [500, 540], [500, 560], [510, 570], [520, 580], [530, 590], [540, 600], [560, 620], [570, 630], [580, 640], [590, 650], [610, 670], [620, 680], [630, 690], [650, 710], [660, 720], [680, 740], [690, 750], [710, 760], [730, 770], [750, 780], [770, 800], [780, 800], [800, 800]]'::jsonb)
    returning id into v_exam;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "The lengths of two sides of a triangle are $4$ centimeters and $6$ centimeters. If the perimeter of the triangle is $18$ centimeters, what is the length, in centimeters, of the third side of this triangle?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$18 - 4 - 6 = 8$ centimeters."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Geometry and Trigonometry'), 'easy', 'source', 'approved', 1, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "math", "latex": "16x + 30 = 190"}, {"type": "paragraph", "text": "Which equation has the same solution as the given equation?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Subtracting $30$ from both sides gives the equivalent equation $16x = 160$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'easy', 'source', 'approved', 2, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "Ty set a goal to walk at least $24$ kilometers every day to prepare for a multiday hike. On a certain day, Ty plans to walk at an average speed of $4$ kilometers per hour. What is the minimum number of hours Ty must walk on that day to fulfill the daily goal?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$24 \\div 4 = 6$ hours."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'easy', 'source', 'approved', 3, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "The function $g$ is defined by $g(x) = x^2 + 9$. For which value of $x$ is $g(x) = 25$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$x^2 + 9 = 25$ gives $x^2 = 16$, so $x = 4$ (or $-4$)."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Advanced Math'), 'easy', 'source', 'approved', 4, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "Which expression is equivalent to $9x^2 + 5x$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Factor out $x$: $x(9x + 5)$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Advanced Math'), 'easy', 'source', 'approved', 5, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "Each value in the data set shown represents the height, in centimeters, of a plant."}, {"type": "math", "latex": "6, 10, 13, 2, 15, 22, 10, 4, 4, 4"}, {"type": "paragraph", "text": "What is the mean height, in centimeters, of these plants?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "The sum is $90$ and there are $10$ values, so the mean is $9$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Problem-Solving and Data Analysis'), 'easy', 'source', 'approved', 6, 'spr', array['9']::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "A student council group is selling school posters for a fundraiser. They use the function $p(x) = 5x - 220$ to determine their profit $p(x)$, in dollars, for selling $x$ school posters. In order to earn a profit of $\\$900$, how many school posters must they sell?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$5x - 220 = 900$, so $5x = 1{,}120$ and $x = 224$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'easy', 'source', 'approved', 7, 'spr', array['224']::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "Jay walks at a speed of $3$ miles per hour and runs at a speed of $5$ miles per hour. He walks for $w$ hours and runs for $r$ hours for a combined total of $14$ miles. Which equation represents this situation?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Distance is speed times time: $3w$ miles walking and $5r$ miles running, for a total of $14$: $3w + 5r = 14$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'easy', 'source', 'approved', 8, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "John paid a total of $\\$165$ for a microscope by making a down payment of $\\$37$ plus $p$ monthly payments of $\\$16$ each. Which of the following equations represents this situation?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "The monthly payments total $16p$, plus the $\\$37$ down payment: $16p + 37 = 165$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'easy', 'source', 'approved', 9, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "math", "latex": "y - 57 = px"}, {"type": "paragraph", "text": "The given equation relates the positive numbers $p$, $x$, and $y$. Which equation correctly expresses $y$ in terms of $p$ and $x$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Add $57$ to both sides: $y = px + 57$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'easy', 'source', 'approved', 10, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "A company opens an account with an initial balance of $\\$36{,}100.00$. The account earns interest, and no additional deposits or withdrawals are made. The account balance is given by an exponential function $A$, where $A(t)$ is the account balance, in dollars, $t$ years after the account is opened. The account balance after $13$ years is $\\$68{,}071.93$. Which equation could define $A$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "The initial value $A(0)$ must be $36{,}100.00$, and the balance grows, so the base is greater than $1$: $A(t) = 36{,}100.00(1.05)^t$. (Check: $36{,}100(1.05)^{13} \\approx 68{,}072$.)"}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Advanced Math'), 'medium', 'source', 'approved', 11, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "image", "src": "/sat/test-09/math-m1-q12.png", "alt": "Figure for question 12", "width": 288}, {"type": "paragraph", "text": "The circle shown has center $O$, circumference $144\\pi$, and diameters $\\overline{PR}$ and $\\overline{QS}$. The length of arc $PS$ is twice the length of arc $PQ$. What is the length of arc $QR$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Arcs $PQ$ and $PS$ together make a semicircle ($72\\pi$), and $PS = 2 \\cdot PQ$, so $PQ = 24\\pi$ and $PS = 48\\pi$. Arc $QR$ is opposite arc $PS$ (vertical central angles), so it is also $48\\pi$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Geometry and Trigonometry'), 'medium', 'source', 'approved', 12, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "math", "latex": "\\begin{aligned} y &= -2x \\\\ 3x + y &= 40 \\end{aligned}"}, {"type": "paragraph", "text": "The solution to the given system of equations is $(x, y)$. What is the value of $x$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Substitute: $3x - 2x = 40$, so $x = 40$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'easy', 'source', 'approved', 13, 'spr', array['40']::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "image", "src": "/sat/test-09/math-m1-q14.png", "alt": "Figure for question 14", "width": 153}, {"type": "paragraph", "text": "The frequency table summarizes the $57$ data values in a data set. What is the maximum data value in the data set?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "The largest data value with a nonzero frequency is $14$ (frequency $6$)."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Problem-Solving and Data Analysis'), 'easy', 'source', 'approved', 14, 'spr', array['14']::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "One leg of a right triangle has a length of $43.2$ millimeters. The hypotenuse of the triangle has a length of $196.8$ millimeters. What is the length of the other leg of the triangle, in millimeters?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$\\sqrt{196.8^2 - 43.2^2} = \\sqrt{36{,}864} = 192$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Geometry and Trigonometry'), 'medium', 'source', 'approved', 15, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "A wire with a length of $106$ inches is cut into two parts. One part has a length of $x$ inches, and the other part has a length of $y$ inches. The value of $x$ is $6$ more than $4$ times the value of $y$. What is the value of $x$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$x + y = 106$ and $x = 4y + 6$, so $5y + 6 = 106$, $y = 20$, and $x = 86$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'medium', 'source', 'approved', 16, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "math", "latex": "f(x) = (x + 6)(x + 5)(x - 4)"}, {"type": "paragraph", "text": "The function $f$ is given. Which table of values represents $y = f(x) - 3$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$f(-6) = f(-5) = f(4) = 0$, so $f(x) - 3 = -3$ at each of these $x$-values."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Advanced Math'), 'medium', 'source', 'approved', 17, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "A landscaper uses a hose that puts $88x$ ounces of water in a bucket in $5y$ minutes. Which expression represents the number of ounces of water the hose puts in the bucket in $9y$ minutes at this rate?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "The rate is $\\dfrac{88x}{5y}$ ounces per minute, so in $9y$ minutes: $\\dfrac{88x}{5y} \\cdot 9y = \\dfrac{792x}{5}$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Problem-Solving and Data Analysis'), 'medium', 'source', 'approved', 18, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "math", "latex": "\\begin{aligned} 4x - 9y &= 9y + 5 \\\\ hy &= 2 + 4x \\end{aligned}"}, {"type": "paragraph", "text": "In the given system of equations, $h$ is a constant. If the system has no solution, what is the value of $h$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Rewrite: $4x - 18y = 5$ and $4x - hy = -2$. These are parallel with different constants when $h = 18$, so there is no solution."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'hard', 'source', 'approved', 19, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "$13$ is $p\\%$ of $25$. What is the value of $p$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$\\dfrac{13}{25} = 0.52$, so $p = 52$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Problem-Solving and Data Analysis'), 'easy', 'source', 'approved', 20, 'spr', array['52']::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "math", "latex": "\\sqrt{(x - 2)^2} = \\sqrt{3x + 34}"}, {"type": "paragraph", "text": "What is the smallest solution to the given equation?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Square both sides: $(x - 2)^2 = 3x + 34$, so $x^2 - 7x - 30 = 0$ and $(x - 10)(x + 3) = 0$. Both $10$ and $-3$ check in the original equation; the smaller is $-3$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Advanced Math'), 'hard', 'source', 'approved', 21, 'spr', array['-3']::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "Function $f$ is defined by $f(x) = (x + 6)(x + 5)(x + 1)$. Function $g$ is defined by $g(x) = f(x - 1)$. The graph of $y = g(x)$ in the $xy$-plane has $x$-intercepts at $(a, 0)$, $(b, 0)$, and $(c, 0)$, where $a$, $b$, and $c$ are distinct constants. What is the value of $a + b + c$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$g(x) = 0$ when $x - 1$ is a zero of $f$: $-6$, $-5$, or $-1$. So $x = -5$, $-4$, or $0$, and the sum is $-9$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Advanced Math'), 'hard', 'source', 'approved', 22, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "For $x > 0$, the function $f$ is defined as follows:"}, {"type": "paragraph", "text": "$f(x)$ equals $201\\%$ of $x$"}, {"type": "paragraph", "text": "Which of the following could describe this function?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$f(x) = 2.01x$, a line with positive slope: increasing linear."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'medium', 'source', 'approved', 23, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "math", "latex": "f(x) = 4x^2 + 64x + 262"}, {"type": "paragraph", "text": "The function $g$ is defined by $g(x) = f(x + 5)$. For what value of $x$ does $g(x)$ reach its minimum?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$f$ has its minimum at $x = -\\dfrac{64}{2(4)} = -8$. $g(x) = f(x + 5)$ reaches it when $x + 5 = -8$, so $x = -13$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Advanced Math'), 'hard', 'source', 'approved', 24, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "One gallon of stain will cover $170$ square feet of a surface. A yard has a total fence area of $w$ square feet. Which equation represents the total amount of stain $S$, in gallons, needed to stain the fence in this yard twice?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Two coats cover $2w$ square feet, which needs $\\dfrac{2w}{170} = \\dfrac{w}{85}$ gallons."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'medium', 'source', 'approved', 25, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "table", "header": ["Poll Results", ""], "rows": [["Angel Cruz", "$483$"], ["Terry Smith", "$320$"]]}, {"type": "paragraph", "text": "The table shows the results of a poll. A total of $803$ voters selected at random were asked which candidate they would vote for in the upcoming election. According to the poll, if $6{,}424$ people vote in the election, by how many votes would Angel Cruz be expected to win?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "In the poll Cruz led by $483 - 320 = 163$ of $803$ voters. Scaling to $6{,}424$ voters (a factor of $8$): $163 \\times 8 = 1{,}304$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Problem-Solving and Data Analysis'), 'medium', 'source', 'approved', 26, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "Right rectangular prism X is similar to right rectangular prism Y. The surface area of right rectangular prism X is $58$ square centimeters (cm$^2$), and the surface area of right rectangular prism Y is $1{,}450$ cm$^2$. The volume of right rectangular prism Y is $1{,}250$ cubic centimeters (cm$^3$). What is the sum of the volumes, in cm$^3$, of right rectangular prism X and right rectangular prism Y?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "The area ratio is $\\tfrac{1{,}450}{58} = 25$, so the length ratio is $5$ and the volume ratio is $125$. Prism X has volume $\\tfrac{1{,}250}{125} = 10$, and the sum is $1{,}260$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Geometry and Trigonometry'), 'hard', 'source', 'approved', 27, 'spr', array['1260']::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "math", "latex": "w + 7 = 357"}, {"type": "paragraph", "text": "What value of $w$ is the solution to the given equation?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$w = 357 - 7 = 350$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'easy', 'source', 'approved', 1, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "Which expression is equivalent to $16(x + 15)$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Distribute: $16x + 16(15) = 16x + 240$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Advanced Math'), 'easy', 'source', 'approved', 2, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "table", "header": ["", "Live east of the river", "Live west of the river", "Total"], "rows": [["Less than $40$ years old", "$17$", "$11$", "$28$"], ["At least $40$ years old", "$18$", "$89$", "$107$"], ["Total", "$35$", "$100$", "$135$"]]}, {"type": "paragraph", "text": "The table summarizes members of a local organization by age and whether they live east or west of the river. If a member of the organization is selected at random, what is the probability that the selected member is at least $40$ years old?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$107$ of the $135$ members are at least $40$ years old, so the probability is $\\tfrac{107}{135}$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Problem-Solving and Data Analysis'), 'easy', 'source', 'approved', 3, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "math", "latex": "\\begin{aligned} 3x &= 12 \\\\ -3x + y &= -6 \\end{aligned}"}, {"type": "paragraph", "text": "The solution to the given system of equations is $(x, y)$. What is the value of $y$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$3x = 12$, so $-12 + y = -6$ and $y = 6$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'easy', 'source', 'approved', 4, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "A line in the $xy$-plane has a slope of $\\dfrac{1}{9}$ and passes through the point $(0, 14)$. Which equation represents this line?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Slope $\\tfrac{1}{9}$ and $y$-intercept $14$: $y = \\tfrac{1}{9}x + 14$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'easy', 'source', 'approved', 5, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "image", "src": "/sat/test-09/math-m2-q06.png", "alt": "Figure for question 6", "width": 228}, {"type": "paragraph", "text": "In the figure shown, line $c$ intersects parallel lines $s$ and $t$. What is the value of $x$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "The $110^\\circ$ angle at line $t$ and the angle corresponding to it at line $s$ are equal, and angle $x$ forms a straight line with that angle, so $x = 180 - 110 = 70$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Geometry and Trigonometry'), 'easy', 'source', 'approved', 6, 'spr', array['70']::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "math", "latex": "f(x) = x + \\frac{8}{11}"}, {"type": "paragraph", "text": "The function $f$ is defined by the given equation. What is the value of $f(x)$ when $x = \\dfrac{3}{11}$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$\\dfrac{3}{11} + \\dfrac{8}{11} = \\dfrac{11}{11} = 1$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'easy', 'source', 'approved', 7, 'spr', array['1']::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "table", "header": ["$x$", "$y$"], "rows": [["$0$", "$18$"], ["$1$", "$13$"], ["$2$", "$8$"]]}, {"type": "paragraph", "text": "The table shows three values of $x$ and their corresponding values of $y$. There is a linear relationship between $x$ and $y$. Which of the following equations represents this relationship?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "When $x = 0$, $y = 18$, and $y$ decreases by $5$ for each increase of $1$ in $x$: $y = -5x + 18$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'easy', 'source', 'approved', 8, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "math", "latex": "\\begin{aligned} x + 7 &= 10 \\\\ (x + 7)^2 &= y \\end{aligned}"}, {"type": "paragraph", "text": "Which ordered pair $(x, y)$ is a solution to the given system of equations?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$x + 7 = 10$, so $x = 3$ and $y = 10^2 = 100$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Advanced Math'), 'easy', 'source', 'approved', 9, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "The function $f$ is defined by $f(x) = 7x - 84$. What is the $x$-intercept of the graph of $y = f(x)$ in the $xy$-plane?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$7x - 84 = 0$ gives $x = 12$, so the $x$-intercept is $(12, 0)$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'easy', 'source', 'approved', 10, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "image", "src": "/sat/test-09/math-m2-q11.png", "alt": "Figure for question 11", "width": 243}, {"type": "paragraph", "text": "Rosa opened a savings account at a bank. The table shows the exponential relationship between the time $t$, in years, since Rosa opened the account and the total amount $n$, in dollars, in the account. If Rosa made no additional deposits or withdrawals, which of the following equations best represents the relationship between $t$ and $n$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "The starting amount is $604$ and it grows by $\\tfrac{606.42 - 604}{604} \\approx 0.004$ each year: $n = 604(1 + 0.004)^t$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Advanced Math'), 'medium', 'source', 'approved', 11, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "math", "latex": "w(t) = 300 - 4t"}, {"type": "paragraph", "text": "The function $w$ models the volume of liquid, in milliliters, in a container $t$ seconds after it begins draining from a hole at the bottom. According to the model, what is the predicted volume, in milliliters, draining from the container each second?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "The volume drops by $4$ milliliters for each second ($-4t$)."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'easy', 'source', 'approved', 12, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "math", "latex": "h(x) = x + b"}, {"type": "paragraph", "text": "For the linear function $h$, $b$ is a constant and $h(0) = 45$. What is the value of $b$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$h(0) = 0 + b = 45$, so $b = 45$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'easy', 'source', 'approved', 13, 'spr', array['45']::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "math", "latex": "z^2 + 10z - 24 = 0"}, {"type": "paragraph", "text": "What is one of the solutions to the given equation?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Factor: $(z + 12)(z - 2) = 0$, so $z = 2$ or $z = -12$. Either is correct."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Advanced Math'), 'medium', 'source', 'approved', 14, 'spr', array['2', '-12']::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "Triangle $FGH$ is similar to triangle $JKL$, where angle $F$ corresponds to angle $J$ and angles $G$ and $K$ are right angles. If $\\sin(F) = \\dfrac{308}{317}$, what is the value of $\\sin(J)$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Corresponding angles of similar triangles are equal, so $\\sin(J) = \\sin(F) = \\tfrac{308}{317}$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Geometry and Trigonometry'), 'medium', 'source', 'approved', 15, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "The population of Greenville increased by $7\\%$ from $2015$ to $2016$. If the $2016$ population is $k$ times the $2015$ population, what is the value of $k$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "A $7\\%$ increase multiplies by $1 + 0.07 = 1.07$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Problem-Solving and Data Analysis'), 'easy', 'source', 'approved', 16, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "image", "src": "/sat/test-09/math-m2-q17.png", "alt": "Figure for question 17", "width": 306}, {"type": "paragraph", "text": "Each of the dot plots shown represents the number of glue sticks brought in by each student for two classes, class A and class B. Which statement best compares the standard deviations of the numbers of glue sticks brought in by each student for these two classes?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "The two dot plots have exactly the same shape; class B''s values are class A''s shifted up by $13$. Shifting every value does not change the spread, so the standard deviations are equal."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Problem-Solving and Data Analysis'), 'medium', 'source', 'approved', 17, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "math", "latex": "m(t) = -0.0274\\left(\\frac{t}{7}\\right)^2 + 7.3873\\left(\\frac{t}{7}\\right) + 75.032"}, {"type": "paragraph", "text": "The function $m$ gives the predicted body mass $m(t)$, in kilograms (kg), of a certain animal $t$ days after it was born in a wildlife reserve, where $t \\le 390$. Which of the following is the best interpretation of the statement \"$m(330)$ is approximately equal to $362$\" in this context?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "The input $t = 330$ is days after birth and the output $362$ is the predicted mass in kilograms."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Advanced Math'), 'medium', 'source', 'approved', 18, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "Triangle $XYZ$ is similar to triangle $RST$ such that $X$, $Y$, and $Z$ correspond to $R$, $S$, and $T$, respectively. The measure of $\\angle Z$ is $20^\\circ$ and $2XY = RS$. What is the measure of $\\angle T$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Similar triangles have equal corresponding angles, whatever the scale factor, so $\\angle T = \\angle Z = 20^\\circ$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Geometry and Trigonometry'), 'medium', 'source', 'approved', 19, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "The function $f(t) = 60{,}000(2)^{\\frac{t}{410}}$ gives the number of bacteria in a population $t$ minutes after an initial observation. How much time, in minutes, does it take for the number of bacteria in the population to double?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "The base $2$ is raised to $\\tfrac{t}{410}$, so the population doubles every $410$ minutes."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Advanced Math'), 'medium', 'source', 'approved', 20, 'spr', array['410']::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "The function $f$ is defined by $f(x) = a^x + b$, where $a$ and $b$ are constants and $a > 0$. In the $xy$-plane, the graph of $y = f(x)$ has a $y$-intercept at $(0, -25)$ and passes through the point $(2, 23)$. What is the value of $a + b$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$f(0) = 1 + b = -25$, so $b = -26$. Then $a^2 - 26 = 23$, so $a = 7$ and $a + b = -19$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Advanced Math'), 'hard', 'source', 'approved', 21, 'spr', array['-19']::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "math", "latex": "y > 13x - 18"}, {"type": "paragraph", "text": "For which of the following tables are all the values of $x$ and their corresponding values of $y$ solutions to the given inequality?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$13x - 18$ equals $21$, $47$, and $86$ at $x = 3$, $5$, $8$. Only table D has every $y$ strictly greater: $26$, $52$, $91$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'medium', 'source', 'approved', 22, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "A certain town has an area of $4.36$ square miles. What is the area, in **square yards**, of this town? ($1$ mile $= 1{,}760$ yards)"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "One square mile is $1{,}760^2 = 3{,}097{,}600$ square yards, so $4.36 \\times 3{,}097{,}600 = 13{,}505{,}536$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Problem-Solving and Data Analysis'), 'medium', 'source', 'approved', 23, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "A square is inscribed in a circle. The radius of the circle is $\\dfrac{20\\sqrt{2}}{2}$ inches. What is the side length, in inches, of the square?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "The diagonal of the square is a diameter: $20\\sqrt{2}$. A square''s diagonal is its side times $\\sqrt{2}$, so the side is $20$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Geometry and Trigonometry'), 'medium', 'source', 'approved', 24, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "Which expression is equivalent to $\\dfrac{y + 12}{x - 8} + \\dfrac{y(x - 8)}{x^2y - 8xy}$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Over the common denominator $xy(x - 8) = x^2y - 8xy$: the first fraction becomes $\\dfrac{xy(y + 12)}{x^2y - 8xy}$, so the sum is $\\dfrac{xy^2 + 12xy + xy - 8y}{x^2y - 8xy} = \\dfrac{xy^2 + 13xy - 8y}{x^2y - 8xy}$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Advanced Math'), 'hard', 'source', 'approved', 25, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "The function $f$ is defined by $f(x) = a(2.2^x + 2.2^b)$, where $a$ and $b$ are integer constants and $0 < a < b$. The functions $g$ and $h$ are equivalent to function $f$, where $k$ and $m$ are constants. Which of the following equations displays the $y$-coordinate of the $y$-intercept of the graph of $y = f(x)$ in the $xy$-plane as a constant or coefficient?"}, {"type": "math", "latex": "\\begin{aligned} &\\text{I. } g(x) = a(2.2^x + k) \\\\ &\\text{II. } h(x) = a(2.2)^x + m \\end{aligned}"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "The $y$-intercept is $f(0) = a(1 + 2.2^b)$. In I, $k = 2.2^b$, so the intercept is $a(1 + k)$; in II, $m = a(2.2^b)$, so the intercept is $a + m$. Neither shows it directly as a single constant or coefficient."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Advanced Math'), 'hard', 'source', 'approved', 26, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "math", "latex": "x(kx - 56) = -16"}, {"type": "paragraph", "text": "In the given equation, $k$ is an integer constant. If the equation has no real solution, what is the least possible value of $k$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Rewrite as $kx^2 - 56x + 16 = 0$. No real solution requires $56^2 - 4(k)(16) < 0$: $3{,}136 < 64k$, so $k > 49$. The least integer is $50$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Advanced Math'), 'hard', 'source', 'approved', 27, 'spr', array['50']::text[]) returning id into v_q;
    update public.exams set status = 'published' where id = v_exam;
  end if;
end $sat$;

do $sat$
declare
  v_subject uuid; v_exam uuid; v_section uuid; v_stim uuid; v_q uuid;
begin
  -- SAT Practice Test 10: Reading and Writing
  if exists (select 1 from public.exams where slug = 'sat-practice-test-10-reading-and-writing') then
    raise notice 'skipping sat-practice-test-10-reading-and-writing (already imported)';
  else
    select id into v_subject from public.subjects where code = 'sat-english';
    values (v_subject, 'sat-practice-test-10-reading-and-writing', 'SAT Practice Test 10: Reading and Writing', 'Official SAT Practice Test 10 (College Board), Reading and Writing: 66 questions in two modules, timed as the paper test (39 minutes per module).', 'full_mock', 'premium', 'draft', 78, 'source', 220, '[[200, 200], [210, 220], [210, 220], [210, 220], [210, 220], [210, 230], [220, 240], [220, 250], [230, 260], [230, 270], [240, 280], [240, 290], [250, 300], [250, 310], [260, 320], [270, 330], [280, 340], [300, 340], [310, 350], [320, 360], [330, 370], [330, 370], [340, 380], [350, 390], [350, 390], [360, 400], [370, 410], [370, 410], [380, 420], [390, 430], [400, 440], [400, 440], [410, 450], [420, 460], [430, 470], [440, 480], [450, 490], [460, 500], [460, 500], [470, 510], [470, 530], [480, 540], [490, 550], [500, 560], [510, 570], [520, 580], [530, 590], [540, 600], [550, 610], [570, 630], [580, 640], [590, 650], [600, 660], [610, 670], [620, 680], [630, 690], [640, 700], [670, 710], [680, 720], [690, 730], [700, 740], [720, 760], [730, 770], [740, 780], [760, 780], [770, 800], [800, 800]]'::jsonb)
    returning id into v_exam;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text with the most logical and precise word or phrase?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice A is the best answer because it most logically completes the text’s discussion of the role of the general store in US rural communities during the 1800s. In this context, “source” means a place where something originates or is obtained. The text states that people would share news while socializing at the general store. This context supports the idea that the store served as a source of information in rural communities."}, {"type": "paragraph", "text": "Choice B is incorrect because “rival” would mean competitor or opponent. The text doesn’t indicate that the general store was a rival of anything. Instead, the text describes the general store as a place that enabled the sharing of information within rural communities. Choice C is incorrect because in this context, “condition” would mean state, circumstance, or requirement. Although the text implies that visiting the store was helpful for acquiring information since people shared news there, it wouldn’t make sense to say that the general store was a condition of information. Choice D is incorrect because “waste” would mean something that is unused, discarded, or spent unnecessarily, which would not make sense in context. The text describes the general store as an essential part of daily life and a place for socializing and information sharing. The store was therefore a source, not a waste, of information."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Craft and Structure'), 'medium', 'source', 'approved', 1, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text with the most logical and precise word or phrase?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice B is the best answer because it most logically completes the text’s discussion of Jacob Lawrence’s artistic process. In this context, “observant” means watchful and perceptive. The text emphasizes that the “close attention” Lawrence paid to “all the details” of his neighborhood allowed him to reflect subtle elements of “the beauty and vitality of the Black experience” in his artwork. This context indicates that being observant of his surroundings was an important part of Lawrence’s work as an artist."}, {"type": "paragraph", "text": "Choice A is incorrect because the text gives no indication that Lawrence was “skeptical,” or had an attitude of doubt in general or about particular things, let alone that skepticism was important to him as an artist. Rather than indicating that he was skeptical, the text focuses on how Lawrence paid careful attention to everything around him and reflected his observations in his artwork. Choice C is incorrect because the text gives no indication that Lawrence was “critical,” which in this context would mean inclined to criticize harshly or unfairly. Rather than indicating that Lawrence found fault in things, the text suggests that he paid careful attention to everything around him and that his artwork reflects this careful attention. Choice D is incorrect because the text doesn’t suggest that Lawrence was “confident,” or self-assured. Rather than addressing how Lawrence felt about himself and how that feeling affected his artistic process, the text emphasizes the careful attention Lawrence paid to everything around him— attention that allowed him to capture subtle elements of a particular place and time in his artwork."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Craft and Structure'), 'medium', 'source', 'approved', 2, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text with the most logical and precise word or phrase?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice B is the best answer because it most logically completes the text’s discussion of Ochoa’s prediction that humans will one day need to live in places other than Earth. As used in this context, “speculates” would mean puts forward an idea without firm evidence. The text states that Ochoa “doesn’t have a definite idea” about when humans might need to live in other environments and characterizes Ochoa’s prediction as a “conjecture,” or a conclusion presented without convincing evidence. This context indicates that Ochoa speculates when she makes this prediction."}, {"type": "paragraph", "text": "Choice A is incorrect because saying that Ochoa “demands,” or insists or requires, that humans will one day need to live in other environments than Earth’s would not make sense in context. The text indicates that she’s unsure about the timing but hypothesizes that it will someday happen. Choice C is incorrect because saying that Ochoa “doubts,” or questions or disbelieves, that humans will one day need to live in other environments than Earth’s would not make sense in context. The text indicates that although Ochoa is unsure about the timing, she hypothesizes that humans will need to live in places other than Earth and encourages research into future travel to the moon. Choice D is incorrect because saying that Ochoa “establishes,” or proves, that humans will one day need to live in other environments than Earth’s would not make sense in context. Rather than stating that Ochoa discusses her idea with certainty and supports it with evidence, the text indicates that Ochoa is unsure about when humans might need to live in other environments."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Craft and Structure'), 'medium', 'source', 'approved', 3, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text with the most logical and precise word or phrase?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice A is the best answer because it most logically completes the text’s discussion of a relationship between the dodder plant and its host plant. As used in this context, “synchronization” means the act of things happening at the same time. The text indicates that the dodder and its host plant flower in unison and that this synchronization occurs because the dodder makes use of a protein produced by the host shortly before flowering."}, {"type": "paragraph", "text": "Choice B is incorrect because referring to “hibernation,” or the state of being dormant or inactive, wouldn’t make sense in context. The text focuses on something the dodder plant actively engages in—making use of a protein and producing flowers. Choice C is incorrect because stating that the dodder plant and its host engage together in “prediction,” or the act of declaring or indicating something in advance, wouldn’t make sense in context. Rather than indicating that the dodder plant and its host plant make a prediction about flowering activity, the text suggests that the host produces a protein as part of its regular flowering process and that the dodder then absorbs and uses that protein to flower at the same time. Choice D is incorrect because referring to “moderation,” or the act of causing something to become less intense or extreme, wouldn’t make sense in context. Although the text states that the dodder plant absorbs and uses a protein made by its host plant, it doesn’t suggest that the dodder lessens the host plant’s flowering activity; the two plants simply flower in unison."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Craft and Structure'), 'medium', 'source', 'approved', 4, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text with the most logical and precise word or phrase?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice C is the best answer because it most logically completes the text’s discussion of historical evidence about ancient Egypt under the reign of the pharaoh Hatshepsut. In this context, “an exhaustive” account would be a thorough one. The text states that much of the evidence from her reign was purposely destroyed—in other words, there is a lack of surviving records. This context conveys that unless there are major new archaeological discoveries, an exhaustive account of Hatshepsut’s reign is unlikely."}, {"type": "paragraph", "text": "Choice A is incorrect because in this context, “an imaginative” account would be an account based on imagination, or ideas and speculation, rather than facts. The text indicates that much of the evidence of Hatshepsut’s reign was deliberately destroyed, and a lack of evidence actually makes it more likely that accounts will be imaginative to some degree and not strictly factual. Choice B is incorrect because in this context, “a superficial” account would be one that is lacking in depth or concerned only with what is obvious. The text indicates that most evidence of Hatshepsut’s reign was purposely destroyed, which suggests that accounts of that time are likely already somewhat superficial, since there is little information available to support deeper knowledge. Further, it would be illogical to suggest that discovering major new evidence would make it more likely that accounts would be superficial. Choice D is incorrect because “a questionable” account would be one likely to be challenged or doubted, and since the text suggests that little evidence of Hatshepsut’s reign has survived, accounts of that time probably involve some speculation and thus may already be open to doubt. Further, it would be illogical to suggest that discovering major new evidence would make it more likely that accounts would be questionable."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Craft and Structure'), 'medium', 'source', 'approved', 5, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice best states the main purpose of the text?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice B is the best answer because it best describes the main purpose of the text. The text indicates where and when jazz tap first developed (in African American communities in the 1920s) and what influenced it (the quick rhythms and improvisations in jazz music) and then explains that it evolved alongside jazz music in the 1930s and 1940s, resulting in a very different form of tap dance than had existed before. Therefore, the main purpose of the text is to discuss jazz tap’s development."}, {"type": "paragraph", "text": "Choice A is incorrect. Although the text indicates that jazz music became widely popular in the US in the 1920s and describes some of jazz music’s qualities, the text never explains why audiences prefer some kinds of music—jazz or otherwise—over others. Choice C is incorrect because the text never mentions any musical instruments and doesn’t describe how to play one. Choice D is incorrect because the text discusses jazz tap generally and never identifies a particular dancer, famous or otherwise."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Craft and Structure'), 'medium', 'source', 'approved', 6, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice best describes the overall structure of the text?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice D is the best answer because it accurately describes the overall structure of the text. The text begins by pointing out an obstacle to observing the astronomical phenomenon of the NCP: the NCP is visible only at night. The text then indicates that, inspired by the ability of some insects and birds to navigate using visualizations of polarized sunlight, researchers devised a way to locate the NCP during daylight. The text then indicates that the researchers mimicked the insects’ and birds’ polarized-light visualization capabilities using a polarimetric camera. Thus, the text notes an obstacle to observing an astronomical phenomenon, mentions a navigational ability of certain animals that inspired a solution to that obstacle, and then explains how researchers used an optical device to mimic that ability."}, {"type": "paragraph", "text": "Choice A is incorrect. Although it’s reasonable to conjecture that humans have used the NCP for navigation, the text doesn’t indicate this is the case, let alone that the NCP is relevant to a majority of navigational tools. Furthermore, the text doesn’t state that researchers discovered that insects and birds navigate without the NCP; rather, it indicates that it’s known that some animals navigate by using skylight polarization to locate the NCP during the day and that this knowledge inspired the method the researchers devised. Choice B is incorrect. Although it’s reasonable to conjecture that humans have used the NCP for navigation, the text doesn’t state that this is the case. Furthermore, the text discusses how some animals’ use of navigational strategies based on the same celestial occurrence served as the inspiration for the researchers’ polarized-light approach, not as the basis for a comparison of the relative effectiveness of animal and human methods of navigation. Choice C is incorrect. Although the text implies that humans have typically been able to locate the NCP visually at night and indicates that some animals use the NCP to navigate, the text doesn’t state that humans use the NCP for navigation. The text therefore doesn’t emphasize a difference between how humans and animals use the NCP for this purpose. Furthermore, the text doesn’t suggest that existing navigational instruments will be augmented with polarimetric technologies."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Craft and Structure'), 'medium', 'source', 'approved', 7, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, 0, '{"blocks": [{"type": "paragraph", "text": "Which choice best describes the function of the underlined sentence in the text as a whole?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice D is the best answer because it accurately describes how the underlined sentence functions in the text as a whole. The text establishes that John has a strong imagination and then goes on to describe the St. John River near John’s home in the Florida woods. The underlined sentence depicts John sending twigs sailing down the river while he imagines them reaching “Jacksonville, the sea, the wide world,” where he wishes he could follow. This suggests that John longs to expand his life experiences beyond the Florida woods."}, {"type": "paragraph", "text": "Choice A is incorrect because the second and third sentences of the text provide an extended description of the riverbank where John likes to go, whereas the underlined sentence describes what John does at that location. Choice B is incorrect because the first sentence of the text suggests that John’s behavior “was puzzling” to others around him, whereas the underlined sentence concerns the content of John’s imaginings. Choice C is incorrect because the underlined sentence elaborates on John’s imagination but doesn’t mention any other children to whom John could be compared."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Craft and Structure'), 'medium', 'source', 'approved', 8, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice best describes the function of the second sentence in the overall structure of the text?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice C is the best answer because it best describes how the second sentence functions in the text as a whole. The first sentence establishes something astronomers believe with some certainty: that Betelgeuse will explode in a supernova. The second sentence then introduces a problem: astronomers aren’t certain when Betelgeuse will explode because they don’t have enough information about the star’s internal characteristics. Finally, the third sentence indicates that researcher Sarafina El-Badry Nance and colleagues investigated a possible method of obtaining the necessary information about Betelgeuse’s internal characteristics, though they found that the method wouldn’t be sufficient. Thus, the function of the second sentence is to identify the problem that Nance and colleagues attempted to solve but didn’t."}, {"type": "paragraph", "text": "Choice A is incorrect because the second sentence introduces the general problem Nance and colleagues hoped to solve, not a serious limitation of how Nance and colleagues tried to solve it. It is the third sentence that introduces Nance and colleagues, but no serious limitation of their approach to studying a method of determining internal stellar states is described. Choice B is incorrect because the second sentence introduces the general problem Nance and colleagues hoped to solve, not the central finding they ultimately reported. It is the third sentence that presents Nance and colleagues’ conclusion that a potential method for determining internal stellar states would be insufficient."}, {"type": "paragraph", "text": "Choice D is incorrect because the second sentence doesn’t indicate how other astronomers or astrophysicists responded to the work done by Nance and colleagues; the text doesn’t address this information at all."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Craft and Structure'), 'medium', 'source', 'approved', 9, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Based on the texts, how would Putirka and Xu (Text 2) most likely characterize the conclusion presented in Text 1?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice C is the best answer because it reflects how Putirka and Xu (Text 2) would likely characterize the conclusion presented in Text 1. Text 1 discusses a study by Mark Holland and colleagues in which they detected traces of lithium and sodium in the atmospheres of four white dwarf stars. The team claims that this supports the idea that exoplanets with continental crusts like Earth’s once orbited these stars. Text 2 introduces Putirka and Xu, who indicate that sodium and lithium are present in several different minerals and that some of those minerals might exist in types of rock that are not found on Earth. Therefore, Putirka and Xu would likely describe the conclusion in Text 1 as questionable because it does not consider that lithium and sodium are also found in rocks that are not like Earth’s continental crust."}, {"type": "paragraph", "text": "Choice A is incorrect because the texts do not indicate how widely held any of the viewpoints described are. Choice B is incorrect because neither text discusses how new this area of study is. Choice D is incorrect because neither text discusses how likely lithium and sodium are to be detected by analyzing wavelengths of light."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Craft and Structure'), 'medium', 'source', 'approved', 10, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "According to the text, how does the narrator feel about being at summer camp?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice C is the best answer because it most accurately states how the narrator feels about being at summer camp. In the text, the narrator states that after arriving at the camp, he found it to be different than he’d expected and that as a result, he felt “scared, but also excited.”"}, {"type": "paragraph", "text": "Choice A is incorrect. In the text, the narrator describes himself as “excited.” Although excitement is a positive emotion, it isn’t as intensely positive as feeling overjoyed is. Moreover, the narrator also notes that he felt “scared.” In other words, his excitement (a positive emotion) is balanced with fear (a negative emotion). Given this mixture of positive and negative emotions, it would be inaccurate to characterize the narrator as overjoyed. Choice B is incorrect because in the text, the narrator describes himself as having felt both fear and excitement. Neither of these emotions can be thought of as peaceful and, in fact, are almost the opposite of a sense of peace. Choice D is incorrect because in the text, the narrator describes himself as both “scared” and “excited,” not angry and jealous."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 11, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "According to the text, what is true about Dorian?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice B is the best answer because it presents a statement about Dorian that is directly supported by the text. The narrator of the text says that when Dorian sees his portrait, “his cheeks flushed for a moment with pleasure” and “a look of joy came into his eyes.” The narrator goes on to say that Dorian looked at the portrait “in wonder” and presents him as being so entranced by the portrait that he doesn’t notice what Hallward is saying to him. All these details support the description of Dorian as being delighted by what he sees in the portrait."}, {"type": "paragraph", "text": "Choice A is incorrect because Dorian isn’t depicted as interested in Hallward’s opinion of the portrait but rather as so enraptured by the painting that he’s hardly even aware of Hallward. Choice C is incorrect because the portrait of Dorian is the only painting that is mentioned in the text, so there’s no evidence that Dorian prefers portraits to other types of paintings. Although Dorian is depicted as delighted with this particular portrait, there’s no way of knowing from the text whether he likes portraits better than other kinds of paintings. Choice D is incorrect because nothing in the text suggests that Dorian is uncertain about Hallward’s talent. Instead, the text is focused on Dorian’s delight with the portrait."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 12, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice best describes Gibson’s approach to art, as presented in the text?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice A is the best answer because it most accurately describes Gibson’s approach to art. As the text explains, Gibson, who is Cherokee and Choctaw, transforms punching bags into art pieces by applying (or attaching) to them beadwork and elements of Native dressmaking, including leather fringe and the jingles of the jingle dress. The text goes on to say that in most Native communities, the art forms of beadwork and dressmaking are traditionally practiced by women. Therefore, Gibson’s approach to art consists of creating original works by drawing from traditional Native art forms."}, {"type": "paragraph", "text": "Choice B is incorrect. Because Gibson incorporates Native art forms into his own original artwork, it can be inferred that he has been influenced by other Native artists, but the text never suggests that non-Native artists have influenced him."}, {"type": "paragraph", "text": "Choice C is incorrect because the text doesn’t indicate that Gibson designs dresses influenced by boxing but instead that he turns punching bags, which are used in boxing, into works of art by applying elements of Native dressmaking to them. Choice D is incorrect. Although Gibson does incorporate beadwork into his art, the text never mentions the colors or patterns that he uses or suggests that his art defies the expectations that people might have about color and pattern in beadwork."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 13, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which quotation from O Pioneers! most effectively illustrates the claim?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice A is the best answer because it presents the quotation that most directly illustrates the claim that Cather portrays Alexandra as having a deep emotional connection to her natural surroundings. This quotation states that the country meant a great deal to Alexandra and then goes on to detail several ways in which her natural surroundings affect her emotionally: the insects sound like “the sweetest music,” she feels as though “her heart were hiding” in the grass “with the quail and the plover,” and near the ridges she feels “the future stirring.”"}, {"type": "paragraph", "text": "Choice B is incorrect because the quotation doesn’t suggest that Alexandra had a deep emotional connection to her natural surroundings but instead describes how she interacts with the people around her to learn more about crops, poultry, and experiments with clover hay. Choice C is incorrect because the quotation doesn’t suggest that Alexandra has a deep emotional connection to her natural surroundings but instead describes her nighttime departure in a wagon. The quotation says nothing about Alexandra’s emotional state. Choice D is incorrect because the quotation doesn’t convey Alexandra’s deep emotional connection to her natural surroundings; instead, this quotation describes how well she understands the markets and livestock."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 14, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which finding, if true, would most strongly support the scholar’s claim?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice A is the best answer because it presents a finding that, if true, would support the scholar’s claim about Toni Morrison’s likely goal of strengthening the presence of Black writers on Random House’s list of published authors. The text explains that Morrison was the first Black woman to be an editor for Random House and that she was an editor there from 1967 to 1983. If it were true that Random House published a higher percentage of works by Black authors throughout the 1970s—during most of Morrison’s time working there—than it had previously published, that would suggest that Morrison may have made a deliberate effort to strengthen the presence of Black authors on the list of Random House’s published authors, thus supporting the scholar’s claim."}, {"type": "paragraph", "text": "Choice B is incorrect because the scholar’s claim is about Morrison’s work as an editor at a publishing company and her likely effort to strengthen the presence of Black writers on that company’s list of published authors. It might be true that Black authors interviewed in the 1980s and 1990s often cited Morrison’s novels as an influence on their work, but that finding would simply suggest something about how those authors approached their work; it wouldn’t show that Morrison intended to increase the number of Black writers among the published authors specifically at Random House. Choice C is incorrect because the scholar’s claim is about Morrison’s work as an editor at a publishing company, not about her work as a novelist. Therefore, a finding that Morrison’s novels published after 1983 sold more copies and were more widely acclaimed than her earlier novels would have no bearing on the claim that as an editor Morrison made an effort to ensure that more Black writers were present on Random House’s list of published authors."}, {"type": "paragraph", "text": "Choice D is incorrect. Although the text discusses Morrison’s work as an editor at Random House, the scholar’s claim focuses on Morrison’s likely effort in that role to increase the number of Black writers present on Random House’s list of published authors, not on the influence she may have had on the content of the works she edited. Without knowing whether Morrison’s stylistic influence led to more publications or if Morrison applied her influence specifically to works by Black writers, the finding that works edited by Morrison could be identified by stylistic characteristics would have no bearing on the claim that Morrison intended to strengthen the presence of Black writers among the published authors at Random House."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 15, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which finding, if true, would most strongly support the team’s conclusion?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice A is the best answer because it presents a finding that, if true, would most strongly support the team’s conclusion that cattle were likely raised closer to human settlements than sheep and goats were. The text explains that Vaiglova, Liu, and their colleagues analyzed the chemical composition of sheep, goat, and cattle bones from the Bronze Age in China in order to investigate the animals’ domestication, or their adaptation from a wild state to a state in which they existed in close connection with humans. According to the text, the team’s analysis showed that sheep and goats of the era fed largely on wild plants, whereas cattle fed on millet—importantly, a crop cultivated by humans. If analysis of the animal bones shows that the cattle’s diet also consisted of wheat, another crop cultivated by humans in China during the Bronze Age, the finding would support the team’s conclusion by offering additional evidence that cattle during this era fed on human-grown crops—and, by extension, that humans raised cattle relatively close to the settlements where they grew these crops, leaving goats and sheep to roam farther away in areas with wild vegetation, uncultivated by humans."}, {"type": "paragraph", "text": "Choice B is incorrect because if it were true that sheep’s and goats’ diets consisted of small portions of millet, which the text states was a crop cultivated by humans, the finding would suggest that sheep and goats were raised relatively close to human settlements, weakening the team’s conclusion that cattle were likely raised closer to those settlements than sheep and goats were. Choice C is incorrect because the finding that cattle generally require more food and nutrients than do sheep and goats wouldn’t support the team’s conclusion that cattle were likely raised closer to human settlements than sheep and goats were. Nothing in the text suggests that cattle were incapable of obtaining sufficient food and nutrients without access to human-grown crops. Hence, even if cattle’s diets are found to have different requirements than the diets of sheep and goats, the cattle could have met those requirements from food located far from human settlements. Choice D is incorrect because if it were true that the diets of sheep, goats, and cattle varied based on what the farmers in each Bronze Age settlement could grow, the finding would weaken the team’s conclusion that cattle were likely raised closer to human settlements than sheep and goats were, suggesting instead that all three types of animals were raised close enough to human settlements to feed on those settlements’ crops."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 16, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which completion of the text is best supported by data in the graph?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice C is the best answer because it most logically completes the text based on supporting data in the graph. The text indicates that in the fly D. melanogaster, DptA and DptB are genes that encode peptides that both fight pathogens and promote beneficial microbes. Researchers tested D. melanogaster’s resistance to P. rettgeri and A. sicerae bacteria based on which variation of the peptide- encoding gene the flies exhibit: DptA silenced (referred to as type A), DptB silenced (type B), or both silenced (type AB). The text also indicates that resistance to P. rettgeri correlates with DptA activity but not with DptB activity (which would manifest as type B flies surviving at a higher rate than other fly types when exposed to P. rettgeri). The graph shows the post–A. sicerae infection results, which indicate that DptB activity was most strongly associated with survival, whereas DptA activity was not (manifesting in the graph as the type A flies having greater survival rates than the other fly types). In other words, when DptA activity was silenced, the flies showed relatively high survival rates, but when DptB activity was silenced, whether on its own or in conjunction with DptA activity being silenced, survival rates were low, suggesting that DptB may have developed as a specific defense against A. sicerae."}, {"type": "paragraph", "text": "Choice A is incorrect. The graph suggests that DptA activity is associated with a low rate of survival, not a high one. Furthermore, the graph shows results for flies where DptA alone was silenced, DptB alone was silenced, and both were silenced and thus does not show any flies with activity in both DptA and DptB, which would be necessary to determine whether DptA conferred defense against A. sicerae in the presence of DptB. Choice B is incorrect. Only two bacteria species were considered in the text: P. rettgeri and A. sicerae. The text and graph taken together suggest that activity in DptA is associated with resistance to P. rettgeri while DptB activity is not, and that DptB activity is associated with resistance to A. sicerae while DptA is not. There is no further information to suggest one genetic type confers resistance to a greater number of pathogens than the other."}, {"type": "paragraph", "text": "Choice D is incorrect. The graph does not address flies with activity in both DptA and DptB. All flies represented in the graph had one or both of DptA and DptB silenced, or inactive."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 17, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice most logically completes the text?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice D is the best answer because it presents the conclusion that most logically follows from the text’s discussion of leafy spurge and engineered DNA. The text establishes that using chemical herbicides to control leafy spurge in North America can also harm other plants nearby. The text then indicates that it might be possible to use engineered DNA to prevent plants from reproducing, which would be useful for “exclusively targeting” leafy spurge. If it’s possible to exclusively target leafy spurge with engineered DNA—meaning that only leafy spurge is affected by the engineered DNA—and prevent the plant from reproducing, then leafy spurge numbers could be reduced “without harming other organisms.”"}, {"type": "paragraph", "text": "Choice A is incorrect because the text raises the possibility of using engineered DNA to prevent leafy spurge from reproducing, not to make individual leafy spurge plants more vulnerable to chemical herbicides that already exist. Choice B is incorrect because the text doesn’t describe any ecological benefits of leafy spurge in North America; instead, the text is focused on using engineered DNA to prevent leafy spurge from reproducing and thereby reduce its numbers. The only ecological effects of leafy spurge in North America that are described in the text are harmful. Choice C is incorrect because the text describes the possibility of using engineered DNA to prevent leafy spurge from reproducing; it doesn’t offer a way to enable cattle to eat leafy spurge without becoming sick."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 18, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice most logically completes the text?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice C is the best answer because it most logically completes the text’s discussion of accelerated flowering in A. thaliana plants. The text indicates that A. thaliana plants show accelerated flowering at high temperatures. To investigate the mechanism for this accelerated flowering, biologists replaced the ELF3 protein in one group of A. thaliana plants with a similar protein found in another plant species that doesn’t show accelerated flowering. The team then compared these modified plants to A. thaliana plants that retained their original ELF3 protein. The text states that the two samples of plants showed no difference in flowering at 22° Celsius, but at 27° Celsius the unaltered plants with ELF3 showed accelerated flowering while the plants without ELF3 didn’t. If accelerated flowering at the higher temperature occurred in the A. thaliana plants with ELF3 but not in the plants without the protein, then ELF3 likely enables A. thaliana to respond to increased temperatures."}, {"type": "paragraph", "text": "Choice A is incorrect because the text doesn’t mention whether any plants other than A. thaliana and stiff brome show temperature-sensitive flowering, so there is no support for the idea that this type of flowering is unique to A. thaliana. Choice B is incorrect because the text discusses the effects of ELF3 and not the production of it. There’s nothing in the text to suggest that the amount of ELF3 in A. thaliana varies with temperature. Choice D is incorrect. While the text states that there was no difference in the flowering of modified and unmodified A. thaliana plants at 22° Celsius, there’s no suggestion that A. thaliana only begins to flower at 22° Celsius; the text doesn’t mention a specific temperature threshold required for A. thaliana flowering."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 19, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text so that it conforms to the conventions of Standard English?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice B is the best answer. The convention being tested is the coordination of main clauses within a sentence. This choice correctly uses a comma and the coordinating conjunction “but” to join the first main clause (“the Alvarez…out”) and the second main clause (“it left…extinctions”)."}, {"type": "paragraph", "text": "Choice A is incorrect because when coordinating two longer main clauses such as these, it’s conventional to use a comma before the coordinating conjunction."}, {"type": "paragraph", "text": "Choice C is incorrect because it results in a run-on sentence. The two main clauses are fused without punctuation and/or a conjunction. Choice D is incorrect because it results in a comma splice. Without a conjunction following it, a comma can’t be used in this way to join two main clauses."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Standard English Conventions'), 'medium', 'source', 'approved', 20, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text so that it conforms to the conventions of Standard English?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice A is the best answer. The convention being tested is the coordination of independent clauses within a sentence. An independent clause is a phrase containing a subject and a verb that can stand on its own as a sentence. This choice uses a comma and the coordinating conjunction “but” to join the first independent clause (“underlines…lower a book’s value”) and the second independent clause (“such markings…can be a gold mine to scholars”) to create a compound sentence."}, {"type": "paragraph", "text": "Choice B is incorrect because it results in a run-on sentence. The two independent clauses are fused without punctuation and/or a conjunction."}, {"type": "paragraph", "text": "Choice C is incorrect because it results in a comma splice. A comma can’t be used in this way to mark the boundary between two independent clauses. Choice D is incorrect because a comma is needed to mark the boundary between two coordinated independent clauses."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Standard English Conventions'), 'medium', 'source', 'approved', 21, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text so that it conforms to the conventions of Standard English?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice C is the best answer. The convention being tested is the use of finite and nonfinite verb forms within a sentence. The nonfinite present participle “forcing” is correctly used to form a participial phrase that supplements the main clause “those...cover,” describing the effects on monkeys of the lack of food sources."}, {"type": "paragraph", "text": "Choice A is incorrect because the finite present tense verb “forces” can’t be used in this way to supplement the main clause (“those...cover”). Choice B is incorrect. While the nonfinite to-infinitive “to force” could be used to form a subordinate clause that supplements the main clause (“those...cover”), to-infinitives conventionally express purpose, and nothing in the sentence suggests that the food sources become unavailable for the purpose of forcing monkeys to hunt marine animals. Choice D is incorrect because the finite past tense verb “forced” can’t be used in this way to supplement the main clause (“those...cover”)."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Standard English Conventions'), 'medium', 'source', 'approved', 22, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text so that it conforms to the conventions of Standard English?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice C is the best answer. The convention being tested is punctuation between a subordinate clause and a main clause. This choice correctly uses a comma to mark the boundary between the subordinate clause (“While…lifelike”) and the main clause (“others look to the past”)."}, {"type": "paragraph", "text": "Choice A is incorrect because it results in an incomplete sentence with no main clause. Choice B is incorrect because it fails to mark the boundary between the subordinate clause (“While…lifelike”) and the main clause (“others…past”)."}, {"type": "paragraph", "text": "Choice D is incorrect because it results in an incomplete sentence with no main clause."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Standard English Conventions'), 'medium', 'source', 'approved', 23, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text so that it conforms to the conventions of Standard English?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice C is the best answer. The convention being tested is the use of verbs to express tense. In this choice, the present tense verb “experiences” is consistent with the other present tense verbs (e.g., “connects” and “prepares”) used to describe the events in Truong’s novels. Furthermore, it’s conventional to use the present tense when discussing a literary work."}, {"type": "paragraph", "text": "Choice A is incorrect because the past tense verb “experienced” isn’t consistent with the other present tense verbs used to describe the events in Truong’s novels."}, {"type": "paragraph", "text": "Choice B is incorrect because the past perfect tense verb “had experienced” isn’t consistent with the other present tense verbs used to describe the events in Truong’s novels. Choice D is incorrect because the future progressive tense verb “will be experiencing” isn’t consistent with the other present tense verbs used to describe the events in Truong’s novels."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Standard English Conventions'), 'medium', 'source', 'approved', 24, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text so that it conforms to the conventions of Standard English?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice C is the best answer. The convention being tested is the use of punctuation in a sentence. In this choice, a colon is correctly used to mark the boundary between one main clause (“Along with...photosynthesis”) and another main clause (“as light...oxygen”) and to introduce the following explanation of how light intensity affects photosynthesis."}, {"type": "paragraph", "text": "Choice A is incorrect because when coordinating two longer main clauses such as these, it’s conventional to use a comma before the coordinating conjunction (“and”). Choice B is incorrect because it results in a comma splice. Without a coordinating conjunction following it, a comma can’t be used in this way to join two main clauses (“Along with...photosynthesis” and “as light...oxygen”). Choice D is incorrect because it results in a run-on sentence. The two main clauses (“Along with...photosynthesis” and “as light...oxygen”) are fused without punctuation and/or a conjunction."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Standard English Conventions'), 'medium', 'source', 'approved', 25, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text so that it conforms to the conventions of Standard English?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice C is the best answer. The convention being tested is the use of possessive determiners. The plural possessive determiner “their” agrees in number with the plural noun “types” and thus indicates that the more personal subject matter of Marisol’s 1968 sculpture takes the place of those types of pop culture references that made Marisol a star."}, {"type": "paragraph", "text": "Choice A is incorrect because the singular possessive determiner “its” doesn’t agree in number with the plural noun “types.” Choice B is incorrect because “they’re” is the contraction for “they are,” not a possessive determiner. Choice D is incorrect because “it’s” is the contraction for “it is” or “it has,” not a possessive determiner."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Standard English Conventions'), 'medium', 'source', 'approved', 26, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text so that it conforms to the conventions of Standard English?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice A is the best answer. The convention being tested is the use of verb forms within a sentence. The singular verb “is” agrees in number with the singular subject “each one of a ghazal’s couplets.” While the prepositional phrase “of a ghazal’s couplets” within the subject contains a plural noun, the head of the subject (“each one”) is singular, indicating that each individual couplet (not the couplets as a group) is “thematically and logically autonomous,” or self-standing."}, {"type": "paragraph", "text": "Choice B is incorrect because the plural verb “were” doesn’t agree in number with the singular subject “each one of a ghazal’s couplets.” Choice C is incorrect because the plural verb “have been” doesn’t agree in number with the singular subject “each one of a ghazal’s couplets.” Choice D is incorrect because the plural verb “are” doesn’t agree in number with the singular subject “each one of a ghazal’s couplets.”"}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Standard English Conventions'), 'medium', 'source', 'approved', 27, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text with the most logical transition?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice B is the best answer. “For example” logically signals that the information in this sentence—that tadpole shrimp embryos can pause development during extended periods of drought— exemplifies the previous sentence’s claim that organisms have evolved surprising adaptations to survive in adverse conditions."}, {"type": "paragraph", "text": "Choice A is incorrect because “in contrast” illogically signals that the information in this sentence contrasts with the claim about organisms in the previous sentence. Instead, it exemplifies this claim. Choice C is incorrect because “meanwhile” illogically signals that the information in this sentence is separate from (while occurring simultaneously with) the claim about organisms in the previous sentence. Instead, it exemplifies this claim. Choice D is incorrect because “consequently” illogically signals that the information in this sentence is a consequence, or result, of the claim about organisms in the previous sentence. Instead, it exemplifies this claim."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Expression of Ideas'), 'medium', 'source', 'approved', 28, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text with the most logical transition?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice B is the best answer. “Previously” logically signals that the event described in this sentence—Bigelow being named best director—occurred before Zhao’s win. The fact that only one other woman had won the award before puts Zhao’s win in perspective."}, {"type": "paragraph", "text": "Choice A is incorrect because “as a result” illogically signals that the event described in this sentence occurred as a result or consequence of Zhao’s win. Instead, it occurred before Zhao was named best director and puts Zhao’s win in perspective. Choice C is incorrect because “however” illogically signals that the event described in this sentence occurred in spite of or in contrast to Zhao’s win. Instead, it occurred before Zhao was named best director and puts Zhao’s win in perspective. Choice D is incorrect because “likewise” illogically signals that this sentence merely adds a second, similar piece of information to the information about Zhao’s win. Instead, the fact that only one other woman had won the award before puts Zhao’s win in perspective."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Expression of Ideas'), 'medium', 'source', 'approved', 29, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text with the most logical transition?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice B is the best answer. “Hence” correctly signals that the claim in this sentence regarding extraterrestrial material follows logically from the information in the previous sentences. The previous sentences establish that siderophile elements in the mantle are more abundant than predicted in the core- differentiation model. This sentence claims, logically, that these elements came from extraterrestrial material that accreted to Earth after core differentiation."}, {"type": "paragraph", "text": "Choice A is incorrect because “that said” illogically signals that the information in this sentence regarding extraterrestrial material is an exception to the previous information about siderophiles’ abundance in the mantle. Instead, it is a new claim that follows logically from the previous information. Choice C is incorrect because “for example” illogically signals that the information in this sentence regarding extraterrestrial material exemplifies the previous information about siderophiles’ abundance in the mantle. Instead, it is a new claim that follows logically from the previous information. Choice D is incorrect because “likewise” illogically signals that the information in this sentence regarding extraterrestrial material is merely similar to the previous information about siderophiles’ abundance in the mantle. Instead, it is a new claim that follows logically from the previous information."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Expression of Ideas'), 'medium', 'source', 'approved', 30, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice most effectively uses relevant information from the notes to accomplish this goal?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice B is the best answer. The sentence presents the study, describing it as a 2013 analysis of Quanhucun cat bone fragments, and its conclusions, indicating what the analysis suggests about cat domestication in Quanhucun."}, {"type": "paragraph", "text": "Choice A is incorrect because the sentence focuses on the study’s methodology; it doesn’t present conclusions from the study. Choice C is incorrect. While the sentence provides a general overview of the study, it doesn’t present conclusions from the study. Choice D is incorrect. The sentence describes a finding from the study; it doesn’t present conclusions from the study."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 31, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice most effectively uses relevant information from the notes to accomplish this goal?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice C is the best answer. The sentence emphasizes a difference between the portraits, noting that one is a painting and the other is a drawing."}, {"type": "paragraph", "text": "Choice A is incorrect. The sentence emphasizes a similarity between the two portraits rather than a difference. Choice B is incorrect. The sentence makes a generalization about Enriquez’s portraits; it doesn’t emphasize a difference between the portraits of Jimenez and Anaya. Choice D is incorrect. While the sentence notes a difference between Jimenez and Anaya, it doesn’t emphasize a difference between, or even mention, their portraits."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 32, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice most effectively uses relevant information from the notes to accomplish this goal?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice C is the best answer. The sentence emphasizes both the duration (the length of time) and the purpose of Cohen’s and Rodrigues’s work by noting that the women have been working since 2003 to preserve Gullah culture."}, {"type": "paragraph", "text": "Choice A is incorrect. While the sentence emphasizes what visitors to Cohen’s and Rodrigues’s museums can learn, it doesn’t mention the duration or purpose of the women’s work. Choice B is incorrect. While the sentence emphasizes the purpose of Cohen’s and Rodrigues’s work, it doesn’t mention the duration of that work (the length of time the women have been working to preserve Gullah culture)."}, {"type": "paragraph", "text": "Choice D is incorrect. While the sentence emphasizes where and when Gullah culture developed, it doesn’t mention the duration or purpose of Cohen’s and Rodrigues’s work."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 33, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text with the most logical and precise word or phrase?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice A is the best answer because it most logically completes the text’s discussion of the writing system created by Sequoyah. In this context, “widespread” means widely accepted or practiced. The text indicates that because Sequoyah’s script accurately represented the spoken sounds of the Cherokee language and was easy to learn, nearly all Cherokee people were able to read and write it soon after it was created. This context demonstrates that the script was widely used by the Cherokee people."}, {"type": "paragraph", "text": "Choice B is incorrect. In this context, “careful” would mean exercised with care and attentive concern. Although the work of creating a writing system likely involved great care, the text indicates that the system was “easy to learn,” which conflicts with the idea that using this system requires a noteworthy amount of care. Choice C is incorrect because in this context “unintended” means not deliberate. The idea that using Sequoyah’s script was unintentional conflicts directly with the claim that it was easy to learn and used by “over 90% of the Cherokee people” by 1830. In fact, because one had to learn this system, it’s not clear how one could use it unintentionally. Choice D is incorrect because in this context “infrequent” means rare or not occurring often, which conflicts directly with the claim that “over 90% of the Cherokee people” were using Sequoyah’s script by 1830."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Craft and Structure'), 'medium', 'source', 'approved', 1, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text with the most logical and precise word or phrase?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice A is the best answer because it most logically completes the text’s discussion of diaphragm contractions and hiccups. In this context, “involuntarily” means done without any control, or by reflex. The text explains that when a person’s diaphragm contracts and results in hiccups (which may be important for infants), those muscle contractions are “uncontrollable.” This context indicates that the diaphragm contractions occur without the person’s control."}, {"type": "paragraph", "text": "Choice B is incorrect because the text indicates that researchers haven’t determined exactly why people hiccup, suggesting that it isn’t known that the uncontrollable muscle contractions generally occur “beneficially,” or with a good or helpful effect—even if one neuroscientist has found that it’s possible hiccups play an important positive role for a specific group of people (infants). Choice C is incorrect because the text describes the diaphragm contractions that result in hiccups as “uncontrollable,” or happening without the person’s control, so it wouldn’t make sense to describe them as occurring “strenuously,” or in a way that requires great effort or energy. Choice D is incorrect because nothing in the text indicates that the diaphragm contractions resulting in hiccups occur “smoothly,” or evenly and continuously. The text doesn’t describe the quality of the muscle contractions beyond stating that they are “uncontrollable.”"}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Craft and Structure'), 'medium', 'source', 'approved', 2, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text with the most logical and precise word or phrase?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice D is the best answer because it most logically completes the text’s discussion of the location of the province of Xoconochco within the Aztec Empire. As used in this context, “peripheral” means situated toward the outer bounds rather than the center. The text indicates that Xoconochco was located on a coast, hundreds of kilometers away from the capital of the Aztec Empire. The text also states that trade between the province and the capital required “a long overland journey.” This context suggests that Xoconochco was situated toward an edge of the empire’s territory rather than near its center."}, {"type": "paragraph", "text": "Choice A is incorrect because it wouldn’t make sense in context to refer to Xoconochco’s location within the Aztec Empire as “unobtrusive,” or not blatant or undesirably prominent; it’s not clear how a province’s physical location would or wouldn’t be blatant. Instead of focusing on how noticeable Xoconochco’s location was, the text emphasizes the province’s distance from the capital of the empire, pointing out that because of this distance trade between the two required “a long overland journey.” Choice B is incorrect because the text indicates that the province of Xoconochco was located on a coast far from the capital of the Aztec Empire, not that it was “concealed,” or kept out of sight or hidden from view. Nothing in the text suggests that Xoconochco was actually hidden such that people couldn’t see it, and being hidden wouldn’t necessarily result in trade between the province and the capital requiring “a long overland journey.” Choice C is incorrect because to say that Xoconochco’s location within the Aztec Empire was “approximate” would mean that the location either wasn’t precisely correct or was close to some other location. Neither of these meanings would make sense in context because the text indicates that Xoconochco’s location is known and that it was far from the empire’s capital, so there’s no reason to characterize the location as either not precisely correct or close to another location."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Craft and Structure'), 'medium', 'source', 'approved', 3, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text with the most logical and precise word or phrase?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice A is the best answer because it most logically completes the text’s discussion of the consequences of raising the age at which retirees begin receiving government funds. The text indicates that raising the age for these funds is usually discussed in terms of effects on fund recipients but that Andria Smythe is instead considering the effects on working family members who care for retirees. Smythe notes that raising the age for the funds would increase the length of time retirees are dependent on financial assistance from working family members. This is suggested to have an effect on wealth creation for those workers, and most logically, that effect would be disadvantageous. Thus, “stymie,” which means to prevent or greatly hinder, is the most logical choice in context."}, {"type": "paragraph", "text": "Choice B is incorrect because in this context, “compound” would most nearly mean multiply or greatly enhance. The text indicates that raising the age at which retirees are eligible for government funds will increase the amount of time retirees are dependent on working family members for financial support. This would likely have a negative rather than a positive effect on wealth creation. Choice C is incorrect because in this context, “disparage” would most nearly mean criticize or defame. Nothing in the text suggests that raising the age at which retirees are eligible for government funds would defame wealth creation among working adults. Choice D is incorrect because in this context, “outstrip” would most nearly mean to exceed, and nothing in the text indicates that the financial support provided to retirees would exceed the amount of wealth these workers can create. The text does suggest that workers providing funds to retirees works against those workers’ wealth accumulation, but not that the support to retirees exceeds the workers’ accumulated wealth."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Craft and Structure'), 'medium', 'source', 'approved', 4, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text with the most logical and precise word or phrase?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice A is the best answer because it most logically completes the text’s discussion of political blogs. In this context, “sanguine” means optimistic. The text begins by noting the rise of political blogs with readily identifiable ideological alignments in the early 2000s. The text then indicates that some commentators saw this as a positive development, citing a reason why (their difference from traditional news). Finally, the text goes on to contrast those commentators with others who have a negative opinion of the rise of political blogs (because they increase political polarization among their readers). This context supports the idea that the second group of commentators is less positive than the first: thus, the second group of commentators is less optimistic, or sanguine."}, {"type": "paragraph", "text": "Choice B is incorrect because it would not make sense in this context to describe those commentators who have a negative opinion of political blogs as less “recalcitrant,” or obstinately uncooperative, than those commentators who supported political blogs. Choice C is incorrect because the text gives no indication that those commentators who have a negative opinion of political blogs are less “misanthropic,” or less contemptuous of humankind, than those commentators who have a positive opinion of political blogs— there is no indication in the text that those commentators who like political blogs would be contemptuous of humankind at all. Choice D is incorrect because there is no evidence that those commentators who have a negative opinion of political blogs are less “earnest,” or sincere, than those who have a positive opinion of such blogs—presumably, both groups of commentators hold their beliefs with equal conviction."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Craft and Structure'), 'medium', 'source', 'approved', 5, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice best describes the overall purpose of the text?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice D is the best answer because it most accurately describes the overall purpose of the text. The text indicates that “for as long as he could remember,” Max had “begged” his father to take him to La Reina. This point is later emphasized in the text by indicating that “this summer” his father might “finally take” Max to visit La Reina. Thus, the purpose of the text as a whole is to show how much Max wants to visit La Reina."}, {"type": "paragraph", "text": "Choice A is incorrect. The text does not discuss Papa’s feelings toward Max. Rather, it mentions that Max has long wanted Papa to take him to La Reina and that, unlike Max and some other children, Papa does not believe that La Reina is haunted. Choice B is incorrect. The text mentions that Max is “almost twelve” at the time, which suggests anticipation of growing up rather than refusal to."}, {"type": "paragraph", "text": "Choice C is incorrect. The text indicates that Max hopes to visit La Reina during the current summer, but nothing suggests that Max dislikes summer."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 6, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice best states the main purpose of the text?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice B is the best answer because it most accurately states the main purpose of the text, which is to show that Henry’s mother, Mrs. Higgins, wants Henry to leave her house. In the text, Mrs. Higgins complains that Henry offends all her friends and that they stop coming when he’s also visiting. She then tells him directly, “you mustn’t stay.” The overall exchange conveys Mrs. Higgins’s intention for Henry to leave so as not to drive away her friends with his behavior."}, {"type": "paragraph", "text": "Choice A is incorrect because the text doesn’t indicate what Henry’s mother does when she’s out with her friends. Instead, it focuses on what goes on when Henry and her friends visit her at the same time, indicating that since her friends find Henry’s company disagreeable, she wishes him to leave before they arrive."}, {"type": "paragraph", "text": "Choice C is incorrect because the text doesn’t contain an account of what Henry’s home looks like. The setting is established as the house of Henry’s mother, and the dialogue focuses solely on her wish that Henry should depart before her friends arrive. Choice D is incorrect because the text doesn’t mention how often Henry visits his mother nor does it provide any explanation for why he visits his mother. Instead, it indicates that she thinks her friends dislike Henry and that she therefore wants him to depart before they arrive."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Craft and Structure'), 'medium', 'source', 'approved', 7, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, 0, '{"blocks": [{"type": "paragraph", "text": "Which choice best describes the function of the underlined portion in the text as a whole?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice B is the best answer because it most accurately describes how the underlined portion functions in the text as a whole. The text presents the speaker’s experience of viewing the sea. In the underlined portion, the speaker focuses on the idea that the waves hitting rocks on the shore are a relentless and enduring force: they are constantly pushed back (“ever repulsed”) but always return (“ever rushing on”), as though they have an energy that can’t be overcome (“a life that will not know defeat”)."}, {"type": "paragraph", "text": "Choice A is incorrect. Although the underlined portion characterizes the waves as a relentless force (always “repulsed” but still “rushing on” and never being defeated), the speaker doesn’t suggest that the surroundings are intimidating. Instead, the speaker presents the scene in a positive way, describing the “deep delight” of the “gladsome,” or cheerful, waves and feeling “the heart / Leap joyous” while viewing the sea. Choice C is incorrect because the underlined portion doesn’t suggest that the speaker is ambivalent, or has mixed feelings about, the natural world. Instead, it presents a single view of one part of the immediate surroundings: the speaker characterizes the sea’s waves as an unstoppable force, since they are constantly pushed back but always return (“ever repulsed, yet ever rushing on”). Choice D is incorrect. Although the text later suggests the speaker’s view of her own thoughts by referring to a “clouded brain” and a heart that leaps joyously, this reference neither occurs within the underlined portion nor establishes a clear contrast with the relentless determination of the waves. The underlined portion addresses only the speaker’s view of the waves and doesn’t suggest what her own thoughts might be."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Craft and Structure'), 'medium', 'source', 'approved', 8, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice best states the main idea of the text?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice D is the best answer because it most accurately states the main idea of the text. According to the text, conceptual artists Gins and Arakawa have designed an apartment building that is disorienting because of several unconventional elements, such as uneven kitchen counters and “a door to nowhere.” The text goes on to suggest that there may be benefits to this kind of design because filmmaker Yamaoka lived in the apartment building for four years and reported health benefits. Thus, although the design is impractical, it may improve the well-being of the apartment building’s residents."}, {"type": "paragraph", "text": "Choice A is incorrect. Although the text mentions that Yamaoka lived in the apartment for four years, it doesn’t address how long someone can beneficially live in a home surrounded by fanciful features or whether doing so can be sustained. Choice B is incorrect. Although the text mentions the potential benefits of living in a home with disorienting design features, it doesn’t suggest that this is the most effective method to create a physically stimulating environment."}, {"type": "paragraph", "text": "Choice C is incorrect because the text refers to Yamaoka to support the claim that Gins and Arakawa’s apartment building design may be beneficial, but the text doesn’t indicate that Yamaoka supports the designs of other conceptual artists."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 9, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Based on the text, how does the Lord Chancellor respond to the crowd?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice D is the best answer because it presents a statement about how the Lord Chancellor responds to the crowd that is supported by the text. The text indicates that the people in the crowd are roaring and shouting “Bread!” or “Taxes!” and presents them as not knowing what they really want. The Lord Chancellor’s response is to ask what their shouting means but also to observe that they’re shouting with “unanimity,” or total agreement. Clearly, this isn’t the case, which supports the statement that the Lord Chancellor describes the crowd as being united even though it’s not."}, {"type": "paragraph", "text": "Choice A is incorrect because it isn’t supported by the text. Although the text indicates that the Lord Chancellor asks about the meaning of the crowd’s shouting, it doesn’t suggest that he knows what the crowd really wants. Choice B is incorrect because the text doesn’t suggest that the Lord Chancellor wants to speak to the crowd. Furthermore, the text doesn’t indicate that the crowd wants to hear from the Sub-Warden. Although the crowd roars when asked “Who roar for the Sub-Warden?” it’s unclear what the roaring means. Choice C is incorrect because the text doesn’t suggest that the Lord Chancellor knows of or sympathizes with the crowd’s demands. In addition, the text doesn’t indicate that the crowd’s shouting annoys the Lord Chancellor, just that it causes him to keep repeating “What can it all mean?”"}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 10, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice most effectively uses data from the graph to complete the sentence?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice D is the best answer because it accurately identifies the species with the highest global biomass, the white-tailed deer at approximately 2.7 million metric tons. The graph shows the global biomass for four wild land mammal species with the highest global biomass. The graph indicates that the African bush elephant’s global biomass is about 1.3 million metric tons, the eastern gray kangaroo’s is about 0.6 million metric tons, and the wild boar’s is about 1.9 million metric tons. These values are all lower than the global biomass for the white-tailed deer’s approximately 2.7 million metric tons. Thus, the white-tailed deer is the species with the highest global biomass."}, {"type": "paragraph", "text": "Choice A is incorrect because although the graph indicates that the wild boar has a relatively high global biomass of about 1.9 million metric tons, it is not the species with the highest value. The white-tailed deer is the species with the highest global biomass at about 2.7 million metric tons. Choice B is incorrect because the eastern gray kangaroo has the lowest global biomass value shown on the graph at about 0.6 million metric tons, not the highest global biomass. The white-tailed deer has the highest at about 2.7 million metric tons. Choice C is incorrect because although the African bush elephant has a substantial global biomass of about 1.3 million metric tons, it is not the species with the highest value according to the graph. The white-tailed deer has the highest global biomass at about 2.7 million metric tons."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 11, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice most effectively uses data from the table to support the research team’s conclusion?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice A is the best answer because it most effectively uses data from the table to support the researchers’ conclusion about the harvesting of clamshells by Neanderthals for use as tools. The text explains that Neanderthals used clamshells to make tools and that the sturdiest, and therefore the most desirable, shells for this purpose are found on the seafloor, not on the beach. However, the researchers also concluded that the clamshell tools made from shells from the seafloor are rarer than those made from shells from the beach. Meanwhile the table shows that at each depth, the number of tools made from shells from the beach exceeds the number made from the more desirable shells from the seafloor. The fact that the more desirable shells are less common suggests that it was significantly more difficult to harvest shells from the seafloor than from the beach."}, {"type": "paragraph", "text": "Choice B is incorrect because knowing which depth represents the period of time with the highest Neanderthal population does not help answer the question of why the Neanderthals consistently made more tools from the less desirable shells from the beach than they made from the more desirable shells from the seafloor."}, {"type": "paragraph", "text": "Choice C is incorrect because it claims that the beach shells are more durable than the seafloor shells, which contradicts the text’s description of shells from the seafloor as smoother and sturdier than shells from the beach. Choice D is incorrect because knowing which depth has the most artifacts or whether the clam population fluctuated does not help explain why tools made from the less desirable shells from the beach outnumber tools made from the more desirable shells from the seafloor."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 12, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice best describes data from the graph that support Taylor and colleagues’ conclusion?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice B is the best answer because it describes data from the graph that support Taylor and colleagues’ conclusion that spray coating holds promise for improving the power conversion efficiency of ETLs in perovskite solar cells. The text explains that perovskite solar cells’ efficiency at converting light into electricity is diminished by their electron transport layer (ETL), which is applied through spin coating, but that Taylor’s team devised a new spray coating method for applying the ETL that improves its power conversion efficiency. The graph displays data on the power conversion efficiency of solar cells in tests conducted by Taylor’s team, with bars for both the highest- and lowest-performing ETLs in two data categories: spray coating and spin coating. According to the graph, the lowest-performing ETL applied through spray coating had a power conversion efficiency of between 14% and 16%, while the highest-performing ETL applied through spin coating had a power conversion efficiency of less than 14%. These data confirm that ETLs applied through novel spray coating are more efficient than those applied though traditional spin coating. Thus, the data support Taylor and colleagues’ conclusion about spray coating’s potential value."}, {"type": "paragraph", "text": "Choice A is incorrect. Although this claim correctly describes the data in the graph by stating that both the lowest-performing ETL applied through spin coating and the lowest- performing ETL applied through spray coating had a power conversion efficiency greater than 10%, this relationship in the data doesn’t support or relate to Taylor and colleagues’ conclusion that spray coating promises greater efficiency for solar cells than traditional spin coating does."}, {"type": "paragraph", "text": "Choice C is incorrect. This claim does address the greater power conversion efficiency of the highest-performing ETL applied through spray coating, compared with the highest-performing ETL applied through spin coating. However, it also incorrectly cites the value for the efficiency of the highest- performing ETL applied through spray coating as approximately 13%, instead of a value between 14% and 16%, and the value for the efficiency of the highest- performing ETL applied through spin coating as approximately 11%, instead of a value between 12% and 14%, as shown in the graph. Choice D is incorrect because Taylor and colleagues’ conclusion is based on the difference in the power conversion efficiency of ETLs applied through spray coating and that of ETLs applied through spin coating, not on the difference between the highest- and lowest-performing ETLs applied through just spray coating."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 13, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice most effectively uses data from the table to complete the statement?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice A is the best answer because it presents data from the table that most effectively complete the statement about the rates at which employment shifted in France and the United States. The text states that over the last two hundred years employment in the agricultural sector has declined while employment in the service sector has risen in both France and the US, and the data from the table reflect these trends. The text asserts, however, that the transition from agriculture to services “happened at very different rates in the two countries.” This assertion is best supported by a comparison of data from 1900 and 1950: the table shows that in those years, employment in agriculture went from 43% to 32% in France (a decline of 11 percentage points) and from 41% to 14% in the US (a decline of 27 percentage points), and that employment in services went from 28% to 35% in France (an increase of 7 percentage points) and from 31% to 53% in the US (an increase of 22 percentage points). In other words, the rate of change was greater in the US than in France for both sectors."}, {"type": "paragraph", "text": "Choice B is incorrect because comparing the data for 1800 and 2012 would suggest a similar rate of change in the two countries, not very different rates: employment in agriculture went from 64% in 1800 to 3% in 2012 in France, which is close to the change from 68% in 1800 to 2% in 2012 in the US, while employment in services went from 14% in 1800 to 76% in 2012 in France, which is close to the change from 13% in 1800 to 80% in 2012 in the US. Choice C is incorrect because comparing the data for 1900 and 2012 would suggest a similar rate of change in the two countries rather than very different rates: employment in agriculture went from 43% in 1900 to 3% in 2012 in France, which is close to the change from 41% in 1900 to 2% in 2012 in the US, while employment in services went from 28% in 1900 to 76% in 2012 in France, which is close to the change from 31% in 1900 to 80% in 2012 in the US. Choice D is incorrect because comparing the data for 1800 and 1900 would suggest a similar rate of change in the two countries, not very different rates: employment in agriculture went from 64% in 1800 to 43% in 1900 in France, which is fairly close to the change from 68% in 1800 to 41% in 1900 in the US, while employment in services went from 14% in 1800 to 28% in 1900 in France, which is close to the change from 13% in 1800 to 31% in 1900 in the US."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 14, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which finding, if true, would most directly support Shcherbakova and colleagues’ claim?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice D is the best answer because it presents a finding that, if true, would support Shcherbakova and colleagues’ claim that the outcome of their study is inconsistent with the linguistic niche hypothesis (LNH). The text explains that the LNH holds that there is an inverse relationship between the prevalence of non- native speakers of a language (exotericity) and the grammatical complexity of that language—that is, that as the number of non-native speakers increases, grammatical complexity decreases, and vice versa. According to the text, Shcherbakova and colleagues focused on two positive indications of grammatical complexity—fusion and informativity—and analyzed their occurrence in over 1,300 languages. If the researchers found a slightly positive correlation between fusion and exotericity and between informativity and exotericity—meaning that to some extent, grammatical complexity increases as the number of non-native speakers of a language increases—their outcome would not be consistent with the assumption that exotericity and grammatical complexity are inversely related (the LNH)."}, {"type": "paragraph", "text": "Choice A is incorrect because it wouldn’t be possible to say that a finding of a slightly negative correlation between grammatical complexity and both fusion and informativity is inconsistent or consistent with the LNH, since the finding would address only grammatical complexity (given that fusion and informativity are aspects of grammatical complexity) and wouldn’t move beyond that factor to address its relationship to the prevalence of non-native speakers of a language (exotericity), which is the relationship the LNH focuses on. Choice B is incorrect because a finding of a slightly negative correlation between grammatical complexity and the prevalence of non-native speakers of a language (exotericity)—meaning that as the number of non-native speakers increases, grammatical complexity somewhat decreases, and vice versa—would be consistent, not inconsistent, with the LNH, since the text indicates that according to the LNH, there is an inverse relationship between grammatical complexity and exotericity; a negative correlation reflects an inverse relationship. Choice C is incorrect because it wouldn’t be possible to say that a finding of a slightly positive correlation between grammatical complexity and fusion is inconsistent or consistent with the LNH, since the finding would address only grammatical complexity (given that fusion is a positive indication of grammatical complexity) and wouldn’t move beyond that factor to address its relationship to the prevalence of non-native speakers of a language (exotericity), which is the relationship the LNH focuses on."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 15, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice most logically completes the text?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice A is the best answer because it most logically completes the text’s discussion of the evidence found in Queen Merneith’s tomb. The text begins by mentioning archaeologists’ efforts to excavate the tomb of Queen Merneith, the wife of a pharaoh who some scholars think was actually the first female pharaoh. The text states that a tablet discovered in her tomb suggests she “was in charge of the country’s treasury and other central offices,” which supports the idea that she had an important role in Egypt’s government."}, {"type": "paragraph", "text": "Choice B is incorrect because since the text explicitly states that Merneith’s husband was a First Dynasty pharaoh, it can be inferred that she lived during the First Dynasty, not after it. Choice C is incorrect because the text does not provide any evidence that Merneith traveled beyond Egypt’s borders often. The text is focused on the archaeological discovery in her tomb and the implications about her potential role as a ruler in Egypt but does not mention anything about her traveling habits. Choice D is incorrect because the text does not mention anything about Merneith creating a new form of writing in Egypt. The text discusses the discovery of a tablet with writing suggesting her governmental role but does not imply that this writing represented a new form created by Merneith."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 16, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice most logically completes the text?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice A is the best answer because it presents the conclusion that most logically follows from the text’s discussion of the study of capuchin monkeys’ cognitive abilities. The text explains that the study failed to distinguish between outcomes for the tasks performed by the capuchin monkeys, such that simpler tasks requiring less dexterity, or skill, were judged by the same criteria as tasks that demanded more dexterity. Because the study didn’t account for this discrepancy, the researchers might have assumed that observed differences in performance were due to the abilities of the monkeys rather than the complexity of the tasks. In other words, the results may suggest cognitive differences among the monkeys even though such differences may not really exist."}, {"type": "paragraph", "text": "Choice B is incorrect because the text focuses on the fact that the tasks assigned to the capuchin monkeys in the study varied in difficulty and that the variety wasn’t taken into consideration. The text doesn’t suggest that the capuchin monkeys couldn’t perform certain tasks, just that some tasks were more difficult to do. Choice C is incorrect because the text doesn’t suggest that the study’s results are indicative of the abilities of capuchin monkeys but not of other monkey species; in fact, the text suggests that the results may not even be an accurate reflection of capuchin monkeys’ abilities. Choice D is incorrect because the text doesn’t indicate that the researchers compared results for artificial tasks with those for tasks encountered in the wild, although the tasks described in the text—sliding a panel and putting a straw in a bottle—are presumably artificial."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 17, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text so that it conforms to the conventions of Standard English?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice A is the best answer. The convention being tested is pronoun-antecedent agreement. The plural pronoun “they” agrees in number with the plural antecedent “customers.”"}, {"type": "paragraph", "text": "Choice B is incorrect because the singular pronoun “one” doesn’t agree in number with the plural antecedent “customers.” Choice C is incorrect because the second person pronoun “you” isn’t conventional as a substitute for “customers.” It suggests that the audience (“you”) is the customer. Choice D is incorrect because the singular pronoun “it” doesn’t agree in number with the plural antecedent “customers.”"}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Standard English Conventions'), 'medium', 'source', 'approved', 18, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text so that it conforms to the conventions of Standard English?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice D is the best answer. The convention being tested is end-of-sentence punctuation. This choice correctly uses a question mark to punctuate the interrogative clause “could the blueberries thrive,” which asks a direct question at the end of the sentence."}, {"type": "paragraph", "text": "Choice A is incorrect because a period can’t be used in this way to punctuate an interrogative clause, such as “could the blueberries thrive,” at the end of a sentence. Choice B is incorrect because the context requires an interrogative clause. The declarative clause “the blueberries could thrive” incorrectly indicates that it was known that the blueberries could thrive in alkaline soil, whereas Michel had yet to find this out. Choice C is incorrect because a question mark can’t be used in this way to punctuate a declarative clause, such as “the blueberries could thrive,” at the end of a sentence."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Standard English Conventions'), 'medium', 'source', 'approved', 19, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text so that it conforms to the conventions of Standard English?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice B is the best answer. The convention being tested is the use of verbs to express tense in a sentence. In this choice, the present tense verb “reach” is consistent with the present tense verbs “travel” and “are diverted” used to describe how atoms move through the synchrotron."}, {"type": "paragraph", "text": "Choice A is incorrect because the future tense verb “will reach” is inconsistent with the present tense verbs used to describe how atoms move through the synchrotron. Though the atoms’ movement is a recurring action and “will reach” can also be used to indicate a habitual or recurring action, it creates a logical inconsistency in this sentence when paired with the present tense verbs “travel” and “are diverted.” Choice C is incorrect because the past perfect tense verb “had reached” is inconsistent with the present tense verbs used to describe how atoms move through the synchrotron. Choice D is incorrect because the present progressive tense verb “are reaching” is inconsistent with the present tense verbs used to describe how atoms move through the synchrotron. While both verbs occur in the present, the present progressive tense suggests that the action is currently in progress. This creates a logical inconsistency when paired with the present tense verbs “travel” and “are diverted,” which offer a general description of the tendencies of the atoms’ movement, rather than a description of an action that is currently in progress."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Standard English Conventions'), 'medium', 'source', 'approved', 20, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text so that it conforms to the conventions of Standard English?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice D is the best answer. The convention being tested is the use of verbs to express tense. In this choice, the present tense verb “is,” used in conjunction with the word “today,” correctly indicates that Paik is currently considered the first video artist."}, {"type": "paragraph", "text": "Choice A is incorrect because the future tense verb “will be” doesn’t indicate that Paik is currently considered the first video artist. Choice B is incorrect because the past perfect tense verb “had been” doesn’t indicate that Paik is currently considered the first video artist. Choice C is incorrect because the past tense verb “was” doesn’t indicate that Paik is currently considered the first video artist."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Standard English Conventions'), 'medium', 'source', 'approved', 21, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text so that it conforms to the conventions of Standard English?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice C is the best answer. The convention being tested is subject-verb agreement. The singular verb “outlines” agrees in number with the singular subject “document.”"}, {"type": "paragraph", "text": "Choice A is incorrect because the plural verb “have outlined” doesn’t agree in number with the singular subject “document.” Choice B is incorrect because the plural verb “were outlining” doesn’t agree in number with the singular subject “document.” Choice D is incorrect because the plural verb “outline” doesn’t agree in number with the singular subject “document.”"}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Standard English Conventions'), 'medium', 'source', 'approved', 22, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text so that it conforms to the conventions of Standard English?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice A is the best answer. The convention being tested is the use of punctuation within a sentence. In this choice, the colon correctly introduces the series of goals held by the 1919 Inter-Allied Women’s Conference."}, {"type": "paragraph", "text": "Choice B is incorrect because placing a period after “threefold” results in a rhetorically unacceptable sentence fragment beginning with “To.” Choice C is incorrect because it results in a run-on sentence. The main clause (“The conference’s goals were threefold”) and the series supplement (“to…rights”) are fused without punctuation. Choice D is incorrect because a semicolon can’t be used in this way to introduce a series. A semicolon is conventionally used to join two main clauses, whereas a colon is conventionally used to introduce a series, making the colon the better choice in this context."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Standard English Conventions'), 'medium', 'source', 'approved', 23, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text so that it conforms to the conventions of Standard English?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice D is the best answer. The convention being tested is subject-verb agreement. The singular verb “is credited” agrees in number with the singular subject “mathematician Grigori Perelman.”"}, {"type": "paragraph", "text": "Choice A is incorrect because the plural verb “are credited” doesn’t agree in number with the singular subject “mathematician Grigori Perelman.” Choice B is incorrect because the plural verb “have been credited” doesn’t agree in number with the singular subject “mathematician Grigori Perelman.” Choice C is incorrect because the plural verb “are being credited” doesn’t agree in number with the singular subject “mathematician Grigori Perelman.”"}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Standard English Conventions'), 'medium', 'source', 'approved', 24, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text so that it conforms to the conventions of Standard English?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice A is the best answer. The convention being tested is colon use within a sentence. A colon used in this way introduces information that illustrates or explains information that has come before it. In this case, the colon introduces the following explanation of why some roundworms in the Southern Hemisphere move in the opposite direction of Earth’s magnetic field."}, {"type": "paragraph", "text": "Choice B is incorrect because it results in a comma splice. A comma can’t be used in this way to join two long independent clauses (“Researchers…food” and “in… sources”) such as these. Choice C is incorrect because it results in a run-on sentence. The two clauses (“Researchers…food” and “in…sources”) are fused without punctuation. Furthermore, the conjunction “while” fails to indicate that what follows is an explanation of why some roundworms in the Southern Hemisphere move in the opposite direction of Earth’s magnetic field. Choice D is incorrect because it results in a run-on sentence. The two clauses (“Researchers… food” and “in…sources”) are fused without punctuation and/or a conjunction."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Standard English Conventions'), 'medium', 'source', 'approved', 25, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text with the most logical transition?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice A is the best answer. “For instance” logically signals that the information in this sentence—that larch trees lose their needles every fall—is an example supporting the claim in the previous sentence (that not all conifer species keep their leaves or needles year-round)."}, {"type": "paragraph", "text": "Choice B is incorrect because “nevertheless” illogically signals that the information in this sentence is true in spite of the claim about conifer species in the previous sentence. Instead, it’s an example supporting that claim. Choice C is incorrect because “meanwhile” illogically signals that the information in this sentence is separate from (while occurring simultaneously with) the claim about conifer species in the previous sentence. Instead, it’s an example supporting that claim. Choice D is incorrect because “in addition” illogically signals that the information in this sentence is merely an additional fact related to the claim about conifer species in the previous sentence. Instead, it’s an example supporting that claim."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Expression of Ideas'), 'medium', 'source', 'approved', 26, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text with the most logical transition?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice B is the best answer. “Next” logically signals that the action described in this sentence—Konkoly recording participants’ eye movements—is the next step in Konkoly’s experiment."}, {"type": "paragraph", "text": "Choice A is incorrect because “specifically” illogically signals that this sentence specifies or elaborates on an aspect of the action described in the previous sentence. Instead, it describes the next step in Konkoly’s experiment. Choice C is incorrect because “for instance” illogically signals that the action described in this sentence is an example of the action described in the previous sentence. Instead, it is the next step in Konkoly’s experiment. Choice D is incorrect because “in sum” illogically signals that this sentence summarizes or concludes the action described in the previous sentence. Instead, it describes the next step in Konkoly’s experiment."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Expression of Ideas'), 'medium', 'source', 'approved', 27, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text with the most logical transition?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice D is the best answer. “Specifically” logically signals that the information in this sentence about Sauer’s argument—that, according to Sauer, cultures play a role in their own development, as opposed to being shaped solely by natural surroundings—provides specific, precise details elaborating on the more general information in the previous sentence about how Sauer challenged prevailing views about how natural landscapes influence human cultures."}, {"type": "paragraph", "text": "Choice A is incorrect because “similarly” illogically signals that the information in this sentence about Sauer’s argument is similar to, but separate from, the more general information in the previous sentence. Instead, it provides specific, precise details elaborating on that information. Choice B is incorrect because “finally” illogically signals that the information in this sentence about Sauer’s argument indicates a last step in a process or a concluding summary. Instead, it provides specific, precise details elaborating on the general information in the previous sentence. Choice C is incorrect because “therefore” illogically signals that the information in this sentence about Sauer’s argument is a result of the more general information in the previous sentence. Instead, it provides specific, precise details elaborating on that information."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Expression of Ideas'), 'medium', 'source', 'approved', 28, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text with the most logical transition?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice A is the best answer. “Fittingly” logically signals that the naming of an unprecedented radiocarbon surge for Fusa Miyake is appropriate to the situation, since Miyake is the person who identified the surge (through her Yaku Island tree-ring analysis)."}, {"type": "paragraph", "text": "Choice B is incorrect because “similarly” illogically signals that the information in this sentence is similar to the previous information about Miyake’s identification of a massive radiation burst through tree-ring analysis. Instead, the naming of the event for its discoverer is a fitting and appropriate outcome. Choice C is incorrect because “however” illogically signals that the information in this sentence contrasts with the previous information about Miyake’s identification of a massive radiation burst through tree-ring analysis. Instead, the naming of the event for its discoverer is a fitting and appropriate outcome. Choice D is incorrect because “in other words” illogically signals that the information in this sentence is a paraphrase or restatement of the previous information about Miyake’s identification of a massive radiation burst through tree-ring analysis. Instead, the naming of the event for its discoverer is a fitting and appropriate outcome."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Expression of Ideas'), 'medium', 'source', 'approved', 29, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text with the most logical transition?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice D is the best answer. “Increasingly” logically signals that the claim in this sentence— that mathematicians are collaborating with their peers—marks a change relative to what was traditionally done. As the previous sentence explains, while mathematicians may have traditionally worked alone, evidence points to a shift in the opposite direction. The claim describes the shift: a rise in collaboration."}, {"type": "paragraph", "text": "Choice A is incorrect because “similarly” illogically signals that the claim in this sentence is similar to, but separate from, the previous claim about the shift away from mathematicians working alone. Instead, the claim about the rise in collaboration elaborates on the previous claim, describing the shift. Choice B is incorrect because “for this reason” illogically signals that the claim in this sentence is caused by the previous claim about the shift away from mathematicians working alone. Instead, the claim about the rise in collaboration elaborates on the previous claim, describing the shift. Choice C is incorrect because “furthermore” illogically signals that the claim in this sentence is in addition to the previous claim about the shift away from mathematicians working alone. Instead, the claim about the rise in collaboration elaborates on the previous claim, describing the shift."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Expression of Ideas'), 'medium', 'source', 'approved', 30, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice most effectively uses relevant information from the notes to accomplish this goal?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice D is the best answer. The sentence uses “both” to emphasize a thematic similarity between Tan’s two books, noting that both Tales from Outer Suburbia and Tales from the Inner City describe surreal events occurring in otherwise ordinary places."}, {"type": "paragraph", "text": "Choice A is incorrect. The sentence emphasizes a difference (one contains fewer stories than the other), not a similarity, between the two books. Choice B is incorrect. The sentence indicates that Tan’s books were published ten years apart; it doesn’t emphasize a similarity between the two books. Choice C is incorrect. The sentence uses “unlike” to emphasize a difference between Tales from Outer Suburbia and Tales from the Inner City; it doesn’t emphasize a similarity between the two books."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 31, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice most effectively uses relevant information from the notes to accomplish this goal?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice A is the best answer. Noting that “guerdon” is of Anglo-French origin and “Laodicean” is of ancient Greek origin, the sentence uses “while” to emphasize a difference in the origins of the two words."}, {"type": "paragraph", "text": "Choice B is incorrect. While the sentence emphasizes two words used in the Scripps National Spelling Bee, it doesn’t emphasize (or mention) the words’ linguistic origins. Choice C is incorrect. While the sentence specifies the linguistic origin of one word used in the Scripps National Spelling Bee, it doesn’t mention the other word or emphasize a difference in the two words’ origins. Choice D is incorrect. While the sentence makes a generalization about words used in the Scripps National Spelling Bee, it doesn’t emphasize a difference in the words’ origins."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 32, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice most effectively uses relevant information from the notes to accomplish this goal?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice C is the best answer. The sentence emphasizes a similarity between the two paintings, noting that Leutze’s painting (which measures 149 × 255 inches) and Monkman’s painting (which measures 132 × 264 inches) are both very large."}, {"type": "paragraph", "text": "Choice A is incorrect. The sentence mentions that Monkman’s painting was completed in 2019 and Leutze’s was completed in 1851; it doesn’t emphasize a similarity between the two paintings. Choice B is incorrect. While the sentence acknowledges that one painting was inspired by the other, it emphasizes differences between the two paintings; it doesn’t emphasize a similarity between them. Choice D is incorrect. The sentence mentions a difference between the two paintings; it doesn’t emphasize a similarity between them."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 33, 'choice', array[]::text[]) returning id into v_q;
    update public.exams set status = 'published' where id = v_exam;
  end if;
  -- SAT Practice Test 10: Math
  if exists (select 1 from public.exams where slug = 'sat-practice-test-10-math') then
    raise notice 'skipping sat-practice-test-10-math (already imported)';
  else
    select id into v_subject from public.subjects where code = 'sat-math';
    values (v_subject, 'sat-practice-test-10-math', 'SAT Practice Test 10: Math', 'Official SAT Practice Test 10 (College Board), Math: 54 questions in two modules, including student-produced responses. Calculator allowed; 43 minutes per module.', 'full_mock', 'premium', 'draft', 86, 'source', 221, '[[200, 200], [210, 220], [210, 220], [210, 220], [210, 230], [210, 240], [220, 250], [230, 260], [240, 300], [250, 310], [260, 320], [280, 340], [310, 350], [320, 360], [330, 370], [340, 380], [350, 390], [360, 400], [370, 410], [380, 420], [380, 420], [390, 430], [390, 430], [400, 440], [410, 450], [420, 460], [430, 470], [440, 480], [450, 490], [460, 500], [470, 510], [480, 520], [490, 530], [490, 550], [510, 570], [520, 580], [530, 590], [540, 600], [550, 610], [560, 620], [580, 640], [590, 650], [600, 660], [610, 670], [620, 680], [640, 700], [650, 710], [670, 730], [680, 740], [700, 760], [730, 770], [750, 780], [770, 790], [780, 800], [800, 800]]'::jsonb)
    returning id into v_exam;
    values (v_subject, null, null, '{"blocks": [{"type": "image", "src": "/sat/test-10/math-m1-q01.png", "alt": "Figure for question 1", "width": 310}, {"type": "paragraph", "text": "The line graph shows the percent of cars for sale at a used car lot on a given day by model year."}, {"type": "paragraph", "text": "For what model year is the percent of cars for sale the smallest?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "The lowest point on the graph, about $4\\%$, is at $2014$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Problem-Solving and Data Analysis'), 'easy', 'source', 'approved', 1, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "image", "src": "/sat/test-10/math-m1-q02.png", "alt": "Figure for question 2", "width": 262}, {"type": "paragraph", "text": "The graph of a system of linear equations is shown. What is the solution $(x, y)$ to the system?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "The two lines intersect at $(4, -5)$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'easy', 'source', 'approved', 2, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "The total cost, in dollars, to rent a surfboard consists of a $\\$25$ service fee and a $\\$10$ per hour rental fee. A person rents a surfboard for $t$ hours and intends to spend a maximum of $\\$75$ to rent the surfboard. Which inequality represents this situation?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "The cost is the $\\$25$ fee plus $\\$10$ for each of $t$ hours, and it can be at most $\\$75$: $25 + 10t \\le 75$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'easy', 'source', 'approved', 3, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "image", "src": "/sat/test-10/math-m1-q04.png", "alt": "Figure for question 4", "width": 266}, {"type": "paragraph", "text": "The graph shown will be translated up $4$ units. Which of the following will be the resulting graph?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "The vertex $(2, -2)$ moves up $4$ units to $(2, 2)$, and the shape stays the same. Graph A has vertex $(2, 2)$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Advanced Math'), 'easy', 'source', 'approved', 4, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "math", "latex": "s = 40 + 3t"}, {"type": "paragraph", "text": "The equation gives the speed $s$, in miles per hour, of a certain car $t$ seconds after it began to accelerate. What is the speed, in miles per hour, of the car $5$ seconds after it began to accelerate?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$s = 40 + 3(5) = 55$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'easy', 'source', 'approved', 5, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "The function $f$ is defined by $f(x) = x^2 + x + 71$. What is the value of $f(2)$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$f(2) = 4 + 2 + 71 = 77$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Advanced Math'), 'easy', 'source', 'approved', 6, 'spr', array['77']::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "An event planner is planning a party. It costs the event planner a onetime fee of $\\$35$ to rent the venue and $\\$10.25$ per attendee. The event planner has a budget of $\\$300$. What is the greatest number of attendees possible without exceeding the budget?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$35 + 10.25n \\le 300$ gives $10.25n \\le 265$, so $n \\le 25.8\\ldots$. The greatest whole number is $25$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'medium', 'source', 'approved', 7, 'spr', array['25']::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "image", "src": "/sat/test-10/math-m1-q08.png", "alt": "Figure for question 8", "width": 267}, {"type": "paragraph", "text": "The table gives the distribution of votes for a new school mascot and grade level for $80$ students."}, {"type": "paragraph", "text": "If one of these students is selected at random, what is the probability of selecting a student whose vote for new mascot was for a lion?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$20$ of the $80$ students voted for the lion: $\\tfrac{20}{80} = \\tfrac{1}{4}$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Problem-Solving and Data Analysis'), 'easy', 'source', 'approved', 8, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "Triangles $ABC$ and $DEF$ are congruent, where $A$ corresponds to $D$, and $B$ and $E$ are right angles. The measure of angle $A$ is $18^\\circ$. What is the measure of angle $F$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Angle $C = 180 - 90 - 18 = 72^\\circ$, and angle $F$ corresponds to angle $C$, so it is $72^\\circ$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Geometry and Trigonometry'), 'easy', 'source', 'approved', 9, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "If $4x + 2 = 12$, what is the value of $16x + 8$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$16x + 8 = 4(4x + 2) = 4(12) = 48$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'easy', 'source', 'approved', 10, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "Which expression is equivalent to $(m^4q^4z^{-1})(mq^5z^3)$, where $m$, $q$, and $z$ are positive?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Add the exponents of each base: $m^{4+1}q^{4+5}z^{-1+3} = m^5q^9z^2$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Advanced Math'), 'easy', 'source', 'approved', 11, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "An airplane descends from an altitude of $9{,}500$ feet to $5{,}000$ feet at a constant rate of $400$ feet per minute. What type of function best models the relationship between the descending airplane''s altitude and time?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "The altitude falls by the same amount each minute, so the relationship is decreasing linear."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'easy', 'source', 'approved', 12, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "math", "latex": "\\begin{aligned} 3x + 6 &= 4y \\\\ 3x + 4 &= 2y \\end{aligned}"}, {"type": "paragraph", "text": "The solution to the given system of equations is $(x, y)$. What is the value of $y$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Subtract the second equation from the first: $2 = 2y$, so $y = 1$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'medium', 'source', 'approved', 13, 'spr', array['1']::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "The function $f$ is defined by $f(x) = (x - 6)(x - 2)(x + 6)$. In the $xy$-plane, the graph of $y = g(x)$ is the result of translating the graph of $y = f(x)$ up $4$ units. What is the value of $g(0)$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$f(0) = (-6)(-2)(6) = 72$, and translating up $4$ units adds $4$: $g(0) = 76$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Advanced Math'), 'medium', 'source', 'approved', 14, 'spr', array['76']::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "The function $f(w) = 6w^2$ gives the area of a rectangle, in square feet (ft$^2$), if its width is $w$ ft and its length is $6$ times its width. Which of the following is the best interpretation of $f(14) = 1{,}176$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "The input $14$ is the width in feet and the output $1{,}176$ is the area in square feet."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Advanced Math'), 'easy', 'source', 'approved', 15, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "The number of bacteria in a liquid medium doubles every day. There are $44{,}000$ bacteria in the liquid medium at the start of an observation. Which of the following represents the number of bacteria, $y$, in the liquid medium $t$ days after the start of the observation?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Start at $44{,}000$ and multiply by $2$ each day: $y = 44{,}000(2)^t$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Advanced Math'), 'easy', 'source', 'approved', 16, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "table", "header": ["$x$", "$h(x)$"], "rows": [["$0$", "$1.23$"], ["$2$", "$1.54$"], ["$4$", "$1.94$"]]}, {"type": "paragraph", "text": "The table shows the exponential relationship between the number of years, $x$, since Hana started training in pole vault, and the estimated height $h(x)$, in meters, of her best pole vault for that year. Which of the following functions best represents this relationship, where $x \\le 4$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$h(0) = 1.23$ is the initial value, and $\\tfrac{1.54}{1.23} \\approx 1.25 \\approx 1.12^2$, so the yearly growth factor is about $1.12$: $h(x) = 1.23(1.12)^x$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Advanced Math'), 'medium', 'source', 'approved', 17, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "The function $h$ is defined by $h(x) = 4x + 28$. The graph of $y = h(x)$ in the $xy$-plane has an $x$-intercept at $(a, 0)$ and a $y$-intercept at $(0, b)$, where $a$ and $b$ are constants. What is the value of $a + b$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$4a + 28 = 0$ gives $a = -7$, and $b = h(0) = 28$, so $a + b = 21$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'medium', 'source', 'approved', 18, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "math", "latex": "y < 5x + 6"}, {"type": "paragraph", "text": "For which of the following tables are all the values of $x$ and their corresponding values of $y$ solutions to the given inequality?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$5x + 6$ equals $21$, $31$, and $41$ at $x = 3$, $5$, $7$. Only table A has every $y$ strictly less: $17$, $27$, $37$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'medium', 'source', 'approved', 19, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "math", "latex": "\\begin{aligned} y &= 4x + 1 \\\\ 4y &= 15x - 8 \\end{aligned}"}, {"type": "paragraph", "text": "The solution to the given system of equations is $(x, y)$. What is the value of $x - y$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Substitute: $4(4x + 1) = 15x - 8$, so $x = -12$ and $y = -47$. Then $x - y = -12 + 47 = 35$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'medium', 'source', 'approved', 20, 'spr', array['35']::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "A right triangle has legs with lengths of $24$ centimeters and $21$ centimeters. If the length of this triangle''s hypotenuse, in centimeters, can be written in the form $3\\sqrt{d}$, where $d$ is an integer, what is the value of $d$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "The hypotenuse is $\\sqrt{576 + 441} = \\sqrt{1{,}017} = \\sqrt{9 \\cdot 113} = 3\\sqrt{113}$, so $d = 113$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Geometry and Trigonometry'), 'medium', 'source', 'approved', 21, 'spr', array['113']::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "The floor of a ballroom has an area of $600$ square meters. An architect creates a scale model of the floor of the ballroom, where the length of each side of the model is $\\dfrac{1}{10}$ times the length of the corresponding side of the actual floor of the ballroom. What is the area, in square meters, of the scale model?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Lengths scale by $\\tfrac{1}{10}$, so areas scale by $\\tfrac{1}{100}$: $\\tfrac{600}{100} = 6$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Geometry and Trigonometry'), 'medium', 'source', 'approved', 22, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "Which of the following equations represents a circle in the $xy$-plane that intersects the $y$-axis at exactly one point?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Each circle has radius $4$. A circle touches the $y$-axis at exactly one point when its center is $4$ units from the axis, that is, its $x$-coordinate is $\\pm 4$. That is choice C, centered at $(4, 9)$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Geometry and Trigonometry'), 'hard', 'source', 'approved', 23, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "In triangles $ABC$ and $DEF$, angles $B$ and $E$ each have measure $27^\\circ$ and angles $C$ and $F$ each have measure $41^\\circ$. Which additional piece of information is sufficient to determine whether triangle $ABC$ is congruent to triangle $DEF$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Two pairs of equal angles make the triangles similar. They are congruent only if a pair of corresponding sides is equal, so we need to compare the lengths of corresponding sides such as $BC$ and $EF$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Geometry and Trigonometry'), 'hard', 'source', 'approved', 24, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "The result of increasing the quantity $x$ by $1{,}800\\%$ is $684$. What is the value of $x$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Increasing by $1{,}800\\%$ multiplies by $1 + 18 = 19$: $19x = 684$, so $x = 36$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Problem-Solving and Data Analysis'), 'medium', 'source', 'approved', 25, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "A window repair specialist charges $\\$220$ for the first two hours of repair plus an hourly fee for each additional hour. The total cost for $5$ hours of repair is $\\$400$. Which function $f$ gives the total cost, in dollars, for $x$ hours of repair, where $x \\ge 2$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "The $3$ extra hours cost $400 - 220 = 180$ dollars, or $\\$60$ per hour. So $f(x) = 220 + 60(x - 2) = 60x + 100$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'hard', 'source', 'approved', 26, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "math", "latex": "x(x + 1) - 56 = 4x(x - 7)"}, {"type": "paragraph", "text": "What is the sum of the solutions to the given equation?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Expand: $x^2 + x - 56 = 4x^2 - 28x$, so $3x^2 - 29x + 56 = 0$. The sum of the solutions is $\\tfrac{29}{3}$ (about $9.667$)."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Advanced Math'), 'hard', 'source', 'approved', 27, 'spr', array['29/3', '9.666', '9.667']::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "An object''s speed is $64$ yards per second. What is the object''s speed, in **feet** per second? ($1$ yard $= 3$ feet)"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$64 \\times 3 = 192$ feet per second."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Problem-Solving and Data Analysis'), 'easy', 'source', 'approved', 1, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "image", "src": "/sat/test-10/math-m2-q02.png", "alt": "Figure for question 2", "width": 256}, {"type": "paragraph", "text": "The scatterplot shows the relationship between two variables, $x$ and $y$. A line of best fit is also shown."}, {"type": "paragraph", "text": "Which of the following equations best represents the line of best fit shown?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "The line rises (positive slope) and crosses the $y$-axis above $0$, near $3.4$: $y = x + 3.4$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Problem-Solving and Data Analysis'), 'easy', 'source', 'approved', 2, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "image", "src": "/sat/test-10/math-m2-q03.png", "alt": "Figure for question 3", "width": 262}, {"type": "paragraph", "text": "The graph shows the linear relationship between $x$ and $y$. Which table gives three values of $x$ and their corresponding values of $y$ for this relationship?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "The line passes through $(0, -5)$, $(1, -3)$, and $(2, -1)$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'easy', 'source', 'approved', 3, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "What is the perimeter, in inches, of a rectangle with a length of $4$ inches and a width of $9$ inches?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$2(4 + 9) = 26$ inches."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Geometry and Trigonometry'), 'easy', 'source', 'approved', 4, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "math", "latex": "7m = 2(n + p)"}, {"type": "paragraph", "text": "The given equation relates the positive numbers $m$, $n$, and $p$. Which equation correctly gives $m$ in terms of $n$ and $p$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Divide both sides by $7$: $m = \\dfrac{2(n + p)}{7}$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'easy', 'source', 'approved', 5, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "math", "latex": "73, 74, 75, 77, 79, 82, 84, 85, 91"}, {"type": "paragraph", "text": "What is the median of the data shown?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "The $9$ values are in order, so the median is the $5$th value: $79$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Problem-Solving and Data Analysis'), 'easy', 'source', 'approved', 6, 'spr', array['79']::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "The function $f$ is defined by $f(x) = 4x$. For what value of $x$ does $f(x) = 8$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$4x = 8$, so $x = 2$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'easy', 'source', 'approved', 7, 'spr', array['2']::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "Of $300{,}000$ paper clips, $234{,}000$ are size large. What percentage of the paper clips are size large?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$\\dfrac{234{,}000}{300{,}000} = 0.78$, or $78\\%$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Problem-Solving and Data Analysis'), 'easy', 'source', 'approved', 8, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "math", "latex": "f(x) = 8x + 4"}, {"type": "paragraph", "text": "The function $f$ gives the estimated height, in feet, of a willow tree $x$ years after its height was first measured. Which statement is the best interpretation of $4$ in this context?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$f(0) = 4$: when $x = 0$, at the first measurement, the estimated height was $4$ feet."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'easy', 'source', 'approved', 9, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "math", "latex": "\\begin{aligned} y &= 76 \\\\ y &= x^2 - 5 \\end{aligned}"}, {"type": "paragraph", "text": "The graphs of the given equations in the $xy$-plane intersect at the point $(x, y)$. What is a possible value of $x$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$x^2 - 5 = 76$, so $x^2 = 81$ and $x = 9$ or $-9$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Advanced Math'), 'easy', 'source', 'approved', 10, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "Each side of equilateral triangle S is multiplied by a scale factor of $k$ to create equilateral triangle T. The length of each side of triangle T is greater than the length of each side of triangle S. Which of the following could be the value of $k$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "T''s sides are longer only if $k > 1$. Of the choices, only $\\tfrac{29}{28}$ is greater than $1$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Geometry and Trigonometry'), 'easy', 'source', 'approved', 11, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "math", "latex": "66x = 66x"}, {"type": "paragraph", "text": "How many solutions does the given equation have?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Both sides are identical, so every value of $x$ works: infinitely many solutions."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'easy', 'source', 'approved', 12, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "Vivian bought party hats and cupcakes for $\\$71$. Each package of party hats cost $\\$3$, and each cupcake cost $\\$1$. If Vivian bought $10$ packages of party hats, how many cupcakes did she buy?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "The hats cost $10 \\times 3 = 30$ dollars, leaving $71 - 30 = 41$ dollars for $41$ cupcakes."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'easy', 'source', 'approved', 13, 'spr', array['41']::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "The exponential function $g$ is defined by $g(x) = 19 \\cdot a^x$, where $a$ is a positive constant. If $g(3) = 2{,}375$, what is the value of $g(4)$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$19a^3 = 2{,}375$, so $a^3 = 125$ and $a = 5$. Then $g(4) = 19 \\cdot 625 = 11{,}875$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Advanced Math'), 'medium', 'source', 'approved', 14, 'spr', array['11875']::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "In right triangle $RST$, the sum of the measures of angle $R$ and angle $S$ is $90$ degrees. The value of $\\sin(R)$ is $\\dfrac{\\sqrt{15}}{4}$. What is the value of $\\cos(S)$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "For complementary angles, the cosine of one equals the sine of the other: $\\cos(S) = \\sin(R) = \\tfrac{\\sqrt{15}}{4}$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Geometry and Trigonometry'), 'medium', 'source', 'approved', 15, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "image", "src": "/sat/test-10/math-m2-q16.png", "alt": "Figure for question 16", "width": 291}, {"type": "paragraph", "text": "The graph shows the relationship between the number of shares of stock from Company A, $x$, and the number of shares of stock from Company B, $y$, that Simone can purchase. Which equation could represent this relationship?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "The line has intercepts $(60, 0)$ and $(0, 40)$. In $8x + 12y = 480$, $y = 0$ gives $x = 60$ and $x = 0$ gives $y = 40$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'medium', 'source', 'approved', 16, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "Which expression is equivalent to $\\dfrac{8x(x - 7) - 3(x - 7)}{2x - 14}$, where $x > 7$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Factor: $\\dfrac{(x - 7)(8x - 3)}{2(x - 7)} = \\dfrac{8x - 3}{2}$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Advanced Math'), 'medium', 'source', 'approved', 17, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "The function $f$ is defined by $f(x) = (-8)(2)^x + 22$. What is the $y$-intercept of the graph of $y = f(x)$ in the $xy$-plane?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$f(0) = -8(1) + 22 = 14$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Advanced Math'), 'medium', 'source', 'approved', 18, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "Keenan made $32$ cups of vegetable broth. Keenan then filled $x$ small jars and $y$ large jars with all the vegetable broth he made. The equation $3x + 5y = 32$ represents this situation. Which is the best interpretation of $5y$ in this context?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Each large jar holds $5$ cups and there are $y$ of them, so $5y$ is the total broth in the large jars."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'medium', 'source', 'approved', 19, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "A circle in the $xy$-plane has a diameter with endpoints $(2, 4)$ and $(2, 14)$. An equation of this circle is $(x - 2)^2 + (y - 9)^2 = r^2$, where $r$ is a positive constant. What is the value of $r$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "The diameter has length $14 - 4 = 10$, so $r = 5$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Geometry and Trigonometry'), 'medium', 'source', 'approved', 20, 'spr', array['5']::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "Line $\\ell$ is defined by $3y + 12x = 5$. Line $n$ is perpendicular to line $\\ell$ in the $xy$-plane. What is the slope of line $n$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Line $\\ell$: $y = -4x + \\tfrac{5}{3}$, slope $-4$. A perpendicular line has slope $\\tfrac{1}{4}$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'medium', 'source', 'approved', 21, 'spr', array['0.25', '1/4']::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "math", "latex": "|-5x + 13| = 73"}, {"type": "paragraph", "text": "What is the sum of the solutions to the given equation?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$-5x + 13 = 73$ gives $x = -12$, and $-5x + 13 = -73$ gives $x = \\tfrac{86}{5}$. The sum is $\\tfrac{86}{5} - 12 = \\tfrac{26}{5}$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'hard', 'source', 'approved', 22, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "For the exponential function $f$, the value of $f(1)$ is $k$, where $k$ is a constant. Which of the following equivalent forms of the function $f$ shows the value of $k$ as the coefficient or the base?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "In $f(x) = 128(1.6)^{x-1}$, $f(1) = 128(1.6)^0 = 128$, which is the coefficient."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Advanced Math'), 'hard', 'source', 'approved', 23, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "math", "latex": "-9x^2 + 30x + c = 0"}, {"type": "paragraph", "text": "In the given equation, $c$ is a constant. The equation has exactly one solution. What is the value of $c$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Exactly one solution means the discriminant is $0$: $30^2 - 4(-9)(c) = 900 + 36c = 0$, so $c = -25$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Advanced Math'), 'hard', 'source', 'approved', 24, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "Which of the following expressions has a factor of $x + 2b$, where $b$ is a positive integer constant?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "If $x + 2b$ is a factor, the expression is $(x + 2b)(3x + 7) = 3x^2 + (7 + 6b)x + 14b$. Then $7 + 6b = 49$ gives the integer $b = 7$; $28$ and $42$ do not give integers, and $7$ gives $b = 0$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Advanced Math'), 'hard', 'source', 'approved', 25, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "image", "src": "/sat/test-10/math-m2-q26.png", "alt": "Figure for question 26", "width": 324}, {"type": "paragraph", "text": "Two data sets of $23$ integers each are summarized in the histograms shown. For each of the histograms, the first interval represents the frequency of integers greater than or equal to $10$, but less than $20$. The second interval represents the frequency of integers greater than or equal to $20$, but less than $30$, and so on. What is the smallest possible difference between the mean of data set A and the mean of data set B?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "The histograms have the same frequencies, but each bar for A is one interval higher. To make the means as close as possible, put A''s values at the bottom of each interval and B''s at the top: each A value is then at least $1$ more than its B partner (for example $20$ versus $19$), so the means differ by at least $1$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Problem-Solving and Data Analysis'), 'hard', 'source', 'approved', 26, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "The perimeter of an equilateral triangle is $624$ centimeters. The height of this triangle is $k\\sqrt{3}$ centimeters, where $k$ is a constant. What is the value of $k$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Each side is $208$, and the height of an equilateral triangle is $\\tfrac{\\sqrt{3}}{2}$ times the side: $104\\sqrt{3}$. So $k = 104$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Geometry and Trigonometry'), 'hard', 'source', 'approved', 27, 'spr', array['104']::text[]) returning id into v_q;
    update public.exams set status = 'published' where id = v_exam;
  end if;
end $sat$;

do $sat$
declare
  v_subject uuid; v_exam uuid; v_section uuid; v_stim uuid; v_q uuid;
begin
  -- SAT Practice Test 11: Reading and Writing
  if exists (select 1 from public.exams where slug = 'sat-practice-test-11-reading-and-writing') then
    raise notice 'skipping sat-practice-test-11-reading-and-writing (already imported)';
  else
    select id into v_subject from public.subjects where code = 'sat-english';
    values (v_subject, 'sat-practice-test-11-reading-and-writing', 'SAT Practice Test 11: Reading and Writing', 'Official SAT Practice Test 11 (College Board), Reading and Writing: 66 questions in two modules, timed as the paper test (39 minutes per module).', 'full_mock', 'premium', 'draft', 78, 'source', 222, '[[200, 200], [210, 220], [210, 220], [210, 220], [210, 220], [210, 230], [220, 240], [220, 240], [220, 250], [230, 260], [230, 270], [240, 280], [250, 290], [250, 300], [260, 310], [270, 320], [270, 330], [290, 330], [300, 340], [310, 350], [320, 360], [330, 370], [340, 380], [340, 380], [350, 390], [360, 400], [360, 400], [370, 410], [380, 420], [390, 430], [390, 430], [400, 440], [410, 450], [420, 460], [430, 470], [440, 480], [450, 490], [450, 490], [460, 500], [470, 510], [470, 530], [480, 540], [490, 550], [500, 560], [510, 570], [520, 580], [530, 590], [540, 600], [560, 620], [570, 630], [580, 640], [590, 650], [600, 660], [620, 680], [630, 690], [640, 700], [660, 700], [680, 720], [690, 730], [700, 740], [710, 750], [720, 760], [730, 770], [740, 780], [760, 780], [780, 800], [800, 800]]'::jsonb)
    returning id into v_exam;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text with the most logical and precise word or phrase?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice A is the best answer because it most logically completes the text’s discussion of Ezra Pound’s poetry. In this context, “comprehend” would mean to understand or grasp the meaning of something. The text describes Pound’s poetry as “dense” and “experimental,” with many references that readers may not understand. The text also states that many readers may not even be able to identify a poem’s subject. This context clearly suggests that readers struggle to understand Pound’s poetry as a result of its complexity and obscure references."}, {"type": "paragraph", "text": "Choice B is incorrect. To say that Pound’s poetry is “hard to dislike” would suggest that people generally like it, but the text doesn’t focus on how likeable or enjoyable the poems are; rather, it focuses on how challenging many readers find it to understand them. Choice C is incorrect. To say that Pound’s poetry is “hard to interrupt” would mean that it is hard to stop or break into it while it’s being read or recited, but the text doesn’t discuss any such breaks; instead, the text focuses on the challenge of understanding the content of Pound’s poems. Choice D is incorrect. In this context, “overlook” would mean look past or fail to notice, so to say that Pound’s poetry is “hard to overlook” would mean that it is very likely to be noticed. The text focuses on the difficulty people have in understanding Pound’s poems when reading them, not how noticeable his poetry is in the first place."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Craft and Structure'), 'medium', 'source', 'approved', 1, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text with the most logical and precise word or phrase?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice C is the best answer because it most logically completes the text’s discussion of Bali’s subak water management system. In this context, “interconnected” would mean joined or linked together. The text describes the various components of the subak system—“terraces, canals, and water temples”—and then states that they are “joined together into a single cohesive unit.” This context indicates that these elements are connected with one another in an integrated system."}, {"type": "paragraph", "text": "Choice A is incorrect because “outmoded” would mean outdated or no longer in use. While the text does indicate that the subak system has “rich cultural, philosophical, and historical significance,” the text doesn’t suggest that the subak system is obsolete or not currently used. Choice B is incorrect because “informal” would suggest that the subak system lacks structure or organization. The text contradicts this by describing a complex system with specific components (“terraces, canals, and water temples”) that are “joined together into a single cohesive unit,” indicating formal organization rather than informality. Choice D is incorrect because “optional” would suggest that the various elements of the subak system are not necessary or required. The text indicates the opposite by stating that these elements are “joined together into a single cohesive unit,” suggesting that each component plays a necessary role in the functioning of the integrated system."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Craft and Structure'), 'medium', 'source', 'approved', 2, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text with the most logical and precise word or phrase?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice D is the best answer because it most logically completes the text’s discussion of Georgi Vladimov’s novel Faithful Ruslan. In this context, “suppress” means to prevent something, such as a book, from being accessed by the public. The text indicates that the novel was circulated secretly within the Soviet Union, a stratagem that was necessary because of the government’s efforts to suppress the book, or prevent it from being circulated and read."}, {"type": "paragraph", "text": "Choice A is incorrect because in this context, “replicate” would mean to copy or reproduce a book, and this meaning wouldn’t make sense in the text’s discussion of Faithful Ruslan. If the Soviet government had attempted to replicate Vladimov’s novel, there would be no reason for copies to circulate “in secret,” since the government would be actively making more copies available, not restricting access. Choice B is incorrect. Although a repressive government might well “critique” a novel, or evaluate it negatively, simply critiquing one wouldn’t necessarily lead to copies of it circulating “in secret.” Instead, the text suggests that the Soviet government took decisive action against Faithful Ruslan that necessitated its underground circulation and did not merely offer criticism of the novel. Choice C is incorrect because “import” means to bring a product, such as a book, into a country from elsewhere. However, the text suggests that copies of Faithful Ruslan were already present in the Soviet Union and that the government was trying to restrict their circulation rather than increasing access to the novel by importing copies from another country."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Craft and Structure'), 'medium', 'source', 'approved', 3, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text with the most logical and precise word or phrase?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice D is the best answer because it most logically completes the text’s discussion of the initial spread of silk beyond China. In this context, “contradicted” means opposed or challenged. The text indicates that new archaeological evidence about silk use in South Asia has done something to a long-held thought about the initial spread of silk. According to the text, the new evidence reveals that people used silk in South Asia 1,000 years before the second century CE, which directly challenges the previous belief that silk first spread beyond China in the second century CE."}, {"type": "paragraph", "text": "Choice A is incorrect because the text indicates that an archaeological finding about silk use has done something to a long-held thought about the initial spread of silk, and it wouldn’t make sense to suggest that the finding could have “investigated,” or examined, a belief; evidence can’t examine anything. Choice B is incorrect because the text indicates that an archaeological finding about silk use has done something to a long-held thought about the initial spread of silk, and it wouldn’t make sense to suggest that the finding could have “misinterpreted,” or incorrectly understood, a belief; evidence can’t try to understand anything."}, {"type": "paragraph", "text": "Choice C is incorrect. In this context, “anticipated” would mean expected or predicted. The text indicates that a new archaeological finding about silk use has done something to a long-held thought about the initial spread of silk, and a new finding can’t predict a belief that is already established."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Craft and Structure'), 'medium', 'source', 'approved', 4, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text with the most logical and precise word or phrase?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice A is the best answer because it most logically completes the text’s discussion of Scherezade García’s mural Blame It on the Bean: The Power of Coffee. In this context, “unassuming” means ordinary or unremarkable. The text draws a contrast between a “casual description” of the mural’s ordinary location (a coffee shop) and subject matter (three women drinking coffee)—details that would make it seem relatively unambitious—and a characterization of the painting as a “dynamic meditation” on gender and colonialism deserving of “serious attention.” This context suggests that the mural has significant depth and complexity, but a superficial description of it might make the mural seem ordinary and unremarkable—that is, unassuming."}, {"type": "paragraph", "text": "Choice B is incorrect because in this context, “shrewd” would mean clever or astute, and there’s nothing in the text to suggest that a casual yet misleading description that only mentions the apparent simplicity of the mural’s location and subject matter would make the mural seem particularly clever or astute. Though it’s possible that the text’s assertion that the mural is a “complex, dynamic meditation” demanding “serious attention” might convey the idea that it’s a particularly clever or astute—that is, shrewd—artwork, the text wouldn’t suggest that a casual description that fails to account for the work’s complexity would likewise characterize the work as shrewd. Choice C is incorrect because in this context, “incongruous” would mean unsuitable for its surroundings or internally inconsistent. The “casual description” presented in the text indicates that the painting is housed in a coffee shop and depicts women drinking coffee, which would imply that the mural may in fact be well suited to its surroundings, not that it’s ill suited to its location. Moreover, none of the details mentioned in this description would suggest that the painting contains internal inconsistencies of any kind. Choice D is incorrect because in this context, “pretentious” would mean expressive of exaggerated importance, which wouldn’t fit the contrast established in the text between a “casual description” of the painting and the work’s deeper themes. Though the text argues that the painting is worthy of “serious attention,” which would suggest its importance, the text doesn’t suggest that the casual description would by contrast imply that the painting’s importance is exaggerated. Rather, by merely mentioning the mural’s relatively ordinary location and subject matter without reference to this complexity, the casual description conveys that the painting is more unassuming and understated than it actually is, not that it expresses an exaggerated self-importance."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Craft and Structure'), 'medium', 'source', 'approved', 5, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, 0, '{"blocks": [{"type": "paragraph", "text": "Which choice best states the function of the underlined sentence in the text as a whole?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice B is the best answer because it most accurately describes how the underlined sentence functions in the text as a whole. The text establishes that Jam hears Bitter’s studio door open early in the morning, when it is still dark. Jam then listens to her mother’s footsteps, which seem to create a song that runs through the floorboards. The text indicates that the sound of Bitter’s footsteps convey to Jam that Bitter is done painting. The underlined sentence then builds on this idea, stating explicitly that Bitter’s feet sing the news of her completion of a painting. Thus, the sentence stating that “Bitter’s feet were singing the news” further emphasizes that Bitter’s footsteps themselves reveal information to Jam."}, {"type": "paragraph", "text": "Choice A is incorrect because the text provides no evidence that Jam prefers music to art. While the underlined sentence uses musical imagery to describe the vibrations Jam feels, this is figurative language that is describing the footsteps’ vibrations; it isn’t an indication of Jam’s personal interests. Choice C is incorrect because the text doesn’t suggest that Bitter herself sings while working on paintings. The references to singing in the text are figurative descriptions of how Bitter’s footsteps sound or feel to Jam, not literal statements about Bitter singing."}, {"type": "paragraph", "text": "Choice D is incorrect because the underlined sentence only describes Jam’s perception of her mother’s footsteps. It doesn’t provide any details about Aloe or his reaction to the painting; in fact, the text doesn’t mention Aloe seeing the painting at all."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Craft and Structure'), 'medium', 'source', 'approved', 6, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice best states the main purpose of the text?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice B is the best answer because it most accurately describes the main purpose of the text, which is to showcase how Adam’s flexibility and consideration strengthen his relationship with his great-uncle Richard. The text begins by stating that the meeting between the two characters is proceeding well and then describes Adam’s thoughtful behavior: noticing his great-uncle’s interest in the ship, Adam suggests staying on board overnight and expresses willingness to accommodate his great-uncle’s schedule and destination preferences. The text goes on to describe the positive effect of Adam’s thoughtfulness and flexibility, indicating that Adam’s “affectionate willingness” to accommodate Richard’s preferences “quite won the old man’s heart.” The text concludes by suggesting that Adam’s ability to anticipate his great-uncle’s wishes and willingness to accommodate them result in the rapid development of affection and intimacy between them, stating that they soon became “almost like old friends.” Therefore, the text’s main purpose is to demonstrate how Adam’s flexibility and consideration strengthened his and his great-uncle’s relationship."}, {"type": "paragraph", "text": "Choice A is incorrect. Although the text explains Adam’s reason for suggesting that Richard spend the night on the ship rather than finding lodging on land (which is that Adam perceives Richard’s interest in the ship), this isn’t the text’s main purpose. Rather, Adam’s suggestion about where to sleep for the night serves as an example of the consideration Adam shows toward Richard, and the text mentions it mainly to explain how an affectionate relationship developed so quickly between them. Moreover, the text only states that Adam encourages Richard to stay on the ship; it doesn’t specify where Adam plans to spend the night. Choice C is incorrect because the text doesn’t describe why Adam and his great-uncle Richard are excited about their journey. While the text mentions that Adam is willing to “start at any hour and go anywhere,” it provides no details about any planned journey, its destination, or even whether they will be continuing by ship or some other mode of transportation, nor does the text mention anything about either character’s feelings of excitement about their plans. We learn only that Adam is accommodating about potential travel plans, not that either character is particularly eager about the journey itself. The text’s main focus is on Adam and Richard’s developing relationship, not on any anticipated travel experiences. Choice D is incorrect because the text doesn’t show a contrast between initial wariness and later affection. On the contrary, the text begins by stating that the meeting between Adam and his great-uncle Richard has begun in an “auspicious,” or promising, manner and is “proceed[ing] well,” suggesting that Richard’s impression is positive from the outset. There’s no indication of any initial suspicion, caution, or reserve on Richard’s part that later changes to affection. Instead, the text describes a consistently positive interaction that deepens from a good first impression into a stronger, more familiar relationship because of Adam’s considerate behavior."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Craft and Structure'), 'medium', 'source', 'approved', 7, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, 0, '{"blocks": [{"type": "paragraph", "text": "Which choice best states the function of the underlined portion in the text as a whole?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice D is the best answer because it most accurately describes how the underlined portion functions in the text as a whole. The text first establishes that in order to investigate visual perception of objects in dreams, LaBerge and team observed the eye movements of lucid dreamers (people who are aware of their dreaming as it occurs) when these participants signaled that they were in a dream state. The underlined portion then describes a finding that rests on a comparison: the way participants’ eyes tracked objects in dream states was very similar to how sighted people track real objects when awake. Finally, the text states that the team concluded from this finding that objects in dreams are perceived as more than just products of imagination—implying that the team thinks the eye movements are an indication that the brain treats dream objects as more real than imaginary. Thus, the function of the underlined portion is to identify a circumstance that is comparable to one in the study and that helps justify LaBerge and team’s conclusion, presenting the close similarity of visual tracking in wakeful and dreaming scenarios as support for the implicit idea that the brain perceives dream objects not as imaginary but as somewhat or fully real objects."}, {"type": "paragraph", "text": "Choice A is incorrect because the text never presents LaBerge and team’s initial hypothesis, only what question they were interested in studying and what they found. So although the underlined portion does present evidence, that evidence doesn’t serve to undermine any hypothesis in the text. Choice B is incorrect because the text gives no indication that LaBerge and team changed the focus of their study at any point or that the finding described in the underlined portion (or any other finding) was unexpected or surprising. Choice C is incorrect. Rather than illustrating an implication of the main finding by LaBerge and team, the underlined portion only presents the finding itself, stating that the team found that the movements of lucid dreamers’ eyes while dreaming were very similar to those of sighted people visually tracking objects while awake. The next part of the text indicates what the finding implied to the team but still doesn’t offer a real-world example as illustration."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Craft and Structure'), 'medium', 'source', 'approved', 8, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, 0, '{"blocks": [{"type": "paragraph", "text": "Based on the texts, how would the critics mentioned in Text 2 most likely respond to the underlined claim in Text 1?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice D is the best answer because the critics mentioned in Text 2 would argue that negative reactions to controversial public art are not solely the result of the nature of the art itself. The claim in Text 1 suggests that public artworks tend to provoke backlash when they are not “aesthetically and conceptually bland.” This implies that the content of public art alone can cause backlash. However, the critics in Text 2 offer a more nuanced explanation. They argue that norm-defying pieces of public art that are not “effectively integrated within their surroundings” are more likely to be judged harshly by the public. They also imply that a museum provides a context that prepares viewers to expect challenging art, while public environments that serve other purposes often do not. This indicates that the critics in Text 2 would contend that factors beyond the attributes of the art, like environment and presentation, play a significant role in how public art is received."}, {"type": "paragraph", "text": "Choice A is incorrect because the critics in Text 2 do not argue that unconventionality is unrelated to public disagreement about a public artwork’s merits. Rather, they acknowledge that norm-defying pieces do face unfavorable reactions, but they attribute such reactions to contextual factors like poor integration with the environment rather than dismissing the role of unconventionality entirely. Choice B is incorrect because the critics in Text 2 do not advocate for restricting public art to universally appealing works. Instead, they argue that better integration with the surroundings and situating the work in appropriate contexts could help norm-defying art be better received by passersby. Choice C is incorrect because the critics in Text 2 do not address whether civic leaders and community members are easily satisfied by norm- reinforcing art. The critics in Text 2 instead argue that installation and integration with the surrounding environment factor into how norm-defying art is received by the general public, rather than disputing how people respond to conventional art."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Craft and Structure'), 'medium', 'source', 'approved', 9, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Based on the text, what would Hincapié most likely say is a promising way to increase entrepreneurship in early adulthood?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice C is the best answer because it presents a conclusion about increasing entrepreneurship in early adulthood that can be reasonably inferred from the text. The text explains that Andrés Hincapié investigated why young adults are less likely than older adults to start businesses and found that lack of knowledge of practical aspects of starting a business is a barrier. The text then states that Hincapié found that providing relevant informational resources greatly helps address that problem. Offering young adults practical information about how to start a business would be an example of providing relevant informational resources, so Hincapié would most likely say it is a promising way to increase early adult entrepreneurship."}, {"type": "paragraph", "text": "Choice A is incorrect because creating social networks of young adults interested (but presumably inexperienced) in starting a business wouldn’t involve a clear source of practical information for those young adults, and the text indicates that Hincapié identified offering relevant informational resources about starting a business as a way to significantly reduce the problem of young adults’ low participation in entrepreneurship. Choice B is incorrect because encouraging young people to brainstorm business ideas wouldn’t involve a clear source of practical information for those young adults, and the text indicates that Hincapié identified offering relevant informational resources about starting a business as a way to significantly reduce the problem of young adults’ low participation in entrepreneurship. Choice D is incorrect because providing young adults with training opportunities at existing businesses would give those young people exposure to businesses that already exist but not necessarily information about how to start a business, and the text indicates that Hincapié identified offering relevant informational resources about starting a business as a way to significantly reduce the problem of young adults’ low participation in entrepreneurship."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 10, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice best states the main topic of the text?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice B is the best answer because it most accurately states the main topic of the text. The text begins by noting that few animals are known to spit, and then it focuses on Clare Jacobs’s January 2022 observation of a gray seal spitting water at a white-tailed eagle. The text explicitly notes that this behavior had never before been observed in seals, highlighting that this was a previously unseen behavior. The text concludes with biologist Sean Twiss’s hypotheses about why the seal might have been spitting. Thus, the main topic is the observation of a previously unseen behavior (spitting) of gray seals."}, {"type": "paragraph", "text": "Choice A is incorrect because while the text does mention bird-watcher Clare Jacobs making an observation in southern England, bird-watching itself is not the main topic. The reference to bird-watching is incidental to the central focus of the novel behavior of a gray seal spitting water at an eagle. Choice C is incorrect because the text only mentions a white-tailed eagle as the target of a seal’s spitting behavior; it doesn’t provide any information about how these eagles typically behave when defending territory or interacting with other predators."}, {"type": "paragraph", "text": "Choice D is incorrect because the text doesn’t discuss differences between gray seals and white-tailed eagles. While both animals are mentioned, the text is focused on the seal’s unusual spitting behavior rather than comparing the two animals in any way."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 11, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Based on the text, what is notable about Schmidt’s behavior?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice D is the best answer because it most accurately describes what is notable about Schmidt’s behavior. According to the text, when the narrator’s first wife admits she doesn’t find art particularly compelling, Schmidt responds by wincing, sighing dramatically, and abruptly leaving dinner with an obviously false excuse about a remembered appointment. The narrator makes it clear that there is no actual appointment and that the excuse is merely a pretense. Through these actions—the physical reactions of wincing and sighing, followed by the transparent excuse to leave—Schmidt clearly communicates his disapproval of the wife without directly stating his feelings about her."}, {"type": "paragraph", "text": "Choice A is incorrect because the text provides no evidence that Schmidt’s theatrical behavior—wincing, sighing dramatically, and abruptly leaving dinner—is unique to situations involving the narrator and his first wife. The text describes only one interaction involving Schmidt, so there’s no basis for determining whether his dramatic reactions are typical of him in all situations or limited to this particular social context. Choice B is incorrect because nothing in the text suggests that Schmidt is typically mindful of his schedule or that forgetting appointments would be uncharacteristic of him. Rather, the text makes it clear that Schmidt hasn’t actually forgotten an appointment at all—the narrator indicates that Schmidt’s reason for leaving is an obvious fabrication, not a genuine instance of absentmindedness. Choice C is incorrect because the text doesn’t mention any previous disagreement between Schmidt and the narrator’s first wife about a particular painting or any other topic. The text presents what appears to be a spontaneous reaction by Schmidt to the wife’s statement about not finding art compelling, not the continuation of an earlier conversation or dispute."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 12, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Based on the text, which choice best describes Sir Winston Day?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice A is the best answer because it accurately describes Sir Winston Day as he is portrayed in the text. The text indicates that Sir Winston’s “features seemed moulded to adorn a bust, or possibly a stamp,” suggesting that he appeared distinguished. But the text also indicates that his “actual achievements” during his long public service constitute an “enigma,” or mystery, highlighting the point with a joke about Sir Winston’s uninteresting memoirs (any information about his achievements past the first thirty pages “might as well have remained state secrets” since, it’s implied, no one bothered to read that far). Thus, the text suggests that Sir Winston appears distinguished even though his known accomplishments, if any, are relatively few."}, {"type": "paragraph", "text": "Choice B is incorrect because nothing in the text indicates that Sir Winston behaved dishonorably. Rather, the text indicates that his “actual achievements” during his long public service constitute an enigma, or mystery, suggesting that he may have done very little, not that what he has done was disreputable."}, {"type": "paragraph", "text": "Choice C is incorrect. Although the text says that Sir Winston’s achievements that appear “after the thirty-page mark” in his memoirs “might as well have remained state secrets,” this is a joke about the public’s lack of interest in the memoirs, not a sincere claim that secrecy was intended. Choice D is incorrect because the text does not associate Sir Winston with modesty, nor does it suggest that he was a capable public servant. Rather, by indicating that Sir Winston’s “features seemed moulded to adorn a bust, or possibly a stamp,” the text suggests that Sir Winston’s appearance communicated importance, not modesty. The text further indicates that his “actual achievements” during his long public service constitute an enigma, or mystery, suggesting that he may have done very little, not that he was particularly capable."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 13, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice best states the main idea of the text?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice D is the best answer because it most accurately states the main idea of the text. The text begins by explaining that most studies of ocean wave breaking have focused on traveling waves (those that move horizontally) but that McAllister et al. studied spike waves, which form when traveling waves moving in opposing directions intersect. The text establishes that while traveling waves break when their steepness exceeds a critical threshold (limiting their height), McAllister et al. found that spike waves can exceed these constraints because factors like jet stability and cavity shape can mitigate the effects of steepness. Thus, the main idea of the text is that spike waves resulting from traveling waves intersecting in specific ways can reach heights greater than what would be expected based on the general properties of traveling waves."}, {"type": "paragraph", "text": "Choice A is incorrect because it misrepresents the information in the text; the text indicates that McAllister et al. showed that jet stability and cavity shape (along with steepness) influence breaking in spike waves, not in traveling waves. Further, the information about specific influences is not the main focus of the text."}, {"type": "paragraph", "text": "Choice B is incorrect because it misrepresents the information in the text; the text indicates that McAllister et al. found that spike waves can pass the steepness threshold at which traveling waves break because factors like jet stability and cavity shape affect the breaking of spike waves, not because they’ve simply reached a critical threshold of steepness. Choice C is incorrect. Although the text does explain that spike waves can form when traveling waves intersect, it presents this as a known fact that McAllister et al.’s study was based on, not as something the researchers suggested. Further, the text indicates that spike waves can exceed a threshold that limits traveling wave height but doesn’t focus on the idea that spike waves typically are higher than traveling waves."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 14, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice most effectively uses data from the graph to complete the sentence?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice B is the best answer because it most effectively uses data from the graph to complete the sentence about which fuel has the highest energy density. Of the four bars in the graph, the highest (indicating the greatest energy density in MJ/L) is for POP biofuel. According to the graph, the energy densities of the fuels shown are approximately 40 MJ/L for POP biofuel, 36 MJ/L for gasoline, 34 MJ/L for jet fuel, and 23 MJ/L for ethanol."}, {"type": "paragraph", "text": "Choice A is incorrect. The task is to find the fuel in the graph with the highest bar (indicating the greatest energy density in MJ/L), and jet fuel has the third-highest bar in the graph, not the highest. According to the graph, the energy densities of the fuels shown are approximately 40 MJ/L for POP biofuel, 36 MJ/L for gasoline, 34 MJ/L for jet fuel, and 23 MJ/L for ethanol. Choice C is incorrect. The task is to find the fuel in the graph with the highest bar (indicating the greatest energy density in MJ/L), and ethanol has the lowest bar in the graph, not the highest. According to the graph, the energy densities of the fuels shown are approximately 40 MJ/L for POP biofuel, 36 MJ/L for gasoline, 34 MJ/L for jet fuel, and 23 MJ/L for ethanol. Choice D is incorrect. The task is to find the fuel in the graph with the highest bar (indicating the greatest energy density in MJ/L), and gasoline has the second-highest bar in the graph, not the highest. According to the graph, the energy densities of the fuels shown are approximately 40 MJ/L for POP biofuel, 36 MJ/L for gasoline, 34 MJ/L for jet fuel, and 23 MJ/L for ethanol."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 15, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which quotation from the article would best illustrate the theater historian’s claim?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice A is the best answer because it most effectively illustrates the theater historian’s claim that El Teatro Campesino’s early performances were influenced stylistically by carpa theater, vaudeville-style shows with “audience-mediated slapstick comedy.” The quotation indicates that El Teatro presented comedic sketches that often featured exaggerated physical humor and that the performers improvised based on the cheers and boos from the audience; thus, it illustrates that El Teatro’s performances were similar to carpa theater in the physical, slapstick nature of their comedy and in the way the performances were mediated, or shaped, by the audience’s reactions."}, {"type": "paragraph", "text": "Choice B is incorrect. Although the quotation refers to El Teatro’s use of comedy and mentions audiences, it focuses on the company’s use of comedic aspects of reality as a tool to critique society while providing audiences with entertainment and inspiration; it doesn’t give any indication that El Teatro’s performances featured slapstick, or very physical, comedy or that they were directly shaped by the audience. Choice C is incorrect. Although the quotation refers to El Teatro’s aesthetic, or style, and mentions comedy, it indicates only that the company relied on satire and humor and had a style that reflected their limited financial means and sociopolitical message; it doesn’t give any indication that El Teatro’s performances featured slapstick, or very physical, comedy or that they were directly shaped by the audience. Choice D is incorrect. Although the quotation refers to El Teatro’s performance of comedy, it mentions only that the company performed brief humorous vignettes, or short humorous scenes, in farm fields; it doesn’t give any indication that El Teatro’s performances featured slapstick, or very physical, comedy or that they were directly shaped by the audience."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 16, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice most logically completes the text?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice D is the best answer because it most logically completes the text’s discussion of the relationship between street lighting and people’s cycling behavior. According to the text, Eugeni Vidal-Tortosa and Robin Lovelace found that poor street lighting deters new or inexperienced cyclists from riding their bikes in a city but has little effect on experienced cyclists. This finding establishes a causal relationship between street lighting and the willingness of new or inexperienced cyclists to ride a bicycle in the city: if poor lighting discourages new or inexperienced cyclists from riding, then improving lighting conditions by increasing the number of streetlights would logically remove this deterrent, potentially leading to an increase in the number of new or inexperienced cyclists willing to ride in the city."}, {"type": "paragraph", "text": "Choice A is incorrect because it contradicts the logical relationship established in the text. If poor street lighting deters new or inexperienced cyclists from riding in the city, then increasing the number of streetlights (improving lighting conditions) would be expected to encourage more of these cyclists to ride, not decrease their numbers. Choice B is incorrect because the text explicitly states that street lighting didn’t have an effect on experienced cyclists. If lighting conditions don’t significantly influence experienced cyclists’ decisions to ride, then increasing the number of streetlights wouldn’t necessarily increase the number of experienced cyclists riding in the city. Choice C is incorrect. The text indicates that street lighting didn’t affect experienced cyclists, so increasing the number of streetlights wouldn’t decrease the participation of these cyclists. Instead, their numbers would be expected to remain about the same."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 17, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice most logically completes the text?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice D is the best answer because it most logically completes the text’s discussion of wild-bee declines. The text establishes that bumblebees and other wild bees have been experiencing population collapse as a result of habitat destruction, climate variation, and other factors. The text then indicates that because bumblebees are very extensively researched, ecologists rely heavily on findings about them to understand wild-bee declines in general. However, the text then introduces Ghisbain’s observation that unlike most other wild-bee genera, bumblebees have certain traits (social behaviors and dietary generalism) linked to increased resilience to certain environmental changes. In other words, bumblebees aren’t necessarily representative of wild bees as a whole because they are likely more tolerant of some pressures. Therefore, it logically follows that Ghisbain would urge researchers to exercise caution when using bumblebee data to draw conclusions about other wild-bee population declines, since bumblebees and other wild bees don’t always respond comparably to environmental threats."}, {"type": "paragraph", "text": "Choice A is incorrect because the text doesn’t indicate that climate variation is more of a threat to bumblebees than habitat destruction is or that it is a bigger threat to bumblebees than it is to other wild bees. The text simply indicates that climate variation and habitat destruction are among the factors that have caused population collapses for bumblebees and other wild-bee genera. Choice B is incorrect. As it is presented in the text, Ghisbain notes that bumblebees may respond to environmental changes differently than many other wild-bee genera do; this suggests that bumblebees shouldn’t be treated as representative of all wild bees, but there’s no reason to think that Ghisbain would go so far as to assert that bumblebee data shouldn’t be used to draw conclusions about other wild-bee genera that are similar to bumblebees in their dietary and social traits, even if there are relatively few. The text suggests caution in extrapolation, not a complete rejection of using bumblebee research. Choice C is incorrect. Although the text indicates that dietary generalism is linked to increased resilience to specific environmental changes (that is, to some but not all environmental stresses), it doesn’t suggest that bumblebees and other bees with this trait are less likely than bees with specialized diets to experience major population changes. In fact, the text makes it clear that like many other wild-bee genera—most of which don’t display dietary generalism—bumblebees are already experiencing population collapse."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 18, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text so that it conforms to the conventions of Standard English?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice D is the best answer. The convention being tested is end-of-sentence punctuation. This choice correctly uses a period to punctuate a declarative sentence that ends with an indirect question (“which link you should choose.”)"}, {"type": "paragraph", "text": "Choice A is incorrect. The structure requires a declarative clause that presents an indirect question about what is evaluated in click restraint, not an interrogative clause that presents a direct question, such as “which link should you choose.”"}, {"type": "paragraph", "text": "Choice B is incorrect. It’s unconventional to use a question mark in this way to punctuate a declarative clause that presents an indirect question, such as “which link you should choose.” Choice C is incorrect. The structure requires a declarative clause that presents an indirect question about what is evaluated in click restraint, not an interrogative clause that presents a direct question, such as “which link should you choose.”"}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Standard English Conventions'), 'medium', 'source', 'approved', 19, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text so that it conforms to the conventions of Standard English?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice D is the best answer. The convention being tested is the use of verbs to express tense in a sentence. The past perfect tense indicates an action that was completed before another past action. In this choice, the past perfect verb “had become,” together with the supplemental phrase “by 2023,” indicates that Lafourcade earned her status as one of the most celebrated musicians in Latin America before 2023."}, {"type": "paragraph", "text": "Choice A is incorrect because the future tense “will become” doesn’t indicate that Lafourcade earned her celebrated status before 2023. Choice B is incorrect because the present tense “becomes” doesn’t indicate that Lafourcade earned her celebrated status before 2023. Choice C is incorrect because the future perfect tense “will have become” doesn’t indicate that Lafourcade earned her celebrated status by 2023."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Standard English Conventions'), 'medium', 'source', 'approved', 20, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text so that it conforms to the conventions of Standard English?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice A is the best answer. The convention being tested is the use of verbs to express tense in a sentence. In this choice, the present tense verb “includes,” used in conjunction with the word “currently,” correctly indicates that the frog’s current range includes parts of northern New South Wales and southeastern Queensland."}, {"type": "paragraph", "text": "Choice B is incorrect because the past tense verb “included” doesn’t indicate that the frog’s range currently includes parts of northern New South Wales and southeastern Queensland. Choice C is incorrect because the future perfect tense “will have included” doesn’t indicate that the frog’s range currently includes parts of northern New South Wales and southeastern Queensland. Choice D is incorrect because the past perfect tense “had included” doesn’t indicate that the frog’s range currently includes parts of northern New South Wales and southeastern Queensland."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Standard English Conventions'), 'medium', 'source', 'approved', 21, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text so that it conforms to the conventions of Standard English?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice B is the best answer. The convention being tested is the use of punctuation within a sentence. The comma after “1804” pairs with the comma after “amendment” to separate the supplementary element “ratified in 1804” from the rest of the sentence. This supplementary element functions to provide additional information on the term “12th amendment,” and the pair of commas indicates that this element could be removed without affecting the grammatical coherence of the sentence."}, {"type": "paragraph", "text": "Choice A is incorrect because a dash can’t be paired with a comma in this way to separate the supplementary element from the rest of the sentence. Choice C is incorrect because a colon can’t be paired with a comma in this way to separate the supplementary element from the rest of the sentence. Choice D is incorrect because it fails to use appropriate punctuation to separate the supplemental element from the rest of the sentence."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Standard English Conventions'), 'medium', 'source', 'approved', 22, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text so that it conforms to the conventions of Standard English?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice B is the best answer. The convention being tested is subject-modifier placement. This choice makes the noun phrase “the titles” the subject of the sentence and places it immediately after the modifying phrases “laden with emojis and seemingly meaningless words, and driven largely by Sawano’s ‘personal feeling and mood.’” In doing so, this choice clearly establishes that the titles—and not another noun in the sentence—are being described as laden with emojis and driven by Sawano’s personal feeling."}, {"type": "paragraph", "text": "Choice A is incorrect because it results in a dangling modifier. The placement of “the listener” immediately after the modifying phrases illogically suggests that the listener, rather than the titles, is laden with emojis and driven by Sawano’s personal feeling. Choice C is incorrect because it results in a dangling modifier. The placement of “each piece” (i.e., musical score) immediately after the modifying phrases illogically suggests that the pieces, rather than the titles of the pieces, are laden with emojis and driven by Sawano’s personal feeling. Choice D is incorrect because it results in a dangling modifier. The placement of “the listener’s approach” immediately after the modifying phrases illogically suggests that the listener’s approach, rather than the titles, is laden with emojis and driven by Sawano’s personal feeling."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Standard English Conventions'), 'medium', 'source', 'approved', 23, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text so that it conforms to the conventions of Standard English?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice A is the best answer. The convention being tested is subject-verb agreement. The plural verb “explore” agrees in number with the plural subject “Barrada’s pieces.”"}, {"type": "paragraph", "text": "Choice B is incorrect because the singular verb phrase “has explored” doesn’t agree in number with the plural subject “Barrada’s pieces.” Choice C is incorrect because the singular verb “explores” doesn’t agree in number with the plural subject “Barrada’s pieces.” Choice D is incorrect because the nonfinite participle “exploring” doesn’t supply the main clause with a finite verb."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Standard English Conventions'), 'medium', 'source', 'approved', 24, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text so that it conforms to the conventions of Standard English?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice D is the best answer. The convention being tested is the use of punctuation within a sentence. The comma after “swimming” pairs with the dash after “ciliates” to offset the supplementary element (“widely…ciliates”) that interrupts the main clause of the sentence."}, {"type": "paragraph", "text": "Choice A is incorrect. Adding the verb “is” here creates an ungrammatical sentence structure with two main verbs (“is” and “bestows”) without appropriate punctuation and/or conjunction. Choice B is incorrect because it fails to offset the supplementary element with appropriate punctuation. Furthermore, adding the verb “is” here creates an ungrammatical sentence that has two finite verbs (“is” and “bestows”) without appropriate punctuation and/or conjunction. Choice C is incorrect because it fails to offset the supplementary element with appropriate punctuation. Furthermore, adding the verb “has been” here creates an ungrammatical sentence that has two finite verbs (“has been” and “bestows”) without appropriate punctuation and/or conjunction."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Standard English Conventions'), 'medium', 'source', 'approved', 25, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text with the most logical transition?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice D is the best answer. “As a result” logically signals that the information in this sentence—that the widened grooves in balsa wood can accommodate electrical conductors—is a direct consequence of the researchers’ method described in the previous sentence (using heat and chemicals to widen the grooves)."}, {"type": "paragraph", "text": "Choice A is incorrect because “for example” illogically signals that this sentence provides an example of the researchers’ method described in the previous sentence. Instead, the sentence indicates a consequence of that method."}, {"type": "paragraph", "text": "Choice B is incorrect because “previously” illogically signals that this sentence describes an event that occurred before the researchers’ development of the method described in the previous sentence. Instead, the sentence indicates a consequence of that method. Choice C is incorrect because “in contrast” illogically signals that the information in this sentence contrasts with the previous sentence’s description of the researchers’ method. Instead, the sentence indicates a consequence of that method."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Expression of Ideas'), 'medium', 'source', 'approved', 26, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text with the most logical transition?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice D is the best answer. “Consequently” logically signals that the information in this sentence—that many Arabic words entered the Spanish language—is a result or consequence of the previous information about Arabic-speaking Muslim states ruling Al-Andalus for centuries."}, {"type": "paragraph", "text": "Choice A is incorrect because “for example” illogically signals that the information about Arabic words entering Spanish exemplifies the Arabic-speaking history of Al-Andalus mentioned in the previous sentence. Instead, Arabic words entering Spanish is a consequence of that history. Choice B is incorrect because “instead” illogically signals that the information about Arabic words entering Spanish provides an alternative to the Arabic-speaking history of Al-Andalus mentioned in the previous sentence. The information about Arabic words entering Spanish is a consequence of that history. Choice C is incorrect because “specifically” illogically signals that the information about Arabic words entering Spanish provides specific details elaborating on the Arabic-speaking history of Al-Andalus mentioned in the previous sentence. Instead, Arabic words entering Spanish is a consequence of that history."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Expression of Ideas'), 'medium', 'source', 'approved', 27, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text with the most logical transition?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice A is the best answer. “By contrast” logically signals that the information in this sentence—that paper scraps left over from printing a magazine are pre- consumer waste—contrasts with the previous information about magazines being post-consumer waste."}, {"type": "paragraph", "text": "Choice B is incorrect because “for example” illogically signals that the information in this sentence exemplifies the previous information about post-consumer waste. Instead, the paper scraps being pre-consumer waste contrasts with the previous information. Choice C is incorrect because “as a result” illogically signals that the information in this sentence is a result or consequence of the previous information about post-consumer waste. Instead, the paper scraps being pre- consumer waste contrasts with the previous information. Choice D is incorrect because “specifically” illogically signals that the information in this sentence provides specific, precise details elaborating on the previous information about post-consumer waste. Instead, the paper scraps being pre-consumer waste contrasts with the previous information."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Expression of Ideas'), 'medium', 'source', 'approved', 28, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text with the most logical transition?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice A is the best answer. “Though” logically signals that the information in this sentence—that Morgado and colleagues detected a dense ring orbiting outside the Roche limit that remained intact—presents an exception to the previous sentence’s claim about debris orbiting outside an object’s Roche limit. Such debris would be expected to accrete into a satellite, not remain intact as a ring."}, {"type": "paragraph", "text": "Choice B is incorrect because “for example” illogically signals that the information about Morgado’s discovery exemplifies the previous sentence’s claim about debris orbiting outside an object’s Roche limit. Instead, the sentence presents an exception to the claim. Choice C is incorrect because “fittingly” illogically signals that the information about Morgado’s discovery aligns with the previous sentence’s claim about debris orbiting outside an object’s Roche limit. Instead, the sentence presents an exception to the claim. Choice D is incorrect because “likewise” illogically signals that the information about Morgado’s discovery is similar to the previous sentence’s claim about debris orbiting outside an object’s Roche limit. Instead, the sentence presents an exception to the claim."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Expression of Ideas'), 'medium', 'source', 'approved', 29, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice most effectively uses relevant information from the notes to accomplish this goal?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice C is the best answer. The sentence indicates how long John Cage’s musical piece will last, noting that it will last 639 years and be the longest continuous musical performance in history."}, {"type": "paragraph", "text": "Choice A is incorrect. The sentence identifies John Cage as the composer and provides the name of the musical piece; it doesn’t indicate how long the piece will last. Choice B is incorrect. The sentence provides the name of the musical piece and where it is currently being played; it doesn’t indicate how long the piece will last. Choice D is incorrect. The sentence mentions where the musical piece is being played and identifies John Cage as the composer; it doesn’t indicate how long the piece will last."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 30, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice most effectively uses relevant information from the notes to accomplish this goal?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice A is the best answer. The sentence provides a historical overview of the Shackleton expedition, noting that the explorers left for Antarctica in 1914, lost their ship in 1915, and were rescued in 1916."}, {"type": "paragraph", "text": "Choice B is incorrect. The sentence misrepresents information from the notes; Shackleton and his crew were themselves rescued in 1916—they weren’t rescuing others. Choice C is incorrect. The sentence provides examples of works and discoveries inspired by the expedition; it doesn’t provide an overview of the expedition itself. Choice D is incorrect. The sentence provides examples of works made about the expedition; it doesn’t provide an overview of the expedition itself."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 31, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice most effectively uses relevant information from the notes to accomplish this goal?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice D is the best answer. Noting that Meghadūta uses a pattern of long and short syllables in its lines (quantitative meter) and Widsith uses a pattern of repeated sounds in its lines (alliterative meter), and signaling a contrast with “whereas,” the sentence emphasizes a difference between the meters of the two poems."}, {"type": "paragraph", "text": "Choice A is incorrect. The sentence indicates that the two poems were written in different languages; it doesn’t emphasize a difference between the meters of the two poems. Choice B is incorrect. The sentence mentions the meters of the two poems but misrepresents information from the notes; the overall definition of a meter (the rhythmic structure or pattern of accents in a poem’s lines) applies to both alliterative and quantitative meters, not just quantitative. Choice C is incorrect. While the sentence emphasizes a difference between the meters of the two poems, it misrepresents information from the notes; Widsith uses an alliterative meter, which is structured by a pattern of repeated sounds, not a pattern of long and short syllables."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 32, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice most effectively uses relevant information from the notes to accomplish this goal?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice B is the best answer. The sentence places the Declaration of Independence in the context of Valle’s changing political beliefs, noting that Valle was long an opponent of Central American independence but changed his mind after an 1820 revolt and then wrote the Declaration of Independence in 1821."}, {"type": "paragraph", "text": "Choice A is incorrect. The sentence states that Valle’s political beliefs changed after Riego’s revolt but doesn’t indicate how these changed beliefs provide context for the 1821 Declaration of Independence. Choice C is incorrect because it misrepresents information from the notes. Valle’s political beliefs changed after Riego’s 1820 revolt, not when the Spanish king repealed the 1812 constitution."}, {"type": "paragraph", "text": "Choice D is incorrect. While the sentence indicates a relationship between Colonel Riego’s 1820 revolt and Central America’s Declaration of Independence, it doesn’t mention Valle’s changing political beliefs."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 33, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text with the most logical and precise word or phrase?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice C is the best answer because it most logically completes the text’s discussion of the ancient Inca farming method. In this context, “effective” means successful in producing a desired result. The text describes how the Inca used terraces with built-in irrigation systems to grow crops at different altitudes and then indicates that this farming method produced positive results “as evidenced by the great number and variety of crops grown at that time.” The context clearly suggests that the terraced farming approach was highly productive, or effective."}, {"type": "paragraph", "text": "Choice A is incorrect because to describe the Inca farming method as “chaotic” contradicts the text’s description of a systematic approach using deliberately constructed terraces with built-in irrigation systems. Moreover, the “great number and variety of crops” yielded by this method seems unlikely to result from a disorganized, or chaotic, approach. Choice B is incorrect because “uniform” means consistent or the same throughout. It does not make sense in this context to describe a farming method as highly uniform if it produced a “great number and variety of crops.” Moreover, the text indicates that Inca terrace farming was specifically designed to accommodate different crops at different altitudes, highlighting the diversity rather than uniformity of this approach. Choice D is incorrect because the success of the method, “as evidenced by the great number and variety of crops grown,” does not support the claim that the Inca farming method was “burdensome,” or difficult to implement or maintain. In fact, the context clearly emphasizes the advantages, rather than the burdens, of Inca terrace farming."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Craft and Structure'), 'medium', 'source', 'approved', 1, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text with the most logical and precise word or phrase?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice C is the best answer because it most logically completes the text’s discussion of repairing the Hubble Space Telescope. In this context, “relying on” means depending on. The text states that astronauts have regularly had to go on missions to repair the Hubble Space Telescope but that robots might soon be able to make the repairs, which would be helpful because involving astronauts in the process is expensive. It is most reasonable to assume that it is the need to send astronauts on missions that is expensive; thus, the context suggests that employing robots for repairs will be helpful because depending on repeatedly sending humans to space is costly."}, {"type": "paragraph", "text": "Choice A is incorrect. In this context, “straightening” would mean physically aligning or removing curves and bends. It’s not clear how astronauts would be physically straightened to maintain the telescope or why that would be expensive."}, {"type": "paragraph", "text": "Choice B is incorrect because the text suggests that it is the ongoing involvement of astronauts—the need to send them to space regularly—that is expensive. Nothing in the text indicates that astronauts have been forgotten about or that forgetting about them would be expensive. Choice D is incorrect. In this context, “reducing” would most likely mean lowering in status, and nothing in the text suggests that astronauts are diminished in any way by repairing the telescope (indeed, they have regularly done repairs for years). Further, it isn’t clear how a decrease in status would be expensive."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Craft and Structure'), 'medium', 'source', 'approved', 2, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text with the most logical and precise word or phrase?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice C is the best answer because it most logically completes the text’s discussion of election polling. In this context, to “neglect” would mean to disregard or pay insufficient attention to something. The text states that there have been many cases of election pollsters incorrectly predicting presidential elections and then says that neuroscientist and pollster Sam Wang notes that campaigns shouldn’t react to these failures in a certain way. The text then adds that polls are valuable for informing strategists’ efforts throughout campaigns, not just for predicting the outcome. This context conveys that Wang’s advice is not to neglect, or disregard, polling because even though it sometimes fails to predict the winner, it can help improve campaign strategies."}, {"type": "paragraph", "text": "Choice A is incorrect. In this context, to “distort” would mean to give a false or misleading account. Though the text states that many election pollsters have failed in their predictions in presidential elections, it gives no indication that Wang would therefore argue that campaigns shouldn’t react to such polling failures by giving inaccurate accounts of election polling. Instead, the text emphasizes that polls have value beyond predicting winners, suggesting that Wang’s point is that campaigns shouldn’t stop polling entirely. Choice B is incorrect because it wouldn’t make sense to suggest that Wang encourages campaigns not to “enact,” or establish, election polling; the text indicates that election polling is something that already takes place and that has value for campaign strategies even if it sometimes leads to inaccurate predictions of winners, suggesting an argument in favor of continuing to use election polling. Choice D is incorrect. Although the text indicates that many election pollsters have failed in their predictions in presidential elections, there’s no reason to think Wang would say that these failures should lead campaigns not to “supplement,” or add to, election polling; it would be reasonable to suggest that campaigns would want to consider more than just election polling information if that information may lead to inaccurate predictions. Moreover, the text’s main point is that polls provide some utility even if their predictions may be inaccurate, which suggests that Wang’s recommendations pertain to whether campaigns should or shouldn’t use polling data, not whether polling data should or shouldn’t be supplemented with other kinds of information."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Craft and Structure'), 'medium', 'source', 'approved', 3, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text with the most logical and precise word or phrase?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice D is the best answer because it most logically completes the text’s discussion of Steiger Butte Drum’s contributions to the musical work Natural History. In this context, “integral” means essential or necessary to the whole. The text states that Steiger Butte Drum not only took part in the piece’s creation, collaborating with composer Michael Gordon on it, but also “must be included in all performances.” This context clearly indicates that the ensemble’s participation is essential, or integral, to the piece, both in its creation and its performance."}, {"type": "paragraph", "text": "Choice A is incorrect because in this context, “tangential” would mean peripheral or of little relevance to something. The text emphasizes the importance of Steiger Butte Drum’s involvement in both the composition and performance of Natural History, indicating their role is central, not tangential. Choice B is incorrect because in this context, “subsequent” would mean following after or coming later than something else. The text doesn’t establish a temporal sequence where the participation of Steiger Butte Drum followed after the creation of Natural History; rather, it indicates that the ensemble was involved with the piece from the beginning, having worked with Michael Gordon during the creation process."}, {"type": "paragraph", "text": "Choice C is incorrect because in this context, “analogous” would mean similar or comparable to something else, and the text doesn’t compare Steiger Butte Drum’s participation in the creation and performances of Natural History to anything else; instead, it describes the nature and importance of the ensemble’s involvement."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Craft and Structure'), 'medium', 'source', 'approved', 4, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "As used in the text, what does the word “manifest” most nearly mean?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice B is the best answer because as used in the text, “manifest” most nearly means perceptible or detectable. The text indicates that the sun was “already down,” meaning it was below the horizon and not directly visible. However, the sun’s presence was nonetheless perceptible or manifest in the “tongues of fire” (or beams of light) that still flickered in the darkening sky."}, {"type": "paragraph", "text": "Choice A is incorrect. Although in some contexts “manifest” can mean “realized” or “brought into being,” that is not the context here. Rather, the text is about how the sun’s presence was perceptible or manifest in the “darting” beams of light that could still be seen in the sky. Choice C is incorrect. This choice would suggest that the sun is situated, or located, in the light it emits, which is not supported by the surrounding context. Rather, the text is about how the sun’s presence was perceptible or manifest in the remaining light that could still be seen in the sky."}, {"type": "paragraph", "text": "Choice D is incorrect. Although the text is about the decreasing light in the scene at sunset, the text’s use of “manifest” is about how the sun’s presence was nonetheless perceptible or manifest in the “tongues of fire” still visible in the sky as night approached."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Craft and Structure'), 'medium', 'source', 'approved', 5, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, 0, '{"blocks": [{"type": "paragraph", "text": "Which choice best describes the function of the underlined portion in the text as a whole?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice B is the best answer because it most accurately describes how the underlined portion functions in the text as a whole. The underlined portion is a parenthetical phrase directly following the word “microfilm,” and it describes film containing small (“scaled-down”) images; the placement and focus of the portion indicate that it is serving to define the term “microfilm.”"}, {"type": "paragraph", "text": "Choice A is incorrect. Although the text is about accessing the writings of a famous historical figure (Douglass), the underlined portion doesn’t give information about Douglass or any other person. Instead, it explains what microfilms are. Choice C is incorrect because the text never describes any kind of debate or disagreement; it simply describes a change in how researchers can access historical documents, with the underlined portion defining an important term. Choice D is incorrect because the text never makes any mention of a particular finding, unexpected or otherwise; it simply describes a change in how researchers do some of their work, with the underlined portion defining an important term."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Craft and Structure'), 'medium', 'source', 'approved', 6, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice best describes the overall structure of the text?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice B is the best answer because it most accurately describes the overall structure of the text. The text begins by stating that the gray wolf was eradicated from Yellowstone National Park in 1926. It then explains the consequences of this elimination—namely that the elk population grew too large and overgrazing occurred, negatively affecting other animals in the area. The text then states that once scientists realized the importance of the gray wolf to the Yellowstone food chain, they undertook efforts leading to the wolves’ reintroduction to the park in 1996. Thus, the structure of the text can be accurately described as mentioning the elimination of the gray wolf from Yellowstone and then explaining why the wolf was later restored to the park."}, {"type": "paragraph", "text": "Choice A is incorrect. While the text does summarize a problem associated with an event in the 1920s (the eradication of gray wolves from Yellowstone in 1926), the problems discussed arose after that event—namely, the subsequent elk overpopulation, resultant overgrazing, and then further impacts to other animals in Yellowstone. Furthermore, the text doesn’t present multiple potential solutions. Instead, it describes one solution that was actually implemented: the reintroduction of gray wolves in 1996. Choice C is incorrect because the text doesn’t make a claim about the health of the gray wolf population apart from pointing out that the wolves had been eradicated from, and then subsequently restored to, Yellowstone. Instead, the text focuses on outcomes associated with the gray wolf’s eradication and reintroduction. Choice D is incorrect. Though the text does mention that the ecosystem of Yellowstone rebounded after the gray wolf was reintroduced in 1996, the text never explains why the park allowed the wolves to be eradicated in 1926. It simply states that this eradication occurred without elaborating on the decision-making process behind it."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Craft and Structure'), 'medium', 'source', 'approved', 7, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice best describes the overall structure of the text?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice A is the best answer because it most accurately describes the overall structure of the text. The text first presents what researchers found from studying Matabele ants: the ants can tell when colony members have infected wounds and can largely successfully treat those infections with their antimicrobial secretions. The text then indicates that the findings about the ants could help with the future development of antibiotics for humans. Thus, the text summarizes research findings and then identifies an area for further research."}, {"type": "paragraph", "text": "Choice B is incorrect. Although the text introduces a study about Matabele ants, it never discusses how the researchers did their work or any methods they used to produce their findings. Choice C is incorrect. Although the text does describe properties of Matabele ants—their ability to detect and largely successfully treat infected wounds in colony members—it never addresses evolution or how these properties might have changed. Choice D is incorrect because the text doesn’t present anything about Matabele ants as an issue or problem to be solved. Instead, it discusses beneficial abilities the ants have (detecting and treating infected wounds) and suggests that understanding those abilities might be useful for human medicine."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Craft and Structure'), 'medium', 'source', 'approved', 8, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice best states the main purpose of the text?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice B is the best answer because it most accurately describes the main purpose of the text, which is to explain the basics of how a specific energy technology works. The text introduces Raccoon Mountain as a pumped-storage hydropower facility built in the 1970s and then explains how it operates: during periods of low demand, excess power pumps water up to a lake at the mountain’s summit, and when demand for energy peaks, the water flows back down, spinning turbines along the way to generate electricity. The text provides some additional details, like the name of the water source, but the overall focus is on explaining the basics of how pumped-storage hydropower works."}, {"type": "paragraph", "text": "Choice A is incorrect because the text focuses on one method of energy generation—pumped-water hydropower—and briefly mentions another type of energy generation (nuclear plants) only to identify it as a source of power for the pumping process. The text never makes any comparison between the two methods. Choice C is incorrect because the text simply gives a factual description of how Raccoon Mountain, a pumped-storage hydropower facility, operates; it never suggests that more energy storage facilities should be built, whether by regional utilities or by any other entity. Choice D is incorrect because the text doesn’t present pumped-storage hydropower as a new technology; it indicates that Raccoon Mountain was built in the 1970s, meaning that, rather than being new, this facility is approximately 50 years old."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Craft and Structure'), 'medium', 'source', 'approved', 9, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice best states the main idea of the text?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice C is the best answer because it most accurately states the main idea of the text. The text begins by establishing Ruth Asawa as an artist who worked in several art forms but emphasizes that she was interested in art for reasons other than her desire to create it. The text mentions two ways in which Asawa brought art to children through public schools: cofounding the Alvarado School Arts Workshop in 1968 and helping found a public arts high school in 1982. Thus, the main idea is that Asawa’s interest in art education motivated her to establish arts programs for students in San Francisco."}, {"type": "paragraph", "text": "Choice A is incorrect because the text doesn’t mention Asawa inspiring other artists to share their work with students. While the text does note that the Alvarado School Arts Workshop brought works of art and artists into public schools, it doesn’t state that Asawa motivated these artists. Choice B is incorrect because the text makes no comparison between local and national appreciation of Asawa’s sculptures. While the text does mention that Asawa created unique tied-wire sculptures and was connected to San Francisco, it does not contrast her local and national critical receptions. Choice D is incorrect. Although the text emphasizes Asawa’s educational initiatives, it doesn’t state or imply that she abandoned her career as a sculptor to work as an art teacher. Instead, the text portrays her educational work as a complement to her career as a successful artist."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 10, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "According to the graph, which city had the largest population in 1891?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice B is the best answer because the graph shows that Montréal had the largest population in 1891 among the four cities represented. According to the data points in the graph for the year 1891, Montréal’s population was approximately 220,000, which is greater than the respective populations of Toronto (approximately 180,000), Québec City (approximately 60,000), and Halifax (approximately 40,000)."}, {"type": "paragraph", "text": "Choice A is incorrect because Toronto’s population in 1891 was approximately 180,000, which is the second largest among the four cities shown but still clearly smaller than Montréal’s population of approximately 220,000. Choice C is incorrect because Québec City had a population of approximately 60,000 in 1891, making it only the third largest of the four cities shown. Choice D is incorrect because Halifax had a population of approximately 40,000 people in 1891. Of the four cities shown in the graph, Halifax has the smallest population, not the largest."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 11, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice best describes data from the graph that support the researchers’ conclusion?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice D is the best answer because it accurately describes data from the graph that support the researchers’ conclusion that children may be more aware of mammals than of other animals. The graph presents the percent of drawings by schoolchildren that contained an example of an animal from a certain group (mammals, birds, or insects). The graph shows that approximately 80% of the drawings contained an example of a mammal, while only approximately 69% contained an example of a bird and only about 55% contained an example of an insect. The fact that mammals were included in more drawings than either birds or insects were supports the idea that children may be particularly aware of mammals in their environments."}, {"type": "paragraph", "text": "Choice A is incorrect because the graph shows that there were not “about as many” drawings with insects as there were drawings with birds (approximately 69% of the drawings included an example of a bird, while only about 55% included an example of an insect). Further, comparing only the numbers for birds and insects wouldn’t indicate anything about the schoolchildren’s awareness of mammals. Choice B is incorrect because the graph shows that insects, not birds, were the group that appeared in the fewest number of drawings (approximately 69% of the drawings included an example of a bird but only about 55% included an example of an insect). Further, stating that examples from one nonmammal group appeared in the fewest number of drawings would provide no evidence about the schoolchildren’s awareness of mammals. Choice C is incorrect because the graph shows that more drawings had an example of a mammal than an example of an insect, not the other way around (approximately 80% of the drawings included an example of a mammal, while only about 55% included an example of an insect). Further, examples of a nonmammal group appearing in more drawings than examples of mammals did would actually weaken the claim that schoolchildren may be more aware of mammals than of other animals."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 12, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice most effectively uses data from the graph to complete the sentence?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice C is the best answer because it accurately uses data from the graph to complete the statement regarding the research institute’s findings about veteran representation in Congress. The graph shows that the percentage of veterans in both houses of Congress decreased dramatically from 1973 to 2013. In 1973, the House of Representatives consisted of approximately 74% veterans, and the Senate was made up of approximately 79% veterans. By 2013, veteran members of both houses had fallen to approximately 17%–18%. This represents a substantial decrease of more than 50% in each house over this 40-year period."}, {"type": "paragraph", "text": "Choice A is incorrect because from 2003 to 2023, the House of Representatives did not consistently have a higher percentage of veterans than the Senate did. According to the graph, in 2003 the Senate was made up of approximately 35% veterans, while the House consisted of approximately 23% veterans. In 2013, the number of veterans in the Senate was still slightly higher (approximately 18%) than in the House (approximately 17%). Only in 2023 did the House have a marginally higher percentage than the Senate. Choice B is incorrect because veterans did not constitute a majority in both houses throughout the entire period shown in the graph from 1953 to 2003. According to the graph, both houses had a majority of veterans in 1953 (approximately 62% in the House and approximately 74% in the Senate) and in 1973 (approximately 74% in the House and approximately 79% in the Senate), but by 1993 the House had fallen below 50% to approximately 40% veterans. By 2003, both houses were well below 50%."}, {"type": "paragraph", "text": "Choice D is incorrect because the percentage of veterans in Congress did not remain consistent from 1993 to 2023. The graph shows significant changes in the number of members reporting past military service during this period, particularly the continued decline from 1993 to 2003. In 1993, the House had approximately 40% veterans and the Senate had approximately 63% veterans, but by 2003 these percentages had dropped to approximately 23% and 35%, respectively. Furthermore, there was a large gap between the two houses in 1993 that narrowed considerably by 2013, which contradicts the claim that the percentage of veterans across both houses “remained fairly consistent” during this period."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 13, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice most effectively uses a quotation from “Aunt Sue’s Stories” to illustrate the claim?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice B is the best answer because it most effectively illustrates the speaker of the poem’s claim that the stories Aunt Sue tells are based on Aunt Sue’s personal experiences. In the quotation, the speaker conveys the listening child’s point of view that Aunt Sue’s stories originate from her personal experiences and are not taken from books or other external sources. The listening child explicitly contrasts two possible sources for Aunt Sue’s stories: a book (whose potentially fictitious stories are implied to be written by someone else) or “her own life.” By having the child confidently assert that Aunt Sue “never got her stories out of any book at all,” the speaker indicates that Aunt Sue’s stories are instead informed by her lived experiences."}, {"type": "paragraph", "text": "Choice A is incorrect because it describes an element or image that recurs within Aunt Sue’s stories rather than indicating that these stories have a real-life basis. The reference to dark shadows that “cross and recross” the stories functions as imagery on a literal, visual level and may also evoke figurative darkness, but this detail by itself doesn’t suggest that the stories are based on Aunt Sue’s personal experiences. Choice C is incorrect because it identifies the setting of Aunt Sue’s storytelling rather than describing the real-life basis of the stories themselves. The quotation states that Aunt Sue tells her stories on “summer nights on the front porch,” which establishes when and where the storytelling occurs; however, no information is provided about the origins of the stories that Aunt Sue tells within this setting. Choice D is incorrect because it describes the movement or circulation of characters in the stories as Aunt Sue speaks rather than establishing that these stories have a real-life basis. The quotation primarily evokes the sounds of Aunt Sue’s voice and the seemingly easy “flow” of this voice in her storytelling. Although the characters who “mingle…in the flow of old Aunt Sue’s voice” are to some extent created or animated by her voice, no information is provided about the characters themselves or their relationship to Aunt Sue’s actual experiences."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 14, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, 0, '{"blocks": [{"type": "paragraph", "text": "Which finding, if true, would most strongly support the underlined claim?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice C is the best answer because it presents a finding that, if true, would most strongly support Manenti and team’s claim that olms regularly come to the surface to find food. The text explains that scientists previously believed olms remained in their underwater caves throughout their lives, but Manenti’s team claims that olms actually surface regularly to perform important activities like finding food. Since earthworms from surface soils would not be present in underwater caves, the finding that such earthworms constitute a major part of olms’ diet would provide compelling evidence that olms regularly leave their underwater cave environment to obtain food from the surface, thus supporting the underlined claim."}, {"type": "paragraph", "text": "Choice A is incorrect because information about olms’ breeding frequency wouldn’t support the claim about their leaving their underwater habitats to obtain food. While breeding patterns might be relevant to understanding olm behavior in general, this finding doesn’t address whether olms surface to find food, which is the specific behavior that the underlined claim addresses. Choice B is incorrect because learning that olms live in only a few cave systems wouldn’t support the claim about their regular visits to the surface. This finding would provide information about the geographic distribution of olm habitats but wouldn’t address whether olms leave these caves to find food or perform other activities on the surface. Choice D is incorrect because the differences between olms’ brains and other salamanders’ brains have no clear connection to olms’ movement beyond their underwater habitats or to their feeding habits. A finding about the uniqueness of olms’ brains wouldn’t address whether olms leave their caves to find food or support Manenti and team’s claim about olms’ motivation for coming to the surface."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 15, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which quotation from an art historian would most directly support the claim made in the text?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice C is the best answer because it most directly supports the text’s claim that Stevens strove to convey the ephemeral and dynamic characteristics of ikaah as a cultural practice. The text challenges the characterization of Stevens’s preserved sandpaintings as mere “static objects” that cannot “authentically represent” a practice defined in part by the absence of an end product; it claims instead that this “overly object-focused” interpretation overlooks how Stevens preserved the essential characteristics of traditional ikaah practice. This quotation supports the claim by explaining that Stevens’s sandpaintings should be understood “not as self-contained objects but as reminders of the public creations of the sandpaintings,” during which Stevens “conducted appropriate ikaah rituals and encouraged viewers to closely track his movements and subtle shifts in the sand throughout the process.” The fact that Stevens created the sandpaintings in a public setting and invited viewers to attentively engage with this process supports the claim that he sought to portray ikaah as a dynamic practice rather than as a static product. Further, the inherently impermanent nature of such a performance evokes the ephemerality that characterizes ikaah."}, {"type": "paragraph", "text": "Choice A is incorrect because it contradicts rather than supports the text’s claim that Stevens strove to convey the ephemeral and dynamic characteristics of ikaah as a cultural practice. This quotation argues that Stevens’s preserved sandpaintings “should not be confused with authentic ikaah” and emphasizes that authentic ikaah “cannot be extricated from a practice that is intentionally and necessarily transitory.” This view aligns with the “overly object-focused” perspective that the text argues against, rather than supporting the claim that Stevens successfully conveyed ikaah’s ephemeral and dynamic characteristics."}, {"type": "paragraph", "text": "Choice B is incorrect because it focuses on reconciling the tension between ephemeral and permanent forms rather than supporting the claim that Stevens actively conveyed ikaah’s ephemeral and dynamic characteristics. While this quotation acknowledges an apparent contradiction, it suggests that Stevens was accommodating US preferences for permanent artworks; it doesn’t demonstrate how he communicated the ephemeral and dynamic nature of traditional ikaah practice. Choice D is incorrect. Although the quotation mentions Stevens’s “temporary and performative role” as a gift-giver, it doesn’t address how Stevens conveyed the ephemeral and dynamic characteristics of ikaah itself during his ambassadorial activities. The quotation focuses on Stevens’s role in transmitting knowledge and representing cultural dynamism but doesn’t specifically support the claim about his efforts to communicate the essential characteristics of ikaah practice. Further, the quotation incorrectly implies that Stevens shared his knowledge of preservative additives; the text doesn’t establish that he revealed how the sandpaintings were preserved."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 16, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice most logically completes the text?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice A is the best answer because it most logically completes the text’s discussion of mountain climbers’ motivations for exaggerating the difficulty of reaching edelweiss. The text establishes that edelweiss became symbols of strength and courage in Switzerland in the mid-1800s. The text goes on to state that mountain climbing became popular around the same time and that climbers spread the false idea that the flowers grew only in dangerous, hard-to-reach locations. According to the text, historian Tobias Scheidegger argues that these claims were “self-interested,” meaning they served the climbers’ own purposes. The text therefore implies that by claiming that edelweiss could be found only in perilous locations, mountain climbers could enhance their own reputations: climbers who encountered edelweiss would appear to have undertaken a dangerous journey, thereby making themselves seem brave and strong."}, {"type": "paragraph", "text": "Choice B is incorrect because making edelweiss seem more dangerous to reach than other mountain flowers are would likely discourage flower enthusiasts from trying to reach edelweiss rather than encourage them to explore the Swiss Alps. The text suggests that climbers’ self-interested motivation for exaggerating the difficulty of climbing to areas where edelweiss grew was to enhance their own reputations for being especially brave, not to promote tourism in the Swiss Alps."}, {"type": "paragraph", "text": "Choice C is incorrect because the text states that according to Scheidegger, mountain climbers exaggerated the difficulty of reaching edelweiss for self- interested reasons, not because they wanted to report genuine scientific observations about the flower’s unique characteristics. The text provides no indication that the climbers sincerely believed that their claims about the especially challenging terrain in which edelweiss grew were accurate, much less that they wanted to share this information with scientists. Choice D is incorrect because the text doesn’t suggest that mountain climbers were trying to prove that edelweiss were more common in Switzerland than elsewhere. The text’s focus is on the supposed difficulty and danger of reaching the flowers, not on their relative abundance in the Swiss Alps compared to other regions. In fact, the text implies that mountain climbers exaggerated how difficult edelweiss were to reach; it therefore wouldn’t make sense to say that they exaggerated this difficulty to demonstrate that edelweiss were relatively common."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 17, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice most logically completes the text?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice A is the best answer because it most logically completes the text’s discussion of modeling the atmosphere of Titan. The text establishes that the methane mole fraction (the ratio of methane to other atmospheric components) influences precipitation, humidity, and other meteorological phenomena and that observational data for Titan are too lacking (“too sparse and discrepant”) to fully determine the range of this measure across the moon’s various atmospheric levels. The text indicates that because of this limitation, researchers developed an atmospheric model (IPSL) that uses a simplified approach: it applies a uniform methane mole fraction for the lowest atmospheric level. Since it is very unlikely that the actual methane distribution across atmospheric levels on Titan is uniform, and since the methane mole fraction directly affects precipitation and humidity, it logically follows that the model’s simplified treatment of the methane mole fraction would lead to some disagreements between the model’s simulations and Titan’s actual precipitation and humidity."}, {"type": "paragraph", "text": "Choice B is incorrect because the text makes it clear that the model already uses a single value for Titan’s methane mole fraction instead of a range. Further, the text suggests that the single value is a simplification of what is likely a more complex reality, so there’s no reason to assume that a single value would be more desirable than a range. Choice C is incorrect. The text strongly suggests that Titan’s actual methane mole fraction differs from the uniform value used in the model, even though some of the model’s outputs align closely with observations, but nothing in the text indicates how the actual value would differ. There’s no reason to assume that the actual methane mole fraction is higher than what the model uses. The “lowest level” mentioned in the text refers to the atmosphere and not Titan’s methane mole fraction. Choice D is incorrect because the text makes it clear that the model doesn’t reflect the actual variations in the methane mole fraction across Titan’s atmospheric levels, since observational data are too limited. Because the model uniformly applies a set methane mole fraction, no inconsistencies in the simulations would be attributable to actual variations in the moon’s methane mole fraction."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 18, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text so that it conforms to the conventions of Standard English?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice B is the best answer. The convention being tested is end-of-sentence punctuation. This choice correctly uses a period to punctuate a declarative sentence ending with a relative clause that presents an indirect question (“why ganga has been used as a communication method.”)"}, {"type": "paragraph", "text": "Choice A is incorrect. It’s unconventional to use a question mark to punctuate a declarative sentence that presents an indirect question. Choice C is incorrect. The structure requires a declarative clause at the end of the sentence, not an interrogative clause that asks a direct question, such as “has ganga been used as a communication method.” Choice D is incorrect. The structure requires a declarative clause at the end of the sentence, not an interrogative clause that asks a direct question, such as “has ganga been used as a communication method.”"}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Standard English Conventions'), 'medium', 'source', 'approved', 19, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text so that it conforms to the conventions of Standard English?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice B is the best answer. The convention being tested is the use of verb forms within a sentence. The nonfinite to-infinitive verb “to create” is correctly used to form a subordinate clause that expresses how ArcGIS facilitates the creation of maps (by analyzing and arranging certain data)."}, {"type": "paragraph", "text": "Choice A is incorrect because it results in an ungrammatical sentence. The finite verb “create” can’t be used in this way to form a subordinate clause that expresses how ArcGIS facilitates the creation of maps. Choice C is incorrect because it results in an ungrammatical sentence. The nonfinite participle “creating” can’t be used in this way to form a subordinate clause that expresses how ArcGIS facilitates the creation of maps. Choice D is incorrect because it results in an ungrammatical sentence. The finite verb “created” can’t be used in this way to form a subordinate clause that expresses how ArcGIS facilitates the creation of maps."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Standard English Conventions'), 'medium', 'source', 'approved', 20, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text so that it conforms to the conventions of Standard English?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice B is the best answer. The convention being tested is punctuation use between a verb and its complement. No punctuation is needed between the verb “is called” and its complement “the chromophore.” The complement helps complete the idea of the verb—in this case, it explains what the part of a compound that determines the compound’s color is called—and any punctuation between the two results in an ungrammatical sentence."}, {"type": "paragraph", "text": "Choice A is incorrect because no punctuation is needed between the verb and its complement. Choice C is incorrect because no punctuation is needed between the verb and its complement. Choice D is incorrect because no punctuation is needed between the verb and its complement."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Standard English Conventions'), 'medium', 'source', 'approved', 21, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text so that it conforms to the conventions of Standard English?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice B is the best answer. The convention being tested is the use of punctuation within a sentence. This choice correctly uses a dash after “cooperation” to pair with the dash after “that” to separate the supplementary element “assuming solar panel installers’ cooperation” from the rest of the sentence."}, {"type": "paragraph", "text": "Choice A is incorrect because a comma can’t be paired with a dash in this way to separate the supplementary element from the rest of the sentence. Choice C is incorrect because a colon can’t be paired with a dash in this way to separate the supplementary element from the rest of the sentence. Choice D is incorrect because it fails to use appropriate punctuation to separate the supplemental element from the rest of the sentence."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Standard English Conventions'), 'medium', 'source', 'approved', 22, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text so that it conforms to the conventions of Standard English?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice B is the best answer. The convention being tested is the use of punctuation within a sentence. The comma after “newts” pairs with the comma after “instance” to separate the supplementary element “for instance” from the rest of the sentence. The supplementary element appears between the prepositional phrase (“In…newts”) and the main clause of the sentence (“you… orientalis”) and signals that the sentence is presenting an example of how keys and values function in JSON files."}, {"type": "paragraph", "text": "Choice A is incorrect because it results in a sentence fragment (“In a JSON file storing data about fire belly newts”). Choice C is incorrect because a colon can’t be paired with a comma in this way to separate the supplementary element “for instance” from the rest of the sentence. Choice D is incorrect because a semicolon can’t be paired with a comma in this way to separate the supplementary element “for instance” from the rest of the sentence."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Standard English Conventions'), 'medium', 'source', 'approved', 23, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text so that it conforms to the conventions of Standard English?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice B is the best answer. The convention being tested is subject-modifier placement. This choice makes the noun phrase “amorphous ice” the subject of the sentence and places it immediately after the modifying phrase “defined… structure.” In doing so, this choice clearly establishes that amorphous ice—and not another noun in the sentence—is being described as having a disorganized molecular structure."}, {"type": "paragraph", "text": "Choice A is incorrect because it results in a dangling modifier. The placement of the noun “ice Ih” immediately after the modifying phrase illogically suggests that ice Ih has a disorganized molecular structure, whereas ice Ih is previously described as having molecules that form a hexagonal pattern. Choice C is incorrect because it results in a dangling modifier. The placement of the noun phrase “the lack of thermal energy” immediately after the modifying phrase illogically suggests that the lack of thermal energy has a disorganized molecular structure. Choice D is incorrect because it results in a dangling modifier. The placement of “ice Ih” immediately after the modifying phrase illogically suggests that ice Ih has a disorganized molecular structure, whereas ice Ih is previously described as having molecules that form a hexagonal pattern."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Standard English Conventions'), 'medium', 'source', 'approved', 24, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text so that it conforms to the conventions of Standard English?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice A is the best answer. The convention being tested is subject-modifier placement. This choice makes the noun “electrograms” the subject of the sentence and places it immediately after the modifying phrase “recordings of electrical activity in the brain.” In doing so, this choice clearly establishes that electrograms—and not other nouns or noun phrases in the sentence—are recordings of electrical activity in the brain."}, {"type": "paragraph", "text": "Choice B is incorrect because it results in a dangling modifier. The placement of the noun phrase “the most highly skilled soccer players” immediately after the modifying phrase illogically suggests that the players are recordings of electrical activity in the brain. Choice C is incorrect because it results in a dangling modifier. The placement of the noun phrase “responses to hypothetical match scenarios” immediately after the modifying phrase illogically suggests that these responses are recordings of electrical activity in the brain. Choice D is incorrect because it results in a dangling modifier. The placement of the noun phrase “hypothetical match scenario responses” immediately after the opening phrase illogically suggests that these responses are recordings of electrical activity in the brain."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Standard English Conventions'), 'medium', 'source', 'approved', 25, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text so that it conforms to the conventions of Standard English?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice B is the best answer. The convention being tested is the use of verb forms within a sentence. The nonfinite present participle “searching” is correctly used to form a supplementary element that modifies the subject “scientists,” indicating that the scientists who adapted the test were looking for evidence of self- awareness in snakes."}, {"type": "paragraph", "text": "Choice A is incorrect because it results in an ungrammatical sentence. The finite past tense verb “searched” can’t be used in this way to form a supplementary element that indicates what evidence the scientists who adapted the test were looking for. Choice C is incorrect because it results in an ungrammatical sentence. The finite past progressive verb “were searching” can’t be used in this way to form a supplementary element that indicates what evidence the scientists who adapted the test were looking for. Choice D is incorrect because it results in an ungrammatical sentence. The finite present perfect verb “have searched” can’t be used in this way to form a supplementary element that indicates what evidence the scientists who adapted the test were looking for."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Standard English Conventions'), 'medium', 'source', 'approved', 26, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text with the most logical transition?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice D is the best answer. “Finally” logically signals that the information in this sentence—that the artisan slips paper in and out of the liquid to transfer the design onto paper—is the final step in the process of Turkish paper marbling, which began with what happens “first” (filling a tray with a solution) and continued with what happens “next” (adding inks or paints to the solution)."}, {"type": "paragraph", "text": "Choice A is incorrect because “actually” illogically signals that the information in this sentence about slipping paper in and out of liquid to transfer a design onto paper is unexpected in light of the previously described steps. Instead, the sentence describes the final step in the process of Turkish paper marbling."}, {"type": "paragraph", "text": "Choice B is incorrect because “therefore” illogically signals that the information in this sentence about slipping paper in and out of liquid to transfer a design onto paper is a consequence of the previously described steps. Instead, the sentence describes the final step in the process of Turkish paper marbling. Choice C is incorrect because “nevertheless” illogically signals that the information in this sentence about slipping paper in and out of liquid to transfer a design onto paper contrasts with the previously described steps. Instead, the sentence describes the final step in the process of Turkish paper marbling."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Expression of Ideas'), 'medium', 'source', 'approved', 27, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text with the most logical transition?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice B is the best answer. “Instead” logically signals that the information about the researchers’ discovery in this sentence—that jorō spiders are gentle giants who “freeze” in place when disturbed—contradicts their initial hypothesis about the spiders’ aggressiveness described in the previous sentence."}, {"type": "paragraph", "text": "Choice A is incorrect because “therefore” illogically signals that the discovery about jorō spiders’ gentleness is a result of the initial hypothesis about their aggressive behavior. Instead, the sentence presents information that contradicts the initial hypothesis. Choice C is incorrect because “for example” illogically signals that the discovery about jorō spiders’ gentleness exemplifies the initial hypothesis about their aggressive behavior. Instead, the sentence presents information that contradicts the initial hypothesis. Choice D is incorrect because “in other words” illogically signals that the discovery about jorō spiders’ gentleness is merely restating or rephrasing the initial hypothesis about their aggressive behavior. Instead, the sentence presents information that contradicts the initial hypothesis."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Expression of Ideas'), 'medium', 'source', 'approved', 28, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text with the most logical transition?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice C is the best answer. “Indeed” logically signals that the information that follows—that the majority of jets reach heights of only 20 to 50 km—offers additional emphasis in support of the previous claim that jets reaching the ionosphere (about 80 km above Earth) are outliers."}, {"type": "paragraph", "text": "Choice A is incorrect because “nevertheless” illogically signals that the information about most jets reaching heights of only 20 to 50 km contrasts with the previous claim that jets reaching the ionosphere are outliers. Instead, it provides additional emphasis in support of that claim. Choice B is incorrect because “consequently” illogically signals that the information about most jets reaching heights of only 20 to 50 km is a consequence, or result, of some jets being outliers. Instead, it offers additional emphasis in support of the claim that jets reaching the ionosphere are outliers. Choice D is incorrect because “in addition” illogically signals that the information about most jets reaching heights of only 20 to 50 km merely adds to the previous claim that jets reaching the ionosphere are considered outliers. Instead, it provides additional emphasis in support of that claim."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Expression of Ideas'), 'medium', 'source', 'approved', 29, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text with the most logical transition?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice B is the best answer. “Ultimately” logically signals that the information in this sentence—that, for Dillard, nature’s mesmerizing intricacy and pitiless harshness are inextricably linked—is the final conclusion or realization reached after her struggle to reconcile the juxtapositions of the natural world mentioned in the previous sentence."}, {"type": "paragraph", "text": "Choice A is incorrect because “to that end” illogically signals that linking nature’s intricacy and harshness was Dillard’s deliberate goal or purpose in struggling to reconcile nature’s juxtapositions. Instead, the sentence presents her final realization after that struggle. Choice C is incorrect because “moreover” illogically signals that the information in this sentence merely adds to Dillard’s struggle to reconcile nature’s juxtapositions mentioned in the previous sentence. Instead, the sentence presents her final realization after that struggle. Choice D is incorrect because “hence” illogically signals that nature’s intricacy and harshness being linked is a direct consequence of Dillard’s struggle to reconcile the juxtapositions mentioned in the previous sentence. Instead, the sentence presents her final realization after that struggle."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Expression of Ideas'), 'medium', 'source', 'approved', 30, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice most effectively uses relevant information from the notes to accomplish this goal?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice C is the best answer. The sentence presents the methods used in the study, noting that researchers tagged 138 female wood ducks with radio frequency ID trackers and recorded the number of nest boxes each duck visited."}, {"type": "paragraph", "text": "Choice A is incorrect. While the sentence mentions an aspect of the study’s design (that the researchers recorded the number of nest boxes the wood ducks visited), it primarily focuses on a finding of the study rather than the methods the researchers used. Choice B is incorrect. While the sentence mentions an aspect of the study’s design (that the researchers tracked the number of nest boxes the wood ducks visited), it primarily focuses on a finding of the study rather than the methods the researchers used. Choice D is incorrect. The sentence misrepresents information from the notes. The researchers used radio frequency ID trackers to record the ducks’ visits; they didn’t investigate each site to look for evidence that it had been visited."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 31, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice most effectively uses relevant information from the notes to accomplish this goal?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice A is the best answer. The sentence emphasizes a similarity between the ages of the two pedestrian malls, noting that both are relatively old—Qianmen Dajie has roots that go back hundreds of years and Rue Mouffetard has existed for centuries."}, {"type": "paragraph", "text": "Choice B is incorrect. The sentence emphasizes that both locations are famous pedestrian malls and notes that they are in different locations; it doesn’t emphasize a similarity in their ages. Choice C is incorrect. While the sentence emphasizes that both locations are pedestrian malls, it doesn’t emphasize a similarity in their ages. Choice D is incorrect. The sentence explains that Qianmen Dajie and Rue Mouffetard are examples of pedestrian malls and gives information about pedestrian malls in general; it doesn’t emphasize a similarity in the ages of these two malls specifically."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 32, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice most effectively uses relevant information from the notes to accomplish this goal?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice A is the best answer. The sentence compares Fodor’s hypothesis with Carruthers’s, noting that because Fodorian modularity considers some but not all cognitive systems modular, it is not as expansive in its definition of modularity as Carruthers’s MMH, which includes all cognitive systems."}, {"type": "paragraph", "text": "Choice B is incorrect. The sentence describes Carruthers’s hypothesis—that modularity of mind includes all cognitive systems—but indicates only that this hypothesis followed Fodor’s 1983 hypothesis rather than making a comparison between the hypotheses. Choice C is incorrect. The sentence misrepresents a difference between Fodor’s and Carruthers’s hypotheses. According to the information in the notes, both Fodor and Carruthers consider low-level cognitive systems modular, and their difference lies in whether they also consider high-level systems modular. Choice D is incorrect. The sentence misrepresents a difference between Fodor’s and Carruthers’s hypotheses. According to the information in the notes, both Fodor and Carruthers consider the mind to be at least partly composed of innate neural structures (modules). Their difference lies in whether they consider high-level systems modular."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 33, 'choice', array[]::text[]) returning id into v_q;
    update public.exams set status = 'published' where id = v_exam;
  end if;
  -- SAT Practice Test 11: Math
  if exists (select 1 from public.exams where slug = 'sat-practice-test-11-math') then
    raise notice 'skipping sat-practice-test-11-math (already imported)';
  else
    select id into v_subject from public.subjects where code = 'sat-math';
    values (v_subject, 'sat-practice-test-11-math', 'SAT Practice Test 11: Math', 'Official SAT Practice Test 11 (College Board), Math: 54 questions in two modules, including student-produced responses. Calculator allowed; 43 minutes per module.', 'full_mock', 'premium', 'draft', 86, 'source', 223, '[[200, 200], [210, 220], [210, 220], [210, 230], [220, 240], [230, 250], [240, 270], [250, 290], [260, 320], [270, 330], [290, 350], [310, 350], [330, 370], [340, 380], [350, 390], [350, 390], [360, 400], [370, 410], [370, 410], [380, 420], [390, 430], [390, 430], [400, 440], [410, 450], [410, 450], [420, 460], [430, 470], [440, 480], [450, 490], [460, 500], [470, 510], [480, 520], [490, 530], [490, 550], [500, 560], [510, 570], [530, 590], [540, 600], [550, 610], [560, 620], [570, 630], [590, 650], [600, 660], [610, 670], [620, 680], [640, 700], [650, 710], [660, 720], [680, 740], [700, 760], [710, 770], [730, 780], [750, 800], [770, 800], [790, 800]]'::jsonb)
    returning id into v_exam;
    values (v_subject, null, null, '{"blocks": [{"type": "image", "src": "/sat/test-11/math-m1-q01.png", "alt": "Figure for question 1", "width": 276}, {"type": "paragraph", "text": "In the triangle shown, $PQ = QR$. What is the value of $x$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Since $PQ = QR$, the angles opposite those sides are equal: angle $R$ equals angle $P$, so $x = 24$. (Check: $24 + 24 + 132 = 180$.)"}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Geometry and Trigonometry'), 'easy', 'source', 'approved', 1, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "math", "latex": "4x + 1 = 33"}, {"type": "paragraph", "text": "Which equation has the same solution as the given equation?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Subtracting $1$ from both sides gives $4x = 32$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'easy', 'source', 'approved', 2, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "For the linear function $f$, the graph of $y = f(x)$ in the $xy$-plane has a slope of $7$ and passes through the point $(0, 5)$. Which equation defines $f$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Slope $7$ and $y$-intercept $5$: $f(x) = 7x + 5$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'easy', 'source', 'approved', 3, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "math", "latex": "8x^2 - 40 = 32"}, {"type": "paragraph", "text": "What is the positive solution to the given equation?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$8x^2 = 72$, so $x^2 = 9$ and the positive solution is $3$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Advanced Math'), 'easy', 'source', 'approved', 4, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "image", "src": "/sat/test-11/math-m1-q05.png", "alt": "Figure for question 5", "width": 270}, {"type": "paragraph", "text": "A total of $50$ children attended a summer camp and were offered $4$ types of sandwiches. The table shows the number of children who chose each type of sandwich."}, {"type": "paragraph", "text": "If one of these children is selected at random, what is the probability of selecting a child who chose a vegetarian sandwich?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$9$ of the $50$ children chose vegetarian: $\\tfrac{9}{50}$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Problem-Solving and Data Analysis'), 'easy', 'source', 'approved', 5, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "Amara grows cherry tomatoes in her backyard. This year, she harvested $750$ cherry tomatoes and gave $10\\%$ of them to her neighbor. How many of the harvested cherry tomatoes did Amara give to her neighbor?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$0.10 \\times 750 = 75$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Problem-Solving and Data Analysis'), 'easy', 'source', 'approved', 6, 'spr', array['75']::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "math", "latex": "\\begin{aligned} x + y &= 125 \\\\ x + y + y &= 155 \\end{aligned}"}, {"type": "paragraph", "text": "The solution to the given system of equations is $(x, y)$. What is the value of $y$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "The second equation is the first plus $y$: $125 + y = 155$, so $y = 30$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'easy', 'source', 'approved', 7, 'spr', array['30']::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "In a chess tournament, each participant earns $1$ point for each game the participant plays that ends in a draw and $3$ points for each game the participant wins. A certain participant in this tournament has earned $41$ points. Which equation represents this situation, where $d$ represents the number of games this participant has played that ended in a draw and $w$ represents the number of games this participant has won?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Draws earn $1$ point each ($d$) and wins $3$ points each ($3w$): $d + 3w = 41$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'easy', 'source', 'approved', 8, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "The function $g$ is defined by $g(x) = \\sqrt{x} + 300$. What is the value of $g(x)$ when $x = 81$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$g(81) = 9 + 300 = 309$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Advanced Math'), 'easy', 'source', 'approved', 9, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "A cable provider wanted to know how many of its $30{,}000$ customers would be interested in a new service plan. The provider selected $300$ customers at random and asked each customer whether the customer would be interested in the new plan. Of those surveyed, $8$ said they would be interested. Which of the following is the best estimate of the total number of customers who would be interested in the new service plan?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "The sample is $\\tfrac{300}{30{,}000} = \\tfrac{1}{100}$ of all customers, so the estimate is $8 \\times 100 = 800$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Problem-Solving and Data Analysis'), 'easy', 'source', 'approved', 10, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "Which expression is equivalent to $64t^2s^3 - 56t^3s$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Expand D: $4t^2s \\cdot 16s^2 = 64t^2s^3$ and $4t^2s \\cdot 14t = 56t^3s$. The other choices expand to different terms."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Advanced Math'), 'medium', 'source', 'approved', 11, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "math", "latex": "\\begin{aligned} x + 5 &= 14 \\\\ y &= 4x^2 + 4 \\end{aligned}"}, {"type": "paragraph", "text": "At what point $(x, y)$ do the graphs of the equations in the given system intersect?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$x = 9$, so $y = 4(81) + 4 = 328$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Advanced Math'), 'easy', 'source', 'approved', 12, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "math", "latex": "8x + 11y = 170"}, {"type": "paragraph", "text": "The equation gives the possible combinations of the number of $2009$ premium grade Log Cabin Pennies, $x$, and the number of $1996$ select grade Lincoln Pennies, $y$, in a collection that is worth a total of $\\$170$. If there are $6$ $1996$ select grade Lincoln Pennies in the collection, how many $2009$ premium grade Log Cabin Pennies are in the collection?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$8x + 66 = 170$, so $8x = 104$ and $x = 13$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'easy', 'source', 'approved', 13, 'spr', array['13']::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "The population of the town of Smithville doubled every $75$ years from $1659$ to $1959$. The population of this town was $240{,}000$ in $1959$. What was the population of this town in $1659$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$300$ years is $4$ doubling periods, so the population grew by a factor of $2^4 = 16$: $\\tfrac{240{,}000}{16} = 15{,}000$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Advanced Math'), 'medium', 'source', 'approved', 14, 'spr', array['15000']::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "image", "src": "/sat/test-11/math-m1-q15.png", "alt": "Figure for question 15", "width": 267}, {"type": "paragraph", "text": "The scatterplot shows the relationship between $x$ and $y$. A line of best fit is also shown."}, {"type": "paragraph", "text": "Which of the following is closest to the slope of this line of best fit?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "The line rises from about $3.2$ at $x = 0$ to about $9.2$ at $x = 10$: a slope of about $\\tfrac{6}{10} = 0.6$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Problem-Solving and Data Analysis'), 'easy', 'source', 'approved', 15, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "Which quadratic equation has exactly one distinct real solution?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$(x + 15)^2 = 0$ only when $x = -15$. B has no real solutions, and C and D have two."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Advanced Math'), 'medium', 'source', 'approved', 16, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "The cost to rent a bus from Company X is $\\$950$ for the first $3$ hours and an additional $\\$50$ per hour for each hour after the first $3$ hours. If the total cost to rent the bus from Company X for $t$ hours, where $t > 3$, is $\\$1{,}150$, which equation represents this situation?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "The first $3$ hours cost $\\$950$, and each of the remaining $t - 3$ hours costs $\\$50$: $950 + 50(t - 3) = 1{,}150$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'medium', 'source', 'approved', 17, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "math", "latex": "\\begin{aligned} x + y &= 53 \\\\ 11x + 18y &= 730 \\end{aligned}"}, {"type": "paragraph", "text": "The given equations represent the possible numbers of beach chairs, $x$, and umbrellas, $y$, rented at a park last month and the total spent, in dollars, to rent those beach chairs and umbrellas. Which of the following graphs represents this situation?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$x + y = 53$ has both intercepts at $53$, and $11x + 18y = 730$ has intercepts near $(66.4, 0)$ and $(0, 40.6)$. Both lines slope downward; graph B shows exactly these two lines."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'medium', 'source', 'approved', 18, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "image", "src": "/sat/test-11/math-m1-q19.png", "alt": "Figure for question 19", "width": 302}, {"type": "paragraph", "text": "In triangle $QRS$ shown, $QR < RS$. Which expression represents the length of $\\overline{QS}$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$RS = 18$ is opposite angle $Q$ and $QS$ is the hypotenuse, so $\\sin Q = \\dfrac{18}{QS}$ and $QS = \\dfrac{18}{\\sin Q}$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Geometry and Trigonometry'), 'medium', 'source', 'approved', 19, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "Circle A in the $xy$-plane has the equation $(x + 5)^2 + (y - 5)^2 = 25$. Circle B has the same center as circle A. The radius of circle B is two times the radius of circle A. The equation defining circle B in the $xy$-plane is $(x + 5)^2 + (y - 5)^2 = k$, where $k$ is a constant. What is the value of $k$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Circle A''s radius is $5$, so circle B''s radius is $10$ and $k = 10^2 = 100$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Geometry and Trigonometry'), 'medium', 'source', 'approved', 20, 'spr', array['100']::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "math", "latex": "x^2 + 7x + 5 = 0"}, {"type": "paragraph", "text": "One solution to the given equation can be written as $x = \\dfrac{-7 + \\sqrt{k}}{2}$, where $k$ is a constant. What is the value of $k$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "By the quadratic formula, $x = \\dfrac{-7 \\pm \\sqrt{49 - 20}}{2} = \\dfrac{-7 \\pm \\sqrt{29}}{2}$, so $k = 29$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Advanced Math'), 'medium', 'source', 'approved', 21, 'spr', array['29']::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "A scientist measured the lengths of $240$ gray seals from Muskeget Island and $120$ gray seals from Sable Island. The scientist determined that the mean length of the $240$ gray seals from Muskeget Island was $88$ inches and the mean length of the $120$ gray seals from Sable Island was $94$ inches. What was the mean length of all $360$ gray seals the scientist measured for this study?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Total length $= 240(88) + 120(94) = 21{,}120 + 11{,}280 = 32{,}400$, and $\\tfrac{32{,}400}{360} = 90$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Problem-Solving and Data Analysis'), 'medium', 'source', 'approved', 22, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "image", "src": "/sat/test-11/math-m1-q23.png", "alt": "Figure for question 23", "width": 315}, {"type": "paragraph", "text": "The graph of $y = f(x) + 4$ is shown. Which equation defines function $f$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "The graph crosses the $y$-axis at $8$, so $f(0) + 4 = 8$ and $f(0) = 4$. For $f(x) = -3^x + c$, $f(0) = -1 + c = 4$ gives $c = 5$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Advanced Math'), 'hard', 'source', 'approved', 23, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "Two lines intersect at exactly one point, forming two acute angles and two obtuse angles. The measure of one of these angles is $(9x - 140)^\\circ$. Which of the following could **NOT** be the sum of the measures of any two of these angles?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "If $(9x - 140)^\\circ$ is one angle, the other angles are $(9x - 140)^\\circ$ and $(320 - 9x)^\\circ$ twice each. The possible sums are $18x - 280$, $640 - 18x$, and $180$. $(-18x + 280)^\\circ$ is not one of them."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Geometry and Trigonometry'), 'hard', 'source', 'approved', 24, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "math", "latex": "2x + 9y = 7"}, {"type": "paragraph", "text": "The given equation is one equation in a system of two linear equations. If the system of equations has at least one solution, which of the following equations could be the other equation in the system?"}, {"type": "math", "latex": "\\begin{aligned} &\\text{I. } 3x + 13.5y = 10.5 \\\\ &\\text{II. } 3x - 13.5y = 10.5 \\end{aligned}"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Equation I is $1.5$ times the given equation, the same line, so the system has infinitely many solutions. Equation II has a different slope, so it meets the given line at exactly one point. Both work."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'hard', 'source', 'approved', 25, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "A right rectangular prism has a base area of $24t$ square centimeters (cm$^2$). The length of the base of the rectangular prism is $\\dfrac{8}{3}$ cm, and the height of the rectangular prism is $15$ cm. Which expression represents the surface area, in cm$^2$, of the right rectangular prism?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "The base width is $24t \\div \\tfrac{8}{3} = 9t$. Surface area $= 2(24t) + 2\\left(\\tfrac{8}{3}\\right)(15) + 2(9t)(15) = 48t + 80 + 270t = 318t + 80$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Geometry and Trigonometry'), 'hard', 'source', 'approved', 26, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "For a particular car, the linear function $f$ gives the predicted power, in brake horsepower (bhp), for engine speeds between $1{,}000$ revolutions per minute (rpm) and $6{,}000$ rpm. According to this function, the car''s predicted power is $433$ bhp at an engine speed of $3{,}331$ rpm and $600$ bhp at an engine speed of $4{,}500$ rpm. The equation $f(x) = \\dfrac{1}{7}(x - a) + 433$ defines $f$, where $x$ is the engine speed, in rpm, and $a$ is a constant. What is the value of $a$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$f(a) = 433$, and we know $f(3{,}331) = 433$, so $a = 3{,}331$. (The slope $\\tfrac{600 - 433}{4{,}500 - 3{,}331} = \\tfrac{167}{1{,}169} = \\tfrac{1}{7}$ confirms the form.)"}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'hard', 'source', 'approved', 27, 'spr', array['3331']::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "Which expression is equivalent to $6x + 5x + 4y$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Combine the like terms $6x + 5x = 11x$; $4y$ stays: $11x + 4y$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Advanced Math'), 'easy', 'source', 'approved', 1, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "image", "src": "/sat/test-11/math-m2-q02.png", "alt": "Figure for question 2", "width": 142}, {"type": "paragraph", "text": "To study the characteristics of sea stars in a group of tide pools, researchers measured the diameter of the sea stars within the tide pools. The dot plot gives the diameter, to the nearest inch, of each of the sea stars in these tide pools."}, {"type": "paragraph", "text": "Based on the dot plot, how many sea stars had a diameter, to the nearest inch, of $16$ inches?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "There are $6$ dots above $16$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Problem-Solving and Data Analysis'), 'easy', 'source', 'approved', 2, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "A rectangle has a length of $56$ inches and a width of $28$ inches. What is the area, in square inches, of the rectangle?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$56 \\times 28 = 1{,}568$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Geometry and Trigonometry'), 'easy', 'source', 'approved', 3, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "math", "latex": "\\begin{aligned} 10x &= 110 \\\\ 6x - 63 &= y \\end{aligned}"}, {"type": "paragraph", "text": "The solution to the given system of equations is $(x, y)$. What is the value of $y$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$x = 11$, so $y = 66 - 63 = 3$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'easy', 'source', 'approved', 4, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "The function $f$ is defined by $f(x) = 9(2x + 3)$. For what value of $x$ does $f(x) = 63$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$2x + 3 = 7$, so $x = 2$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'easy', 'source', 'approved', 5, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "math", "latex": "10x = 86"}, {"type": "paragraph", "text": "What value of $x$ is the solution to the given equation?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$x = \\tfrac{86}{10} = 8.6$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'easy', 'source', 'approved', 6, 'spr', array['8.6', '43/5']::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "math", "latex": "y = 3{,}600(a)^x"}, {"type": "paragraph", "text": "The given equation, where $a$ is a positive constant, gives the predicted number of bacteria, $y$, in a growth medium $x$ hours after the number of bacteria was initially measured. According to the equation, what was the predicted number of bacteria initially measured in the growth medium?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "At $x = 0$, $y = 3{,}600(a)^0 = 3{,}600$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Advanced Math'), 'easy', 'source', 'approved', 7, 'spr', array['3600']::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "Leo goes to a packing store to buy containers and tape. Leo has $\\$15$. Each container costs $\\$1.87$ and each roll of tape costs $\\$2.40$. Which inequality represents the relationship between the number of containers, $c$, and the number of rolls of tape, $t$, Leo can buy?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Containers cost $1.87c$, tape costs $2.40t$, and the total can be at most $\\$15$: $1.87c + 2.40t \\le 15$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'easy', 'source', 'approved', 8, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "image", "src": "/sat/test-11/math-m2-q09.png", "alt": "Figure for question 9", "width": 264}, {"type": "paragraph", "text": "The graph of the function $f$ is shown, where $y = f(x)$."}, {"type": "paragraph", "text": "Which of the following best describes the function $f$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "The curve stays near $0$ on the left, then rises more and more steeply: increasing exponential."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Advanced Math'), 'easy', 'source', 'approved', 9, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "image", "src": "/sat/test-11/math-m2-q10.png", "alt": "Figure for question 10", "width": 314}, {"type": "paragraph", "text": "The shaded region shown in the graph represents all the solutions to which inequality?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "The region is everything on or above the horizontal line $y = 36$: $y \\ge 36$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'easy', 'source', 'approved', 10, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "There are $240$ players in a tennis competition that includes $4$ rounds of matches. Each player in the competition will play a match against another player in round 1. At the end of each round, the player who loses the match is eliminated and the player who won the match advances to the next round to play a match against another winning player. Which equation gives the number of players, $p$, eliminated at the end of round $r$, where $r \\le 4$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Half the remaining players are eliminated each round: $120$, $60$, $30$, $15$. That is $p = 240\\left(\\tfrac{1}{2}\\right)^r$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Advanced Math'), 'medium', 'source', 'approved', 11, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "Line $k$ is defined by $y = 6x + 4$. Line $j$ is parallel to line $k$ in the $xy$-plane and passes through the point $(0, 5)$. Which equation defines line $j$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Same slope, $6$, and $y$-intercept $5$: $y = 6x + 5$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'easy', 'source', 'approved', 12, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "image", "src": "/sat/test-11/math-m2-q13.png", "alt": "Figure for question 13", "width": 267}, {"type": "paragraph", "text": "In the triangle shown, what is the value of $x$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "The legs are equal ($15$ and $15$), so it is an isosceles right triangle and both acute angles are $45^\\circ$: $x = 45$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Geometry and Trigonometry'), 'easy', 'source', 'approved', 13, 'spr', array['45']::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "What is the radius of the circle in the $xy$-plane defined by $(x + 2)^2 + (y + 5)^2 = 169$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$r^2 = 169$, so $r = 13$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Geometry and Trigonometry'), 'easy', 'source', 'approved', 14, 'spr', array['13']::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "image", "src": "/sat/test-11/math-m2-q15.png", "alt": "Figure for question 15", "width": 312}, {"type": "paragraph", "text": "The graph shows the estimated boiling point $y$, in degrees Celsius, of a normal paraffin with a molecular weight of $x$ grams per mole, where $1 \\le x \\le 280$. Which statement is the best interpretation of the point $(149.02, 186.05)$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$x = 149.02$ is the molecular weight and $y = 186.05$ is the boiling point. The point is neither the lowest nor the highest on the curve."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Advanced Math'), 'easy', 'source', 'approved', 15, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "For the polynomial function $f$, the graph of $y = f(x)$ in the $xy$-plane passes through the points $(-5, 0)$, $(1, 0)$, and $(4, 0)$. Which of the following must be a factor of $f(x)$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$f(1) = 0$, so $x - 1$ is a factor. (The other factors are $x + 5$ and $x - 4$.)"}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Advanced Math'), 'easy', 'source', 'approved', 16, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "table", "header": ["$x$", "$g(x)$"], "rows": [["$1$", "$32$"], ["$2$", "$28$"], ["$3$", "$24$"], ["$4$", "$20$"]]}, {"type": "paragraph", "text": "For the linear function $g$, the table shows four values of $x$ and their corresponding values of $g(x)$. The function can be written as $g(x) = mx + b$, where $m$ and $b$ are constants. What is the value of $b$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "The slope is $-4$, and going back one step from $x = 1$ gives $g(0) = 32 + 4 = 36$, so $b = 36$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'medium', 'source', 'approved', 17, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "table", "header": ["$x$", "$24$", "$30$", "$32$"], "rows": [["$f(x)$", "$-8$", "$-8$", "$8$"]]}, {"type": "paragraph", "text": "For the quadratic function $f$, the table shows three values of $x$ and their corresponding values of $f(x)$. Which equation defines $f$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "B gives $f(24) = f(30) = -8$ and $f(32) = (8)(2) - 8 = 8$, matching all three values. A gives $4$ at $x = 24$, and C and D don''t give $-8$ at both $24$ and $30$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Advanced Math'), 'medium', 'source', 'approved', 18, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "image", "src": "/sat/test-11/math-m2-q19.png", "alt": "Figure for question 19", "width": 288}, {"type": "paragraph", "text": "A certain open star cluster contains M-type stars and K-type stars. The estimated total mass of M-type and K-type stars in this open star cluster is $127{,}882$ quettagrams. The graph shown models the possible combinations of the number of M-type stars, $x$, and K-type stars, $y$, that could be in this open star cluster if all the M-type stars have the same estimated mass and all the K-type stars have the same estimated mass. Based on the graph, which of the following is closest to the estimated mass, in quettagrams, of each M-type star in this cluster?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "The $x$-intercept (about $158$) is the number of M-type stars if there are no K-type stars, so each M-type star has mass about $\\tfrac{127{,}882}{158} \\approx 811$ quettagrams."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'hard', 'source', 'approved', 19, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "math", "latex": "\\sqrt[3]{p^2} = t^{\\frac{9}{7}}"}, {"type": "paragraph", "text": "In the given equation, $p > 1$ and $t > 1$. If $t = p^{3n - 1}$, where $n$ is a constant, what is the value of $n$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$p^{2/3} = \\left(p^{3n - 1}\\right)^{9/7}$, so $\\tfrac{9}{7}(3n - 1) = \\tfrac{2}{3}$. Then $3n - 1 = \\tfrac{14}{27}$, $3n = \\tfrac{41}{27}$, and $n = \\tfrac{41}{81}$ (about $0.5062$)."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Advanced Math'), 'hard', 'source', 'approved', 20, 'spr', array['.5061', '.5062', '41/81']::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "The number $a$ is $55\\%$ less than the number $b$. The number $b$ is $320\\%$ greater than $160$. What is the value of $a$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$b = 160(1 + 3.2) = 672$, and $a = 672(1 - 0.55) = 302.4$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Problem-Solving and Data Analysis'), 'hard', 'source', 'approved', 21, 'spr', array['1512/5', '302.4']::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "math", "latex": "f(x) = -6x^2 + 60x - 126"}, {"type": "paragraph", "text": "The function $f$ is defined by the given equation. Which of the following equivalent forms of the equation displays the maximum value of the function as a constant or coefficient?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Vertex form $-6(x - 5)^2 + 24$ shows the maximum, $24$, as a constant."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Advanced Math'), 'medium', 'source', 'approved', 22, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "image", "src": "/sat/test-11/math-m2-q23.png", "alt": "Figure for question 23", "width": 333}, {"type": "paragraph", "text": "In the figure shown, $\\overline{WZ}$ and $\\overline{XY}$ intersect at point $Q$. $YQ = 21$, $WQ = 70$, $WX = 60$, and $XQ = 120$. What is the length of $\\overline{YZ}$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "The angles marked $a^\\circ$ are equal and the angles at $Q$ are vertical, so triangles $QWX$ and $QYZ$ are similar with ratio $\\tfrac{WQ}{YQ} = \\tfrac{70}{21} = \\tfrac{10}{3}$. So $YZ = \\tfrac{3}{10}(60) = 18$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Geometry and Trigonometry'), 'hard', 'source', 'approved', 23, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "math", "latex": "52(x^3 + 64)(x^4 - 81) = 0"}, {"type": "paragraph", "text": "How many distinct real solutions does the given equation have?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$x^3 = -64$ gives $x = -4$, and $x^4 = 81$ gives $x = 3$ or $x = -3$. That is three distinct real solutions."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Advanced Math'), 'hard', 'source', 'approved', 24, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "image", "src": "/sat/test-11/math-m2-q25.png", "alt": "Figure for question 25", "width": 238}, {"type": "paragraph", "text": "The histogram summarizes data set A, which represents the number of points per player earned by $50$ players of a game. A new player earns $18$ points playing the game, and this number of points is added to data set A to create data set B with $51$ values. Which of the following must be true?"}, {"type": "paragraph", "text": "I. The median number of points per player for data set B is less than the median number of points per player for data set A."}, {"type": "paragraph", "text": "II. The mean number of points per player for data set B is less than the mean number of points per player for data set A."}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Every original value is at least $30$, so adding $18$ lowers the mean: II is true. The old median is the average of the $25$th and $26$th values and the new median is the old $25$th value. Both are in the $50$ to $60$ bar and could be equal, so I need not be true."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Problem-Solving and Data Analysis'), 'hard', 'source', 'approved', 25, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "In triangle $XYZ$, the measure of angle $X$ is $90^\\circ$. Point $W$ lies on segment $YZ$, and segment $WX$ is perpendicular to segment $YZ$. The length of segment $WY$ is $572$, and the length of segment $WX$ is $429$. What is the value of $\\tan Z$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "In right triangle $XWY$, $\\tan Y = \\tfrac{429}{572} = \\tfrac{3}{4}$. Angles $Y$ and $Z$ are complementary, so $\\tan Z = \\tfrac{4}{3}$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Geometry and Trigonometry'), 'hard', 'source', 'approved', 26, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "An area of $46.00$ square nautical miles is equivalent to $k$ square kilometers. To the nearest tenth, what is the value of $k$? ($1$ nautical mile $= 1.852$ kilometers)"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "One square nautical mile is $1.852^2 \\approx 3.4299$ square kilometers, so $k = 46 \\times 3.4299 \\approx 157.8$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Problem-Solving and Data Analysis'), 'hard', 'source', 'approved', 27, 'spr', array['157.8', '789/5']::text[]) returning id into v_q;
    update public.exams set status = 'published' where id = v_exam;
  end if;
end $sat$;
