    insert into public.stimuli (subject_id, kind, content, origin) values (v_subject, 'passage', '{"blocks": [{"type": "paragraph", "text": "While researching a topic, a student has taken the following notes:"}, {"type": "list", "items": ["Chemical leavening agents cause carbon dioxide to be released within a liquid batter, making the batter rise as it bakes.", "Baking soda and baking powder are chemical leavening agents.", "Baking soda is pure sodium bicarbonate.", "To produce carbon dioxide, baking soda needs to be mixed with liquid and an acidic ingredient such as honey.", "Baking powder is a mixture of sodium bicarbonate and an acid.", "To produce carbon dioxide, baking powder needs to be mixed with liquid but not with an acidic ingredient."]}, {"type": "paragraph", "text": "The student wants to emphasize a difference between baking soda and baking powder."}]}'::jsonb, 'source') returning id into v_stim;
