    insert into public.question_options (question_id, label, content, is_correct) values (v_q, 'A', '{"blocks": [{"type": "paragraph", "text": "To make batters rise, bakers use chemical leavening agents such as baking soda and baking powder."}]}'::jsonb, false), (v_q, 'B', '{"blocks": [{"type": "paragraph", "text": "Baking soda and baking powder are chemical leavening agents that, when mixed with other ingredients, cause carbon dioxide to be released within a batter."}]}'::jsonb, false), (v_q, 'C', '{"blocks": [{"type": "paragraph", "text": "Baking soda is pure sodium bicarbonate, and honey is a type of acidic ingredient."}]}'::jsonb, false), (v_q, 'D', '{"blocks": [{"type": "paragraph", "text": "To produce carbon dioxide within a liquid batter, baking soda needs to be mixed with an acidic ingredient, whereas baking powder does not."}]}'::jsonb, true);
