    insert into public.stimuli (subject_id, kind, content, origin) values (v_subject, 'passage', '{"blocks": [{"type": "paragraph", "text": "While researching a topic, a student has taken the following notes:"}, {"type": "list", "items": ["Soo Sunny Park is a Korean American artist who uses light as her primary medium of expression.", "She created her work Unwoven Light in 2013.", "Unwoven Light featured a chain-link fence fitted with iridescent plexiglass tiles.", "When light passed through the fence, colorful prisms formed."]}, {"type": "paragraph", "text": "The student wants to describe Unwoven Light to an audience unfamiliar with Soo Sunny Park."}]}'::jsonb, 'source') returning id into v_stim;
