    insert into public.stimuli (subject_id, kind, content, origin) values (v_subject, 'passage', '{"blocks": [{"type": "paragraph", "text": "While researching a topic, a student has taken the following notes:"}, {"type": "list", "items": ["Cambodia’s Angkor Wat was built in the 1100s to honor the Hindu god Vishnu.", "It has been a Buddhist temple since the sixteenth century.", "Decorrelation stretch analysis is a novel digital imaging technique that enhances the contrast between colors in a photograph.", "Archaeologist Noel Hidalgo Tan applied decorrelation stretch analysis to photographs he had taken of Angkor Wat’s plaster walls.", "Tan’s analysis revealed hundreds of images unknown to researchers."]}, {"type": "paragraph", "text": "The student wants to present Tan’s research to an audience unfamiliar with Angkor Wat."}]}'::jsonb, 'source') returning id into v_stim;
