    insert into public.exam_questions (exam_id, section_id, question_id, position) values (v_exam, v_section, v_q, 61);
    insert into public.stimuli (subject_id, kind, content, origin) values (v_subject, 'passage', '{"blocks": [{"type": "paragraph", "text": "While researching a topic, a student has taken the following notes:"}, {"type": "list", "items": ["The calendar used by most of the world (the Gregorian calendar) has 365 days.", "Because 365 days can’t be divided evenly by 7 (the number of days in a week), calendar dates fall on a different day of the week each year.", "The Hanke-Henry permanent calendar, developed as an alternative to the Gregorian calendar, has 364 days.", "Because 364 can be divided evenly by 7, calendar dates fall on the same day of the week each year, which supports more predictable scheduling."]}, {"type": "paragraph", "text": "The student wants to explain an advantage of the Hanke-Henry calendar."}]}'::jsonb, 'source') returning id into v_stim;
    insert into public.questions (subject_id, stimulus_id, stimulus_marker, stem, explanation, topic_id, difficulty, origin, status, source_question_number, answer_format, accepted_answers)
    insert into public.question_options (question_id, label, content, is_correct) values (v_q, 'A', '{"blocks": [{"type": "paragraph", "text": "The Gregorian calendar has 365 days, which is one day longer than the Hanke-Henry permanent calendar."}]}'::jsonb, false), (v_q, 'B', '{"blocks": [{"type": "paragraph", "text": "Adopting the Hanke-Henry permanent calendar would help solve a problem with the Gregorian calendar."}]}'::jsonb, false), (v_q, 'C', '{"blocks": [{"type": "paragraph", "text": "Designed so calendar dates would occur on the same day of the week each year, the Hanke-Henry calendar supports more predictable scheduling than does the Gregorian calendar."}]}'::jsonb, true), (v_q, 'D', '{"blocks": [{"type": "paragraph", "text": "The Hanke-Henry permanent calendar was developed as an alternative to the Gregorian calendar, which is currently the most-used calendar in the world."}]}'::jsonb, false);
    insert into public.exam_questions (exam_id, section_id, question_id, position) values (v_exam, v_section, v_q, 62);
    insert into public.stimuli (subject_id, kind, content, origin) values (v_subject, 'passage', '{"blocks": [{"type": "paragraph", "text": "While researching a topic, a student has taken the following notes:"}, {"type": "list", "items": ["The Haudenosaunee Confederacy is a nearly 1,000-year-old alliance of six Native nations in the northeastern US.", "The members are bound by a centuries-old agreement known as the Great Law of Peace.", "Historian Bruce Johansen is one of several scholars who believe that the principles of the Great Law of Peace influenced the US Constitution.", "This theory is called the influence theory.", "Johansen cites the fact that Benjamin Franklin and Thomas Jefferson both studied the Haudenosaunee Confederacy."]}, {"type": "paragraph", "text": "The student wants to present the influence theory to an audience unfamiliar with the Haudenosaunee Confederacy."}]}'::jsonb, 'source') returning id into v_stim;
    insert into public.questions (subject_id, stimulus_id, stimulus_marker, stem, explanation, topic_id, difficulty, origin, status, source_question_number, answer_format, accepted_answers)
    insert into public.question_options (question_id, label, content, is_correct) values (v_q, 'A', '{"blocks": [{"type": "paragraph", "text": "Historian Bruce Johansen believes that the Great Law of Peace was very influential."}]}'::jsonb, false), (v_q, 'B', '{"blocks": [{"type": "paragraph", "text": "The influence theory is supported by the fact that Benjamin Franklin and Thomas Jefferson both studied the Haudenosaunee Confederacy."}]}'::jsonb, false), (v_q, 'C', '{"blocks": [{"type": "paragraph", "text": "The influence theory holds that the principles of the Great Law of Peace, a centuries-old agreement binding six Native nations in the northeastern US, influenced the US Constitution."}]}'::jsonb, true), (v_q, 'D', '{"blocks": [{"type": "paragraph", "text": "Native people, including the members of the Haudenosaunee Confederacy, influenced the founding of the US in many different ways."}]}'::jsonb, false);
    insert into public.exam_questions (exam_id, section_id, question_id, position) values (v_exam, v_section, v_q, 63);
    insert into public.stimuli (subject_id, kind, content, origin) values (v_subject, 'passage', '{"blocks": [{"type": "paragraph", "text": "While researching a topic, a student has taken the following notes:"}, {"type": "list", "items": ["In 1999, astronomer Todd Henry studied the differences in surface temperature between the Sun and nearby stars.", "His team mapped all stars within 10 parsecs (approximately 200 trillion miles) of the Sun.", "The surface temperature of the Sun is around 9,800°F, which classifies it as a G star.", "327 of the 357 stars in the study were classified as K or M stars, with surface temperatures under 8,900°F (cooler than the Sun).", "11 of the 357 stars in the study were classified as A or F stars, with surface temperatures greater than 10,300°F (hotter than the Sun)."]}, {"type": "paragraph", "text": "The student wants to emphasize how hot the Sun is relative to nearby stars."}]}'::jsonb, 'source') returning id into v_stim;
    insert into public.questions (subject_id, stimulus_id, stimulus_marker, stem, explanation, topic_id, difficulty, origin, status, source_question_number, answer_format, accepted_answers)
    insert into public.question_options (question_id, label, content, is_correct) values (v_q, 'A', '{"blocks": [{"type": "paragraph", "text": "At around 9,800°F, which classifies it as a G star, the Sun is hotter than most but not all of the stars within 10 parsecs of it."}]}'::jsonb, true), (v_q, 'B', '{"blocks": [{"type": "paragraph", "text": "Astronomer Todd Henry determined that the Sun, at around 9,800°F, is a G star, and several other stars within a 10-parsec range are A or F stars."}]}'::jsonb, false), (v_q, 'C', '{"blocks": [{"type": "paragraph", "text": "Of the 357 stars within ten parsecs of the Sun, 327 are classified as K or M stars, with surface temperatures under 8,900°F."}]}'::jsonb, false), (v_q, 'D', '{"blocks": [{"type": "paragraph", "text": "While most of the stars within 10 parsecs of the Sun are classified as K, M, A, or F stars, the Sun is classified as a G star due to its surface temperature of 9,800°F."}]}'::jsonb, false);
