    insert into public.question_options (question_id, label, content, is_correct) values (v_q, 'A', '{"blocks": [{"type": "paragraph", "text": "Cathryn Halverson’s Faraway Women and the “Atlantic Monthly” discusses female authors whose autobiographies appeared in the magazine in the early 1900s."}]}'::jsonb, true), (v_q, 'B', '{"blocks": [{"type": "paragraph", "text": "A magazine called the Atlantic Monthly, referred to in Cathryn Halverson’s book title, was first published in 1857."}]}'::jsonb, false), (v_q, 'C', '{"blocks": [{"type": "paragraph", "text": "Faraway Women and the “Atlantic Monthly” features contributors to the Atlantic Monthly, first published in 1857 as a magazine focusing on politics, art, and literature."}]}'::jsonb, false), (v_q, 'D', '{"blocks": [{"type": "paragraph", "text": "An author discussed by Cathryn Halverson is Juanita Harrison, whose autobiography appeared in the Atlantic Monthly in the early 1900s."}]}'::jsonb, false);
