    insert into public.stimuli (subject_id, kind, content, origin) values (v_subject, 'passage', '{"blocks": [{"type": "paragraph", "text": "While researching a topic, a student has taken the following notes:"}, {"type": "list", "items": ["The magnificent frigatebird (fregata magnificens) is a species of seabird that feeds mainly on fish, tuna, squid, and other small sea animals.", "It is unusual among seabirds in that it doesn’t dive into the water for prey.", "One way it acquires food is by using its hook-tipped bill to snatch prey from the surface of the water.", "Another way it acquires food is by taking it from weaker birds by force.", "This behavior is known as kleptoparasitism."]}, {"type": "paragraph", "text": "The student wants to emphasize a similarity between the two ways a magnificent frigatebird acquires food."}]}'::jsonb, 'source') returning id into v_stim;
