    insert into public.exam_questions (exam_id, section_id, question_id, position) values (v_exam, v_section, v_q, 1);
    insert into public.stimuli (subject_id, kind, content, origin) values (v_subject, 'passage', '{"blocks": [{"type": "paragraph", "text": "Many ancient sculptures of people’s heads are missing their noses. This is because the nose is the most ______ part of a sculpture of a person’s head. It is delicate and sticks out from the rest of the sculpture, making it especially easy to break."}]}'::jsonb, 'source') returning id into v_stim;
