    insert into public.question_options (question_id, label, content, is_correct) values (v_q, 'A', '{"blocks": [{"type": "paragraph", "text": "antecedent"}]}'::jsonb, false), (v_q, 'B', '{"blocks": [{"type": "paragraph", "text": "impending"}]}'::jsonb, true), (v_q, 'C', '{"blocks": [{"type": "paragraph", "text": "innocuous"}]}'::jsonb, false), (v_q, 'D', '{"blocks": [{"type": "paragraph", "text": "perpetual"}]}'::jsonb, false);
    insert into public.exam_questions (exam_id, section_id, question_id, position) values (v_exam, v_section, v_q, 3);
    insert into public.stimuli (subject_id, kind, content, origin) values (v_subject, 'passage', '{"blocks": [{"type": "paragraph", "text": "To demonstrate that the integrity of underground metal pipes can be assessed without unearthing the pipes, engineer Aroba Saleem and colleagues ______ the tendency of some metals’ internal magnetic fields to alter under stress: the team showed that such alterations can be measured from a distance and can reveal concentrations of stress in the pipes."}]}'::jsonb, 'source') returning id into v_stim;
    insert into public.questions (subject_id, stimulus_id, stimulus_marker, stem, explanation, topic_id, difficulty, origin, status, source_question_number, answer_format, accepted_answers)
    insert into public.question_options (question_id, label, content, is_correct) values (v_q, 'A', '{"blocks": [{"type": "paragraph", "text": "hypothesized"}]}'::jsonb, false), (v_q, 'B', '{"blocks": [{"type": "paragraph", "text": "discounted"}]}'::jsonb, false), (v_q, 'C', '{"blocks": [{"type": "paragraph", "text": "redefined"}]}'::jsonb, false), (v_q, 'D', '{"blocks": [{"type": "paragraph", "text": "exploited"}]}'::jsonb, true);
    insert into public.exam_questions (exam_id, section_id, question_id, position) values (v_exam, v_section, v_q, 4);
    insert into public.stimuli (subject_id, kind, content, origin) values (v_subject, 'passage', '{"blocks": [{"type": "paragraph", "text": "Despite the generalizations about human behavior they have produced, many studies of behavioral psychology have used highly unrepresentative subject pools: students at the colleges and universities where the researchers are employed. To ______ this situation, it is necessary to actively recruit subjects from diverse backgrounds and locations."}]}'::jsonb, 'source') returning id into v_stim;
