    insert into public.exam_questions (exam_id, section_id, question_id, position) values (v_exam, v_section, v_q, 24);
    insert into public.stimuli (subject_id, kind, content, origin) values (v_subject, 'passage', '{"blocks": [{"type": "paragraph", "text": "Long attributed to Jacques-Louis David, the preeminent Neoclassical painter of his day, the 1801 painting Marie Joséphine Charlotte du Val d’Ognes gained fresh attention in the 1990s when art historians discovered that the painting—which depicts a solitary young woman sketching—was actually the work of little-known French portrait ______ Marie-Denise Villers (1774–1821)."}]}'::jsonb, 'source') returning id into v_stim;
    insert into public.questions (subject_id, stimulus_id, stimulus_marker, stem, explanation, topic_id, difficulty, origin, status, source_question_number, answer_format, accepted_answers)
    insert into public.question_options (question_id, label, content, is_correct) values (v_q, 'A', '{"blocks": [{"type": "paragraph", "text": "artist—"}]}'::jsonb, false), (v_q, 'B', '{"blocks": [{"type": "paragraph", "text": "artist"}]}'::jsonb, true), (v_q, 'C', '{"blocks": [{"type": "paragraph", "text": "artist:"}]}'::jsonb, false), (v_q, 'D', '{"blocks": [{"type": "paragraph", "text": "artist,"}]}'::jsonb, false);
    insert into public.exam_questions (exam_id, section_id, question_id, position) values (v_exam, v_section, v_q, 25);
    insert into public.stimuli (subject_id, kind, content, origin) values (v_subject, 'passage', '{"blocks": [{"type": "paragraph", "text": "In 1986, conceptual artist Sophie Calle asked twenty-three people, all of whom had been born without sight, to describe “their image of beauty” in rich detail. Calle paired excerpts of these conversations with photographs—both of interviewees and the items they ______ to powerful effect in her exhibition The Blind."}]}'::jsonb, 'source') returning id into v_stim;
