    insert into public.question_options (question_id, label, content, is_correct) values (v_q, 'A', '{"blocks": [{"type": "paragraph", "text": "described, from hair to grass to sculptures"}]}'::jsonb, false), (v_q, 'B', '{"blocks": [{"type": "paragraph", "text": "described, from hair to grass to sculptures—"}]}'::jsonb, true), (v_q, 'C', '{"blocks": [{"type": "paragraph", "text": "described—from hair to grass to sculptures,"}]}'::jsonb, false), (v_q, 'D', '{"blocks": [{"type": "paragraph", "text": "described: from hair to grass to sculptures"}]}'::jsonb, false);
    insert into public.exam_questions (exam_id, section_id, question_id, position) values (v_exam, v_section, v_q, 26);
    insert into public.stimuli (subject_id, kind, content, origin) values (v_subject, 'passage', '{"blocks": [{"type": "paragraph", "text": "Celebrated Tewa potter Maria Martinez (1887–1980) made her signature all-black ceramic vessels using a heating technique called reduction firing. This technique involves smothering the flame surrounding the clay vessel. ______ the vessel takes on a shiny, black hue."}]}'::jsonb, 'source') returning id into v_stim;
