    insert into public.question_options (question_id, label, content, is_correct) values (v_q, 'A', '{"blocks": [{"type": "paragraph", "text": "On the contrary,"}]}'::jsonb, false), (v_q, 'B', '{"blocks": [{"type": "paragraph", "text": "For example,"}]}'::jsonb, false), (v_q, 'C', '{"blocks": [{"type": "paragraph", "text": "Previously,"}]}'::jsonb, false), (v_q, 'D', '{"blocks": [{"type": "paragraph", "text": "As a result,"}]}'::jsonb, true);
    insert into public.exam_questions (exam_id, section_id, question_id, position) values (v_exam, v_section, v_q, 27);
    insert into public.stimuli (subject_id, kind, content, origin) values (v_subject, 'passage', '{"blocks": [{"type": "paragraph", "text": "Historians agree that the jazz pianist Jelly Roll Morton was exaggerating when he claimed to have invented jazz music. No one can deny, ______ that Morton’s innovative compositions and remarkable improvisational skills helped shape jazz as a genre during its early years."}]}'::jsonb, 'source') returning id into v_stim;
