    insert into public.stimuli (subject_id, kind, content, origin) values (v_subject, 'passage', '{"blocks": [{"type": "paragraph", "text": "A turtle shell appears external to the animal, protecting its body like armor. ______ the shell is often incorrectly assumed to be an exoskeleton, a rigid outer casing like that of a crustacean or an insect, when in fact it is an endoskeleton, a part of the turtle’s internal bone structure, more akin to a spine or a pair of ribs."}]}'::jsonb, 'source') returning id into v_stim;
    insert into public.questions (subject_id, stimulus_id, stimulus_marker, stem, explanation, topic_id, difficulty, origin, status, source_question_number, answer_format, accepted_answers)
    insert into public.question_options (question_id, label, content, is_correct) values (v_q, 'A', '{"blocks": [{"type": "paragraph", "text": "That being said,"}]}'::jsonb, false), (v_q, 'B', '{"blocks": [{"type": "paragraph", "text": "However,"}]}'::jsonb, false), (v_q, 'C', '{"blocks": [{"type": "paragraph", "text": "For instance,"}]}'::jsonb, false), (v_q, 'D', '{"blocks": [{"type": "paragraph", "text": "Hence,"}]}'::jsonb, true);
    insert into public.exam_questions (exam_id, section_id, question_id, position) values (v_exam, v_section, v_q, 30);
    insert into public.stimuli (subject_id, kind, content, origin) values (v_subject, 'passage', '{"blocks": [{"type": "paragraph", "text": "While researching a topic, a student has taken the following notes:"}, {"type": "list", "items": ["In 1859, the novel Adam Bede was published in England.", "According to the novel’s title page, the author’s name was George Eliot.", "George Eliot was widely assumed to be a pseudonym.", "A pseudonym is a fake name used to conceal an author’s identity.", "A woman named Mary Ann Evans later revealed herself as the novel’s real author."]}, {"type": "paragraph", "text": "The student wants to identify the real author of Adam Bede."}]}'::jsonb, 'source') returning id into v_stim;
    insert into public.questions (subject_id, stimulus_id, stimulus_marker, stem, explanation, topic_id, difficulty, origin, status, source_question_number, answer_format, accepted_answers)
    insert into public.question_options (question_id, label, content, is_correct) values (v_q, 'A', '{"blocks": [{"type": "paragraph", "text": "The real author of Adam Bede was Mary Ann Evans, who published the novel using the pseudonym George Eliot."}]}'::jsonb, true), (v_q, 'B', '{"blocks": [{"type": "paragraph", "text": "George Eliot, which Adam Bede’s title page indicated was the name of the novel’s author, was widely assumed to be a pseudonym."}]}'::jsonb, false), (v_q, 'C', '{"blocks": [{"type": "paragraph", "text": "The title page of the novel Adam Bede indicated that the author’s name was George Eliot."}]}'::jsonb, false), (v_q, 'D', '{"blocks": [{"type": "paragraph", "text": "A woman who had used a pseudonym to conceal her identity later revealed herself as the real author of Adam Bede."}]}'::jsonb, false);
    insert into public.exam_questions (exam_id, section_id, question_id, position) values (v_exam, v_section, v_q, 31);
    insert into public.stimuli (subject_id, kind, content, origin) values (v_subject, 'passage', '{"blocks": [{"type": "paragraph", "text": "While researching a topic, a student has taken the following notes:"}, {"type": "list", "items": ["Scientists have developed a “freeze-thaw” battery that can retain 92% of its charge after twelve weeks.", "The battery contains molten salt (a type of salt that liquifies when heated and solidifies at room temperature).", "When the salt is in a liquid state, energy flows through the battery.", "When the salt is in a solid state, energy stops flowing and is stored in the battery.", "The stored (frozen) energy can be used by reheating (thawing) the battery."]}, {"type": "paragraph", "text": "The student wants to specify how the salt enables energy storage."}]}'::jsonb, 'source') returning id into v_stim;
    insert into public.questions (subject_id, stimulus_id, stimulus_marker, stem, explanation, topic_id, difficulty, origin, status, source_question_number, answer_format, accepted_answers)
    insert into public.question_options (question_id, label, content, is_correct) values (v_q, 'A', '{"blocks": [{"type": "paragraph", "text": "Scientists have developed a freeze-thaw battery that contains molten salt, which liquifies when heated and solidifies at room temperature."}]}'::jsonb, false), (v_q, 'B', '{"blocks": [{"type": "paragraph", "text": "The stored energy in a freeze-thaw battery, which contains molten salt, can be used by reheating the battery."}]}'::jsonb, false), (v_q, 'C', '{"blocks": [{"type": "paragraph", "text": "When the molten salt in a freeze-thaw battery solidifies at room temperature, energy stops flowing and can be stored in the battery."}]}'::jsonb, true), (v_q, 'D', '{"blocks": [{"type": "paragraph", "text": "Molten salt allows a freeze-thaw battery to retain 92% of its charge after twelve weeks."}]}'::jsonb, false);
    insert into public.exam_questions (exam_id, section_id, question_id, position) values (v_exam, v_section, v_q, 32);
    insert into public.stimuli (subject_id, kind, content, origin) values (v_subject, 'passage', '{"blocks": [{"type": "paragraph", "text": "While researching a topic, a student has taken the following notes:"}, {"type": "list", "items": ["The US Fish and Wildlife Service (FWS) keeps a list of all at-risk species.", "Species on the list are classified as either endangered or threatened.", "A species that is in danger of extinction throughout most or all of its range is classified as endangered.", "A species that is likely to soon become endangered is classified as threatened.", "The California red-legged frog (Rana draytonii) is likely to soon become endangered, according to the FWS."]}, {"type": "paragraph", "text": "The student wants to indicate the California red-legged frog’s FWS classification category."}]}'::jsonb, 'source') returning id into v_stim;
    insert into public.questions (subject_id, stimulus_id, stimulus_marker, stem, explanation, topic_id, difficulty, origin, status, source_question_number, answer_format, accepted_answers)
    insert into public.question_options (question_id, label, content, is_correct) values (v_q, 'A', '{"blocks": [{"type": "paragraph", "text": "Species on the FWS list, which includes the California red-legged frog (Rana draytonii), are classified as either endangered or threatened."}]}'::jsonb, false), (v_q, 'B', '{"blocks": [{"type": "paragraph", "text": "The California red-legged frog (Rana draytonii) appears on the FWS list of at-risk species."}]}'::jsonb, false), (v_q, 'C', '{"blocks": [{"type": "paragraph", "text": "According to the FWS, the California red-legged frog is in the endangered category, in danger of extinction throughout most or all of its range."}]}'::jsonb, false), (v_q, 'D', '{"blocks": [{"type": "paragraph", "text": "Likely to soon become endangered, the California red-legged frog is classified as threatened by the FWS."}]}'::jsonb, true);
    insert into public.exam_questions (exam_id, section_id, question_id, position) values (v_exam, v_section, v_q, 33);
    insert into public.exam_sections (exam_id, position, title) values (v_exam, 2, 'Module 2') returning id into v_section;
    insert into public.stimuli (subject_id, kind, content, origin) values (v_subject, 'passage', '{"blocks": [{"type": "paragraph", "text": "The following text is adapted from Elizabeth von Arnim’s 1922 novel The Enchanted April. Mrs. Wilkins and her friend Rose are traveling in Italy."}, {"type": "paragraph", "text": "“I’m going to have one of these gorgeous oranges,” said Mrs. Wilkins, staying where she was and reaching across to a black bowl piled with them. “Rose, how can you resist them. Look—have this one. Do have this beauty—” And she held out a big one."}]}'::jsonb, 'source') returning id into v_stim;
