    insert into public.exam_questions (exam_id, section_id, question_id, position) values (v_exam, v_section, v_q, 35);
    insert into public.stimuli (subject_id, kind, content, origin) values (v_subject, 'passage', '{"blocks": [{"type": "paragraph", "text": "According to a team of neuroeconomists from the University of Zurich, ease of decision making may be linked to communication between two brain regions, the prefrontal cortex and the parietal cortex. Individuals tend to be more decisive if the information flow between the regions is intensified, whereas they make choices more slowly when information flow is ______."}]}'::jsonb, 'source') returning id into v_stim;
