    insert into public.exam_questions (exam_id, section_id, question_id, position) values (v_exam, v_section, v_q, 36);
    insert into public.stimuli (subject_id, kind, content, origin) values (v_subject, 'passage', '{"blocks": [{"type": "paragraph", "text": "The War of 1812 has ______ place in historical memory in Britain, partly because it is overshadowed by the much larger concurrent conflict against Napoleonic France and partly because it essentially maintained the geopolitical status quo for Britain: the country neither gained nor lost significant territory or position as a result of its participation in the war."}]}'::jsonb, 'source') returning id into v_stim;
