    insert into public.question_options (question_id, label, content, is_correct) values (v_q, 'A', '{"blocks": [{"type": "paragraph", "text": "In 2016, the number of cellular and molecular biology topic submissions was the same as the number of animal science topic submissions."}]}'::jsonb, false), (v_q, 'B', '{"blocks": [{"type": "paragraph", "text": "In 2019, there were more physics and space science topic submissions than there were medicine and health topic submissions."}]}'::jsonb, false), (v_q, 'C', '{"blocks": [{"type": "paragraph", "text": "The lowest number of animal science topic submissions in a year was approximately 95 in 2016."}]}'::jsonb, false), (v_q, 'D', '{"blocks": [{"type": "paragraph", "text": "The highest number of medicine and health topic submissions during the period shown is approximately 285 in 2019."}]}'::jsonb, true);
