    insert into public.exam_questions (exam_id, section_id, question_id, position) values (v_exam, v_section, v_q, 48);
    insert into public.stimuli (subject_id, kind, content, origin) values (v_subject, 'table', '{"blocks": [{"type": "image", "src": "/sat/test-05/rw-m2-q16.png", "alt": "Table or graph for this question", "width": 550}, {"type": "paragraph", "text": "Some climate models for the western United States predict that while total annual precipitation may remain unchanged from the present level, precipitation will become concentrated into fewer but more intense rain and snow events. University of Texas climate scientist Geeta Persad and her colleagues simulated how the amount of water entering aquifers and the amount being used for irrigation purposes would change if this were to occur. Persad and her colleagues concluded that concentration of precipitation into fewer events would result in a higher number of dry days, triggering more irrigation, but that this change in irrigation output is highly sensitive to the baseline concentration of precipitation that currently exists in an area."}]}'::jsonb, 'source') returning id into v_stim;
    insert into public.questions (subject_id, stimulus_id, stimulus_marker, stem, explanation, topic_id, difficulty, origin, status, source_question_number, answer_format, accepted_answers)
