    insert into public.stimuli (subject_id, kind, content, origin) values (v_subject, 'passage', '{"blocks": [{"type": "paragraph", "text": "While researching a topic, a student has taken the following notes:"}, {"type": "list", "items": ["In astronomy, the mass of stars can be described in units called solar masses.", "One solar mass is roughly equal to the mass of the Sun.", "The mass of the star Proxima Centauri is 0.122 solar masses.", "The mass of the star Sirius A is 2.063 solar masses."]}, {"type": "paragraph", "text": "The student wants to emphasize the mass of Sirius A."}]}'::jsonb, 'source') returning id into v_stim;
    insert into public.questions (subject_id, stimulus_id, stimulus_marker, stem, explanation, topic_id, difficulty, origin, status, source_question_number, answer_format, accepted_answers)
    insert into public.question_options (question_id, label, content, is_correct) values (v_q, 'A', '{"blocks": [{"type": "paragraph", "text": "The mass of stars, like Proxima Centauri, can be described in units called solar masses."}]}'::jsonb, false), (v_q, 'B', '{"blocks": [{"type": "paragraph", "text": "In astronomy, the mass of stars can be described in units called solar masses, and one solar mass is roughly equal to the mass of the Sun."}]}'::jsonb, false), (v_q, 'C', '{"blocks": [{"type": "paragraph", "text": "The Sun is more massive than Proxima Centauri, which has a mass of 0.122 solar masses."}]}'::jsonb, false), (v_q, 'D', '{"blocks": [{"type": "paragraph", "text": "With a mass of 2.063 solar masses, Sirius A is more massive than the Sun."}]}'::jsonb, true);
