    insert into public.stimuli (subject_id, kind, content, origin) values (v_subject, 'passage', '{"blocks": [{"type": "paragraph", "text": "While researching a topic, a student has taken the following notes:"}, {"type": "list", "items": ["A lever is a simple machine consisting of a rigid beam and a fulcrum.", "The fulcrum is the point about which the beam pivots.", "The input force (effort) is the force applied to the lever.", "The output force (load) is the force that the lever exerts on another object.", "In first-class levers, the fulcrum is located between the effort and the load.", "In second-class levers, the load is located between the effort and the fulcrum."]}, {"type": "paragraph", "text": "The student wants to contrast first-class levers and second-class levers."}]}'::jsonb, 'source') returning id into v_stim;
