    insert into public.question_options (question_id, label, content, is_correct) values (v_q, 'A', '{"blocks": [{"type": "paragraph", "text": "In levers, the effort is the force applied to the lever; the load, in contrast, is the force that the lever exerts on another object."}]}'::jsonb, false), (v_q, 'B', '{"blocks": [{"type": "paragraph", "text": "In first-class and second-class levers, the fulcrum and the load are in different locations."}]}'::jsonb, false), (v_q, 'C', '{"blocks": [{"type": "paragraph", "text": "First-class levers are simple machines consisting of a rigid beam and a fulcrum, but then again, the same is true of second-class levers."}]}'::jsonb, false), (v_q, 'D', '{"blocks": [{"type": "paragraph", "text": "In first-class levers, the fulcrum is located between the effort and the load, but in second-class levers, the load is located between the effort and the fulcrum."}]}'::jsonb, true);
