    insert into public.question_options (question_id, label, content, is_correct) values (v_q, 'A', '{"blocks": [{"type": "paragraph", "text": "Based on statistical analysis, Glickman, Brown, and Song claim that John Lennon wrote the verse of “In My Life.”"}]}'::jsonb, false), (v_q, 'B', '{"blocks": [{"type": "paragraph", "text": "There is only an 18.9% probability that Paul McCartney wrote the verse for “In My Life”; John Lennon is the more likely author."}]}'::jsonb, false), (v_q, 'C', '{"blocks": [{"type": "paragraph", "text": "It is likely that John Lennon, not Paul McCartney, wrote the verse for “In My Life.”"}]}'::jsonb, false), (v_q, 'D', '{"blocks": [{"type": "paragraph", "text": "Researchers have used statistical methods to address questions of authorship within the field of music."}]}'::jsonb, true);
