    insert into public.question_options (question_id, label, content, is_correct) values (v_q, 'A', '{"blocks": [{"type": "paragraph", "text": "bounds helped"}]}'::jsonb, true), (v_q, 'B', '{"blocks": [{"type": "paragraph", "text": "bounds, helping"}]}'::jsonb, false), (v_q, 'C', '{"blocks": [{"type": "paragraph", "text": "bounds that helped"}]}'::jsonb, false), (v_q, 'D', '{"blocks": [{"type": "paragraph", "text": "bounds to help"}]}'::jsonb, false);
    insert into public.exam_questions (exam_id, section_id, question_id, position) values (v_exam, v_section, v_q, 55);
    insert into public.stimuli (subject_id, kind, content, origin) values (v_subject, 'passage', '{"blocks": [{"type": "paragraph", "text": "The forty-seven geothermal springs of Arkansas’ Hot Springs National Park are sourced via a process known as natural groundwater recharge, in which rainwater percolates downward through the earth—in this case, the porous rocks of the hills around Hot ______ collect in a subterranean basin."}]}'::jsonb, 'source') returning id into v_stim;
    insert into public.questions (subject_id, stimulus_id, stimulus_marker, stem, explanation, topic_id, difficulty, origin, status, source_question_number, answer_format, accepted_answers)
    insert into public.question_options (question_id, label, content, is_correct) values (v_q, 'A', '{"blocks": [{"type": "paragraph", "text": "Springs to"}]}'::jsonb, false), (v_q, 'B', '{"blocks": [{"type": "paragraph", "text": "Springs: to"}]}'::jsonb, false), (v_q, 'C', '{"blocks": [{"type": "paragraph", "text": "Springs—to"}]}'::jsonb, true), (v_q, 'D', '{"blocks": [{"type": "paragraph", "text": "Springs, to"}]}'::jsonb, false);
    insert into public.exam_questions (exam_id, section_id, question_id, position) values (v_exam, v_section, v_q, 56);
    insert into public.stimuli (subject_id, kind, content, origin) values (v_subject, 'passage', '{"blocks": [{"type": "paragraph", "text": "Over twenty years ago, in a landmark experiment in the psychology of choice, professor Sheena Iyengar set up a jam-tasting booth at a grocery store. The number of jams available for tasting ______ some shoppers had twenty-four different options, others only six. Interestingly, the shoppers with fewer jams to choose from purchased more jam."}]}'::jsonb, 'source') returning id into v_stim;
