    insert into public.question_options (question_id, label, content, is_correct) values (v_q, 'A', '{"blocks": [{"type": "paragraph", "text": "Subsequently,"}]}'::jsonb, false), (v_q, 'B', '{"blocks": [{"type": "paragraph", "text": "Besides,"}]}'::jsonb, false), (v_q, 'C', '{"blocks": [{"type": "paragraph", "text": "Nevertheless,"}]}'::jsonb, false), (v_q, 'D', '{"blocks": [{"type": "paragraph", "text": "Thus,"}]}'::jsonb, true);
