    insert into public.exam_questions (exam_id, section_id, question_id, position) values (v_exam, v_section, v_q, 20);
    insert into public.stimuli (subject_id, kind, content, origin) values (v_subject, 'passage', '{"blocks": [{"type": "paragraph", "text": "Typically, underlines, scribbles, and notes left in the margins by a former owner lower a book’s ______ when the former owner is a famous poet like Walt Whitman, such markings, known as marginalia, can be a gold mine to literary scholars."}]}'::jsonb, 'source') returning id into v_stim;
