    insert into public.exam_questions (exam_id, section_id, question_id, position) values (v_exam, v_section, v_q, 22);
    insert into public.stimuli (subject_id, kind, content, origin) values (v_subject, 'passage', '{"blocks": [{"type": "paragraph", "text": "While many video game creators strive to make their graphics ever more ______ others look to the past, developing titles with visuals inspired by the “8-bit” games of the 1980s and 1990s. (The term “8-bit” refers to a console whose processor could only handle eight bits of data at once.)"}]}'::jsonb, 'source') returning id into v_stim;
