    insert into public.exam_questions (exam_id, section_id, question_id, position) values (v_exam, v_section, v_q, 24);
    insert into public.stimuli (subject_id, kind, content, origin) values (v_subject, 'passage', '{"blocks": [{"type": "paragraph", "text": "Along with carbon dioxide concentration and temperature, light intensity affects the chemical reaction rate of ______ as light intensity increases, so does the rate at which the reactants (water and carbon dioxide) are converted into their products (glucose and oxygen)."}]}'::jsonb, 'source') returning id into v_stim;
