    insert into public.exam_questions (exam_id, section_id, question_id, position) values (v_exam, v_section, v_q, 25);
    insert into public.stimuli (subject_id, kind, content, origin) values (v_subject, 'passage', '{"blocks": [{"type": "paragraph", "text": "In Marisol’s 1968 sculpture Mi Mama y Yo, gone are the types of pop culture references that made the Parisian-born Venezuelan American artist a star at the height of the pop art movement. In ______ place is a far more personal subject: a sculptural depiction of the artist as a young girl with her mother."}]}'::jsonb, 'source') returning id into v_stim;
