    insert into public.question_options (question_id, label, content, is_correct) values (v_q, 'A', '{"blocks": [{"type": "paragraph", "text": "is"}]}'::jsonb, true), (v_q, 'B', '{"blocks": [{"type": "paragraph", "text": "were"}]}'::jsonb, false), (v_q, 'C', '{"blocks": [{"type": "paragraph", "text": "have been"}]}'::jsonb, false), (v_q, 'D', '{"blocks": [{"type": "paragraph", "text": "are"}]}'::jsonb, false);
    insert into public.exam_questions (exam_id, section_id, question_id, position) values (v_exam, v_section, v_q, 27);
    insert into public.stimuli (subject_id, kind, content, origin) values (v_subject, 'passage', '{"blocks": [{"type": "paragraph", "text": "Organisms have evolved a number of surprising adaptations to ensure their survival in adverse conditions. Tadpole shrimp (Triops longicaudatus) embryos, ______ can pause development for over ten years during extended periods of drought."}]}'::jsonb, 'source') returning id into v_stim;
