    insert into public.stimuli (subject_id, kind, content, origin) values (v_subject, 'passage', '{"blocks": [{"type": "paragraph", "text": "Researchers have struggled to pinpoint specific causes for hiccups, which happen when a person’s diaphragm contracts ______. However, neuroscientist Kimberley Whitehead has found that these uncontrollable contractions may play an important role in helping infants regulate their breathing."}]}'::jsonb, 'source') returning id into v_stim;
