    insert into public.stimuli (subject_id, kind, content, origin) values (v_subject, 'passage', '{"blocks": [{"type": "paragraph", "text": "In rural Minnesota, ecologist Leroy Walston conducted a study to determine whether seeding solar panel fields with wildflowers could bolster pollinator populations in nearby food crops. Walston’s findings indicate that—assuming solar panel installers’ ______ practice has the potential to increase the number of native bees in crops near solar fields throughout the Midwest by up to 20 percent."}]}'::jsonb, 'source') returning id into v_stim;
