    insert into public.stimuli (subject_id, kind, content, origin) values (v_subject, 'passage', '{"blocks": [{"type": "paragraph", "text": "While researching a topic, a student has taken the following notes:"}, {"type": "list", "items": ["In a 2020 study, researchers in California investigated how many potential nesting sites female wood ducks visited during the nesting season.", "The researchers placed nest boxes throughout the survey area and tagged 138 female wood ducks with radio frequency ID trackers.", "These trackers recorded how many nest boxes each duck visited.", "67 ducks (48.5%) visited only one nest box.", "18 ducks (13.0%) visited 10 or more nest boxes.", "Younger ducks were more likely to visit multiple nest boxes."]}, {"type": "paragraph", "text": "The student wants to present the methods used in the 2020 study."}]}'::jsonb, 'source') returning id into v_stim;
    insert into public.questions (subject_id, stimulus_id, stimulus_marker, stem, explanation, topic_id, difficulty, origin, status, source_question_number, answer_format, accepted_answers)
    insert into public.question_options (question_id, label, content, is_correct) values (v_q, 'A', '{"blocks": [{"type": "paragraph", "text": "By recording how many nest boxes each duck visited, the researchers discovered that only a relatively small percentage (13.0%) of the ducks visited 10 or more nest boxes."}]}'::jsonb, false), (v_q, 'B', '{"blocks": [{"type": "paragraph", "text": "After tracking how many nest boxes the 138 wood ducks visited, the researchers found that the younger ducks tended to visit more nest boxes than the older ducks."}]}'::jsonb, false), (v_q, 'C', '{"blocks": [{"type": "paragraph", "text": "The researchers tagged 138 female wood ducks with radio frequency ID trackers and recorded how many nest boxes each duck visited during the nesting season."}]}'::jsonb, true), (v_q, 'D', '{"blocks": [{"type": "paragraph", "text": "The researchers investigated each nesting site for signs that it had been visited by the female wood ducks."}]}'::jsonb, false);
