    insert into public.stimuli (subject_id, kind, content, origin) values (v_subject, 'passage', '{"blocks": [{"type": "paragraph", "text": "While researching a topic, a student has taken the following notes:"}, {"type": "list", "items": ["Pedestrian malls are outdoor streets in a city or town where vehicle traffic is prohibited.", "Many pedestrian malls were built in the 19th and 20th centuries in Europe and Asia.", "Qianmen Dajie is a famous pedestrian mall in Beijing.", "It has existed since the Ming dynasty (1368–1644 CE).", "Rue Mouffetard is a famous pedestrian mall in Paris.", "It has existed since the mid-Roman Empire (117–235 CE)."]}, {"type": "paragraph", "text": "The student wants to emphasize a similarity between the ages of the malls."}]}'::jsonb, 'source') returning id into v_stim;
    insert into public.questions (subject_id, stimulus_id, stimulus_marker, stem, explanation, topic_id, difficulty, origin, status, source_question_number, answer_format, accepted_answers)
    insert into public.question_options (question_id, label, content, is_correct) values (v_q, 'A', '{"blocks": [{"type": "paragraph", "text": "The Qianmen Dajie pedestrian mall has roots as far back as the Ming dynasty; likewise, Rue Mouffetard has existed for centuries."}]}'::jsonb, true), (v_q, 'B', '{"blocks": [{"type": "paragraph", "text": "Both Qianmen Dajie and Rue Mouffetard are famous pedestrian malls, the former in Beijing and the latter in Paris."}]}'::jsonb, false), (v_q, 'C', '{"blocks": [{"type": "paragraph", "text": "Qianmen Dajie and Rue Mouffetard are pedestrian malls, outdoor streets closed to vehicle traffic."}]}'::jsonb, false), (v_q, 'D', '{"blocks": [{"type": "paragraph", "text": "Qianmen Dajie and Rue Mouffetard are examples of pedestrian malls, which proliferated in Europe in the 19th and 20th centuries."}]}'::jsonb, false);
    insert into public.exam_questions (exam_id, section_id, question_id, position) values (v_exam, v_section, v_q, 65);
    insert into public.stimuli (subject_id, kind, content, origin) values (v_subject, 'passage', '{"blocks": [{"type": "paragraph", "text": "While researching a topic, a student has taken the following notes:"}, {"type": "list", "items": ["Modularity of mind is the notion that the mind is at least partly composed of innate neural structures (modules) that perform fast, necessary tasks.", "1983: cognitive scientist Jerry A. Fodor hypothesized that low-level cognitive systems (e.g., perception, language) are modular.", "In Fodorian modularity, high-level systems (e.g., reasoning) are not modular.", "2003: cognitive scientist Peter Carruthers proposed the massive modularity hypothesis (MMH).", "MMH expands modularity to include all cognitive systems."]}, {"type": "paragraph", "text": "The student wants to compare Fodor’s hypothesis with Carruthers’s."}]}'::jsonb, 'source') returning id into v_stim;
