    insert into public.question_options (question_id, label, content, is_correct) values (v_q, 'A', '{"blocks": [{"type": "paragraph", "text": "In considering some but not all cognitive systems modular, Fodorian modularity is not as expansive in its definition of modularity as MMH is."}]}'::jsonb, true), (v_q, 'B', '{"blocks": [{"type": "paragraph", "text": "Following Fodor’s 1983 hypothesis, Carruthers proposed that modularity of mind includes all cognitive systems."}]}'::jsonb, false), (v_q, 'C', '{"blocks": [{"type": "paragraph", "text": "The hypotheses of Fodor and Carruthers differ in whether they consider low-level cognitive systems, such as perception and language, modular."}]}'::jsonb, false), (v_q, 'D', '{"blocks": [{"type": "paragraph", "text": "In 2003, Carruthers proposed the massive modularity hypothesis, disagreeing with Fodor’s earlier hypothesis that the mind is composed of innate neural structures."}]}'::jsonb, false);
